def target_node(soup: BeautifulSoup, slug: str, language: str, fact_id: str):
    body = soup.select_one(f'[data-language-body="{language}"]')
    return body.find(attrs={"data-fact-id": fact_id}) if body else None


def source_node(soup: BeautifulSoup, language: str, source_id: str, kind: str):
    body = soup.select_one(f'[data-language-body="{language}"]')
    source = body.select_one(f'li[data-source-id="{source_id}"]') if body else None
    if source is None:
        return None
    return source.find("b") if kind == "category" else source.find("a")


def audit_rule(soup: BeautifulSoup, key, spec):
    slug, language, fact_id = key
    node = target_node(soup, slug, language, fact_id)
    if node is None:
        return [f"{slug}/{language}/{fact_id}: target missing"]
    visible = " ".join(node.get_text(" ", strip=True).split()).casefold()
    issues = []
    for value in spec["required"]:
        if value.casefold() not in visible:
            issues.append(f"{slug}/{language}/{fact_id}: required concept missing: {value}")
    for value in spec["forbidden"]:
        if value.casefold() in visible:
            issues.append(f"{slug}/{language}/{fact_id}: rejected phrase present: {value}")
    return issues


def audit_source_rule(soup: BeautifulSoup, key, spec, kind: str):
    slug, language, source_id = key
    node = source_node(soup, language, source_id, kind)
    if node is None:
        return [f"{slug}/{language}/{source_id}: {kind} target missing"]
    visible = " ".join(node.get_text(" ", strip=True).split()).casefold()
    issues = []
    for value in spec["required"]:
        if value.casefold() not in visible:
            issues.append(f"{slug}/{language}/{source_id}: required {kind} concept missing: {value}")
    for value in spec["forbidden"]:
        if value.casefold() in visible:
            issues.append(f"{slug}/{language}/{source_id}: rejected {kind} phrase present: {value}")
    return issues


def audit_source_invariants(pages):
    issues = []
    for language in ("zh", "en", "ja", "ko", "es", "de", "fr", "no", "nl", "it"):
        li_body = pages["li-wenliang"].select_one(f'[data-language-body="{language}"]')
        li_source = li_body.select_one('li[data-source-id="s3"]') if li_body else None
        if li_source is None or li_source.get("data-source-type") != "independent-media retrospective-report":
            issues.append(f"li-wenliang/{language}/s3: metadata type is not independent-media retrospective-report")

        falun_body = pages["falun-gong-persecution"].select_one(f'[data-language-body="{language}"]')
        timeline = falun_body.select_one('[data-fact-id="falun-gong-persecution-timeline-4"]') if falun_body else None
        source = falun_body.select_one('li[data-source-id="s3"]') if falun_body else None
        visible_date = timeline.find("b").get_text(" ", strip=True).rstrip(":： ") if timeline and timeline.find("b") else ""
        source_date = source.get("data-source-date", "") if source else ""
        if timeline is None or timeline.get("data-source-ref") != "s3":
            issues.append(f"falun-gong-persecution/{language}/timeline-4: source reference is not s3")
        if source_date != "2000-03-23" or visible_date != source_date:
            issues.append(
                f"falun-gong-persecution/{language}/timeline-4: visible date {visible_date!r} "
                f"does not match s3 date {source_date!r}"
            )
    return issues


def normalized_visible(node):
    return " ".join(node.get_text(" ", strip=True).split()) if node else ""


def final1_contiguous_stream(value):
    return re.sub(r"[\W_]+", "", (value or "").casefold(), flags=re.UNICODE)


def final1_longest_common_fragment(left, right):
    left_stream = final1_contiguous_stream(left)
    right_stream = final1_contiguous_stream(right)
    if not left_stream or not right_stream:
        return 0
    return difflib.SequenceMatcher(
        None, left_stream, right_stream, autojunk=False
    ).find_longest_match().size


def audit_page_heading_and_dek(soup: BeautifulSoup, slug: str):
    """Check the two public header fields independently of the body graph."""
    issues = []
    for language in CASE_ACTOR_TERMS[slug]:
        for selector, label, minimum in (
            (f"h1.article-title .lang-{language}", "title", 8),
            (f"p.article-dek .lang-{language}", "dek", 35),
        ):
            node = soup.select_one(selector)
            visible = normalized_visible(node)
            folded = visible.casefold()
            if not visible:
                issues.append(f"{slug}/{language}/{label}: public field missing")
                continue
            if len(visible) < minimum:
                issues.append(f"{slug}/{language}/{label}: public field is implausibly short")
            if not any(term.casefold() in folded for term in CASE_ACTOR_TERMS[slug][language]):
                issues.append(f"{slug}/{language}/{label}: case subject missing")
    return issues


def falun_dek_node(soup: BeautifulSoup, language: str):
    return soup.select_one(f"p.article-dek .lang-{language}")


def audit_falun_deks(soup: BeautifulSoup):
    """Audit factual/source-led Falun Gong deks without consulting editorial ledgers."""
    issues = []
    for language, spec in FALUN_LAST_DEK_RULES.items():
        node = falun_dek_node(soup, language)
        if node is None:
            issues.append(f"falun-gong-persecution/{language}/article-dek: target missing")
            continue
        visible = normalized_visible(node).casefold()
        for concept in spec["required"]:
            if concept.casefold() not in visible:
                issues.append(
                    f"falun-gong-persecution/{language}/article-dek: required concept missing: {concept}"
                )
        for phrase in spec["forbidden"]:
            if phrase.casefold() in visible:
                issues.append(
                    f"falun-gong-persecution/{language}/article-dek: rejected meta-subject present: {phrase}"
                )
    return issues


def audit_full_page_rule(soup: BeautifulSoup, slug: str, language: str, fact_id: str, expected_refs: str):
    """Audit one public fact through subject, content, source and legal/date channels."""
    node = target_node(soup, slug, language, fact_id)
    if node is None:
        return [f"{slug}/{language}/{fact_id}: final-page target missing"]

    issues = []
    visible = normalized_visible(node)
    folded = visible.casefold()
    if len(visible) < 20:
        issues.append(f"{slug}/{language}/{fact_id}: substantive public text missing")
    actor_required = fact_id.endswith(("overview-1", "rights-analysis", "protection", "-sources"))
    if actor_required and not any(term.casefold() in folded for term in CASE_ACTOR_TERMS[slug][language]):
        issues.append(f"{slug}/{language}/{fact_id}: case subject/authority channel missing")

    actual_refs = tuple(node.get("data-source-ref", "").split())
    wanted_refs = tuple(expected_refs.split())
    if actual_refs != wanted_refs:
        issues.append(
            f"{slug}/{language}/{fact_id}: source graph {actual_refs!r} does not match {wanted_refs!r}"
        )
    body = soup.select_one(f'[data-language-body="{language}"]')
    available_sources = {
        source.get("data-source-id", "") for source in body.select("li[data-source-id]")
    } if body else set()
    missing_sources = set(actual_refs) - available_sources
    if missing_sources:
        issues.append(f"{slug}/{language}/{fact_id}: unresolved sources {sorted(missing_sources)!r}")

    expected_date = FINAL4_PAGE_FACTS[slug]["dates"].get(fact_id)
    if expected_date:
        date_node = node.find("b")
        visible_date = normalized_visible(date_node or node).rstrip(":： ")
        if expected_date not in visible_date:
            issues.append(
                f"{slug}/{language}/{fact_id}: chronology {visible_date!r} omits {expected_date!r}"
            )
        for attribute in ("data-timeline-subject", "data-timeline-action", "data-timeline-consequence"):
            if not node.get(attribute, "").strip():
                issues.append(f"{slug}/{language}/{fact_id}: {attribute} semantic channel missing")
    elif fact_id.endswith(("rights-analysis", "protection")):
        if not any(term.casefold() in folded for term in REMEDY_TERMS[language]):
            issues.append(f"{slug}/{language}/{fact_id}: effective-remedy channel missing")

    if fact_id.endswith("-sources"):
        actual_source_ids = tuple(source.get("data-source-id", "") for source in node.select("li[data-source-id]"))
        expected_source_ids = FINAL4_PAGE_FACTS[slug]["source_ids"]
        if actual_source_ids != expected_source_ids:
            issues.append(
                f"{slug}/{language}/{fact_id}: visible source order {actual_source_ids!r} "
                f"does not match {expected_source_ids!r}"
            )
        for source in node.select("li[data-source-id]"):
            for attribute in ("data-source-type", "data-source-date"):
                if not source.get(attribute, "").strip():
                    issues.append(
                        f"{slug}/{language}/{fact_id}/{source.get('data-source-id')}: {attribute} missing"
                    )
            anchor = source.find("a", href=True)
            if anchor is None or not normalized_visible(anchor):
                issues.append(
                    f"{slug}/{language}/{fact_id}/{source.get('data-source-id')}: visible source title/link missing"
                )
    return issues


def audit_bad_phrase_scan(pages):
    issues = []
    for slug, language, target, phrase in FINAL4_BAD_PHRASES:
        if target.startswith("source-title:"):
            node = source_node(pages[slug], language, target.split(":", 1)[1], "title")
        else:
            node = target_node(pages[slug], slug, language, target)
        if node is None:
            issues.append(f"{slug}/{language}/{target}: scan target missing")
        elif phrase.casefold() in normalized_visible(node).casefold():
            issues.append(f"{slug}/{language}/{target}: rejected final-page phrase present: {phrase}")

    # These are editorial instructions, not publishable case prose.
    directive_phrases = (
        "cannot be recast", "cannot be rewritten", "the two cannot be confused",
        "不能被重寫", "不能被改寫", "兩者不能混同", "應理解為", "應區分",
    )
    for slug in FINAL4_PAGE_FACTS:
        for language in CASE_ACTOR_TERMS[slug]:
            body = pages[slug].select_one(f'[data-language-body="{language}"]')
            visible = normalized_visible(body).casefold()
            for phrase in directive_phrases:
                if phrase.casefold() in visible:
                    issues.append(f"{slug}/{language}: editorial directive leaked into public text: {phrase}")
    return issues


def audit_final4_source_entry(soup: BeautifulSoup, slug: str, language: str, source_id: str):
    """Audit one visible category/title pair without using the editorial ledgers."""
    body = soup.select_one(f'[data-language-body="{language}"]')
    source = body.select_one(f'li[data-source-id="{source_id}"]') if body else None
    if source is None:
        return [f"{slug}/{language}/{source_id}: final-page source entry missing"]
    issues = []
    category = normalized_visible(source.find("b"))
    title = normalized_visible(source.find("a"))
    if len(category) < 3:
        issues.append(f"{slug}/{language}/{source_id}: visible source category missing")
    if len(title) < 12:
        issues.append(f"{slug}/{language}/{source_id}: visible source title missing")
    if not source.find("a", href=True):
        issues.append(f"{slug}/{language}/{source_id}: external source link missing")
    return issues


def audit_final4_pages(pages):
    issues = []
    for slug in FINAL4_LEGACY_SLUGS:
        page_spec = FINAL4_PAGE_FACTS[slug]
        soup = pages[slug]
        issues.extend(audit_page_heading_and_dek(soup, slug))
        expected_ids = tuple(page_spec["facts"])
        for language in CASE_ACTOR_TERMS[slug]:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"{slug}/{language}: language body missing")
                continue
            actual_ids = tuple(node.get("data-fact-id", "") for node in body.select("[data-fact-id]"))
            if actual_ids != expected_ids:
                issues.append(
                    f"{slug}/{language}: public fact graph {actual_ids!r} does not match {expected_ids!r}"
                )
            for fact_id, refs in page_spec["facts"].items():
                issues.extend(audit_full_page_rule(soup, slug, language, fact_id, refs))
            for source_id in page_spec["source_ids"]:
                issues.extend(audit_final4_source_entry(soup, slug, language, source_id))
    issues.extend(audit_bad_phrase_scan(pages))
    return issues


def parse_falun_card_fields():
    script_text = (ROOT / "script.js").read_text(encoding="utf-8")
    match = re.search(
        r'\{\s*title_zh:\s*"法輪功受迫害：.*?url:\s*"posts/falun-gong-persecution\.html"\s*\}',
        script_text,
        re.DOTALL,
    )
    if not match:
        return {}, ["script.js/Falun Gong card: object missing"]
    fields = {}
    for field, language, raw_value in re.findall(
        r'\b(title|excerpt)_(zh|en|ja|ko|es|de|fr|no|nl|it):\s*("(?:\\.|[^"\\])*")',
        match.group(0),
    ):
        fields[f"{field}_{language}"] = json.loads(raw_value)
    expected_keys = {
        f"{field}_{language}"
        for language in FALUN_CARD_RULES
        for field in ("title", "excerpt")
    }
    issues = []
    if set(fields) != expected_keys:
        issues.append(
            f"script.js/Falun Gong card: fields {sorted(fields)!r} do not match {sorted(expected_keys)!r}"
        )
    return fields, issues


def audit_falun_card(fields):
    issues = []
    for language, spec in FALUN_CARD_RULES.items():
        # These rules describe the evidentiary and chronology chain carried by the
        # excerpt.  Do not let a coincidental word in the title mask a deletion
        # from that chain (for example Korean "구금").
        visible = fields.get(f"excerpt_{language}", "").casefold()
        for concept in spec["required"]:
            if concept.casefold() not in visible:
                issues.append(f"script.js/Falun Gong card/{language}: required concept missing: {concept}")
        for phrase in spec["forbidden"]:
            if phrase.casefold() in visible:
                issues.append(f"script.js/Falun Gong card/{language}: rejected meta-subject present: {phrase}")
    return issues


def parse_ai_card_fields():
    script_text = (ROOT / "script.js").read_text(encoding="utf-8")
