def audit_batch7_cards(cards):
    issues = []
    expected = {f"{field}_{language}" for field in ("title", "excerpt") for language in BATCH5_LANGS}
    for slug in BATCH7_SLUGS:
        card = cards.get(slug)
        if card is None or set(card.get("fields", {})) != expected:
            issues.append(f"script.js/{slug}: batch-seven card missing or language fields incomplete")
            continue
        for field, value in card["fields"].items():
            short_language = field.endswith(("_zh", "_ja", "_ko"))
            if len(value) < (10 if field.startswith("title_") else (20 if short_language else 30)):
                issues.append(f"script.js/{slug}/{field}: card fact chain too short")
            for phrase in BATCH7_FORBIDDEN + BATCH7_CARD_FORBIDDEN:
                if phrase.casefold() in value.casefold():
                    issues.append(f"script.js/{slug}/{field}: rejected phrase present: {phrase}")
            for phrase in BATCH7_CARD_FIELD_FORBIDDEN.get((slug, field), ()):
                if phrase.casefold() in value.casefold():
                    issues.append(f"script.js/{slug}/{field}: rejected field-specific phrase present: {phrase}")
    for (slug, field), concepts in BATCH7_CARD_REQUIRED.items():
        visible = cards.get(slug, {}).get("fields", {}).get(field, "")
        for concept in concepts:
            if concept.casefold() not in visible.casefold():
                issues.append(f"script.js/{slug}/{field}: required card concept missing: {concept}")
    return issues


