def batch8_target_node(soup, language, target_id):
    if target_id == "article-title":
        return soup.select_one(f".article-title .lang-{language}")
    body = soup.select_one(f'[data-language-body="{language}"]')
    return body.select_one(f'[data-fact-id="{target_id}"]') if body else None


def audit_batch8_pages(pages):
    issues = []
    for slug in BATCH8_SLUGS:
        soup = pages[slug]
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            title = soup.select_one(f'.article-title .lang-{language}')
            dek = soup.select_one(f'.article-dek .lang-{language}')
            if body is None or len(normalized_visible(title)) < 8 or len(normalized_visible(dek)) < 30:
                issues.append(f"{slug}/{language}: batch-eight title, deck, or body missing")
                continue
            facts = [node for node in body.select('[data-fact-id]') if not node.select_one('[data-fact-id]') and not node.get('data-fact-id', '').endswith('-sources')]
            if len(facts) != BATCH8_FACT_COUNTS[slug]:
                issues.append(f"{slug}/{language}: batch-eight public fact count changed")
            sources = tuple((node.get('data-source-id', ''), node.get('data-source-type', ''), node.get('data-source-date', '')) for node in body.select('li[data-source-id]'))
            if sources != BATCH8_SOURCE_SIGNATURES[slug]:
                issues.append(f"{slug}/{language}: batch-eight source id/type/date/order signature changed")
            source_ids = {source_id for source_id, _kind, _date in sources}
            for fact in facts:
                refs = tuple(fact.get('data-source-ref', '').split())
                if not refs or set(refs) - source_ids:
                    issues.append(f"{slug}/{language}/{fact.get('data-fact-id')}: source attribution missing or unresolved")
            for suffix in ("rights-analysis", "protection"):
                node = body.select_one(f'[data-fact-id="{slug}-{suffix}"]')
                if node is None or len(normalized_visible(node)) < 110:
                    issues.append(f"{slug}/{language}/{suffix}: actor/action/consequence/remedy chain missing")
            folded = normalized_visible(body).casefold()
            for phrase in BATCH8_FORBIDDEN:
                if phrase.casefold() in folded:
                    issues.append(f"{slug}/{language}: rejected batch-eight phrase present: {phrase}")
    for (slug, language, target_id), required in BATCH8_DEEP_RULES.items():
        node = batch8_target_node(pages[slug], language, target_id)
        visible = normalized_visible(node)
        if node is None:
            issues.append(f"{slug}/{language}/{target_id}: batch-eight deep target missing")
            continue
        for concept in required:
            if concept.casefold() not in visible.casefold():
                    issues.append(f"{slug}/{language}/{target_id}: required independent concept missing: {concept}")
    return issues


def batch8_final_target_node(soup, language, target_id):
    """Return a final-review target without consulting either editorial TSV."""
    if target_id == "article-title":
        return soup.select_one(f".article-title .lang-{language}")
    if target_id == "article-dek":
        return soup.select_one(f".article-dek .lang-{language}")
    if target_id.startswith("source-title:"):
        return source_node(soup, language, target_id.split(":", 1)[1], "title")
    return batch8_target_node(soup, language, target_id)


def audit_batch8_final_rule(soup, slug, language, target_id, spec):
    """Audit one hard-coded final-review target through the public DOM."""
    node = batch8_final_target_node(soup, language, target_id)
    if node is None:
        return [f"{slug}/{language}/{target_id}: batch-eight final-review target missing"]
    visible = normalized_visible(node)
    folded = visible.casefold()
    issues = []
    for concept in spec["required"]:
        if concept.casefold() not in folded:
            issues.append(
                f"{slug}/{language}/{target_id}: final-review concept missing: {concept}"
            )
    for phrase in spec["forbidden"]:
        if phrase.casefold() in folded:
            issues.append(
                f"{slug}/{language}/{target_id}: final-review rejected phrase present: {phrase}"
            )
    return issues


def normalized_hxw_semantic(value):
    """Normalize Unicode and invisible separators for final2 semantic checks."""
    value = unicodedata.normalize("NFKC", value or "")
    value = re.sub(r"[\u200b-\u200f\u2060\ufeff]", "", value)
    return " ".join(value.split())


def audit_batch8_hxw_final2(soup):
    """Audit all 20 Huang/Wang final2 nodes, including semantic attributes."""
    slug = "huang-xueqin-wang-jianbing"
    issues = []
    expected_refs = ("hxw-s1", "hxw-s2", "hxw-s3", "hxw-s4")
    for (language, target_id), spec in BATCH8_HXW_FINAL2_RULES.items():
        prefix = f"{slug}/{language}/{target_id}:"
        body = soup.select_one(f'[data-language-body="{language}"]')
        nodes = body.select(f'[data-fact-id="{target_id}"]') if body else []
        if len(nodes) != 1:
            issues.append(f"{prefix} expected exactly one public target, found {len(nodes)}")
            continue
        node = nodes[0]
        spans = node.find_all("span", attrs={"data-critical-case": True}, recursive=False)
        if len(spans) != 1:
            issues.append(f"{prefix} expected exactly one direct data-critical-case span, found {len(spans)}")
            continue
        span = spans[0]
        visible = normalized_hxw_semantic(span.get_text(" ", strip=True))
        critical_case = normalized_hxw_semantic(span.get("data-critical-case", ""))
        folded_visible = visible.casefold()
        folded_case = critical_case.casefold()
        if not critical_case or not visible.startswith(critical_case):
            issues.append(f"{prefix} data-critical-case is not an exact visible-text prefix")
        for concept in spec["required"]:
            if normalized_hxw_semantic(concept).casefold() not in folded_visible:
                issues.append(f"{prefix} final2 visible concept missing: {concept}")
        for concept in spec["case_required"]:
            if normalized_hxw_semantic(concept).casefold() not in folded_case:
                issues.append(f"{prefix} final2 data-critical-case concept missing: {concept}")
        for phrase in BATCH8_HXW_FINAL2_FORBIDDEN:
            folded_phrase = normalized_hxw_semantic(phrase).casefold()
            if folded_phrase in folded_visible:
                issues.append(f"{prefix} final2 rejected visible phrase present: {phrase}")
            if folded_phrase in folded_case:
                issues.append(f"{prefix} final2 rejected data-critical-case phrase present: {phrase}")
        expected_anchor = (
            "subject state-action second-harm conclusion"
            if target_id.endswith("rights-analysis")
            else "subject state-action pressure-path remedy-responsibility"
        )
        if span.get("data-critical-anchor", "") != expected_anchor:
            issues.append(
                f"{prefix} data-critical-anchor differs from {expected_anchor!r}"
            )
        refs = tuple(node.get("data-source-ref", "").split())
        if refs != expected_refs:
            issues.append(
                f"{prefix} data-source-ref must be exactly {expected_refs!r}, found {refs!r}"
            )
    return issues


def audit_batch8_final3(pages):
    """Audit the final3 evidence and timeline repairs without consulting TSV answers."""
    issues = []
    hxw_slug = "huang-xueqin-wang-jianbing"
    causeway_slug = "causeway-bay-books"
    hxw = pages[hxw_slug]
    causeway = pages[causeway_slug]
    for language, spec in BATCH8_FINAL3_HXW_RULES.items():
        prefix = f"{hxw_slug}/{language}/{BATCH8_FINAL3_HXW_TARGET}:"
        body = hxw.select_one(f'[data-language-body="{language}"]')
        nodes = body.select(f'[data-fact-id="{BATCH8_FINAL3_HXW_TARGET}"]') if body else []
        if len(nodes) != 1:
            issues.append(f"{prefix} expected exactly one public target, found {len(nodes)}")
            continue
        node = nodes[0]
        issues.extend(audit_batch8_final_rule(
            hxw, hxw_slug, language, BATCH8_FINAL3_HXW_TARGET, spec,
        ))
        for attribute, expected in BATCH8_FINAL3_HXW_ATTRS.items():
            if node.get(attribute, "") != expected:
                issues.append(
                    f"{prefix} final3 {attribute} differs from {expected!r}"
                )

    for language, spec in BATCH8_FINAL3_CAUSEWAY_RULES.items():
        prefix = f"{causeway_slug}/{language}/{BATCH8_FINAL3_CAUSEWAY_TARGET}:"
        body = causeway.select_one(f'[data-language-body="{language}"]')
        nodes = body.select(f'[data-fact-id="{BATCH8_FINAL3_CAUSEWAY_TARGET}"]') if body else []
        if len(nodes) != 1:
            issues.append(f"{prefix} expected exactly one public target, found {len(nodes)}")
            continue
        node = nodes[0]
        issues.extend(audit_batch8_final_rule(
            causeway, causeway_slug, language, BATCH8_FINAL3_CAUSEWAY_TARGET, spec,
        ))
        date = node.find("b")
        if date is None or normalized_visible(date) != "2020-02-25：":
            issues.append(f"{prefix} final3 timeline date must remain 2020-02-25")
        for attribute, expected in BATCH8_FINAL3_CAUSEWAY_ATTRS.items():
            if node.get(attribute, "") != expected:
                issues.append(
                    f"{prefix} final3 {attribute} differs from {expected!r}"
                )
    return issues


def replace_final3_visible_fragment(node, old, new):
    """Replace one real text-node fragment while retaining tags and attributes."""
    if node is None:
        raise AssertionError("missing final3 mutation target")
    for text_node in node.find_all(string=True):
        value = str(text_node)
        if old in value:
            text_node.replace_with(value.replace(old, new))
            return
    raise AssertionError(f"final3 mutation source absent: {old}")


def final3_mutation_caught(pages, slug, language, target_id):
    prefix = f"{slug}/{language}/{target_id}:"
    return any(issue.startswith(prefix) for issue in audit_batch8_final3(pages))


def mutate_hxw_final2_text(soup, language, target_id, old, new, sync_case):
    """Replace one real span fragment while preserving its semantic attributes."""
    node = batch8_final_target_node(soup, language, target_id)
    span = node.find("span", attrs={"data-critical-case": True}, recursive=False) if node else None
    if span is None:
        raise AssertionError(f"missing final2 mutation target: {language}/{target_id}")
    visible = span.get_text()
    if old not in visible:
        raise AssertionError(f"mutation source absent: {language}/{target_id}/{old}")
    span.clear()
    span.append(visible.replace(old, new, 1))
    if sync_case:
        critical_case = span.get("data-critical-case", "")
        if old not in critical_case:
            raise AssertionError(
                f"mutation source absent from data-critical-case: {language}/{target_id}/{old}"
            )
        span["data-critical-case"] = critical_case.replace(old, new, 1)


def hxw_final2_mutation_caught(soup, language, target_id):
    prefix = f"huang-xueqin-wang-jianbing/{language}/{target_id}:"
    return any(
        issue.startswith(prefix) for issue in audit_batch8_hxw_final2(soup)
    )


def audit_batch8_final_followup(pages):
    """Audit the three-page final-review additions against independent rules."""
    issues = []
    causeway = pages["causeway-bay-books"]
    for (language, target_id), spec in BATCH8_CAUSEWAY_FINAL_RULES.items():
        issues.extend(audit_batch8_final_rule(
            causeway, "causeway-bay-books", language, target_id, spec,
        ))
    for language in BATCH5_LANGS:
        issues.extend(audit_batch8_final_rule(
            causeway, "causeway-bay-books", language, "source-title:s1",
            BATCH8_CAUSEWAY_SOURCE_TITLE_RULE,
        ))
        for target_id in (
            "causeway-bay-books-evidence-official-gap",
            "causeway-bay-books-rights-analysis",
        ):
            node = batch8_final_target_node(causeway, language, target_id)
            refs = tuple(node.get("data-source-ref", "").split()) if node else ()
            if refs != ("s1", "s2", "s3"):
                issues.append(
                    f"causeway-bay-books/{language}/{target_id}: final-review source roles "
                    f"must be exactly ('s1', 's2', 's3'), found {refs!r}"
                )
    causeway_visible = normalized_visible(causeway).casefold()
    for phrase in BATCH8_CAUSEWAY_FINAL_FORBIDDEN:
        if phrase.casefold() in causeway_visible:
            issues.append(
                f"causeway-bay-books: final-review rejected page phrase present: {phrase}"
            )
    for language, spec in BATCH8_DONG_FINAL_DEK_RULES.items():
        issues.extend(audit_batch8_final_rule(
            pages["dong-yaoqiong-ink-protest"], "dong-yaoqiong-ink-protest",
            language, "article-dek", spec,
        ))
    for language, spec in BATCH8_HUANG_FINAL_DEK_RULES.items():
        issues.extend(audit_batch8_final_rule(
            pages["huang-xueqin-wang-jianbing"], "huang-xueqin-wang-jianbing",
            language, "article-dek", spec,
        ))
    issues.extend(audit_batch8_hxw_final2(pages["huang-xueqin-wang-jianbing"]))
    issues.extend(audit_batch8_final3(pages))
    return issues


def batch8_card_objects(script_text=None):
    text = script_text if script_text is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards = {}
    for slug in BATCH8_SLUGS:
        match = re.search(rf'url\s*:\s*"posts/{re.escape(slug)}\.html"', text)
        if not match:
            continue
        start, end = text.rfind("{", 0, match.start()), text.find("}", match.end())
        obj = text[start:end + 1]
        fields = {f"{field}_{language}": json.loads(raw) for field, language, raw in re.findall(r'\b(title|excerpt)_(zh|en|ja|ko|es|de|fr|no|nl|it):\s*("(?:\\.|[^"\\])*")', obj)}
        cards[slug] = fields
    return cards


BATCH8_CARD_REQUIRED = {
    ("causeway-bay-books", "excerpt_en"): ("five booksellers", "across borders", "publishing"),
    ("causeway-bay-books", "excerpt_ko"): ("서점 관계자", "구이민하이", "출판"),
    ("chen-guangcheng", "excerpt_en"): ("forced abortion", "intentional property damage", "traffic"),
    ("chen-guangcheng", "excerpt_de"): ("erzwungener Abtreibungen", "Sachbeschädigung", "Verkehr"),
    ("hk-12", "title_ja"): ("中国海警", "拿捕"),
    ("hk-12", "title_ko"): ("중국 해경", "해상 나포"),
    ("hk-12", "excerpt_it"): ("guardia costiera", "avvocati scelti dalle famiglie", "consegne a Hong Kong"),
}


def audit_batch8_cards(cards):
    issues = []
    expected = {f"{field}_{language}" for field in ("title", "excerpt") for language in BATCH5_LANGS}
    for slug in BATCH8_SLUGS:
        fields = cards.get(slug)
        if fields is None or set(fields) != expected:
            issues.append(f"script.js/{slug}: batch-eight card missing or language fields incomplete")
            continue
        for field, value in fields.items():
            if len(value) < (7 if field.startswith("title_") else 20):
                issues.append(f"script.js/{slug}/{field}: batch-eight card field too short")
            for phrase in BATCH8_FORBIDDEN:
                if phrase.casefold() in value.casefold():
                    issues.append(f"script.js/{slug}/{field}: rejected batch-eight phrase present: {phrase}")
    for (slug, field), required in BATCH8_CARD_REQUIRED.items():
        value = cards.get(slug, {}).get(field, "")
        for concept in required:
            if concept.casefold() not in value.casefold():
                issues.append(f"script.js/{slug}/{field}: required batch-eight card concept missing: {concept}")
    return issues


