def batch11_final1_prefix_payload(path, data_rows):
    """Return header plus an authenticated number of complete TSV rows."""
    lines = path.read_bytes().splitlines(keepends=True)
    return b"".join(lines[:data_rows + 1])


def batch11_final1_source_date_successor(payload=None):
    """Validate and split the sole authorized HK12/s6 source-date append."""
    path = ROOT / "tools/data/source-date-ledger.tsv"
    if payload is None:
        if not path.exists():
            return None, ["batch11-final1 source-date ledger missing"]
        payload = batch14_source_date_prefix_bytes()
    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError:
        return None, ["batch11-final1 source-date ledger is not UTF-8"]
    reader = csv.DictReader(io.StringIO(text), delimiter="\t")
    rows = list(reader)
    issues = []
    if tuple(reader.fieldnames or ()) != BATCH10_FINAL3_SOURCE_DATE_COLUMNS:
        issues.append("batch11-final1 source-date columns or order changed")
    if len(rows) != BATCH11_FINAL1_SOURCE_DATE_ROWS + 1:
        issues.append(
            "batch11-final1 source-date ledger must be the 293-row prefix plus HK12/s6"
        )
    # Derive the prefix from the payload under review so an in-memory mutation
    # cannot borrow the on-disk prefix and evade a negative test.
    prefix = b"".join(payload.splitlines(keepends=True)[:BATCH11_FINAL1_SOURCE_DATE_ROWS + 1])
    if hashlib.sha256(prefix).hexdigest() != BATCH11_FINAL1_SOURCE_DATE_SHA256:
        issues.append("batch11-final1 source-date 293-row prefix was rewritten")
    expected = {
        "slug": "hk-12",
        "source_id": "s6",
        "source_type": "independent-media overseas-media transfer-report",
        "url": "https://hongkongfp.com/2021/03/22/eight-hongkongers-return-from-china-after-7-months-in-jail-for-illegal-border-crossing/",
        "audited_date": "2021-03-22",
        "precision": "day",
        "verification_status": "VERIFIED_SOURCE_DATE",
        "accessed_at": "2026-07-22",
    }
    row = rows[-1] if rows else {}
    for field, value in expected.items():
        if row.get(field, "") != value:
            issues.append(f"batch11-final1 HK12/s6 source-date {field} differs")
    if "八" not in row.get("note", "") or "七個月" not in row.get("note", ""):
        issues.append("batch11-final1 HK12/s6 note lacks eight-person/seven-month facts")
    if "移交香港" not in row.get("note", "") or "警方" not in row.get("note", ""):
        issues.append("batch11-final1 HK12/s6 note lacks transfer/police role")
    locator = row.get("evidence_locator", "")
    if not all(marker in locator for marker in ("Eight Hongkongers", "18:48", "22 March 2021")):
        issues.append("batch11-final1 HK12/s6 locator lacks persisted headline/time evidence")
    if not row.get("title_zh", "").strip():
        issues.append("batch11-final1 HK12/s6 source-date title is blank")
    return prefix, issues


def batch11_final1_is_desktop_extra(relative, payload):
    expected = BATCH11_FINAL1_DESKTOP_EXTRAS.get(relative)
    return bool(expected and hashlib.sha256(payload).hexdigest() == expected)

