def audit_batch10_source_visible_contracts(pages):
    """Validate source labels/titles against literals, never live-derived data."""
    issues = []
    for (slug, source_id), spec in BATCH10_SOURCE_VISIBLE_CONTRACTS.items():
        soup = pages[slug]
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            nodes = body.select(f'ul.source-list > li[data-source-id="{source_id}"]') if body else []
            if len(nodes) != 1:
                issues.append(f"{slug}/{language}/{source_id}: expected exactly one contracted visible source row")
                continue
            node = nodes[0]
            expected_type = spec.get("source_type")
            if expected_type is not None and node.get("data-source-type", "") != expected_type:
                issues.append(f"{slug}/{language}/{source_id}: contracted source type differs")
            label = node.find("b")
            actual_label = normalized_visible(label)
            if actual_label != spec["labels"][language]:
                issues.append(f"{slug}/{language}/{source_id}: visible source role label differs from static contract")
            expected_titles = spec.get("titles")
            if expected_titles is not None:
                actual_title = normalized_visible(node.find("a"))
                if actual_title != expected_titles[language]:
                    issues.append(f"{slug}/{language}/{source_id}: visible source title differs from static contract")
    return issues


def batch10_tian_s8_japanese_source_mutation_caught(pages):
    """Prove the static contract rejects Japanese text in Tian's English s8 row."""
    mutated_pages = dict(pages)
    mutated_pages["tiananmen-1989"] = deepcopy(pages["tiananmen-1989"])
    row = mutated_pages["tiananmen-1989"].select_one(
        '[data-language-body="en"] li[data-source-id="s8"]'
    )
    label = row.find("b") if row else None
    title = row.find("a") if row else None
    if not label or not title:
        return False
    label.clear()
    label.append("人権団体の特集")
    title.clear()
    title.append("Amnesty International — 天安門事件から30年：中国に刻まれた消えない汚点")
    issues = audit_batch10_source_visible_contracts(mutated_pages)
    return any(
        issue == "tiananmen-1989/en/s8: visible source role label differs from static contract"
        for issue in issues
    ) and any(
        issue == "tiananmen-1989/en/s8: visible source title differs from static contract"
        for issue in issues
    )


def batch10_glf_s6_generic_source_mutation_caught(pages):
    """Prove a generic historical-source label cannot replace the reviewed role."""
    mutated_pages = dict(pages)
    mutated_pages["great-leap-famine"] = deepcopy(pages["great-leap-famine"])
    row = mutated_pages["great-leap-famine"].select_one(
        '[data-language-body="en"] li[data-source-id="s6"]'
    )
    label = row.find("b") if row else None
    if not label:
        return False
    label.clear()
    label.append("Historical archive and academic synthesis")
    issues = audit_batch10_source_visible_contracts(mutated_pages)
    return any(
        issue == "great-leap-famine/en/s6: visible source role label differs from static contract"
        for issue in issues
    )
