def batch9_card_objects(script_text=None):
    text = script_text if script_text is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards = {}
    for slug in BATCH9_SLUGS:
        match = re.search(rf'url\s*:\s*"posts/{re.escape(slug)}\.html"', text)
        if not match:
            continue
        start, end = text.rfind("{", 0, match.start()), text.find("}", match.end())
        if start < 0 or end < 0:
            continue
        obj = text[start:end + 1]
        fields = {
            f"{field}_{language}": json.loads(raw)
            for field, language, raw in re.findall(
                r'\b(title|excerpt)_(zh|en|ja|ko|es|de|fr|no|nl|it):\s*("(?:\\.|[^"\\])*")',
                obj,
            )
        }
        cards[slug] = fields
    return cards


def batch9_final2_report_cards(script_text=None):
    """Parse all literal report-card fields in source order for delta replay."""
    text = script_text if script_text is not None else (ROOT / "script.js").read_text(encoding="utf-8")
    cards = []
    issues = []
    pattern = re.compile(r'\{[^{}]*?url:\s*"posts/([^"]+)"[^{}]*?\}', re.S)
    for match in pattern.finditer(text):
        filename = match.group(1)
        block = match.group(0)
        card = {"slug": filename.removesuffix(".html")}
        for field in BATCH9_FINAL2_CARD_FIELDS[1:]:
            field_match = re.search(rf'{re.escape(field)}:\s*"([^"]*)"', block)
            if field_match is None:
                issues.append(f"script.js/{card['slug']}: final2 card field missing: {field}")
                card[field] = ""
            else:
                card[field] = field_match.group(1)
        cards.append(card)
    if len(cards) != 64:
        issues.append(f"script.js: final2 card inventory is {len(cards)}, expected 64")
    # Historical gates compare against the 54-card batch-nine capture; the ten
    # batch-14 cards are removed for them by batch14_baseline_card_view.
    slugs = [card.get("slug", "") for card in cards]
    if not all(slugs) or len(slugs) != len(set(slugs)):
        issues.append("script.js: final2 card slugs are blank or duplicated")
    return cards, issues


def audit_batch9_final2_semantics(pages, cards=None):
    """Apply only independent, handwritten final2 meanings to live content."""
    issues = []
    rule_keys = {
        (slug, language, "fact", target_id)
        for slug, language, target_id in BATCH9_FINAL2_SEMANTIC_RULES
    }
    if rule_keys != BATCH9_FINAL2_TARGETS:
        issues.append("independent final2 semantic-rule inventory is not the exact 23-key repair set")
    for (slug, language, target_id), rule in BATCH9_FINAL2_SEMANTIC_RULES.items():
        soup = pages.get(slug)
        body = soup.select_one(f'[data-language-body="{language}"]') if soup else None
        node = body.select_one(f'[data-fact-id="{target_id}"]') if body else None
        if node is None:
            issues.append(f"{slug}/{language}/{target_id}: independent final2 target missing")
            continue
        visible = normalized_visible(node)
        folded = visible.casefold()
        for phrase in rule["required"]:
            if phrase.casefold() not in folded:
                issues.append(
                    f"{slug}/{language}/{target_id}: independent final2 concept missing: {phrase}"
                )
        for phrase in rule["forbidden"]:
            if phrase.casefold() in folded:
                issues.append(
                    f"{slug}/{language}/{target_id}: independent final2 regression present: {phrase}"
                )

        key = (slug, language, "fact", target_id)
        if key in BATCH9_FINAL2_CRITICAL_TARGETS:
            critical = node.select("[data-critical-case]")
            if len(critical) != 1:
                issues.append(
                    f"{slug}/{language}/{target_id}: final2 requires exactly one data-critical-case"
                )
                continue
            anchor = " ".join(critical[0].get("data-critical-case", "").split())
            critical_visible = normalized_visible(critical[0])
            terminators = [
                critical_visible.find(mark)
                for mark in ".!?。！？"
                if critical_visible.find(mark) >= 0
            ]
            first_sentence = (
                critical_visible[:min(terminators) + 1] if terminators else critical_visible
            )
            if not anchor or anchor != first_sentence:
                issues.append(
                    f"{slug}/{language}/{target_id}: data-critical-case differs from the visible first sentence"
                )
            if anchor and anchor[-1] not in ".!?。！？":
                issues.append(
                    f"{slug}/{language}/{target_id}: data-critical-case is not a complete first sentence"
                )

    current_cards = cards if cards is not None else batch9_card_objects()
    for (slug, field), rule in BATCH9_FINAL2_CARD_RULES.items():
        value = current_cards.get(slug, {}).get(field, "")
        if not value:
            issues.append(f"script.js/{slug}/{field}: independent final2 card field missing")
            continue
        folded = value.casefold()
        for phrase in rule["required"]:
            if phrase.casefold() not in folded:
                issues.append(f"script.js/{slug}/{field}: final2 card concept missing: {phrase}")
        for phrase in rule["forbidden"]:
            if phrase.casefold() in folded:
                issues.append(f"script.js/{slug}/{field}: final2 card regression present: {phrase}")
    return issues


def audit_batch9_cards(cards):
    """Audit the five cards against handwritten case semantics."""
    issues = []
    expected_fields = {
        f"{field}_{language}"
        for field in ("title", "excerpt")
        for language in BATCH5_LANGS
    }
    for slug in BATCH9_SLUGS:
        fields = cards.get(slug)
        if fields is None or set(fields) != expected_fields:
            issues.append(f"script.js/{slug}: batch-nine card missing or language fields incomplete")
            continue
        for language in BATCH5_LANGS:
            title = fields[f"title_{language}"]
            excerpt = fields[f"excerpt_{language}"]
            combined = f"{title} {excerpt}"
            if len(title) < 7 or len(excerpt) < 60:
                issues.append(f"script.js/{slug}/{language}: batch-nine title or evidence chain too short")
            digits = compact_digits(combined)
            for number in BATCH9_CARD_REQUIRED_NUMBERS[slug]:
                if compact_digits(number) not in digits:
                    issues.append(f"script.js/{slug}/{language}: required card number missing: {number}")
            for anchor in BATCH9_CARD_LANGUAGE_ANCHORS.get(slug, {}).get(language, ()):
                if anchor.casefold() not in excerpt.casefold():
                    issues.append(f"script.js/{slug}/{language}: required card concept missing: {anchor}")
            if slug == "hong-kong-nsl":
                for phrase in BATCH9_HK_CARD_FUTURE[language]:
                    if phrase.casefold() in combined.casefold():
                        issues.append(f"script.js/{slug}/{language}: future-tense regression present: {phrase}")
            for phrase in BATCH9_FORBIDDEN:
                if phrase.casefold() in combined.casefold():
                    issues.append(f"script.js/{slug}/{language}: rejected batch-nine phrase present: {phrase}")
            for phrase in BATCH9_SLUG_FORBIDDEN[slug]:
                if phrase.casefold() in combined.casefold():
                    issues.append(f"script.js/{slug}/{language}: rejected case-specific phrase present: {phrase}")
            for pattern, label in BATCH9_ASSERTION_PATTERNS.get(slug, ()):
                if re.search(pattern, combined, flags=re.IGNORECASE):
                    issues.append(f"script.js/{slug}/{language}: rejected assertion present: {label}")
    return issues


def audit_batch9_pages(pages):
    """Audit batch-nine public DOM without consulting generated contracts."""
    issues = []
    for slug in BATCH9_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"{slug}: batch-nine page missing")
            continue
        article = soup.select_one("article")
        public_visible = normalized_visible(article).casefold()
        for phrase in BATCH9_FORBIDDEN:
            if phrase.casefold() in public_visible:
                issues.append(f"{slug}: rejected batch-nine public phrase present: {phrase}")
        for phrase in BATCH9_SLUG_FORBIDDEN[slug]:
            if phrase.casefold() in public_visible:
                issues.append(f"{slug}: rejected case-specific public phrase present: {phrase}")
        for pattern, label in BATCH9_ASSERTION_PATTERNS.get(slug, ()):
            if re.search(pattern, public_visible, flags=re.IGNORECASE):
                issues.append(f"{slug}: rejected factual assertion present: {label}")
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"{slug}/{language}: batch-nine language body missing")
                continue

            sections = tuple(node.get("data-section", "") for node in body.select("h2"))
            if sections != BATCH9_SECTION_ORDER:
                issues.append(
                    f"{slug}/{language}: seven-section order {sections!r} "
                    f"does not match {BATCH9_SECTION_ORDER!r}"
                )
            if any(len(normalized_visible(node)) < 4 for node in body.select("h2")):
                issues.append(f"{slug}/{language}: localized seven-section heading missing")

            terminal_facts = tuple(
                node.get("data-fact-id", "")
                for node in body.select("[data-fact-id]")
                if not node.select_one("[data-fact-id]")
                and not node.get("data-fact-id", "").endswith("-sources")
            )
            expected_facts = tuple(fact_id for fact_id, _section, _refs in BATCH9_FACT_SPECS[slug])
            if terminal_facts != expected_facts:
                issues.append(
                    f"{slug}/{language}: fact order/inventory {terminal_facts!r} "
                    f"does not match {expected_facts!r}"
                )

            available_sources = {
                source.get("data-source-id", "") for source in body.select("li[data-source-id]")
            }
            for fact_id, expected_section, expected_refs in BATCH9_FACT_SPECS[slug]:
                node = body.select_one(f'[data-fact-id="{fact_id}"]')
                if node is None:
                    issues.append(f"{slug}/{language}/{fact_id}: batch-nine fact missing")
                    continue
                actual_refs = tuple(node.get("data-source-ref", "").split())
                if actual_refs != expected_refs:
                    issues.append(
                        f"{slug}/{language}/{fact_id}: source refs {actual_refs!r} "
                        f"do not match {expected_refs!r}"
                    )
                if set(actual_refs) - available_sources:
                    issues.append(f"{slug}/{language}/{fact_id}: unresolved source reference")
                heading = node.find_previous("h2")
                actual_section = heading.get("data-section", "") if heading else ""
                if actual_section != expected_section:
                    issues.append(
                        f"{slug}/{language}/{fact_id}: section {actual_section!r} "
                        f"does not match {expected_section!r}"
                    )
                minimum_fact_length = 8 if language in {"zh", "ja", "ko"} else 25
                fact_visible = normalized_visible(node)
                if len(fact_visible) < minimum_fact_length:
                    issues.append(f"{slug}/{language}/{fact_id}: visible fact chain too short")
                fact_digits = compact_digits(fact_visible)
                for number in BATCH9_FACT_NUMBER_RULES[slug].get(fact_id, ()):
                    if compact_digits(number) not in fact_digits:
                        issues.append(
                            f"{slug}/{language}/{fact_id}: required fact-specific number missing: {number}"
                        )

            source_nodes = body.select("li[data-source-id]")
            signature = tuple(
                (
                    source.get("data-source-id", ""),
                    source.get("data-source-type", ""),
                    source.get("data-source-date", ""),
                    source.find("a", href=True).get("href", "")
                    if source.find("a", href=True) else "",
                )
                for source in source_nodes
            )
            if signature != BATCH9_SOURCE_SIGNATURES[slug]:
                issues.append(
                    f"{slug}/{language}: source id/type/date/URL/order signature changed"
                )
            for source, expected in zip(source_nodes, BATCH9_SOURCE_SIGNATURES[slug]):
                source_id, _kind, source_date, _url = expected
                source_time = source.find("time")
                if source_date:
                    if (
                        source_time is None
                        or source_time.get("datetime", "") != source_date
                        or normalized_visible(source_time) != source_date
                    ):
                        issues.append(
                            f"{slug}/{language}/{source_id}: visible and machine source date diverged"
                        )
                elif source_time is not None:
                    issues.append(f"{slug}/{language}/{source_id}: undated source gained a visible time")
                if not normalized_visible(source.find("b")) or not normalized_visible(source.find("a")):
                    issues.append(f"{slug}/{language}/{source_id}: localized source label/title missing")

            for fact_id, subject, action, consequence, date_numbers in BATCH9_TIMELINE_SPECS[slug]:
                node = body.select_one(f'[data-fact-id="{fact_id}"]')
                if node is None:
                    continue
                actual_metadata = (
                    node.get("data-timeline-subject", ""),
                    node.get("data-timeline-action", ""),
                    node.get("data-timeline-consequence", ""),
                )
                expected_metadata = (subject, action, consequence)
                if actual_metadata != expected_metadata:
                    issues.append(
                        f"{slug}/{language}/{fact_id}: timeline metadata {actual_metadata!r} "
                        f"does not match {expected_metadata!r}"
                    )
                timeline_visible = normalized_visible(node)
                visible_numbers = {
                    str(int(value)) for value in re.findall(r"\d+", timeline_visible)
                }
                for month_number, month_name in enumerate(
                    BATCH9_MONTH_NAMES.get(language, ()), start=1
                ):
                    if re.search(rf"(?<!\w){re.escape(month_name)}(?!\w)", timeline_visible, re.I):
                        visible_numbers.add(str(month_number))
                for value in date_numbers:
                    if str(int(value)) not in visible_numbers:
                        issues.append(
                            f"{slug}/{language}/{fact_id}: timeline date component missing: {value}"
                        )

            body_text = normalized_visible(body)
            body_digits = compact_digits(body_text)
            for number in BATCH9_BODY_REQUIRED_NUMBERS[slug]:
                if compact_digits(number) not in body_digits:
                    issues.append(f"{slug}/{language}: required visible case number missing: {number}")
            for anchor in BATCH9_LANGUAGE_ANCHORS[slug][language]:
                if anchor.casefold() not in body_text.casefold():
                    issues.append(f"{slug}/{language}: required localized concept missing: {anchor}")
            for suffix in ("rights-analysis", "protection"):
                node = body.select_one(f'[data-fact-id$="-{suffix}"]')
                if node is None or len(normalized_visible(node)) < 120:
                    issues.append(f"{slug}/{language}/{suffix}: responsibility/remedy chain missing")

    for (slug, language, fact_id), required in BATCH9_DEEP_RULES.items():
        body = pages[slug].select_one(f'[data-language-body="{language}"]')
        node = body.select_one(f'[data-fact-id="{fact_id}"]') if body else None
        visible = normalized_visible(node)
        if node is None:
            issues.append(f"{slug}/{language}/{fact_id}: batch-nine deep target missing")
            continue
        for phrase in required:
            if phrase.casefold() not in visible.casefold():
                issues.append(f"{slug}/{language}/{fact_id}: required deep concept missing: {phrase}")
    return issues


def batch9_dynamic_dom_targets(pages):
    """Enumerate the current review surface without a fixed target-ID list."""
    targets = {}
    issues = []
    for slug in BATCH9_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"{slug}: missing from dynamic batch-nine reread audit")
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"{slug}/{language}: no body for dynamic reread audit")
                continue
            source_ids = [
                node.get("data-source-id", "")
                for node in body.select("li[data-source-id]")
            ]
            localized = (
                ("article-title", soup.select_one(f".article-title .lang-{language}")),
                ("article-dek", soup.select_one(f".article-dek .lang-{language}")),
            )
            for target_id, node in localized:
                if node is None:
                    continue
                key = (slug, language, target_id)
                if key in targets:
                    issues.append(f"duplicate dynamic reread target: {'/'.join(key)}")
                targets[key] = {
                    "target_kind": target_id,
                    "text": " ".join(normalized_visible(node).split()),
                    "source_refs": "page-sources:" + " ".join(source_ids),
                }
            for node in body.select("[data-fact-id]"):
                if node.select_one("[data-fact-id]"):
                    continue
                target_id = node.get("data-fact-id", "")
                if not target_id or target_id.endswith("-sources"):
                    continue
                key = (slug, language, target_id)
                if key in targets:
                    issues.append(f"duplicate dynamic reread target: {'/'.join(key)}")
                targets[key] = {
                    "target_kind": "fact",
                    "text": " ".join(normalized_visible(node).split()),
                    "source_refs": node.get("data-source-ref", ""),
                }
            for source in body.select("li[data-source-id]"):
                source_id = source.get("data-source-id", "")
                anchor = source.find("a")
                if not source_id or anchor is None:
                    continue
                key = (slug, language, f"source-title:{source_id}")
                if key in targets:
                    issues.append(f"duplicate dynamic reread target: {'/'.join(key)}")
                targets[key] = {
                    "target_kind": "source-title",
                    "text": " ".join(normalized_visible(anchor).split()),
                    "source_refs": source_id,
                }
    if len(targets) != BATCH9_LIVE_TARGET_COUNT:
        issues.append(
            f"dynamic batch-nine DOM target count is {len(targets)}, expected {BATCH9_LIVE_TARGET_COUNT}"
        )
    return targets, issues


def load_batch9_reread_rows():
    if not BATCH9_REREAD_PATH.exists():
        return [], [f"missing reread ledger: {BATCH9_REREAD_PATH}"]
    with BATCH9_REREAD_PATH.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = set(reader.fieldnames or ())
    required = {
        "slug", "language", "target_id", "target_kind", "revised_text", "source_refs",
    }
    missing = required - fields
    return rows, ([f"reread ledger lacks fields: {sorted(missing)}"] if missing else [])


def batch9_final2_load_tsv(path, columns, label):
    if not path.exists():
        return [], [f"{label} missing: {path}"]
    with path.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    issues = []
    if fields != tuple(columns):
        issues.append(f"{label} columns or column order changed")
    return rows, issues


def batch9_final2_exact_prefix(path, row_count, expected_sha256, label):
    if not path.exists():
        return [f"{label} missing: {path}"]
    lines = path.read_bytes().splitlines(keepends=True)
    required_lines = row_count + 1
    if len(lines) < required_lines:
        return [
            f"{label} lost final1 history: found {max(0, len(lines) - 1)}, "
            f"need at least {row_count} rows"
        ]
    digest = hashlib.sha256(b"".join(lines[:required_lines])).hexdigest()
    return [] if digest == expected_sha256 else [f"{label} rewrote or reordered final1 history"]


def batch9_final2_freeze_issues():
    """Authenticate the 346-file pre-final2 snapshot and its frozen paths."""
    if not BATCH9_FINAL2_FREEZE_PATH.exists():
        return [f"final2 freeze baseline missing: {BATCH9_FINAL2_FREEZE_PATH}"]
    issues = []
    baseline_bytes = BATCH9_FINAL2_FREEZE_PATH.read_bytes()
    if hashlib.sha256(baseline_bytes).hexdigest() != BATCH9_FINAL2_FREEZE_SHA256:
        issues.append("final2 freeze baseline itself changed after capture")
    rows, load_issues = batch9_final2_load_tsv(
        BATCH9_FINAL2_FREEZE_PATH, ("relative_path", "sha256"), "final2 freeze baseline"
    )
    issues.extend(load_issues)
    expected = {}
    for row in rows:
        relative = row.get("relative_path", "")
        digest = row.get("sha256", "")
        if not relative or relative in expected:
            issues.append(f"final2 freeze baseline has blank or duplicate path: {relative!r}")
            continue
        if relative in BATCH9_FINAL2_MUTABLE_FILES or relative == ".git" or relative.startswith(".git/"):
            issues.append(f"final2 freeze baseline improperly contains mutable/git path: {relative}")
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            issues.append(f"final2 freeze baseline has invalid SHA-256: {relative}")
        expected[relative] = digest
    if len(expected) != 346 or ".DS_Store" not in expected or len(set(expected) - {".DS_Store"}) != 345:
        issues.append(
            "final2 freeze baseline must contain 346 files including .DS_Store "
            "(345 excluding .DS_Store)"
        )
    actual = {
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file()
        and ".git" not in path.relative_to(ROOT).parts
        and path.relative_to(ROOT).as_posix() not in (
            BATCH9_FINAL2_MUTABLE_FILES | BATCH10_ALLOWED_FILES
            | BATCH11_ALLOWED_FILES
        )
    }
    expected_paths = set(expected) - BATCH10_ALLOWED_FILES - BATCH11_ALLOWED_FILES
    if (ROOT / ".git").exists():
        for relative in sorted(expected_paths - actual):
            issues.append(f"final2 frozen file missing: {relative}")
        for relative in sorted(actual - expected_paths):
            issues.append(f"final2 file added outside whitelist: {relative}")
    for relative in sorted(actual & expected_paths):
        digest = hashlib.sha256((ROOT / relative).read_bytes()).hexdigest()
        if digest != expected[relative]:
            issues.append(f"final2 frozen file changed: {relative}")
    return issues


def audit_batch10_start_freeze():
    """Independently authenticate the one-time batch-ten file snapshot.

    Extra-path enforcement applies to the source Git worktree.  A non-Git
    Desktop delivery may have pre-existing extra files, but it must still carry
    every captured path and authenticate the baseline and protected contents.
    """
    if not BATCH10_START_FREEZE_PATH.exists():
        return ["batch10 start freeze is missing"]
    issues = []
    if hashlib.sha256(BATCH10_START_FREEZE_PATH.read_bytes()).hexdigest() != BATCH10_START_FREEZE_SHA256:
        issues.append("batch10 start freeze was regenerated or edited")
    rows, load_issues = batch9_final2_load_tsv(
        BATCH10_START_FREEZE_PATH,
        ("relative_path", "sha256", "scope"),
        "batch10 start freeze",
    )
    issues.extend(load_issues)
    expected = {}
    scopes = {}
    for row in rows:
        relative = row.get("relative_path", "")
        digest = row.get("sha256", "")
        scope = row.get("scope", "")
        if not relative or relative in expected:
            issues.append(f"batch10 start freeze blank/duplicate path: {relative!r}")
            continue
        if relative == ".DS_Store" or ".git" in Path(relative).parts:
            issues.append(f"batch10 start freeze contains excluded path: {relative}")
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            issues.append(f"batch10 start freeze has invalid digest: {relative}")
        expected[relative] = digest
        scopes[scope] = scopes.get(scope, 0) + 1
    expected_scopes = {
        "batch10-target-article": 8,
        "batch9-final2-captured;batch10-authorized-support": 6,
        "batch9-final2-frozen": 5,
        "non-target-article-frozen": 44,
        "non-target-file-frozen": 282,
        "public-page-frozen": 9,
        "runtime-frozen": 2,
    }
    if len(rows) != 356 or scopes != expected_scopes:
        issues.append("batch10 start freeze row or scope cardinality changed")
    allowed_new = {
        "tools/data/batch10-start-freeze-baseline.tsv",
        "tools/data/batch10-card-baseline.tsv",
        "tools/data/batch10-card-delta.tsv",
        "tools/data/batch10-final1-preimage.tsv",
    }
    actual = {
        path.relative_to(ROOT).as_posix()
        for path in ROOT.rglob("*")
        if path.is_file() and ".git" not in path.relative_to(ROOT).parts and path.name != ".DS_Store"
    }
    if (ROOT / ".git").exists():
        for relative in sorted(actual - set(expected) - allowed_new):
            issues.append(f"batch10 added a file outside its whitelist: {relative}")
    for relative in sorted(set(expected) - actual):
        issues.append(f"batch10 start-snapshot file missing: {relative}")
    for relative, digest in expected.items():
        if (
            relative in BATCH10_ALLOWED_FILES
            or relative in BATCH11_ALLOWED_FILES
            or relative not in actual
        ):
            continue
        if hashlib.sha256((ROOT / relative).read_bytes()).hexdigest() != digest:
            issues.append(f"batch10 protected file changed: {relative}")
    for relative in sorted(allowed_new - actual):
        issues.append(f"batch10 required ledger missing: {relative}")
    return issues


def audit_batch10_final2_frozen(overrides=None):
    """Authenticate files that final2 expressly freezes, including runtime UI."""
    # Replayed against the authenticated pre-batch13 bytes; an explicit
    # override still wins so the historical negative tests keep working.
    overrides = {
        **batch14_historical_bytes(),
        **batch13_historical_bytes(),
        **(overrides or {}),
    }
    issues = []
    for relative, expected in BATCH10_FINAL2_FROZEN_SHA256.items():
        path = ROOT / relative
        if not path.exists():
            issues.append(f"batch10-final2 frozen file missing: {relative}")
            continue
        payload = overrides.get(relative, path.read_bytes())
        if hashlib.sha256(payload).hexdigest() != expected:
            issues.append(f"batch10-final2 frozen file changed: {relative}")
    return issues


def audit_batch10_final2_structure(pages):
    """Verify frozen structure plus the three authorized timeline corrections.

    The source and fact digests cover stable DOM relationships, never revised
    prose.  For timeline graphs, the exact required final2 values are checked
    first and only those fields are restored to their authenticated preimage
    values for hashing.  The Liu/Tian dispute tuples remain separately written
    semantic rules.
    """
    issues = []
    for slug in BATCH10_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"{slug}: batch10-final2 structural page missing")
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"{slug}/{language}: batch10-final2 language body missing")
                continue
            sources = tuple(
                (
                    node.get("data-source-id", ""),
                    node.get("data-source-type", ""),
                    node.get("data-source-date", ""),
                    node.find("a").get("href", "") if node.find("a") else "",
                )
                for node in body.select("ul.source-list > li[data-source-id]")
            )
            source_payload = "\x1e".join(
                "\x1f".join(item) for item in sources
            ).encode("utf-8")
            if hashlib.sha256(source_payload).hexdigest() != (
                BATCH10_FINAL2_SOURCE_SIGNATURE_SHA256[slug]
            ):
                issues.append(
                    f"{slug}/{language}: source ID/type/date/URL/order differs "
                    "from the pre-final2 structure"
                )

            facts = []
            for node in body.select("[data-fact-id]"):
                if node.name in {"ol", "ul"} or node.select_one("[data-fact-id]"):
                    continue
                heading = node.find_previous("h2")
                facts.append(
                    (
                        node.get("data-fact-id", ""),
                        heading.get("data-section", "") if heading else "",
                        node.get("data-source-ref", ""),
                    )
                )
            fact_payload = "\x1e".join(
                "\x1f".join(item) for item in facts
            ).encode("utf-8")
            if hashlib.sha256(fact_payload).hexdigest() != (
                BATCH10_FINAL2_FACT_GRAPH_SHA256[slug]
            ):
                issues.append(
                    f"{slug}/{language}: fact IDs, section duties or source "
                    "relationships differ from the pre-final2 structure"
                )

            heading = body.select_one('h2[data-section="timeline"]')
            timeline_list = heading.find_next_sibling("ol") if heading else None
            timeline_nodes = (
                timeline_list.find_all("li", recursive=False)
                if timeline_list else []
            )
            timeline = tuple(
                (
                    node.get("data-fact-id", ""),
                    node.get("data-timeline-subject", ""),
                    node.get("data-timeline-action", ""),
                    node.get("data-timeline-consequence", ""),
                    node.get("data-source-ref", ""),
                )
                for node in timeline_nodes
            )
            hash_timeline = [list(item) for item in timeline]
            field_indexes = {"action": 2, "consequence": 3}
            authorized = BATCH10_FINAL2_AUTHORIZED_TIMELINE_EDITS.get(slug, {})
            by_id = {item[0]: item for item in hash_timeline}
            for fact_id, edits in authorized.items():
                item = by_id.get(fact_id)
                if item is None:
                    issues.append(
                        f"{slug}/{language}: authorized final2 timeline node missing: {fact_id}"
                    )
                    continue
                for field, (preimage_value, final2_value) in edits.items():
                    field_index = field_indexes[field]
                    if item[field_index] != final2_value:
                        issues.append(
                            f"{slug}/{language}/{fact_id}: final2 timeline {field} "
                            f"must equal {final2_value}"
                        )
                    # Restore only the expressly authorized field so the old
                    # whole-graph digest still authenticates everything else.
                    item[field_index] = preimage_value
            timeline_payload = "\x1e".join(
                "\x1f".join(item) for item in hash_timeline
            ).encode("utf-8")
            if hashlib.sha256(timeline_payload).hexdigest() != (
                BATCH10_FINAL2_TIMELINE_GRAPH_SHA256[slug]
            ):
                issues.append(
                    f"{slug}/{language}: timeline actor/action/consequence/source "
                    "graph differs outside authorized final2 semantic fields"
                )
            if tuple(item[0] for item in timeline) != BATCH10_TIMELINE_IDS[slug]:
                issues.append(f"{slug}/{language}: timeline ID/order changed")

            dispute_expected = BATCH10_FINAL2_DISPUTE_CONTRACTS.get(slug)
            if dispute_expected is not None:
                dispute = body.select_one(
                    f'[data-fact-id="{slug}-evidence-official-gap"]'
                )
                dispute_actual = (
                    dispute.get("data-inference-subject", "") if dispute else "",
                    dispute.get("data-official-response", "") if dispute else "",
                    dispute.get("data-response-gap", "") if dispute else "",
                    dispute.get("data-accountability", "") if dispute else "",
                )
                if dispute_actual != dispute_expected:
                    issues.append(
                        f"{slug}/{language}: dispute actor/accountability contract changed"
                    )

            if slug == "tiananmen-1989":
                for node in body.find_all(True):
                    for name, value in node.attrs.items():
                        values = value if isinstance(value, list) else [str(value)]
                        if name.startswith("data-") and "state-council" in " ".join(values):
                            issues.append(
                                f"{slug}/{language}: unsupported state-council actor "
                                f"returned in {name}"
                            )
    return issues


def audit_batch10_cards(script_text=None, baseline_rows=None, delta_rows=None):
    """Replay the 54×23 start capture and require a target-only card delta."""
    issues = []
    if hashlib.sha256(BATCH10_CARD_BASELINE_PATH.read_bytes()).hexdigest() != BATCH10_CARD_BASELINE_SHA256:
        issues.append("batch10 card baseline was regenerated or edited")
    if baseline_rows is None:
        baseline_rows, load_issues = batch9_final2_load_tsv(
            BATCH10_CARD_BASELINE_PATH,
            BATCH9_FINAL2_CARD_DELTA_COLUMNS,
            "batch10 card baseline",
        )
        issues.extend(load_issues)
    if delta_rows is None:
        delta_rows, load_issues = batch9_final2_load_tsv(
            BATCH10_CARD_DELTA_PATH,
            BATCH9_FINAL2_CARD_DELTA_COLUMNS,
            "batch10 card delta",
        )
        issues.extend(load_issues)
    cards, card_issues = batch9_final2_report_cards(script_text)
    cards = batch14_baseline_card_view(cards)
    issues.extend(card_issues)
    expected_count = 54 * len(BATCH9_FINAL2_CARD_FIELDS)
    if len(baseline_rows) != expected_count or len(delta_rows) != expected_count:
        issues.append("batch10 card baseline/delta is not 54×23")
        return issues
    current = {
        (index, card.get("slug", ""), field): card.get(field, "")
        for index, card in enumerate(cards, start=1)
        for field in BATCH9_FINAL2_CARD_FIELDS
    }
    baseline = {}
    target_rows = 0
    for row in baseline_rows:
        try:
            key = (int(row.get("card_index", "")), row.get("slug", ""), row.get("field", ""))
        except ValueError:
            issues.append("batch10 card baseline has a non-numeric index")
            continue
        baseline[key] = row
        target = key[1] in BATCH10_SLUG_SET
        target_rows += int(target)
        if row.get("batch_tag") != "reread:batch10-start":
            issues.append(f"batch10 card baseline tag changed: {key}")
        if row.get("scope") != ("target" if target else "non-target"):
            issues.append(f"batch10 card baseline scope changed: {key}")
        if row.get("before_value") != row.get("after_value") or row.get("changed") != "NO":
            issues.append(f"batch10 card baseline no longer records the start value: {key}")
        if not target and current.get(key) != row.get("before_value", ""):
            issues.append(f"batch10 non-target card changed: {key[1]}/{key[2]}")
    if len(baseline) != expected_count or target_rows != 8 * len(BATCH9_FINAL2_CARD_FIELDS):
        issues.append("batch10 card baseline key/scope inventory changed")
    seen = set()
    for row in delta_rows:
        try:
            key = (int(row.get("card_index", "")), row.get("slug", ""), row.get("field", ""))
        except ValueError:
            issues.append("batch10 card delta has a non-numeric index")
            continue
        seen.add(key)
        base = baseline.get(key)
        if base is None:
            issues.append(f"batch10 card delta has an unknown key: {key}")
            continue
        before = base.get("before_value", "")
        after = current.get(key, "")
        changed = before != after
        target = key[1] in BATCH10_SLUG_SET
        if row.get("batch_tag") != "reread:batch10" or row.get("scope") != ("target" if target else "non-target"):
            issues.append(f"batch10 card delta tag/scope changed: {key}")
        if row.get("before_value") != before or row.get("after_value") != after:
            issues.append(f"batch10 card delta is not recomputable: {key}")
        if row.get("changed") != ("YES" if changed else "NO"):
            issues.append(f"batch10 card delta changed flag is false: {key}")
        expected_result = "PASS_CHANGED_AUTHORIZED" if changed else "PASS_UNCHANGED"
        if row.get("integrity_result") != expected_result:
            issues.append(f"batch10 card delta result is false: {key}")
        if changed and not target:
            issues.append(f"batch10 card delta records a non-target change: {key}")
    if seen != set(baseline):
        issues.append("batch10 card delta key coverage changed")
    great_leap = next((card for card in cards if card.get("slug") == "great-leap-famine"), {})
    if great_leap.get("date") != "1958-08-29":
        issues.append("great-leap-famine card must use the sourced 1958-08-29 commune-resolution node")
    if any(card.get("date", "").endswith("-01-01") for card in cards if card.get("slug") in BATCH10_SLUG_SET):
        issues.append("batch10 target card retains an unsupported January-1 placeholder")
    return issues


def batch10_card_delta_counts(script_text=None, baseline_rows=None):
    """Recompute changed target/non-target fields without an expected target count."""
    if baseline_rows is None:
        baseline_rows, _ = batch9_final2_load_tsv(
            BATCH10_CARD_BASELINE_PATH, BATCH9_FINAL2_CARD_DELTA_COLUMNS,
            "batch10 card baseline",
        )
    cards, _ = batch9_final2_report_cards(script_text)
    cards = batch14_baseline_card_view(cards)
    current = {
        (index, card.get("slug", ""), field): card.get(field, "")
        for index, card in enumerate(cards, start=1)
        for field in BATCH9_FINAL2_CARD_FIELDS
    }
    target = 0
    non_target = 0
    for row in baseline_rows:
        try:
            key = (
                int(row.get("card_index", "")), row.get("slug", ""),
                row.get("field", ""),
            )
        except ValueError:
            continue
        if current.get(key) == row.get("before_value", ""):
            continue
        if key[1] in BATCH10_SLUG_SET:
            target += 1
        else:
            non_target += 1
    return target, non_target


def audit_batch10_final2_card_transition(
    reread_rows=None, script_text=None, baseline_rows=None,
):
    """Recompute final2 card movement from authenticated final1 DOM tips.

    Counts are descriptive, never pass constants.  This distinguishes fields
    already different at final2 start from fields newly entering the cumulative
    batch-ten delta, while protecting the frozen Cultural Revolution card and
    all date/URL fields during final2.
    """
    issues = []
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch10-final2 card predecessor ledger",
        )
        issues.extend(load_issues)
    if baseline_rows is None:
        baseline_rows, load_issues = batch9_final2_load_tsv(
            BATCH10_CARD_BASELINE_PATH, BATCH9_FINAL2_CARD_DELTA_COLUMNS,
            "batch10-final2 card start baseline",
        )
        issues.extend(load_issues)
    cards, card_issues = batch9_final2_report_cards(script_text)
    cards = batch14_baseline_card_view(cards)
    issues.extend(card_issues)
    current = {
        (index, card.get("slug", ""), field): card.get(field, "")
        for index, card in enumerate(cards, start=1)
        for field in BATCH9_FINAL2_CARD_FIELDS
    }
    final1_tips = batch10_final1_prefix_tips(reread_rows)
    final1 = {}
    start = {}
    for row in baseline_rows:
        try:
            key = (
                int(row.get("card_index", "")), row.get("slug", ""),
                row.get("field", ""),
            )
        except ValueError:
            issues.append("batch10-final2 card baseline has a non-numeric index")
            continue
        start[key] = row.get("before_value", "")
        _index, slug, field = key
        predecessor = start[key]
        if slug in BATCH10_SLUG_SET and field.startswith("title_"):
            language = field.removeprefix("title_")
            tip = final1_tips.get((slug, language, "article-title"))
            if tip is None:
                issues.append(f"batch10-final2 card title lacks final1 tip: {slug}/{field}")
            else:
                predecessor = tip.get("revised_text", "")
        elif slug in BATCH10_SLUG_SET and field.startswith("excerpt_"):
            language = field.removeprefix("excerpt_")
            tip = final1_tips.get((slug, language, "article-dek"))
            if tip is None:
                issues.append(f"batch10-final2 card excerpt lacks final1 tip: {slug}/{field}")
            else:
                predecessor = tip.get("revised_text", "")
        elif slug in BATCH10_SLUG_SET and field == "date":
            predecessor = BATCH10_CARD_DATES[slug]
        elif slug in BATCH10_SLUG_SET and field == "url":
            predecessor = f"posts/{slug}.html"
        elif slug in BATCH10_SLUG_SET and field == "slug":
            predecessor = slug
        final1[key] = predecessor

    cumulative_target = cumulative_non_target = 0
    final2_changed = new_cumulative = continued_revision = 0
    for key, before in start.items():
        now = current.get(key, "")
        prior = final1.get(key, before)
        slug, field = key[1], key[2]
        if now != before:
            if slug in BATCH10_SLUG_SET:
                cumulative_target += 1
            else:
                cumulative_non_target += 1
        if now == prior:
            continue
        final2_changed += 1
        if slug not in BATCH10_FINAL2_SLUG_SET:
            issues.append(f"batch10-final2 changed a frozen card: {slug}/{field}")
        if not (field.startswith("title_") or field.startswith("excerpt_")):
            issues.append(f"batch10-final2 changed a non-text card field: {slug}/{field}")
        if prior == before and now != before:
            new_cumulative += 1
        elif prior != before:
            continued_revision += 1
    return issues, {
        "start_cumulative": sum(
            final1.get(key, value) != value
            for key, value in start.items()
            if key[1] in BATCH10_SLUG_SET
        ),
        "final2_changed": final2_changed,
        "new_cumulative": new_cumulative,
        "continued_revision": continued_revision,
        "current_cumulative": cumulative_target,
        "current_non_target": cumulative_non_target,
    }


def batch10_final2_sentences(value):
    return tuple(
        batch10_final1_normalize(part)
        for part in re.split(r"(?<=[.!?。！？])\s+|[；;]\s*", value or "")
        if len(final1_contiguous_stream(part)) >= 18
    )


def audit_batch10_final2_named_semantics(pages):
    """Handwritten final2 rules for the actual human-review regressions."""
    issues = []
    for slug, duties in BATCH10_FINAL2_COLUMN_ANCHORS.items():
        soup = pages[slug]
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            rights = body.select_one(
                f'[data-fact-id="{slug}-rights-analysis"]'
            ) if body else None
            protection = body.select_one(
                f'[data-fact-id="{slug}-protection"]'
            ) if body else None
            rights_text = normalized_visible(rights)
            protection_text = normalized_visible(protection)
            if rights is None or protection is None:
                issues.append(f"{slug}/{language}: final2 duty column missing")
                continue
            for duty_name, visible in (
                ("rights", rights_text), ("protection", protection_text),
            ):
                for anchor in duties[duty_name][language]:
                    if anchor.casefold() not in visible.casefold():
                        issues.append(
                            f"{slug}/{language}/{duty_name}: independent duty anchor missing: {anchor}"
                        )
            rights_sentences = {
                final1_contiguous_stream(sentence)
                for sentence in batch10_final2_sentences(rights_text)
            }
            protection_sentences = {
                final1_contiguous_stream(sentence)
                for sentence in batch10_final2_sentences(protection_text)
            }
            repeated = rights_sentences & protection_sentences
            if repeated:
                issues.append(
                    f"{slug}/{language}: rights/protection repeat a complete normalized sentence"
                )
            common_fragment = final1_longest_common_fragment(
                rights_text, protection_text,
            )
            if common_fragment >= 50:
                issues.append(
                    f"{slug}/{language}: rights/protection longest continuous fragment "
                    f"is {common_fragment}, expected below 50"
                )
            rights_parts = batch10_final2_sentences(rights_text)
            protection_parts = batch10_final2_sentences(protection_text)
            if rights_parts and protection_parts:
                ending_overlap = final1_longest_common_fragment(
                    rights_parts[-1], protection_parts[-1],
                )
                if ending_overlap >= 35:
                    issues.append(
                        f"{slug}/{language}: rights/protection reuse an accountability ending "
                        f"({ending_overlap} normalized characters)"
                    )

    tian = pages["tiananmen-1989"]
    for language in BATCH5_LANGS:
        title = normalized_visible(
            tian.select_one(f'.article-title .lang-{language}')
        )
        dek = normalized_visible(tian.select_one(f'.article-dek .lang-{language}'))
        if title == BATCH10_FINAL2_TIAN_AMBIGUOUS_TITLES[language]:
            issues.append(f"tiananmen-1989/{language}: ambiguous old title returned")
        for anchor in BATCH10_FINAL2_TIAN_TITLE_ANCHORS[language]:
            if anchor.casefold() not in title.casefold():
                issues.append(f"tiananmen-1989/{language}: split-subject title anchor missing: {anchor}")
        for anchor in BATCH10_FINAL2_TIAN_DEK_ANCHORS[language]:
            if anchor.casefold() not in dek.casefold():
                issues.append(f"tiananmen-1989/{language}: active firing summary anchor missing: {anchor}")

    liu = pages["liu-xiaobo"]
    for language in BATCH5_LANGS:
        body = liu.select_one(f'[data-language-body="{language}"]')
        timeline = body.select_one(
            '[data-fact-id="liu-xiaobo-timeline-3"]'
        ) if body else None
        visible = normalized_visible(timeline)
        if timeline is None or "2009-06-23" not in visible:
            issues.append(f"liu-xiaobo/{language}/timeline-3: formal-arrest date missing")
        if timeline is not None and timeline.get("data-timeline-action") != (
            "formally-arrested"
        ):
            issues.append(f"liu-xiaobo/{language}/timeline-3: final2 formal-arrest action missing")
        if timeline is not None and timeline.get("data-timeline-consequence") != (
            "formal-criminal-custody-followed"
        ):
            issues.append(f"liu-xiaobo/{language}/timeline-3: final2 custody consequence missing")
        if re.search(r"2008|12月25|December 25|25 de diciembre|25\. Dezember|25 décembre|25\. desember|25 december|25 dicembre", visible, re.I):
            issues.append(f"liu-xiaobo/{language}/timeline-3: later/editorial procedure returned")

    jiang = pages["jiangyou-school-bullying-protests"]
    huang = pages["huang-qi"]
    for language in BATCH5_LANGS:
        jiang_dek = normalized_visible(
            jiang.select_one(f'.article-dek .lang-{language}')
        )
        for anchor in BATCH10_FINAL2_JIANG_DEK_ANCHORS[language]:
            if anchor.casefold() not in jiang_dek.casefold():
                issues.append(f"jiangyou-school-bullying-protests/{language}: police/platform/remedy summary anchor missing: {anchor}")
        huang_dek = normalized_visible(
            huang.select_one(f'.article-dek .lang-{language}')
        )
        for anchor in BATCH10_FINAL2_HUANG_DEK_ANCHORS[language]:
            if anchor.casefold() not in huang_dek.casefold():
                issues.append(f"huang-qi/{language}: concrete website/prosecution summary anchor missing: {anchor}")

    glf = pages["great-leap-famine"]
    for language in BATCH5_LANGS:
        title = normalized_visible(glf.select_one(f'.article-title .lang-{language}'))
        dek = normalized_visible(glf.select_one(f'.article-dek .lang-{language}'))
        if language in BATCH10_FINAL2_GLF_NAMES and (
            BATCH10_FINAL2_GLF_NAMES[language].casefold() not in title.casefold()
        ):
            issues.append(f"great-leap-famine/{language}: complete conventional name missing")
        requisition = BATCH10_FINAL2_GLF_REQUISITION[language]
        if requisition.casefold() not in f"{title} {dek}".casefold():
            issues.append(f"great-leap-famine/{language}: compulsory state grain requisition weakened")
        body = glf.select_one(f'[data-language-body="{language}"]')
        milestone = body.select_one(
            '[data-fact-id="great-leap-famine-timeline-2"]'
        ) if body else None
        if milestone is None or not re.search(
            r"重要.{0,8}(?:政策|節目)|important policy milestone|政策上の節目|정책적 이정표|"
            r"hito normativo importante|wichtiger politischer Meilenstein|jalon politique important|"
            r"viktig politisk milepæl|belangrijke beleidsmijlpaal|importante tappa politica",
            normalized_visible(milestone), re.I,
        ):
            issues.append(f"great-leap-famine/{language}/timeline-2: commune policy milestone framing missing")

    land = pages["land-reform-anti-rightist"]
    for language, anchors in BATCH10_FINAL2_LAND_DEK_ANCHORS.items():
        visible = " ".join((
            normalized_visible(land.select_one(f'.article-title .lang-{language}')),
            normalized_visible(land.select_one(f'.article-dek .lang-{language}')),
        ))
        for anchor in anchors:
            if anchor.casefold() not in visible.casefold():
                issues.append(f"land-reform-anti-rightist/{language}: natural work-team/labour term missing: {anchor}")
    for language in BATCH5_LANGS:
        body = land.select_one(f'[data-language-body="{language}"]')
        milestone = body.select_one(
            '[data-fact-id="land-reform-anti-rightist-timeline-5"]'
        ) if body else None
        if milestone is None or not re.search(
            r"重要.{0,8}(?:政策|節目)|important policy milestone|政策上の節目|정책적 이정표|"
            r"hito político importante|wichtigen politischen Meilenstein|jalon politique important|"
            r"viktig politisk milepæl|belangrijke beleidsmijlpaal|importante tappa politica",
            normalized_visible(milestone), re.I,
        ):
            issues.append(f"land-reform-anti-rightist/{language}/timeline-5: Anti-Rightist milestone framing missing")
    return issues


def audit_batch10_semantics(pages, cards=None):
    """Independent batch-ten actor/date/legal/source/card regression audit."""
    issues = audit_batch10_source_visible_contracts(pages)
    issues.extend(audit_batch10_final2_named_semantics(pages))
    for slug in BATCH10_SLUGS:
        soup = pages[slug]
        if BATCH10_BAD_PATTERNS[slug].search(normalized_visible(soup)):
            issues.append(f"{slug}: rejected batch-ten semantic or machine-translation phrase returned")
        expected_period = {
            "great-leap-famine": "1958—1962",
            "land-reform-anti-rightist": "1950—1980",
        }.get(slug)
        reference_sources = None
        reference_timeline = None
        for language in BATCH5_LANGS:
            if expected_period is not None:
                meta = soup.select_one(f'.article-meta .lang-{language}')
                if meta is None or expected_period not in normalized_visible(meta):
                    issues.append(
                        f"{slug}/{language}: visible period boundary must include {expected_period}"
                    )
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"{slug}/{language}: batch-ten language body missing")
                continue
            sources = tuple(
                (
                    node.get("data-source-id", ""), node.get("data-source-type", ""),
                    node.get("data-source-date", ""),
                    (node.find("a").get("href", "") if node.find("a") else ""),
                )
                for node in body.select("ul.source-list > li[data-source-id]")
            )
            source_ids = {row[0] for row in sources}
            referenced_source_ids = {
                source_id
                for node in body.select("[data-fact-id][data-source-ref]")
                for source_id in node.get("data-source-ref", "").split()
            }
            if source_ids != referenced_source_ids:
                issues.append(
                    f"{slug}/{language}: source/fact relationship differs "
                    f"(orphan={sorted(source_ids - referenced_source_ids)}, "
                    f"missing={sorted(referenced_source_ids - source_ids)})"
                )
            if reference_sources is None:
                reference_sources = sources
            elif sources != reference_sources:
                issues.append(f"{slug}/{language}: source signature differs from the batch-ten reference language")
            heading = body.select_one('h2[data-section="timeline"]')
            timeline = heading.find_next_sibling("ol") if heading else None
            nodes = timeline.find_all("li", recursive=False) if timeline else []
            ids = tuple(node.get("data-fact-id", "") for node in nodes)
            if ids != BATCH10_TIMELINE_IDS[slug]:
                issues.append(f"{slug}/{language}: timeline order or fact IDs changed")
            semantic_graph = tuple(
                (
                    node.get("data-fact-id", ""), node.get("data-timeline-subject", ""),
                    node.get("data-timeline-action", ""), node.get("data-timeline-consequence", ""),
                    node.get("data-source-ref", ""),
                ) for node in nodes
            )
            if reference_timeline is None:
                reference_timeline = semantic_graph
            elif semantic_graph != reference_timeline:
                issues.append(f"{slug}/{language}: timeline actor/action/consequence/ref graph differs")
            for (required_slug, fact_id), required_refs in BATCH10_REQUIRED_REFS.items():
                if required_slug != slug:
                    continue
                node = body.select_one(f'[data-fact-id="{fact_id}"]')
                actual_refs = set(node.get("data-source-ref", "").split()) if node else set()
                if node is None or not required_refs.issubset(actual_refs):
                    issues.append(f"{slug}/{language}/{fact_id}: named-source relationship missing")
            rights = body.select_one(f'[data-fact-id="{slug}-rights-analysis"]')
            rights_text = normalized_visible(rights)
            if slug in BATCH10_ACCOUNTABILITY_SLUGS:
                if rights is None or any(
                    not re.search(pattern, rights_text, re.I)
                    for pattern in BATCH10_ACCOUNTABILITY_TERMS[language]
                ):
                    issues.append(
                        f"{slug}/{language}: visible reliable-evidence, individualized international-accountability, "
                        "or non-collective boundary is missing"
                    )
            if slug == "falun-gong-persecution":
                missing_falun_rights = [
                    concept for concept in BATCH10_FALUN_RIGHTS_REQUIRED[language]
                    if concept.casefold() not in rights_text.casefold()
                ]
                if missing_falun_rights:
                    issues.append(
                        f"{slug}/{language}: batch10-final1 Falun Gong rights chain is missing "
                        f"{missing_falun_rights}"
                    )
            if slug in {
                "jiangyou-school-bullying-protests", "huang-qi", "falun-gong-persecution",
            }:
                protection = body.select_one(f'[data-fact-id="{slug}-protection"]')
                common_fragment = final1_longest_common_fragment(
                    rights_text, normalized_visible(protection)
                )
                if protection is None or common_fragment >= 50:
                    issues.append(
                        f"{slug}/{language}: rights/protection longest common normalized "
                        f"continuous fragment is {common_fragment}, expected below 50"
                    )
            if slug == "jiangyou-school-bullying-protests":
                node = body.select_one('[data-fact-id="jiangyou-school-bullying-protests-evidence-2"]')
                if node is None or not re.search(
                    r"RFA|Radio Free Asia|自由亞洲|自由亚洲|ラジオ・フリー・アジア|자유아시아",
                    normalized_visible(node), re.I,
                ):
                    issues.append(f"{slug}/{language}: visible RFA evidence subject missing")
            if slug == "falun-gong-persecution":
                retrospective = body.select_one('li[data-source-id="s2"]')
                if retrospective is None or retrospective.get("data-source-type", "") != (
                    "state-media official-position retrospective-legal-summary"
                ):
                    issues.append(
                        f"{slug}/{language}/s2: People’s Daily retrospective is misclassified"
                    )
                arrest = body.select_one('[data-fact-id="falun-gong-persecution-timeline-2"]')
                ban = body.select_one('[data-fact-id="falun-gong-persecution-timeline-2b"]')
                if not normalized_visible(arrest).startswith("1999-07-20") or not normalized_visible(ban).startswith("1999-07-22"):
                    issues.append(f"{slug}/{language}: July 20 arrests and July 22 formal ban were exchanged")
                evidence = body.select_one('[data-fact-id="falun-gong-persecution-evidence-2"]')
                if not re.search(
                    r"UN Special Procedures|UN allegation letter|聯合國(?:特別程序|指控函)|联合国(?:特别程序|指控函)|"
                    r"国連(?:特別手続|の申立書簡)|유엔 (?:특별절차|혐의 서한|의혹 서한)|"
                    r"procedimientos especiales de la ONU|la carta (?:de alegaciones )?de la ONU|UN-Sonderverfahren|das UN-Vorwurfsschreiben|"
                    r"procédures spéciales de l[’']ONU|la lettre (?:d[’']allégations )?de l[’']ONU|FNs spesialprosedyrer|FN-brevet|"
                    r"speciale VN-procedures|de VN-brief|procedure speciali dell[’']ONU|la lettera (?:di accuse )?dell[’']ONU|la lettera ONU",
                    normalized_visible(evidence), re.I,
                ):
                    issues.append(f"{slug}/{language}: UN allegation source subject missing")
    if cards is None:
        report_cards, card_issues = batch9_final2_report_cards()
        report_cards = batch14_baseline_card_view(report_cards)
        issues.extend(card_issues)
        cards = {card.get("slug", ""): card for card in report_cards}
    for slug, expected_date in BATCH10_CARD_DATES.items():
        card = cards.get(slug, {})
        if card.get("date", "") != expected_date:
            issues.append(f"script.js/{slug}: event date differs from {expected_date}")
        soup = pages[slug]
        for language in BATCH5_LANGS:
            title = normalized_visible(soup.select_one(f".article-title .lang-{language}"))
            dek = normalized_visible(soup.select_one(f".article-dek .lang-{language}"))
            if card.get(f"title_{language}", "") != title or card.get(f"excerpt_{language}", "") != dek:
                issues.append(f"script.js/{slug}/{language}: card is not synchronized with article header")
    return issues


def batch10_final1_prefix_payload_issues(
    payload, row_count, expected_sha256, label,
):
    """Authenticate a header-plus-fixed-row TSV prefix from raw bytes."""
    lines = payload.splitlines(keepends=True)
    required_lines = row_count + 1
    if len(lines) < required_lines:
        return [
            f"{label} lost its authenticated batch10 prefix: "
            f"found {max(0, len(lines) - 1)} rows, need at least {row_count}"
        ]
    digest = hashlib.sha256(b"".join(lines[:required_lines])).hexdigest()
    if digest != expected_sha256:
        return [f"{label} rewrote or reordered its authenticated batch10 prefix"]
    return []


def batch10_final1_exact_prefix(path, row_count, expected_sha256, label):
    if not path.exists():
        return [f"{label} missing: {path}"]
    return batch10_final1_prefix_payload_issues(
        path.read_bytes(), row_count, expected_sha256, label,
    )


def batch10_final1_normalize(value):
    return " ".join((value or "").split())


def batch10_final1_row_key(row):
    return (
        row.get("slug", ""), row.get("language", ""),
        row.get("target_id", ""),
    )


def batch10_final1_contract_key(row):
    return (
        row.get("slug", ""), row.get("language", ""),
        row.get("target_kind", ""), row.get("target_id", ""),
    )


def batch10_final1_tombstone_source_id(row):
    """Return the removed source id only for the canonical tombstone shape."""
    if row.get("target_kind", "") != "source-title":
        return ""
    refs = row.get("source_refs", "")
    revised = row.get("revised_text", "")
    if not refs.startswith("source-removed:") or not revised.startswith("[SOURCE REMOVED:"):
        return ""
    return refs.split(":", 1)[1].strip()


def batch10_final1_dom_targets(pages):
    """Enumerate the final1 ledger surface from DOM structure, not TSV prose.

    The ledger may prove append-chain and coverage integrity, but it never
    supplies semantic anchors to this checker.  Semantic wording remains under
    the independently authored batch-ten rules above.
    """
    targets = {}
    issues = []

    def add(key, value):
        if key in targets:
            issues.append(f"batch10-final1 duplicate live DOM target: {'/'.join(key)}")
        else:
            targets[key] = value

    for slug in BATCH10_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"batch10-final1 target page missing: {slug}")
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"batch10-final1 language body missing: {slug}/{language}")
                continue
            source_nodes = body.select("ul.source-list > li[data-source-id]")
            source_ids = [node.get("data-source-id", "") for node in source_nodes]
            if not all(source_ids) or len(source_ids) != len(set(source_ids)):
                issues.append(f"batch10-final1 blank or duplicate live source id: {slug}/{language}")
            page_refs = "page-sources:" + " ".join(source_ids)
            for target_id, selector in (
                ("article-title", f".article-title .lang-{language}"),
                ("article-dek", f".article-dek .lang-{language}"),
            ):
                node = soup.select_one(selector)
                if node is None:
                    issues.append(f"batch10-final1 live target missing: {slug}/{language}/{target_id}")
                    continue
                add(
                    (slug, language, target_id),
                    {
                        "target_kind": target_id,
                        "text": batch10_final1_normalize(normalized_visible(node)),
                        "source_refs": page_refs,
                    },
                )
            if (slug, language) in BATCH10_FINAL1_META_TARGETS:
                node = soup.select_one(f".article-meta .lang-{language}")
                if node is None:
                    issues.append(
                        f"batch10-final1 live target missing: {slug}/{language}/article-meta"
                    )
                else:
                    add(
                        (slug, language, "article-meta"),
                        {
                            "target_kind": "article-meta",
                            "text": batch10_final1_normalize(normalized_visible(node)),
                            "source_refs": page_refs,
                        },
                    )
            for node in body.select("[data-fact-id]"):
                if node.select_one("[data-fact-id]"):
                    continue
                target_id = node.get("data-fact-id", "")
                if not target_id or target_id.endswith("-sources"):
                    continue
                add(
                    (slug, language, target_id),
                    {
                        "target_kind": "fact",
                        "text": batch10_final1_normalize(normalized_visible(node)),
                        "source_refs": " ".join(
                            node.get("data-source-ref", "").split()
                        ),
                    },
                )
            for source in source_nodes:
                source_id = source.get("data-source-id", "")
                anchor = source.find("a")
                if not source_id or anchor is None:
                    issues.append(f"batch10-final1 malformed live source: {slug}/{language}")
                    continue
                add(
                    (slug, language, f"source-title:{source_id}"),
                    {
                        "target_kind": "source-title",
                        "text": batch10_final1_normalize(normalized_visible(anchor)),
                        "source_refs": source_id,
                    },
                )
    return targets, issues


def batch10_final1_prefix_tips(reread_rows):
    tips = {}
    for row in reread_rows[:BATCH10_FINAL1_REREAD_ROWS]:
        if (
            row.get("slug", "") in BATCH10_SLUG_SET
            and row.get("language", "") in BATCH5_LANGS
            and row.get("target_kind", "") in BATCH10_FINAL1_TARGET_KINDS
        ):
            tips[batch10_final1_row_key(row)] = row
    return tips


def batch10_final1_expected_changes(pages, reread_rows):
    """Diff authenticated chain tips against live DOM to fix suffix coverage."""
    live, issues = batch10_final1_dom_targets(pages)
    tips = batch10_final1_prefix_tips(reread_rows)
    expected = {}
    live_keys = set(live)
    tip_keys = set(tips)

    for key in sorted(live_keys - tip_keys):
        slug, language, target_id = key
        if target_id == "article-meta" and (slug, language) in BATCH10_FINAL1_META_TARGETS:
            current = live[key]
            expected_new = batch10_final1_normalize(
                batch10_final1_meta_text(slug, language, revised=True)
            )
            if current["text"] != expected_new:
                issues.append(
                    "batch10-final1 metadata differs from its independent final text: "
                    + "/".join(key)
                )
                continue
            expected[key] = {
                "prior": {
                    "slug": slug,
                    "language": language,
                    "target_id": target_id,
                    "target_kind": "article-meta",
                    "revised_text": batch10_final1_meta_text(
                        slug, language, revised=False,
                    ),
                    "source_refs": current["source_refs"],
                },
                "live": current,
                "tombstone": False,
            }
            continue
        issues.append(
            "batch10-final1 live target lacks an authenticated predecessor: "
            + "/".join(key)
        )
    for key in sorted(tip_keys - live_keys):
        prior = tips[key]
        if prior.get("target_kind", "") != "source-title":
            issues.append(
                "batch10-final1 removed a non-source DOM target: " + "/".join(key)
            )
            continue
        expected[key] = {"prior": prior, "live": None, "tombstone": True}
    for key in sorted(live_keys & tip_keys):
        prior = tips[key]
        current = live[key]
        prior_state = (
            prior.get("target_kind", ""),
            batch10_final1_normalize(prior.get("revised_text", "")),
            batch10_final1_normalize(prior.get("source_refs", "")),
        )
        live_state = (
            current["target_kind"], current["text"],
            batch10_final1_normalize(current["source_refs"]),
        )
        if prior_state != live_state:
            expected[key] = {"prior": prior, "live": current, "tombstone": False}
    return expected, live, issues


def batch10_final1_coverage_issue(label, expected, actual):
    missing = sorted(expected - actual)
    extra = sorted(actual - expected)
    if not missing and not extra:
        return ""
    missing_sample = ["/".join(value) for value in missing[:3]]
    extra_sample = ["/".join(value) for value in extra[:3]]
    return (
        f"{label} coverage differs: missing={len(missing)} {missing_sample}; "
        f"extra={len(extra)} {extra_sample}"
    )


def audit_batch10_final1_append_integrity(
    pages, *, reread_rows=None, contract_rows=None, check_file=True,
):
    """Audit the authenticated final1 append without learning TSV semantics."""
    issues = []
    if check_file:
        issues.extend(
            batch10_final1_exact_prefix(
                BATCH9_REREAD_PATH, BATCH10_FINAL1_REREAD_ROWS,
                BATCH10_FINAL1_REREAD_SHA256,
                "semantic reread batch10-final1 ledger",
            )
        )
        issues.extend(
            batch10_final1_exact_prefix(
                BATCH9_CONTRACT_PATH, BATCH10_FINAL1_CONTRACT_ROWS,
                BATCH10_FINAL1_CONTRACT_SHA256,
                "editorial contract batch10-final1 ledger",
            )
        )
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "semantic reread batch10-final1 ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "editorial contract batch10-final1 ledger",
        )
        issues.extend(load_issues)
    if len(reread_rows) < BATCH10_FINAL1_REREAD_ROWS:
        issues.append("semantic reread batch10-final1 ledger is shorter than its prefix")
    if len(contract_rows) < BATCH10_FINAL1_CONTRACT_ROWS:
        issues.append("editorial contract batch10-final1 ledger is shorter than its prefix")

    expected, live, expected_issues = batch10_final1_expected_changes(
        pages, reread_rows,
    )
    issues.extend(expected_issues)
    reread_suffix = reread_rows[BATCH10_FINAL1_REREAD_ROWS:]
    contract_suffix = contract_rows[BATCH10_FINAL1_CONTRACT_ROWS:]
    if not reread_suffix or not contract_suffix:
        missing_parts = []
        if not reread_suffix:
            missing_parts.append("reread")
        if not contract_suffix:
            missing_parts.append("contract")
        issues.append(
            "batch10-final1 append missing " + "/".join(missing_parts)
            + f" suffix: {len(expected)} authenticated-prefix-to-DOM changes require paired rows"
        )

    tips = batch10_final1_prefix_tips(reread_rows)
    expected_keys = {
        (
            key[0], key[1], value["prior"].get("target_kind", ""), key[2],
        )
        for key, value in expected.items()
    }
    reread_seen_ids = set()
    reread_seen_keys = set()
    prefix_contract_ids = {
        row.get("contract_id", "")
        for row in contract_rows[:BATCH10_FINAL1_CONTRACT_ROWS]
        if row.get("contract_id", "")
    }
    reread_by_id = {}
    for row in reread_suffix:
        key3 = batch10_final1_row_key(row)
        key4 = batch10_final1_contract_key(row)
        label = "/".join(key4)
        contract_id = row.get("contract_id", "")
        if row.get("slug", "") not in BATCH10_SLUG_SET:
            issues.append(f"batch10-final1 reread has a non-target page: {label}")
        if row.get("language", "") not in BATCH5_LANGS:
            issues.append(f"batch10-final1 reread has a non-target language: {label}")
        if row.get("target_kind", "") not in BATCH10_FINAL1_TARGET_KINDS:
            issues.append(f"batch10-final1 reread has an unsupported target kind: {label}")
        if not contract_id.startswith(BATCH10_FINAL1_PREFIX):
            issues.append(f"batch10-final1 reread contract prefix differs: {label}")
        if contract_id in reread_seen_ids or contract_id in prefix_contract_ids:
            issues.append(f"batch10-final1 reread contract id is duplicate or non-append: {label}")
        if key4 in reread_seen_keys:
            issues.append(f"batch10-final1 reread duplicates a target: {label}")
        reread_seen_ids.add(contract_id)
        reread_seen_keys.add(key4)
        reread_by_id[contract_id] = row
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch10-final1 reread is not a revision: {label}")
        if "reread:batch10-final1" not in row.get("review_basis", ""):
            issues.append(f"batch10-final1 reread lacks its review marker: {label}")
        if not row.get("issue_found", "").strip():
            issues.append(f"batch10-final1 reread lacks issue detail: {label}")
        expected_change = expected.get(key3)
        prior = tips.get(key3)
        if (
            prior is None
            and expected_change is not None
            and key3[2] == "article-meta"
            and (key3[0], key3[1]) in BATCH10_FINAL1_META_TARGETS
        ):
            prior = expected_change["prior"]
        if prior is None:
            issues.append(f"batch10-final1 reread lacks a continuous predecessor: {label}")
            continue
        if row.get("target_kind", "") != prior.get("target_kind", ""):
            issues.append(f"batch10-final1 revision changes target kind: {label}")
        if batch10_final1_normalize(row.get("original_text", "")) != (
            batch10_final1_normalize(prior.get("revised_text", ""))
        ):
            issues.append(f"batch10-final1 revision chain is broken: {label}")
        if expected_change is None:
            issues.append(f"batch10-final1 reread records an unchanged target: {label}")
            continue
        if expected_change["tombstone"]:
            source_id = key3[2].split(":", 1)[1] if ":" in key3[2] else ""
            tombstone_id = batch10_final1_tombstone_source_id(row)
            if tombstone_id != source_id or source_id not in row.get("revised_text", ""):
                issues.append(f"batch10-final1 source-removal tombstone is malformed: {label}")
            if key3 in live:
                issues.append(f"batch10-final1 tombstone still has a live source: {label}")
            for live_key, current in live.items():
                if live_key[:2] != key3[:2]:
                    continue
                refs = current.get("source_refs", "").replace("page-sources:", "").split()
                if source_id and source_id in refs:
                    issues.append(f"batch10-final1 removed source remains referenced: {label}")
                    break
        else:
            current = expected_change["live"]
            if batch10_final1_normalize(row.get("revised_text", "")) != current["text"]:
                issues.append(f"batch10-final1 reread tip differs from current DOM: {label}")
            if batch10_final1_normalize(row.get("source_refs", "")) != (
                batch10_final1_normalize(current["source_refs"])
            ):
                issues.append(f"batch10-final1 reread source refs differ from current DOM: {label}")
        genuine_text_change = batch10_final1_normalize(
            row.get("original_text", "")
        ) != batch10_final1_normalize(row.get("revised_text", ""))
        genuine_ref_change = batch10_final1_normalize(
            prior.get("source_refs", "")
        ) != batch10_final1_normalize(row.get("source_refs", ""))
        if not (genuine_text_change or genuine_ref_change or expected_change["tombstone"]):
            issues.append(f"batch10-final1 reread is not a genuine change: {label}")

    contract_seen_ids = set()
    contract_seen_keys = set()
    contract_by_id = {}
    for row in contract_suffix:
        key4 = batch10_final1_contract_key(row)
        label = "/".join(key4)
        contract_id = row.get("contract_id", "")
        if row.get("slug", "") not in BATCH10_SLUG_SET:
            issues.append(f"batch10-final1 contract has a non-target page: {label}")
        if row.get("language", "") not in BATCH5_LANGS:
            issues.append(f"batch10-final1 contract has a non-target language: {label}")
        if row.get("target_kind", "") not in BATCH10_FINAL1_TARGET_KINDS:
            issues.append(f"batch10-final1 contract has an unsupported target kind: {label}")
        if not contract_id.startswith(BATCH10_FINAL1_PREFIX):
            issues.append(f"batch10-final1 contract prefix differs: {label}")
        if contract_id in contract_seen_ids or contract_id in prefix_contract_ids:
            issues.append(f"batch10-final1 contract id is duplicate or non-append: {label}")
        if key4 in contract_seen_keys:
            issues.append(f"batch10-final1 contract duplicates a target: {label}")
        contract_seen_ids.add(contract_id)
        contract_seen_keys.add(key4)
        contract_by_id[contract_id] = row
        required = batch9_final2_contract_literals(row.get("required_all", ""))
        forbidden = batch9_final2_contract_literals(row.get("forbidden_any", ""))
        if len(set(required)) < 4 or len(set(forbidden)) < 2:
            issues.append(f"batch10-final1 contract lacks four required/two forbidden anchors: {label}")
        summary = batch10_final1_normalize(row.get("fact_summary", "")).casefold()
        if any(marker not in summary for marker in BATCH10_FINAL1_SUMMARY_MARKERS):
            issues.append(f"batch10-final1 contract summary is incomplete: {label}")

    if reread_seen_ids != contract_seen_ids:
        issues.append(
            "batch10-final1 reread/contract ids are not one-to-one: "
            f"reread_only={len(reread_seen_ids - contract_seen_ids)} "
            f"contract_only={len(contract_seen_ids - reread_seen_ids)}"
        )
    for contract_id in sorted(reread_seen_ids & contract_seen_ids):
        if batch10_final1_contract_key(reread_by_id[contract_id]) != (
            batch10_final1_contract_key(contract_by_id[contract_id])
        ):
            issues.append(f"batch10-final1 paired contract points to another target: {contract_id}")

    coverage = batch10_final1_coverage_issue(
        "batch10-final1 reread", expected_keys, reread_seen_keys,
    )
    if coverage:
        issues.append(coverage)
    coverage = batch10_final1_coverage_issue(
        "batch10-final1 contract", expected_keys, contract_seen_keys,
    )
    if coverage:
        issues.append(coverage)
    if reread_suffix:
        if {row.get("slug", "") for row in reread_suffix} != BATCH10_SLUG_SET:
            issues.append("batch10-final1 reread suffix does not cover exactly the eight target pages")
        if {row.get("language", "") for row in reread_suffix} != set(BATCH5_LANGS):
            issues.append("batch10-final1 reread suffix does not cover exactly the ten languages")

    stats = {
        "expected_rows": len(expected_keys),
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "tombstones": sum(value["tombstone"] for value in expected.values()),
    }
    return issues, stats


def batch10_final1_append_self_test(pages):
    """Inject prefix, pairing, chain, scope, DOM and tombstone failures."""
    reread_rows, reread_load = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch10-final1 self-test reread",
    )
    contract_rows, contract_load = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch10-final1 self-test contract",
    )
    misses = []
    if reread_load or contract_load:
        return 0, 0, [
            "batch10-final1 self-test setup failed: "
            + "; ".join(reread_load + contract_load)
        ]
    reread_prefix = deepcopy(reread_rows[:BATCH10_FINAL1_REREAD_ROWS])
    contract_prefix = deepcopy(contract_rows[:BATCH10_FINAL1_CONTRACT_ROWS])
    expected, _live, expected_issues = batch10_final1_expected_changes(
        pages, reread_prefix,
    )
    if expected_issues or not expected:
        return 0, 0, [
            "batch10-final1 self-test setup has no clean expected diff: "
            + "; ".join(expected_issues[:3])
        ]
    synthetic_reread = deepcopy(reread_prefix)
    synthetic_contract = deepcopy(contract_prefix)
    for index, (key, change) in enumerate(sorted(expected.items()), start=1):
        slug, language, target_id = key
        prior = change["prior"]
        target_kind = prior.get("target_kind", "")
        contract_id = (
            f"{BATCH10_FINAL1_PREFIX}{slug}:{language}:{target_kind}:"
            f"{target_id}:selftest-{index:04d}"
        )
        if change["tombstone"]:
            source_id = target_id.split(":", 1)[1]
            revised_text = f"[SOURCE REMOVED: {source_id}]"
            source_refs = f"source-removed:{source_id}"
        else:
            revised_text = change["live"]["text"]
            source_refs = change["live"]["source_refs"]
        synthetic_reread.append(
            {
                "slug": slug, "language": language, "target_id": target_id,
                "target_kind": target_kind,
                "original_text": prior.get("revised_text", ""),
                "issue_found": "self-test final1 integrity revision",
                "revised_text": revised_text,
                "review_basis": "reread:batch10-final1 synthetic integrity fixture",
                "source_refs": source_refs, "contract_id": contract_id,
                "result": "PASS_AFTER_REVISION",
            }
        )
        synthetic_contract.append(
            {
                "contract_id": contract_id, "slug": slug,
                "language": language, "target_kind": target_kind,
                "target_id": target_id,
                "required_all": "anchor one || anchor two || anchor three || anchor four",
                "forbidden_any": "bad anchor one || bad anchor two",
                "fact_summary": (
                    "subject: fixture. action: fixture. legal term: fixture. "
                    "consequence: fixture. remedy: fixture."
                ),
            }
        )
    baseline_issues, _stats = audit_batch10_final1_append_integrity(
        pages, reread_rows=synthetic_reread,
        contract_rows=synthetic_contract, check_file=False,
    )
    if baseline_issues:
        return 0, 0, [
            "batch10-final1 self-test synthetic baseline failed: "
            + "; ".join(baseline_issues[:4])
        ]

    intercepted = 0
    total = 0

    def run_case(label, *, case_pages=None, case_reread=None, case_contract=None):
        nonlocal intercepted, total
        total += 1
        found, _case_stats = audit_batch10_final1_append_integrity(
            case_pages or pages,
            reread_rows=case_reread or synthetic_reread,
            contract_rows=case_contract or synthetic_contract,
            check_file=False,
        )
        if found:
            intercepted += 1
        else:
            misses.append(label)

    payload = bytearray(BATCH9_REREAD_PATH.read_bytes())
    if payload:
        payload[len(payload) // 2] ^= 1
    total += 1
    if batch10_final1_prefix_payload_issues(
        bytes(payload), BATCH10_FINAL1_REREAD_ROWS,
        BATCH10_FINAL1_REREAD_SHA256, "self-test prefix",
    ):
        intercepted += 1
    else:
        misses.append("authenticated prefix byte mutation")

    bad_reread = deepcopy(synthetic_reread)
    bad_contract = deepcopy(synthetic_contract)
    suffix_index = BATCH10_FINAL1_REREAD_ROWS
    contract_index = BATCH10_FINAL1_CONTRACT_ROWS
    bad_id = "reread:batch10:wrong-final1-prefix"
    bad_reread[suffix_index]["contract_id"] = bad_id
    bad_contract[contract_index]["contract_id"] = bad_id
    run_case("non-final1 suffix prefix", case_reread=bad_reread, case_contract=bad_contract)

    missing_contract = deepcopy(synthetic_contract)
    missing_contract.pop(contract_index)
    run_case("missing paired contract", case_contract=missing_contract)

    broken_chain = deepcopy(synthetic_reread)
    broken_chain[suffix_index]["original_text"] += " [broken predecessor]"
    run_case("broken revision chain", case_reread=broken_chain)

    wrong_scope_reread = deepcopy(synthetic_reread)
    wrong_scope_contract = deepcopy(synthetic_contract)
    wrong_scope_reread[suffix_index]["slug"] = "outside-batch10"
    wrong_scope_contract[contract_index]["slug"] = "outside-batch10"
    run_case(
        "non-target page in suffix",
        case_reread=wrong_scope_reread, case_contract=wrong_scope_contract,
    )

    regular_key = next(key for key, value in sorted(expected.items()) if not value["tombstone"])
    dom_pages = dict(pages)
    dom_pages[regular_key[0]] = deepcopy(pages[regular_key[0]])
    dom_target = dom_pages[regular_key[0]].select_one(
        f'[data-language-body="{regular_key[1]}"] '
        f'[data-fact-id="{regular_key[2]}"]'
    )
    if regular_key[2] == "article-title":
        dom_target = dom_pages[regular_key[0]].select_one(
            f'.article-title .lang-{regular_key[1]}'
        )
    elif regular_key[2] == "article-dek":
        dom_target = dom_pages[regular_key[0]].select_one(
            f'.article-dek .lang-{regular_key[1]}'
        )
    elif regular_key[2] == "article-meta":
        dom_target = dom_pages[regular_key[0]].select_one(
            f'.article-meta .lang-{regular_key[1]}'
        )
    elif regular_key[2].startswith("source-title:"):
        source_id = regular_key[2].split(":", 1)[1]
        dom_target = dom_pages[regular_key[0]].select_one(
            f'[data-language-body="{regular_key[1]}"] '
            f'li[data-source-id="{source_id}"] a'
        )
    if dom_target is not None:
        dom_target.append(" SELFTEST-DOM-MUTATION")
        run_case("unledgered current DOM mutation", case_pages=dom_pages)
    else:
        total += 1
        misses.append("unledgered current DOM mutation setup")

    tombstone_key = next(
        (key for key, value in sorted(expected.items()) if value["tombstone"]), None,
    )
    if tombstone_key is not None:
        tombstone_reread = deepcopy(synthetic_reread)
        for row in tombstone_reread[BATCH10_FINAL1_REREAD_ROWS:]:
            if batch10_final1_row_key(row) == tombstone_key:
                row["source_refs"] = "source-removed:wrong-source"
                break
        run_case("source-removal tombstone mismatch", case_reread=tombstone_reread)
    else:
        total += 1
        misses.append("source-removal tombstone mismatch setup")
    return intercepted, total, misses


def batch10_final1_preimage_issues(
    *, payload=None, reread_rows=None, check_digest=True,
):
    """Authenticate the persisted genuine pre-final1 snapshot excerpt."""
    issues = []
    if payload is None:
        if not BATCH10_FINAL1_PREIMAGE_PATH.exists():
            return ["batch10-final1 preimage artifact missing"], {
                "rows": 0, "article_meta": 0, "cards": 0,
            }
        payload = BATCH10_FINAL1_PREIMAGE_PATH.read_bytes()
    if check_digest and hashlib.sha256(payload).hexdigest() != (
        BATCH10_FINAL1_PREIMAGE_SHA256
    ):
        issues.append("batch10-final1 preimage artifact was regenerated or edited")
    try:
        reader = csv.DictReader(io.StringIO(payload.decode("utf-8")), delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    except (UnicodeDecodeError, csv.Error) as exc:
        return [f"batch10-final1 preimage artifact cannot be parsed: {exc}"], {
            "rows": 0, "article_meta": 0, "cards": 0,
        }
    if fields != BATCH10_FINAL1_PREIMAGE_COLUMNS:
        issues.append("batch10-final1 preimage columns or column order changed")
    if len(rows) != 57:
        issues.append(
            f"batch10-final1 preimage has {len(rows)} rows, expected 57"
        )

    article_meta = [row for row in rows if row.get("record_type") == "article-meta"]
    cards = [row for row in rows if row.get("record_type") == "card-field"]
    unknown = [
        row for row in rows
        if row.get("record_type") not in {"article-meta", "card-field"}
    ]
    if len(article_meta) != 36 or len(cards) != 21 or unknown:
        issues.append(
            "batch10-final1 preimage classification is not 36 article-meta + 21 card-field"
        )
    expected_card_keys = {
        (slug, f"excerpt_{language}")
        for slug in ("tiananmen-1989", "falun-gong-persecution")
        for language in BATCH5_LANGS
    } | {("huang-qi", "excerpt_no")}
    actual_card_keys = {
        (row.get("slug", ""), row.get("language_or_field", ""))
        for row in cards
    }
    if actual_card_keys != expected_card_keys:
        issues.append("batch10-final1 preimage card set is not Tian 10 + Falun 10 + Huang 1")

    seen = set()
    for row in rows:
        key = (
            row.get("record_type", ""), row.get("slug", ""),
            row.get("language_or_field", ""), row.get("target_id", ""),
        )
        if key in seen or not all(key):
            issues.append(f"batch10-final1 preimage blank/duplicate key: {key}")
        seen.add(key)
        if row.get("snapshot_manifest_sha256", "") != (
            BATCH10_FINAL1_SNAPSHOT_MANIFEST_SHA256
        ):
            issues.append(f"batch10-final1 preimage manifest differs: {key}")
        for value_name, hash_name in (
            ("preimage_value", "preimage_value_sha256"),
            ("post_final1_value", "post_final1_value_sha256"),
        ):
            digest = hashlib.sha256(
                row.get(value_name, "").encode("utf-8")
            ).hexdigest()
            if digest != row.get(hash_name, ""):
                issues.append(f"batch10-final1 preimage value hash differs: {key}/{value_name}")
        if not re.fullmatch(r"[0-9a-f]{64}", row.get("preimage_file_sha256", "")):
            issues.append(f"batch10-final1 preimage file hash malformed: {key}")
        if not re.fullmatch(r"[0-9a-f]{64}", row.get("post_final1_file_sha256", "")):
            issues.append(f"batch10-final1 post-file hash malformed: {key}")

    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch10-final1 preimage reread ledger",
        )
        issues.extend(load_issues)
    final1_rows = reread_rows[
        BATCH10_PRE_FINAL1_REREAD_ROWS:BATCH10_FINAL1_REREAD_ROWS
    ]
    no_predecessor = {}
    pre_tips = {
        batch10_final1_row_key(row): row
        for row in reread_rows[:BATCH10_PRE_FINAL1_REREAD_ROWS]
    }
    for row in final1_rows:
        key = batch10_final1_row_key(row)
        if key not in pre_tips:
            no_predecessor[key] = row
    artifact_meta = {
        (row.get("slug", ""), row.get("language_or_field", ""), row.get("target_id", "")): row
        for row in article_meta
    }
    if set(no_predecessor) != set(artifact_meta):
        issues.append(
            "batch10-final1 preimage article-meta coverage differs from the 36 no-predecessor rows"
        )
    for key in set(no_predecessor) & set(artifact_meta):
        ledger_row = no_predecessor[key]
        artifact = artifact_meta[key]
        if artifact.get("verification") != "VERIFIED_PREIMAGE_WITHOUT_LEDGER_PREDECESSOR":
            issues.append(f"batch10-final1 preimage verification marker differs: {key}")
        if batch10_final1_normalize(artifact.get("preimage_value", "")) != (
            batch10_final1_normalize(ledger_row.get("original_text", ""))
        ):
            issues.append(f"batch10-final1 article-meta preimage differs from ledger original: {key}")
        if batch10_final1_normalize(artifact.get("post_final1_value", "")) != (
            batch10_final1_normalize(ledger_row.get("revised_text", ""))
        ):
            issues.append(f"batch10-final1 article-meta post-value differs from ledger tip: {key}")

    final1_tips = {}
    for row in reread_rows[:BATCH10_FINAL1_REREAD_ROWS]:
        final1_tips[batch10_final1_row_key(row)] = row
    for row in cards:
        slug = row.get("slug", "")
        field = row.get("language_or_field", "")
        language = field.removeprefix("excerpt_")
        tip = final1_tips.get((slug, language, "article-dek"))
        if tip is None or row.get("post_final1_value", "") != tip.get("revised_text", ""):
            issues.append(
                f"batch10-final1 card post-value lacks matching final1 article-dek tip: {slug}/{field}"
            )
        if row.get("verification") != "VERIFIED_FINAL1_CARD_DIFF_FROM_PREIMAGE":
            issues.append(f"batch10-final1 card preimage verification marker differs: {slug}/{field}")
    return issues, {
        "rows": len(rows), "article_meta": len(article_meta), "cards": len(cards),
    }


def batch10_final2_live_targets(pages):
    """Return the seven-page final2 ledger surface plus the one real attribute edit."""
    all_targets, issues = batch10_final1_dom_targets(pages)
    live = {
        key: value for key, value in all_targets.items()
        if key[0] in BATCH10_FINAL2_SLUG_SET
    }
    for language in BATCH5_LANGS:
        body = pages["tiananmen-1989"].select_one(
            f'[data-language-body="{language}"]'
        )
        node = body.select_one(
            '[data-fact-id="tiananmen-1989-evidence-official-gap"]'
        ) if body else None
        key = (
            "tiananmen-1989", language,
            "tiananmen-1989-evidence-official-gap@data-accountability",
        )
        if node is None:
            issues.append(f"{'/'.join(key)}: final2 attribute target missing")
            continue
        live[key] = {
            "target_kind": "fact-attribute",
            "text": node.get("data-accountability", ""),
            "source_refs": " ".join(node.get("data-source-ref", "").split()),
        }
    return live, issues


def batch10_final2_predecessor_tips(reread_rows):
    tips = {}
    for row in reread_rows[:BATCH10_FINAL1_REREAD_ROWS]:
        key = batch10_final1_row_key(row)
        if row.get("slug", "") not in BATCH10_FINAL2_SLUG_SET:
            continue
        if batch10_final1_tombstone_source_id(row):
            tips.pop(key, None)
        else:
            tips[key] = {
                "target_kind": row.get("target_kind", ""),
                "text": batch10_final1_normalize(row.get("revised_text", "")),
                "source_refs": batch10_final1_normalize(row.get("source_refs", "")),
            }
    old_accountability = (
        "ccp-central-leadership-state-council-central-military-commission-"
        "pla-police-and-responsible-commanders"
    )
    for language in BATCH5_LANGS:
        tips[(
            "tiananmen-1989", language,
            "tiananmen-1989-evidence-official-gap@data-accountability",
        )] = {
            "target_kind": "fact-attribute",
            "text": old_accountability,
            "source_refs": "s1 s3 s4 s5 s7",
        }
    return tips


def batch10_final2_expected_changes(pages, reread_rows):
    live, issues = batch10_final2_live_targets(pages)
    predecessors = batch10_final2_predecessor_tips(reread_rows)
    expected = {}
    for key in sorted(set(live) | set(predecessors)):
        current = live.get(key)
        prior = predecessors.get(key)
        if current is None:
            issues.append(f"batch10-final2 removed a ledger target: {'/'.join(key)}")
            continue
        if prior is None:
            issues.append(f"batch10-final2 live target lacks final1 predecessor: {'/'.join(key)}")
            continue
        prior_state = (
            prior["target_kind"], batch10_final1_normalize(prior["text"]),
            batch10_final1_normalize(prior["source_refs"]),
        )
        live_state = (
            current["target_kind"], batch10_final1_normalize(current["text"]),
            batch10_final1_normalize(current["source_refs"]),
        )
        if prior_state != live_state:
            expected[key] = {"prior": prior, "live": current}
    return expected, live, issues


def batch10_final2_source_ledger_issues(
    pages, reread_suffix, *, source_rows=None, check_file=True,
):
    """Authenticate final1 evidence and validate final2 fact/attribute overlays.

    A semantic ``fact-attribute`` target uses ``base@attribute`` in the reread
    and contract ledgers, but the source ledger must retain its real final1
    predecessor key: the base fact ID.  The mapping below is explicit; it does
    not invent an ``@`` source-ledger predecessor that never existed.
    """
    issues = []
    if check_file:
        issues.extend(batch10_final1_exact_prefix(
            BATCH9_SOURCE_LEDGER_PATH, BATCH10_FINAL1_SOURCE_LEDGER_ROWS,
            BATCH10_FINAL1_SOURCE_LEDGER_SHA256,
            "batch10-final1 source ledger",
        ))
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch10-final2 source ledger",
        )
        issues.extend(load_issues)
    if len(source_rows) < BATCH10_FINAL1_SOURCE_LEDGER_ROWS:
        issues.append("batch10-final2 source ledger is shorter than final1 prefix")
        return issues, {"source_rows": 0}
    prefix = source_rows[:BATCH10_FINAL1_SOURCE_LEDGER_ROWS]
    suffix = source_rows[
        BATCH10_FINAL1_SOURCE_LEDGER_ROWS:BATCH10_FINAL2_SOURCE_LEDGER_ROWS
    ]
    final2_fact_rows = [
        row for row in reread_suffix
        if row.get("target_kind", "") in {"fact", "fact-attribute"}
    ]
    expected_by_source_key = {}
    for reread in final2_fact_rows:
        target_id = reread.get("target_id", "")
        source_fact_id = target_id.split("@", 1)[0]
        source_key = (
            reread.get("slug", ""), reread.get("language", ""),
            source_fact_id,
        )
        if source_key in expected_by_source_key:
            issues.append(
                "batch10-final2 multiple reread targets collapse onto one source "
                f"overlay key: {'/'.join(source_key)}"
            )
        expected_by_source_key[source_key] = reread
    expected_keys = set(expected_by_source_key)
    prefix_tips = {}
    for row in prefix:
        key = (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        prefix_tips[key] = row
    mutable_overlay_fields = {
        "current_visible_text", "timeline_subject", "timeline_action",
        "timeline_consequence", "baseline_issue", "resolution_action",
        "reread_h1_current", "reread_dek_current", "reread_timeline_current",
        "reread_rights_current", "reread_protection_current",
        "reread_source_titles_current", "reread_card_current",
        "reread_issue_found", "reread_revision_text", "reread_result",
        "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor",
    }
    seen = set()
    for row in suffix:
        key = (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        label = "/".join(key)
        if key in seen or not all(key):
            issues.append(f"batch10-final2 source ledger blank/duplicate overlay: {label}")
        seen.add(key)
        if key[0] not in BATCH10_FINAL2_SLUG_SET or key[1] not in BATCH5_LANGS:
            issues.append(f"batch10-final2 source ledger has out-of-scope overlay: {label}")
        marker = f"{BATCH10_FINAL2_PREFIX}{key[0]}:{key[1]}:{key[2]}"
        if row.get("baseline_issue", "") != marker:
            issues.append(f"batch10-final2 source overlay baseline marker differs: {label}")
        if not row.get("reread_issue_found", "").startswith(BATCH10_FINAL2_PREFIX):
            issues.append(f"batch10-final2 source overlay lacks final2 issue marker: {label}")
        if row.get("reread_result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch10-final2 source overlay is not a real revision: {label}")
        reread = expected_by_source_key.get(key)
        if reread is None:
            issues.append(f"batch10-final2 source overlay has no paired fact revision: {label}")
            continue
        predecessor = prefix_tips.get(key)
        if predecessor is None:
            issues.append(f"batch10-final2 source overlay lacks final1 predecessor: {label}")
        else:
            for column in BATCH9_FINAL2_SOURCE_COLUMNS:
                if column in mutable_overlay_fields:
                    continue
                if row.get(column, "") != predecessor.get(column, ""):
                    issues.append(
                        f"batch10-final2 source overlay changed protected evidence "
                        f"field {column}: {label}"
                    )
                    break

        slug, language, fact_id = key
        body = pages.get(slug).select_one(
            f'[data-language-body="{language}"]'
        ) if pages.get(slug) is not None else None
        node = body.select_one(f'[data-fact-id="{fact_id}"]') if body else None
        if node is None:
            issues.append(f"batch10-final2 source overlay has no live base fact: {label}")
            continue
        heading = node.find_previous("h2")
        live_fields = {
            "section_id": heading.get("data-section", "") if heading else "",
            "current_visible_text": normalized_visible(node),
            "data_source_ref": " ".join(node.get("data-source-ref", "").split()),
            "timeline_subject": node.get("data-timeline-subject", ""),
            "timeline_action": node.get("data-timeline-action", ""),
            "timeline_consequence": node.get("data-timeline-consequence", ""),
        }
        for field, live_value in live_fields.items():
            if batch10_final1_normalize(row.get(field, "")) != (
                batch10_final1_normalize(live_value)
            ):
                issues.append(
                    f"batch10-final2 source overlay {field} differs from live DOM: {label}"
                )

        title = normalized_visible(
            pages[slug].select_one(f'.article-title .lang-{language}')
        )
        dek = normalized_visible(
            pages[slug].select_one(f'.article-dek .lang-{language}')
        )
        sources = " | ".join(
            f'{source.get("data-source-id", "")}:{normalized_visible(source.find("a"))}'
            for source in body.select("ul.source-list > li[data-source-id]")
        )
        reread_live_fields = {
            "reread_h1_current": title,
            "reread_dek_current": dek,
            "reread_timeline_current": (
                normalized_visible(node)
                if node.has_attr("data-timeline-action") else ""
            ),
            "reread_rights_current": (
                normalized_visible(node)
                if fact_id == f"{slug}-rights-analysis" else ""
            ),
            "reread_protection_current": (
                normalized_visible(node)
                if fact_id == f"{slug}-protection" else ""
            ),
            "reread_source_titles_current": sources,
            "reread_card_current": f"{title} | {dek}",
        }
        for field, live_value in reread_live_fields.items():
            if batch10_final1_normalize(row.get(field, "")) != (
                batch10_final1_normalize(live_value)
            ):
                issues.append(
                    f"batch10-final2 source overlay {field} is stale: {label}"
                )
        visible_stream = re.sub(
            r"\d", "", final1_contiguous_stream(normalized_visible(node))
        )
        for field in (
            "visible_subject_anchor", "visible_action_anchor",
            "visible_consequence_anchor",
        ):
            anchor = re.sub(
                r"\d", "", final1_contiguous_stream(row.get(field, ""))
            )
            if anchor and anchor not in visible_stream:
                issues.append(
                    f"batch10-final2 source overlay {field} is not locatable: {label}"
                )

        target_id = reread.get("target_id", "")
        target_kind = reread.get("target_kind", "")
        revised = batch10_final1_normalize(row.get("reread_revision_text", ""))
        if target_kind == "fact-attribute":
            if target_id != f"{fact_id}@data-accountability":
                issues.append(
                    f"batch10-final2 unsupported source attribute mapping: {label}/{target_id}"
                )
                expected_revision = ""
            else:
                expected_revision = node.get("data-accountability", "")
            if row.get("resolution_action", "") != (
                "revised data-accountability attribute after batch10-final2 reread"
            ):
                issues.append(
                    f"batch10-final2 accountability overlay resolution differs: {label}"
                )
            old_value = (
                "ccp-central-leadership-state-council-central-military-commission-"
                "pla-police-and-responsible-commanders"
            )
            evidence = row.get("reread_issue_found", "")
            if old_value not in evidence or expected_revision not in evidence:
                issues.append(
                    f"batch10-final2 accountability overlay lacks explicit old/new evidence: {label}"
                )
        else:
            expected_revision = normalized_visible(node)
        if revised != batch10_final1_normalize(expected_revision):
            issues.append(f"batch10-final2 source overlay revision differs from live target: {label}")
        if revised != batch10_final1_normalize(reread.get("revised_text", "")):
            issues.append(f"batch10-final2 source overlay differs from paired reread tip: {label}")
    if seen != expected_keys:
        issues.append(
            "batch10-final2 source overlay coverage differs from final2 fact/attribute rows: "
            f"missing={len(expected_keys-seen)} extra={len(seen-expected_keys)}"
        )
    return issues, {"source_rows": len(suffix)}


def audit_batch10_final2_history(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    check_files=True,
):
    """Audit final1 history honestly and final2 as a continuous append."""
    issues = []
    if check_files:
        for path, rows, digest, label in (
            (BATCH9_REREAD_PATH, BATCH10_PRE_FINAL1_REREAD_ROWS,
             BATCH10_PRE_FINAL1_REREAD_SHA256, "batch10 pre-final1 reread ledger"),
            (BATCH9_CONTRACT_PATH, BATCH10_PRE_FINAL1_CONTRACT_ROWS,
             BATCH10_PRE_FINAL1_CONTRACT_SHA256, "batch10 pre-final1 contract ledger"),
            (BATCH9_REREAD_PATH, BATCH10_FINAL1_REREAD_ROWS,
             BATCH10_FINAL1_REREAD_SHA256, "batch10 final1 reread ledger"),
            (BATCH9_CONTRACT_PATH, BATCH10_FINAL1_CONTRACT_ROWS,
             BATCH10_FINAL1_CONTRACT_SHA256, "batch10 final1 contract ledger"),
            (BATCH9_SOURCE_LEDGER_PATH, BATCH10_FINAL1_SOURCE_LEDGER_ROWS,
             BATCH10_FINAL1_SOURCE_LEDGER_SHA256, "batch10 final1 source ledger"),
            (BATCH9_REREAD_PATH, BATCH10_FINAL2_REREAD_ROWS,
             BATCH10_FINAL2_REREAD_SHA256, "batch10 final2 reread ledger"),
            (BATCH9_CONTRACT_PATH, BATCH10_FINAL2_CONTRACT_ROWS,
             BATCH10_FINAL2_CONTRACT_SHA256, "batch10 final2 contract ledger"),
            (BATCH9_SOURCE_LEDGER_PATH, BATCH10_FINAL2_SOURCE_LEDGER_ROWS,
             BATCH10_FINAL2_SOURCE_LEDGER_SHA256, "batch10 final2 source ledger"),
        ):
            issues.extend(batch10_final1_exact_prefix(path, rows, digest, label))
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch10-final2 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch10-final2 contract ledger",
        )
        issues.extend(load_issues)
    if len(reread_rows) < BATCH10_FINAL1_REREAD_ROWS:
        issues.append("batch10-final2 reread ledger is shorter than final1 prefix")
    if len(contract_rows) < BATCH10_FINAL1_CONTRACT_ROWS:
        issues.append("batch10-final2 contract ledger is shorter than final1 prefix")

    final1_rows = reread_rows[
        BATCH10_PRE_FINAL1_REREAD_ROWS:BATCH10_FINAL1_REREAD_ROWS
    ]
    final1_contracts = contract_rows[
        BATCH10_PRE_FINAL1_CONTRACT_ROWS:BATCH10_FINAL1_CONTRACT_ROWS
    ]
    pre_tips = {}
    for row in reread_rows[:BATCH10_PRE_FINAL1_REREAD_ROWS]:
        pre_tips[batch10_final1_row_key(row)] = row
    predecessor_count = 0
    snapshot_count = 0
    dom_text = 0
    tombstones = 0
    source_only = 0
    final1_ids = set()
    final1_keys = set()
    for row in final1_rows:
        key = batch10_final1_row_key(row)
        key4 = batch10_final1_contract_key(row)
        label = "/".join(key4)
        contract_id = row.get("contract_id", "")
        if row.get("slug", "") not in BATCH10_SLUG_SET:
            issues.append(f"batch10-final1 row is out of scope: {label}")
        if row.get("language", "") not in BATCH5_LANGS:
            issues.append(f"batch10-final1 row has unsupported language: {label}")
        if not contract_id.startswith(BATCH10_FINAL1_PREFIX):
            issues.append(f"batch10-final1 row has wrong contract prefix: {label}")
        if contract_id in final1_ids or key4 in final1_keys:
            issues.append(f"batch10-final1 row duplicates id/target: {label}")
        final1_ids.add(contract_id)
        final1_keys.add(key4)
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch10-final1 row is not a revision: {label}")
        prior = pre_tips.get(key)
        if prior is None:
            snapshot_count += 1
            if row.get("target_kind", "") != "article-meta":
                issues.append(f"batch10-final1 no-predecessor row is not article-meta: {label}")
        else:
            predecessor_count += 1
            if batch10_final1_normalize(row.get("original_text", "")) != (
                batch10_final1_normalize(prior.get("revised_text", ""))
            ):
                issues.append(f"batch10-final1 predecessor chain is broken: {label}")
        is_tombstone = bool(batch10_final1_tombstone_source_id(row))
        text_changed = batch10_final1_normalize(row.get("original_text", "")) != (
            batch10_final1_normalize(row.get("revised_text", ""))
        )
        if is_tombstone:
            tombstones += 1
        elif text_changed:
            dom_text += 1
        else:
            source_only += 1
            if prior is None or batch10_final1_normalize(prior.get("source_refs", "")) == (
                batch10_final1_normalize(row.get("source_refs", ""))
            ):
                issues.append(f"batch10-final1 source-only row has no source change: {label}")
    if (
        len(final1_rows), dom_text, tombstones, source_only,
        predecessor_count, snapshot_count,
    ) != (432, 392, 10, 30, 396, 36):
        issues.append(
            "batch10-final1 classification differs from "
            "432=392 DOM text+10 tombstones+30 source-only and 396 predecessor+36 snapshot: "
            f"got {len(final1_rows)}={dom_text}+{tombstones}+{source_only}; "
            f"{predecessor_count}+{snapshot_count}"
        )

    contract_ids = set()
    contract_keys = set()
    for row in final1_contracts:
        key4 = batch10_final1_contract_key(row)
        contract_id = row.get("contract_id", "")
        if contract_id in contract_ids or key4 in contract_keys:
            issues.append(f"batch10-final1 contract duplicates id/target: {'/'.join(key4)}")
        contract_ids.add(contract_id)
        contract_keys.add(key4)
    if final1_ids != contract_ids or final1_keys != contract_keys:
        issues.append("batch10-final1 reread/contract 432-row pairing differs")

    preimage_issues, preimage_stats = batch10_final1_preimage_issues(
        reread_rows=reread_rows,
    )
    issues.extend(preimage_issues)

    history_pages = batch10_final3_preimage_pages(pages, reread_rows)
    expected, live, expected_issues = batch10_final2_expected_changes(
        history_pages, reread_rows,
    )
    issues.extend(expected_issues)
    reread_suffix = reread_rows[
        BATCH10_FINAL1_REREAD_ROWS:BATCH10_FINAL2_REREAD_ROWS
    ]
    contract_suffix = contract_rows[
        BATCH10_FINAL1_CONTRACT_ROWS:BATCH10_FINAL2_CONTRACT_ROWS
    ]
    expected_keys = {
        (key[0], key[1], value["live"]["target_kind"], key[2])
        for key, value in expected.items()
    }
    final2_ids = set()
    final2_keys = set()
    reread_by_id = {}
    for row in reread_suffix:
        key3 = batch10_final1_row_key(row)
        key4 = batch10_final1_contract_key(row)
        label = "/".join(key4)
        contract_id = row.get("contract_id", "")
        if row.get("slug", "") not in BATCH10_FINAL2_SLUG_SET:
            issues.append(f"batch10-final2 reread has out-of-scope page: {label}")
        if row.get("language", "") not in BATCH5_LANGS:
            issues.append(f"batch10-final2 reread has unsupported language: {label}")
        if row.get("target_kind", "") not in BATCH10_FINAL2_TARGET_KINDS:
            issues.append(f"batch10-final2 reread has unsupported target kind: {label}")
        if not contract_id.startswith(BATCH10_FINAL2_PREFIX):
            issues.append(f"batch10-final2 reread has wrong prefix: {label}")
        if contract_id in final2_ids or key4 in final2_keys:
            issues.append(f"batch10-final2 reread duplicates id/target: {label}")
        final2_ids.add(contract_id)
        final2_keys.add(key4)
        reread_by_id[contract_id] = row
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch10-final2 reread is not a real revision: {label}")
        if not row.get("review_basis", "").startswith(
            "reread:batch10-final2;"
        ):
            issues.append(f"batch10-final2 reread lacks final2 review marker: {label}")
        if not row.get("issue_found", "").strip():
            issues.append(f"batch10-final2 reread lacks issue detail: {label}")
        change = expected.get(key3)
        if change is None:
            issues.append(f"batch10-final2 reread records unchanged/unknown target: {label}")
            continue
        prior = change["prior"]
        current = change["live"]
        if row.get("target_kind", "") != current["target_kind"]:
            issues.append(f"batch10-final2 reread target kind differs: {label}")
        if batch10_final1_normalize(row.get("original_text", "")) != (
            batch10_final1_normalize(prior["text"])
        ):
            issues.append(f"batch10-final2 reread predecessor chain is broken: {label}")
        if batch10_final1_normalize(row.get("revised_text", "")) != (
            batch10_final1_normalize(current["text"])
        ):
            issues.append(f"batch10-final2 reread tip differs from current DOM: {label}")
        if batch10_final1_normalize(row.get("source_refs", "")) != (
            batch10_final1_normalize(current["source_refs"])
        ):
            issues.append(f"batch10-final2 reread source refs differ from current DOM: {label}")
        if batch10_final1_normalize(row.get("original_text", "")) == (
            batch10_final1_normalize(row.get("revised_text", ""))
        ):
            issues.append(f"batch10-final2 reread uses a no-change row: {label}")

    contract_ids2 = set()
    contract_keys2 = set()
    contract_by_id = {}
    for row in contract_suffix:
        key4 = batch10_final1_contract_key(row)
        label = "/".join(key4)
        contract_id = row.get("contract_id", "")
        if row.get("slug", "") not in BATCH10_FINAL2_SLUG_SET:
            issues.append(f"batch10-final2 contract has out-of-scope page: {label}")
        if not contract_id.startswith(BATCH10_FINAL2_PREFIX):
            issues.append(f"batch10-final2 contract has wrong prefix: {label}")
        if contract_id in contract_ids2 or key4 in contract_keys2:
            issues.append(f"batch10-final2 contract duplicates id/target: {label}")
        contract_ids2.add(contract_id)
        contract_keys2.add(key4)
        contract_by_id[contract_id] = row
        required = batch9_final2_contract_literals(row.get("required_all", ""))
        forbidden = batch9_final2_contract_literals(row.get("forbidden_any", ""))
        if len(set(required)) < 4 or len(set(forbidden)) < 2:
            issues.append(f"batch10-final2 contract lacks independent anchors: {label}")
        summary = batch10_final1_normalize(row.get("fact_summary", "")).casefold()
        if any(marker not in summary for marker in BATCH10_FINAL1_SUMMARY_MARKERS):
            issues.append(f"batch10-final2 contract summary is incomplete: {label}")
        if row.get("slug") == "tiananmen-1989":
            required_text = row.get("required_all", "").casefold()
            forbidden_text = row.get("forbidden_any", "").casefold()
            all_text = "\t".join(
                row.get(column, "") for column in BATCH9_FINAL2_CONTRACT_COLUMNS
            ).casefold()
            if "state-council" in all_text:
                issues.append(
                    f"batch10-final2 Tian contract reintroduced state-council: {label}"
                )
            is_accountability_contract = row.get("target_id", "") == (
                "tiananmen-1989-evidence-official-gap@data-accountability"
            )
            if is_accountability_contract:
                has_negative_boundary = any(
                    marker in required_text
                    for marker in (
                        "boundary:no-unsupported-executive-body",
                    )
                ) and any(
                    marker in forbidden_text
                    for marker in (
                        "reject:unsupported-executive-body",
                    )
                )
                if not has_negative_boundary:
                    issues.append(
                        f"batch10-final2 Tian accountability contract lacks its "
                        f"unsupported-actor rejection boundary: {label}"
                    )
    if final2_ids != contract_ids2 or final2_keys != contract_keys2:
        issues.append("batch10-final2 reread/contract ids or target pairs differ")
    for contract_id in final2_ids & contract_ids2:
        if batch10_final1_contract_key(reread_by_id[contract_id]) != (
            batch10_final1_contract_key(contract_by_id[contract_id])
        ):
            issues.append(f"batch10-final2 paired contract points elsewhere: {contract_id}")
    if final2_keys != expected_keys:
        issues.append(
            "batch10-final2 append coverage differs from actual final1-to-DOM changes: "
            f"missing={len(expected_keys-final2_keys)} extra={len(final2_keys-expected_keys)}"
        )

    source_issues, source_stats = batch10_final2_source_ledger_issues(
        history_pages, reread_suffix, source_rows=source_rows,
        check_file=check_files,
    )
    issues.extend(source_issues)
    stats = {
        "final1_rows": len(final1_rows), "final1_dom_text": dom_text,
        "final1_tombstones": tombstones, "final1_source_only": source_only,
        "final1_predecessors": predecessor_count,
        "final1_snapshot": snapshot_count,
        "preimage_rows": preimage_stats["rows"],
        "final2_reread_rows": len(reread_suffix),
        "final2_contract_rows": len(contract_suffix),
        "final2_source_rows": source_stats["source_rows"],
    }
    return issues, stats


def batch10_final2_history_self_test(pages):
    """Break persisted evidence, append chains, contracts and source overlays."""
    reread_rows, reread_load = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch10-final2 self-test reread",
    )
    contract_rows, contract_load = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch10-final2 self-test contract",
    )
    source_rows, source_load = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch10-final2 self-test source ledger",
    )
    misses = []
    if reread_load or contract_load or source_load:
        return 0, 0, reread_load + contract_load + source_load
    baseline, _stats = audit_batch10_final2_history(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows, check_files=False,
    )
    if baseline:
        return 0, 0, [
            "batch10-final2 history self-test baseline failed: "
            + "; ".join(baseline[:4])
        ]
    intercepted = 0
    total = 0

    def run_case(label, *, rr=None, cc=None, ss=None, pp=None):
        nonlocal intercepted, total
        total += 1
        found, _case_stats = audit_batch10_final2_history(
            pp or pages, reread_rows=rr or reread_rows,
            contract_rows=cc or contract_rows,
            source_rows=ss or source_rows, check_files=False,
        )
        if found:
            intercepted += 1
        else:
            misses.append(label)

    for label, path, rows, digest in (
        (
            "final1 reread prefix byte tamper", BATCH9_REREAD_PATH,
            BATCH10_FINAL1_REREAD_ROWS, BATCH10_FINAL1_REREAD_SHA256,
        ),
        (
            "final1 contract prefix byte tamper", BATCH9_CONTRACT_PATH,
            BATCH10_FINAL1_CONTRACT_ROWS, BATCH10_FINAL1_CONTRACT_SHA256,
        ),
        (
            "final1 source prefix byte tamper", BATCH9_SOURCE_LEDGER_PATH,
            BATCH10_FINAL1_SOURCE_LEDGER_ROWS,
            BATCH10_FINAL1_SOURCE_LEDGER_SHA256,
        ),
    ):
        total += 1
        payload = bytearray(path.read_bytes())
        if len(payload) > 100:
            payload[100] ^= 1
        if batch10_final1_prefix_payload_issues(
            bytes(payload), rows, digest, label,
        ):
            intercepted += 1
        else:
            misses.append(label)

    payload = bytearray(BATCH10_FINAL1_PREIMAGE_PATH.read_bytes())
    payload[len(payload) // 2] ^= 1
    total += 1
    preimage_mutation, _ = batch10_final1_preimage_issues(
        payload=bytes(payload), reread_rows=reread_rows,
    )
    if preimage_mutation:
        intercepted += 1
    else:
        misses.append("preimage byte tamper")

    suffix_index = BATCH10_FINAL1_REREAD_ROWS
    contract_index = BATCH10_FINAL1_CONTRACT_ROWS
    source_index = BATCH10_FINAL1_SOURCE_LEDGER_ROWS
    if len(reread_rows) > suffix_index:
        broken = deepcopy(reread_rows)
        broken[suffix_index]["original_text"] += " [broken final2 predecessor]"
        run_case("final2 reread predecessor chain", rr=broken)
    else:
        total += 1
        misses.append("final2 reread predecessor chain setup")
    if len(contract_rows) > contract_index:
        tian_index = next((
            index for index in range(contract_index, len(contract_rows))
            if contract_rows[index].get("slug") == "tiananmen-1989"
        ), None)
        if tian_index is not None:
            bad_contract = deepcopy(contract_rows)
            bad_contract[tian_index]["required_all"] += " || actor:state-council"
            run_case("state-council contract reinsertion", cc=bad_contract)
        else:
            total += 1
            misses.append("state-council contract reinsertion setup")
    if len(source_rows) > source_index:
        bad_source = deepcopy(source_rows)
        bad_source[source_index]["reread_revision_text"] += " [stale suffix]"
        run_case("source-ledger suffix/current-DOM mismatch", ss=bad_source)
        protected_source = deepcopy(source_rows)
        protected_source[source_index]["support_urls"] += " https://invalid.example"
        run_case("source-ledger protected evidence rewrite", ss=protected_source)
        stale_header = deepcopy(source_rows)
        stale_header[source_index]["reread_h1_current"] += " [stale H1]"
        run_case("source-ledger stale live H1 evidence", ss=stale_header)
        attr_index = next((
            index for index in range(source_index, len(source_rows))
            if source_rows[index].get("slug") == "tiananmen-1989"
            and source_rows[index].get("fact_id")
            == "tiananmen-1989-evidence-official-gap"
        ), None)
        if attr_index is None:
            total += 1
            misses.append("source-ledger accountability old/new evidence setup")
        else:
            attr_source = deepcopy(source_rows)
            attr_source[attr_index]["reread_issue_found"] = (
                f"{BATCH10_FINAL2_PREFIX}tiananmen-1989:"
                f"{attr_source[attr_index].get('language', '')}:"
                "tiananmen-1989-evidence-official-gap"
            )
            run_case(
                "source-ledger accountability old/new evidence",
                ss=attr_source,
            )
    else:
        total += 1
        misses.append("source-ledger suffix/current-DOM mismatch setup")
    return intercepted, total, misses


def batch10_final2_named_self_test(pages):
    """Mutate the exact final2 review failures in memory and require rejection.

    This suite does not replay the live text as an oracle.  Every mutation is
    an independently written bad meaning, actor, workflow phrase or structural
    change named by the human review; interception requires a newly emitted
    issue beyond any pre-existing baseline issue.
    """
    intercepted = 0
    total = 0
    misses = []

    def new_issues(before, after):
        return list((Counter(after) - Counter(before)).elements())

    def replace_text(node, old, new):
        if node is None:
            raise AssertionError("target node missing")
        value = normalized_visible(node)
        if old not in value:
            raise AssertionError(f"mutation source absent: {old}")
        node.clear()
        node.append(value.replace(old, new, 1))

    def page_case(label, slug, mutator, auditor, expected):
        nonlocal intercepted, total
        total += 1
        before = auditor(pages)
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        try:
            mutator(mutated[slug])
        except (AssertionError, AttributeError, KeyError, TypeError) as exc:
            misses.append(f"{label}: invalid setup ({exc})")
            return
        delta = new_issues(before, auditor(mutated))
        if any(expected in issue for issue in delta):
            intercepted += 1
        else:
            misses.append(label)

    def append_rights_ending(soup, slug, language="en"):
        body = soup.select_one(f'[data-language-body="{language}"]')
        rights = body.select_one(f'[data-fact-id="{slug}-rights-analysis"]')
        protection = body.select_one(f'[data-fact-id="{slug}-protection"]')
        sentences = batch10_final2_sentences(normalized_visible(rights))
        if not sentences:
            raise AssertionError("rights ending missing")
        protection.append(" " + sentences[-1])

    page_case(
        "Liu timeline-3 editor commentary",
        "liu-xiaobo",
        lambda soup: soup.select_one(
            '[data-language-body="en"] [data-fact-id="liu-xiaobo-timeline-3"]'
        ).append(" Indictment, trial, and sentencing are separate procedural nodes."),
        audit_batch10_semantics,
        "rejected batch-ten semantic",
    )
    page_case(
        "Liu copied rights/protection ending",
        "liu-xiaobo",
        lambda soup: append_rights_ending(soup, "liu-xiaobo"),
        audit_batch10_final2_named_semantics,
        "rights/protection",
    )
    page_case(
        "Tian copied rights/protection ending",
        "tiananmen-1989",
        lambda soup: append_rights_ending(soup, "tiananmen-1989"),
        audit_batch10_final2_named_semantics,
        "rights/protection",
    )
    page_case(
        "Tian unsupported State Council DOM actor",
        "tiananmen-1989",
        lambda soup: soup.select_one(
            '[data-language-body="zh"] '
            '[data-fact-id="tiananmen-1989-evidence-official-gap"]'
        ).__setitem__("data-accountability", "state-council"),
        audit_batch10_final2_structure,
        "state-council",
    )
    page_case(
        "Tian ambiguous title",
        "tiananmen-1989",
        lambda soup: (
            soup.select_one(".article-title .lang-zh").clear(),
            soup.select_one(".article-title .lang-zh").append(
                BATCH10_FINAL2_TIAN_AMBIGUOUS_TITLES["zh"]
            ),
        ),
        audit_batch10_final2_named_semantics,
        "ambiguous old title",
    )
    page_case(
        "Falun Gong workflow commentary",
        "falun-gong-persecution",
        lambda soup: soup.select_one(".article-dek .lang-en").append(
            " Each allegation is attributed individually."
        ),
        audit_batch10_semantics,
        "rejected batch-ten semantic",
    )
    page_case(
        "Jiangyou police actor deletion",
        "jiangyou-school-bullying-protests",
        lambda soup: replace_text(
            soup.select_one(".article-dek .lang-en"),
            "police dispersing the crowd", "the crowd dispersing",
        ),
        audit_batch10_final2_named_semantics,
        "police/platform/remedy summary anchor missing",
    )
    page_case(
        "Huang abstract information-space slogan",
        "huang-qi",
        lambda soup: (
            soup.select_one(".article-dek .lang-en").clear(),
            soup.select_one(".article-dek .lang-en").append(
                "Huang Qi criminalized the civil information space."
            ),
        ),
        audit_batch10_final2_named_semantics,
        "concrete website/prosecution summary anchor missing",
    )
    page_case(
        "Great Leap wrong German conventional name",
        "great-leap-famine",
        lambda soup: replace_text(
            soup.select_one(".article-title .lang-de"),
            "Großer Sprung nach vorn", "Großer Sprung und Hungersnot",
        ),
        audit_batch10_final2_named_semantics,
        "complete conventional name missing",
    )
    page_case(
        "Great Leap editor directive",
        "great-leap-famine",
        lambda soup: soup.select_one(".article-dek .lang-en").append(
            " None should be presented as a single official figure."
        ),
        audit_batch10_semantics,
        "rejected batch-ten semantic",
    )
    page_case(
        "Great Leap weakened German requisition",
        "great-leap-famine",
        lambda soup: (
            replace_text(
                soup.select_one(".article-title .lang-de"),
                "staatliche Zwangsrequisitionen von Getreide", "Getreideabgaben",
            ),
            soup.select_one(".article-dek .lang-de").clear(),
            soup.select_one(".article-dek .lang-de").append(
                "Getreideabgaben verschärften die Krise."
            ),
        ),
        audit_batch10_final2_named_semantics,
        "compulsory state grain requisition weakened",
    )
    page_case(
        "Land reform mechanical labour-punishment term",
        "land-reform-anti-rightist",
        lambda soup: replace_text(
            soup.select_one(".article-dek .lang-en"),
            "forced labour", "labour punishment",
        ),
        audit_batch10_final2_named_semantics,
        "natural work-team/labour term missing",
    )
    page_case(
        "Great Leap authorized timeline field reverted",
        "great-leap-famine",
        lambda soup: soup.select_one(
            '[data-language-body="en"] '
            '[data-fact-id="great-leap-famine-timeline-2"]'
        ).__setitem__(
            "data-timeline-action",
            "accelerated-peoples-communes-and-promoted-high-yield-campaigns-and-public-canteens",
        ),
        audit_batch10_final2_structure,
        "final2 timeline action must equal",
    )
    page_case(
        "Land reform non-authorized timeline actor drift",
        "land-reform-anti-rightist",
        lambda soup: soup.select_one(
            '[data-language-body="en"] '
            '[data-fact-id="land-reform-anti-rightist-timeline-5"]'
        ).__setitem__("data-timeline-subject", "anonymous-editors"),
        audit_batch10_final2_structure,
        "differs outside authorized final2 semantic fields",
    )

    before = audit_batch10_final2_frozen()
    for relative in BATCH10_FINAL2_FROZEN_SHA256:
        total += 1
        frozen_delta = new_issues(
            before,
            audit_batch10_final2_frozen(
                {relative: f"final2 frozen mutation:{relative}".encode("utf-8")}
            ),
        )
        if any(f"frozen file changed: {relative}" in issue for issue in frozen_delta):
            intercepted += 1
        else:
            misses.append(f"frozen file mutation: {relative}")

    total += 1
    script_text = (ROOT / "script.js").read_text(encoding="utf-8")
    card_pattern = re.compile(
        r'\{(?=[^{}]*url:\s*"posts/li-wenliang\.html")[^{}]*\}', re.S,
    )
    card_match = card_pattern.search(script_text)
    if card_match is None:
        misses.append("non-target card mutation: setup card missing")
    else:
        block = card_match.group(0)
        changed_block, substitutions = re.subn(
            r'(title_zh:\s*")([^"]*)(")',
            lambda match: match.group(1) + match.group(2) + " [mutated]" + match.group(3),
            block,
            count=1,
        )
        if substitutions != 1:
            misses.append("non-target card mutation: title field missing")
        else:
            mutated_script = (
                script_text[:card_match.start()] + changed_block
                + script_text[card_match.end():]
            )
            card_delta = new_issues(
                audit_batch10_cards(script_text=script_text),
                audit_batch10_cards(script_text=mutated_script),
            )
            if any("batch10 non-target card changed" in issue for issue in card_delta):
                intercepted += 1
            else:
                misses.append("non-target card mutation")

    total += 1
    frozen_card_pattern = re.compile(
        r'\{(?=[^{}]*url:\s*"posts/cultural-revolution\.html")[^{}]*\}', re.S,
    )
    frozen_card_match = frozen_card_pattern.search(script_text)
    if frozen_card_match is None:
        misses.append("final2 frozen Cultural Revolution card: setup card missing")
    else:
        block = frozen_card_match.group(0)
        changed_block, substitutions = re.subn(
            r'(title_en:\s*")([^"]*)(")',
            lambda match: match.group(1) + match.group(2) + " [mutated]" + match.group(3),
            block,
            count=1,
        )
        if substitutions != 1:
            misses.append("final2 frozen Cultural Revolution card: title field missing")
        else:
            mutated_script = (
                script_text[:frozen_card_match.start()] + changed_block
                + script_text[frozen_card_match.end():]
            )
            before_transition, _ = audit_batch10_final2_card_transition(
                script_text=script_text,
            )
            after_transition, _ = audit_batch10_final2_card_transition(
                script_text=mutated_script,
            )
            transition_delta = new_issues(before_transition, after_transition)
            if any("changed a frozen card" in issue for issue in transition_delta):
                intercepted += 1
            else:
                misses.append("final2 frozen Cultural Revolution card")

    return intercepted, total, misses


