def batch10_final3_target_node(pages, slug, language, kind, target_id):
    soup = pages.get(slug)
    if soup is None:
        return None
    if kind == "source-title":
        source_id = target_id.split(":", 1)[1] if ":" in target_id else ""
        return soup.select_one(
            f'[data-language-body="{language}"] li[data-source-id="{source_id}"] a'
        )
    return soup.select_one(
        f'[data-language-body="{language}"] [data-fact-id="{target_id}"]'
    )


def batch10_final3_preimage_pages(pages, reread_rows):
    """Reconstruct the authenticated final2 DOM for its historical audit.

    Only the hardcoded final3 repair keys can be restored.  The independent
    final3 chain audit separately requires every stored original to equal its
    exact final2 predecessor, so this compatibility view cannot authorize an
    unrelated rewrite.
    """
    restored = dict(pages)
    cloned = set()
    for row in reread_rows[
        BATCH10_FINAL2_REREAD_ROWS:
        BATCH10_FINAL2_REREAD_ROWS + BATCH10_FINAL3_REREAD_ROWS
    ]:
        key4 = batch10_final1_contract_key(row)
        if key4 not in BATCH10_FINAL3_TARGET_SET:
            continue
        slug, language, kind, target_id = key4
        if slug not in cloned:
            restored[slug] = deepcopy(pages[slug])
            cloned.add(slug)
        node = batch10_final3_target_node(
            restored, slug, language, kind, target_id,
        )
        if node is not None:
            node.clear()
            node.append(row.get("original_text", ""))
    return restored


def audit_batch10_final3_semantics(pages):
    issues = []
    tian = pages.get("tiananmen-1989")
    for language in BATCH5_LANGS:
        node = batch10_final3_target_node(
            pages, "tiananmen-1989", language, "fact",
            "tiananmen-1989-evidence-2",
        )
        label = f"tiananmen-1989/{language}/evidence-2"
        if node is None:
            issues.append(f"{label}: final3 target missing")
            continue
        text = normalized_visible(node)
        folded = text.casefold()
        if " ".join(node.get("data-source-ref", "").split()) != "s1 s3 s4":
            issues.append(f"{label}: final3 source relationship changed")
        for anchor in (*BATCH10_FINAL3_TIAN_SOURCE_ANCHORS[language], "1990", "2023", "202"):
            if anchor.casefold() not in folded:
                issues.append(f"{label}: independent evidence anchor missing: {anchor}")
        for anchor in BATCH10_FINAL3_TIAN_DECLARATIVE_ANCHORS[language]:
            if anchor.casefold() not in folded:
                issues.append(f"{label}: declarative independence anchor missing: {anchor}")
        for phrase in BATCH10_FINAL3_TIAN_IMPERATIVES[language]:
            if phrase.casefold() in folded:
                issues.append(f"{label}: editorial imperative returned: {phrase}")
        if language == "fr":
            if BATCH10_FINAL3_FRENCH_GOOD_SOURCE.casefold() not in folded:
                issues.append(f"{label}: natural French source grammar missing")
            if BATCH10_FINAL3_FRENCH_BAD_SOURCE.casefold() in folded:
                issues.append(f"{label}: rejected French source grammar returned")

    falun = pages.get("falun-gong-persecution")
    falun_rules = {
        "en": (
            ("Detention", "Article 300", "surveillance", "coercive ideological", "violated freedom of belief", "liberty", "bodily integrity", "fair-trial", "family contact", "Human-rights sources also document allegations", "right to life", "freedom from torture", "discriminatory testing", "forced-organ-harvesting allegations"),
            ("have affected freedom of belief", "not proven", "cannot prove", "not a judicial finding", "unconfirmed"),
        ),
        "ja": (
            ("拘禁", "刑法第300条", "監視", "思想転向", "を侵害した", "信仰の自由", "生命権", "拷問を受けない権利", "身体の自由・不可侵", "公正な裁判", "家族との連絡", "人権資料はさらに", "差別的検査", "強制的な臓器摘出", "申し立て"),
            ("に影響し", "証明できない", "司法認定ではない", "未確認"),
        ),
        "ko": (
            ("구금", "형법 제300조", "감시", "사상 전향", "침해했다", "신앙의 자유", "생명권", "고문받지 않을 권리", "신체의 자유", "온전성", "공정한 재판", "가족과 연락할 권리", "인권 자료는 또한", "차별적 검사", "강제 장기 적출", "의혹"),
            ("에 영향을 미쳤고", "입증할 수 없", "사법적 판단이 아니", "확인되지 않"),
        ),
    }
    for language, (required, forbidden) in falun_rules.items():
        node = batch10_final3_target_node(
            pages, "falun-gong-persecution", language, "fact",
            "falun-gong-persecution-rights-analysis",
        )
        label = f"falun-gong-persecution/{language}/rights-analysis"
        if node is None:
            issues.append(f"{label}: final3 target missing")
