def batch11_semantic_text(pages, slug, language):
    soup = pages.get(slug)
    body = soup.select_one(f'[data-language-body="{language}"]') if soup else None
    return batch11_norm(normalized_visible(body))


def batch11_fact_text(pages, slug, language, fact_id):
    soup = pages.get(slug)
    body = soup.select_one(f'[data-language-body="{language}"]') if soup else None
    node = body.select_one(f'[data-fact-id="{fact_id}"]') if body else None
    return batch11_norm(normalized_visible(node))


def batch11_markers_present(text, markers):
    return all(re.search(marker, text, re.I | re.S) is not None for marker in markers)


