def audit_batch11_semantics(pages, report_cards=None):
    issues = []
    for slug in BATCH11_SLUGS:
        for language in BATCH5_LANGS:
            visible = batch11_semantic_text(pages, slug, language)
            if not visible:
                issues.append(f"{slug}/{language}: batch11 semantic body missing")
                continue
            if len(visible) < 500:
                issues.append(f"{slug}/{language}: batch11 seven-part fact chain is implausibly short")
            if not batch11_markers_present(visible, BATCH11_REMEDY_PARTS[language]):
                issues.append(f"{slug}/{language}: batch11 independent effective remedy missing")

    for language in BATCH5_LANGS:
        state = batch11_fact_text(
            pages, "2024-report", language, "2024-report-state-1",
        )
        protection = batch11_fact_text(
            pages, "2024-report", language, "2024-report-protection",
        )
        if not batch11_markers_present(
            f"{state} {protection}", BATCH11_2024_ACTIONS[language],
        ):
            issues.append(f"2024-report/{language}: platform-action or collateral-pressure facts missing")

        hk12 = batch11_fact_text(
            pages, "hk-12", language, "hk-12-evidence-1",
        )
        if not batch11_markers_present(hk12, BATCH11_HK12_MARKERS[language]):
            issues.append(f"hk-12/{language}: maritime custody/lawyer/procedure chain missing")

        hk_stats = batch11_fact_text(
            pages, "hong-kong-update-2026", language,
            "hong-kong-update-2026-evidence-1",
        )
        if not all(number in compact_digits(hk_stats) for number in ("85", "89", "11")):
            issues.append(f"hong-kong-update-2026/{language}: 85/89/11 evidence triad missing")
        anna = batch11_fact_text(
            pages, "hong-kong-update-2026", language,
            "hong-kong-update-2026-rights-analysis",
        )
        if not batch11_markers_present(anna, BATCH11_ANNA_STATUS[language]):
            issues.append(f"hong-kong-update-2026/{language}: Anna Kwok family charge status missing")

        xt = " ".join((
            batch11_fact_text(
                pages, "xinjiang-tibet-forced-labour-2026", language,
                "xinjiang-tibet-forced-labour-2026-rights-analysis",
            ),
            batch11_fact_text(
                pages, "xinjiang-tibet-forced-labour-2026", language,
                "xinjiang-tibet-forced-labour-2026-protection",
            ),
        ))
        if not batch11_markers_present(xt, BATCH11_XT_MARKERS[language]):
            issues.append(f"xinjiang-tibet-forced-labour-2026/{language}: labour/family/religion/return chain missing")

        press = batch11_fact_text(
            pages, "press-freedom-2026", language,
            "press-freedom-2026-evidence-1",
        )
        if not all(number in compact_digits(press) for number in ("178", "180", "50", "7", "34")):
            issues.append(f"press-freedom-2026/{language}: 178/180/50/7/34 evidence set missing")
        if not batch11_markers_present(press, BATCH11_PRESS_ACTIONS[language]):
            issues.append(f"press-freedom-2026/{language}: press-control action/consequence chain missing")

        camps = batch11_semantic_text(pages, "xinjiang-camps", language)
        if not batch11_markers_present(camps, BATCH11_TURKIC_MUSLIMS[language]):
            issues.append(f"xinjiang-camps/{language}: Turkic-Muslim identity missing")

    if report_cards is None:
        report_cards, card_issues = batch9_final2_report_cards()
        report_cards = batch14_baseline_card_view(report_cards)
        issues.extend(card_issues)
    cards = {card.get("slug", ""): card for card in report_cards}
    public_values = []
    for slug in BATCH11_SLUGS:
        public_values.append(normalized_visible(pages.get(slug)))
    for slug in BATCH11_CARD_SLUGS:
        card = cards.get(slug, {})
        for language in BATCH5_LANGS:
            title = card.get(f"title_{language}", "")
            excerpt = card.get(f"excerpt_{language}", "")
            combined = batch11_norm(f"{title} {excerpt}")
            public_values.append(combined)
            if len(title) < 7 or len(excerpt) < 60:
                issues.append(f"script.js/{slug}/{language}: batch11 card is not a substantive summary")
            if slug == "2024-report" and not batch11_markers_present(
                combined, BATCH11_2024_ACTIONS[language],
            ):
                issues.append(f"script.js/{slug}/{language}: annual card lacks platform/family facts")
            if slug == "hong-kong-update-2026":
                if not all(number in compact_digits(combined) for number in ("85", "89", "11")):
                    issues.append(f"script.js/{slug}/{language}: card lacks 85/89/11 facts")
                if not batch11_markers_present(
                    combined, BATCH11_ANNA_STATUS[language][:-1],
                ):
                    issues.append(f"script.js/{slug}/{language}: card lacks Anna Kwok family status")
            if slug == "xinjiang-tibet-forced-labour-2026" and not batch11_markers_present(
                combined, BATCH11_XT_MARKERS[language],
            ):
                issues.append(f"script.js/{slug}/{language}: card lacks labour/family/return facts")
            if slug == "press-freedom-2026":
                if not all(number in compact_digits(combined) for number in ("178", "180", "50", "7", "34")):
                    issues.append(f"script.js/{slug}/{language}: card lacks 178/180/50/7/34 facts")
                if not batch11_markers_present(combined, BATCH11_PRESS_ACTIONS[language]):
                    issues.append(f"script.js/{slug}/{language}: card lacks press-control actions/consequences")
    folded_public = "\n".join(public_values).casefold()
    for phrase in BATCH11_FORBIDDEN_PHRASES:
        if phrase.casefold() in folded_public:
            issues.append(f"batch11 public disclaimer/mistranslation returned: {phrase}")
    return issues


def audit_batch11_ledgers(
    pages, *, reread_rows=None, contract_rows=None, check_files=True,
):
    """Authenticate the prefix, true preimage, 375 revisions, and contracts."""
    issues = []
    if check_files:
        issues.extend(batch9_final2_exact_prefix(
            BATCH9_REREAD_PATH, BATCH11_REREAD_ROWS,
            BATCH11_REREAD_SHA256, "batch11 reread prefix",
        ))
        issues.extend(batch9_final2_exact_prefix(
            BATCH9_CONTRACT_PATH, BATCH11_CONTRACT_ROWS,
            BATCH11_CONTRACT_SHA256, "batch11 contract prefix",
        ))
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11 semantic reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11 editorial contract ledger",
        )
        issues.extend(load_issues)
    reread_suffix = reread_rows[BATCH11_REREAD_ROWS:]
    contract_suffix = contract_rows[BATCH11_CONTRACT_ROWS:]
    if len(reread_suffix) != BATCH11_CHANGED_TARGETS:
        issues.append(
            f"batch11 reread suffix has {len(reread_suffix)} rows, "
            f"expected exactly {BATCH11_CHANGED_TARGETS}"
        )
    if len(contract_suffix) != BATCH11_CHANGED_TARGETS:
        issues.append(
            f"batch11 contract suffix has {len(contract_suffix)} rows, "
            f"expected exactly {BATCH11_CHANGED_TARGETS}"
        )

    targets, target_issues = batch11_dom_targets(pages)
    issues.extend(target_issues)
    if batch11_target_preimage_digest(targets, reread_suffix) != BATCH11_PREIMAGE_TARGET_SHA256:
        issues.append("batch11 reread originals do not reconstruct the true pre-edit target snapshot")

    predecessor_tips = batch11_prefix_tips(
        reread_rows[:BATCH11_REREAD_ROWS], kind="reread",
    )
    historic_contract_ids = {
        row.get("contract_id", "")
        for row in contract_rows[:BATCH11_CONTRACT_ROWS]
        if row.get("contract_id", "")
    }
    reread_by_id = {}
    reread_by_key = {}
    for row in reread_suffix:
        key = batch10_final1_contract_key(row)
        label = "/".join(key)
        contract_id = row.get("contract_id", "")
        if key in reread_by_key:
            issues.append(f"batch11 reread duplicates target: {label}")
        reread_by_key[key] = row
        if (
            key[0] not in BATCH11_SLUG_SET
            or key[1] not in BATCH5_LANGS
            or key[2] != "fact"
            or key not in targets
        ):
            issues.append(f"batch11 reread has non-fact or out-of-scope target: {label}")
        if not contract_id.startswith(BATCH11_PREFIX):
            issues.append(f"batch11 reread has wrong contract prefix: {label}")
        if not contract_id or contract_id in reread_by_id or contract_id in historic_contract_ids:
            issues.append(f"batch11 reread contract id is blank or duplicate: {label}")
        reread_by_id[contract_id] = row
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11 reread is not PASS_AFTER_REVISION: {label}")
        if row.get("result", "") == "PASS_NO_CHANGE":
            issues.append(f"batch11 reread uses forbidden PASS_NO_CHANGE: {label}")
        if not row.get("issue_found", "").startswith("reread:batch11"):
            issues.append(f"batch11 reread lacks issue evidence: {label}")
        if not row.get("review_basis", "").startswith("reread:batch11"):
            issues.append(f"batch11 reread lacks review evidence: {label}")
        if row.get("original_text", "") == row.get("revised_text", ""):
            issues.append(f"batch11 reread records no real text change: {label}")
        live = targets.get(key)
        if live is not None:
            if batch11_norm(row.get("revised_text", "")) != live["text"]:
                issues.append(f"batch11 reread revised text differs from DOM: {label}")
            if batch11_norm(row.get("source_refs", "")) != live["source_refs"]:
                issues.append(f"batch11 reread source refs differ from DOM: {label}")
        predecessor = predecessor_tips.get(key)
        if key[0] == "xinjiang-tibet-forced-labour-2026":
            if predecessor is not None:
                issues.append(f"batch11 XT first-tip row unexpectedly has a prior reread tip: {label}")
        elif predecessor is None:
            issues.append(f"batch11 reread lacks predecessor chain tip: {label}")
        elif batch11_norm(row.get("original_text", "")) != batch11_norm(
            predecessor.get("revised_text", "")
        ):
            issues.append(f"batch11 reread predecessor chain is broken: {label}")

    contract_by_id = {}
    contract_by_key = {}
    for row in contract_suffix:
        key = batch10_final1_contract_key(row)
        label = "/".join(key)
        contract_id = row.get("contract_id", "")
        if key in contract_by_key:
            issues.append(f"batch11 contract duplicates target: {label}")
        contract_by_key[key] = row
        if (
            key[0] not in BATCH11_SLUG_SET
            or key[1] not in BATCH5_LANGS
            or key[2] != "fact"
            or key not in targets
        ):
            issues.append(f"batch11 contract has non-fact or out-of-scope target: {label}")
        if not contract_id.startswith(BATCH11_PREFIX):
            issues.append(f"batch11 contract has wrong prefix: {label}")
        if not contract_id or contract_id in contract_by_id or contract_id in historic_contract_ids:
            issues.append(f"batch11 contract id is blank or duplicate: {label}")
        contract_by_id[contract_id] = row
        required = batch9_final2_contract_literals(row.get("required_all", ""))
        forbidden = batch9_final2_contract_literals(row.get("forbidden_any", ""))
        required_labels = {value.split(":", 1)[0].casefold() for value in required}
        if len(set(required)) < 4 or not {
            "actor", "action", "consequence", "source", "remedy",
        }.issubset(required_labels):
            issues.append(f"batch11 contract lacks independent actor/action/consequence/source/remedy: {label}")
        if len(set(forbidden)) < 2 or any(
            not value.casefold().startswith("old-error:") for value in forbidden
        ):
            issues.append(f"batch11 contract lacks two genuine old-error classes: {label}")
        summary = row.get("fact_summary", "").casefold()
        if len(summary) < 180 or any(marker not in summary for marker in (
            "subject:", "action:", "source:", "consequence:", "remedy:",
            "why more accurate:",
        )):
            issues.append(f"batch11 contract summary is not a full case-specific analysis: {label}")

    if set(reread_by_key) != set(contract_by_key):
        issues.append("batch11 reread and contract target coverage is not one-to-one")
    if set(reread_by_id) != set(contract_by_id):
        issues.append("batch11 reread and contract IDs are not one-to-one")
    for contract_id in set(reread_by_id) & set(contract_by_id):
        if batch10_final1_contract_key(reread_by_id[contract_id]) != (
            batch10_final1_contract_key(contract_by_id[contract_id])
        ):
            issues.append(f"batch11 paired contract points elsewhere: {contract_id}")
    return issues, {
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "changed_keys": frozenset(reread_by_key),
        "reread_by_key": reread_by_key,
    }


def audit_batch11_source_ledger(
    pages, *, source_rows=None, reread_rows=None, report_cards=None,
    check_file=True,
):
    """Validate one source overlay for every and only changed visible fact."""
    issues = []
    if check_file:
        issues.extend(batch9_final2_exact_prefix(
            BATCH9_SOURCE_LEDGER_PATH, BATCH11_SOURCE_ROWS,
            BATCH11_SOURCE_SHA256, "batch11 source-ledger prefix",
        ))
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11 source ledger",
        )
        issues.extend(load_issues)
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11 source/reread pairing ledger",
        )
        issues.extend(load_issues)
    if report_cards is None:
        report_cards, card_issues = batch9_final2_report_cards()
        report_cards = batch14_baseline_card_view(report_cards)
        issues.extend(card_issues)
    report_by_slug = {card.get("slug", ""): card for card in report_cards}

    suffix = source_rows[BATCH11_SOURCE_ROWS:]
    if len(suffix) != BATCH11_CHANGED_TARGETS:
        issues.append(
            f"batch11 source suffix has {len(suffix)} rows, "
            f"expected exactly {BATCH11_CHANGED_TARGETS}"
        )
    prefix_tips = batch11_prefix_tips(
        source_rows[:BATCH11_SOURCE_ROWS], kind="source",
    )
    targets, target_issues = batch11_dom_targets(pages)
    issues.extend(target_issues)
    fact_targets = {
        (key[0], key[1], key[3]): value
        for key, value in targets.items() if key[2] == "fact"
    }
    if len(prefix_tips) != len(fact_targets) or set(prefix_tips) != set(fact_targets):
        issues.append(
            "batch11 source prefix does not provide one authenticated tip for all 1,670 facts"
        )
    expected_changed = {
        key for key, live in fact_targets.items()
        if key in prefix_tips and (
            batch11_norm(prefix_tips[key].get("current_visible_text", "")) != live["text"]
            or batch11_norm(prefix_tips[key].get("data_source_ref", "")) != live["source_refs"]
        )
    }
    reread_by_key = {
        (row.get("slug", ""), row.get("language", ""), row.get("target_id", "")): row
        for row in reread_rows[BATCH11_REREAD_ROWS:]
        if row.get("target_kind", "") == "fact"
    }
    seen = set()
    mutable = {
        "current_visible_text", "data_source_ref", "baseline_issue",
        "resolution_action", "support_urls", "locatable_support", "source_roles",
        "audit_claim_compared", "source_date_audit", "reread_timeline_current",
        "reread_rights_current", "reread_protection_current",
        "reread_source_titles_current",
        "reread_issue_found", "reread_revision_text", "reread_result",
        "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor", "visible_timeline_order",
        "visible_source_roles",
    }
    for row in suffix:
        key = (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        label = "/".join(key)
        if key in seen:
            issues.append(f"batch11 source overlay duplicates target: {label}")
        seen.add(key)
        predecessor = prefix_tips.get(key)
        reread = reread_by_key.get(key)
        if key not in fact_targets:
            issues.append(f"batch11 source overlay has out-of-scope target: {label}")
        if predecessor is None:
            issues.append(f"batch11 source overlay lacks authenticated predecessor: {label}")
        else:
            for field in BATCH9_FINAL2_SOURCE_COLUMNS:
                if field in mutable:
                    continue
                if row.get(field, "") != predecessor.get(field, ""):
                    issues.append(f"batch11 source overlay changed protected field {field}: {label}")
                    break
            if row.get("data_source_ref", "") != predecessor.get("data_source_ref", ""):
                if batch11_norm(row.get("current_visible_text", "")) == batch11_norm(
                    predecessor.get("current_visible_text", "")
                ):
                    issues.append(f"batch11 source refs changed without a visible fact revision: {label}")
        if reread is None:
            issues.append(f"batch11 source-only row lacks paired fact reread: {label}")
        else:
            if row.get("baseline_issue", "") != reread.get("contract_id", ""):
                issues.append(f"batch11 source baseline marker differs from paired contract: {label}")
            if row.get("reread_issue_found", "") != reread.get("issue_found", ""):
                issues.append(f"batch11 source issue evidence differs from paired reread: {label}")
            if batch11_norm(row.get("reread_revision_text", "")) != batch11_norm(
                reread.get("revised_text", "")
            ):
                issues.append(f"batch11 source revision differs from paired reread: {label}")
        if "batch11" not in row.get("resolution_action", ""):
            issues.append(f"batch11 source overlay lacks resolution marker: {label}")
        if row.get("reread_result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11 source overlay is not PASS_AFTER_REVISION: {label}")
        live_fields = batch11_live_fact_fields(
            pages, *key, report_by_slug=report_by_slug,
        )
        if live_fields is None:
            issues.append(f"batch11 source overlay live fact missing: {label}")
            continue
        for field, value in live_fields.items():
            if field == "reread_card_current":
                continue
            if batch11_norm(row.get(field, "")) != batch11_norm(value):
                issues.append(f"batch11 source overlay {field} differs from live public state: {label}")
        if batch11_norm(row.get("audit_claim_compared", "")) != live_fields["current_visible_text"]:
            issues.append(f"batch11 source audit claim is stale: {label}")

        slug, language, _fact_id = key
        body = pages[slug].select_one(f'[data-language-body="{language}"]')
        source_nodes = {
            node.get("data-source-id", ""): node
            for node in body.select("ul.source-list > li[data-source-id]")
        }
        refs = row.get("data_source_ref", "").split()
        expected_urls = " | ".join(
            source_nodes[source_id].find("a").get("href", "")
            for source_id in refs if source_id in source_nodes
        )
        expected_locators = " | ".join(
            f"{source_id}: {normalized_visible(source_nodes[source_id].find('a'))}"
            for source_id in refs if source_id in source_nodes
        )
        expected_dates = " | ".join(
            f"{source_id}={source_nodes[source_id].get('data-source-date', '') or 'UNDATED'}"
            for source_id in refs if source_id in source_nodes
        )
        if row.get("support_urls", "") != expected_urls:
            issues.append(f"batch11 source support URLs do not follow live refs: {label}")
        if row.get("locatable_support", "") != expected_locators:
            issues.append(f"batch11 source locators do not follow live refs: {label}")
        if row.get("source_date_audit", "") != expected_dates:
            issues.append(f"batch11 source date projection does not follow live refs: {label}")
        for field in ("source_roles", "visible_source_roles"):
            role_ids = [part.split(":", 1)[0].strip() for part in row.get(field, "").split(" | ") if part]
            if role_ids != refs:
                issues.append(f"batch11 source role IDs do not follow live refs in {field}: {label}")
        if row.get("source_roles", "") != row.get("visible_source_roles", ""):
            issues.append(f"batch11 source role projections disagree: {label}")
        if row.get("timeline_action", ""):
            visible_stream = re.sub(
                r"\d", "", final1_contiguous_stream(live_fields["current_visible_text"])
            )
            for field in (
                "visible_subject_anchor", "visible_action_anchor",
                "visible_consequence_anchor",
            ):
                anchor = re.sub(
                    r"\d", "", final1_contiguous_stream(row.get(field, ""))
                )
                if not anchor or anchor not in visible_stream:
                    issues.append(f"batch11 timeline {field} is blank or unlocatable: {label}")
            if not row.get("visible_timeline_order", "").isdigit():
                issues.append(f"batch11 timeline order is not explicit: {label}")

    if seen != expected_changed:
        issues.append(
            "batch11 source overlay coverage differs from recomputed visible/ref changes: "
            f"missing={len(expected_changed-seen)} extra={len(seen-expected_changed)}"
        )
    if seen != set(reread_by_key):
        issues.append("batch11 source overlays and fact rereads are not exact one-to-one pairs")
    return issues, {"source_rows": len(suffix), "changed_keys": frozenset(seen)}


def audit_batch11_wiring(source_text=None):
    """The authoritative live path must call the complete batch11 audit once."""
    if source_text is None:
        source_text = Path(__file__).read_text(encoding="utf-8")
    match = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    needle = "issues.extend(audit_batch11(pages))"
    return [] if match is not None and match.group("body").count(needle) == 1 else [
        "batch11 authoritative audit_live wiring is absent"
    ]


def audit_batch11(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    report_cards=None, script_text=None, frozen_overrides=None,
    check_files=True,
):
    issues = []
    # Once final1 exists, the historical batch11 gate receives only its exact
    # completed state.  The successor suffix is audited separately below and
    # is never allowed to inflate the old 375-row classification.
    if reread_rows is None:
        loaded, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11 historical reread state",
        )
        issues.extend(load_issues)
        reread_rows = loaded[:BATCH11_FINAL1_REREAD_ROWS]
    if contract_rows is None:
        loaded, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11 historical contract state",
        )
        issues.extend(load_issues)
        contract_rows = loaded[:BATCH11_FINAL1_CONTRACT_ROWS]
    if source_rows is None:
        loaded, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11 historical source state",
        )
        issues.extend(load_issues)
        source_rows = loaded[:BATCH11_FINAL1_SOURCE_ROWS]
    issues.extend(audit_batch11_page_integrity(pages))
    issues.extend(audit_batch11_sources(pages))
    issues.extend(audit_batch11_cards(report_cards, script_text))
    issues.extend(audit_batch11_semantics(pages, report_cards))
    ledger_issues, _ledger_stats = audit_batch11_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        check_files=check_files,
    )
    issues.extend(ledger_issues)
    source_issues, _source_stats = audit_batch11_source_ledger(
        pages, source_rows=source_rows, reread_rows=reread_rows,
        report_cards=report_cards, check_file=check_files,
    )
    issues.extend(source_issues)
    issues.extend(audit_batch11_frozen(frozen_overrides))
    issues.extend(audit_batch11_wiring())
    return issues


def batch11_negative_self_test(pages):
    """Exercise exactly the twenty named batch-eleven regression classes."""
    names = []
    misses = []

    def record(name, caught):
        names.append(name)
        if not caught:
            misses.append(name)

    def phrase_caught(slug, language, fact_id, phrase):
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        node = mutated[slug].select_one(
            f'[data-language-body="{language}"] [data-fact-id="{fact_id}"]'
        )
        node.append(" " + phrase)
        return bool(audit_batch11_semantics(mutated))

    phrase_cases = (
        (
            "01 cannot-replace disclaimer reinsertion",
            ("cannot replace", "不能替代", "置き換えることはできない"),
            "2024-report", ("en", "zh", "ja"), "2024-report-evidence-1",
        ),
        (
            "02 only-used disclaimer reinsertion",
            ("only used", "只用于", "のみ使用"),
            "2024-report", ("en", "zh", "ja"), "2024-report-evidence-2",
        ),
        (
            "03 must-not-upgrade/recast reinsertion",
            ("must not be upgraded", "不得升级", "不得改写成"),
            "hong-kong-update-2026", ("en", "zh", "zh"),
            "hong-kong-update-2026-rights-analysis",
        ),
        (
            "04 not-a-judicial-finding reinsertion",
            ("not a judicial finding", "不是司法裁判"),
            "press-freedom-2026", ("en", "zh"), "press-freedom-2026-evidence-1",
        ),
        (
            "05 preserve-links-and-dates reinsertion",
            ("must preserve links", "必须保存链接日期"),
            "xinjiang-tibet-forced-labour-2026", ("en", "zh"),
            "xinjiang-tibet-forced-labour-2026-evidence-1",
        ),
        (
            "06 silence-cannot-prove reinsertion",
            ("silence cannot prove", "沉默不能证明"),
            "2024-report", ("en", "zh"), "2024-report-protection",
        ),
    )
    for name, phrases, slug, languages, fact_id in phrase_cases:
        record(name, all(
            phrase_caught(slug, language, fact_id, phrase)
            for language, phrase in zip(languages, phrases)
        ))

    record(
        "07 German platform-deletion mistranslation",
        phrase_caught(
            "2024-report", "de", "2024-report-state-1",
            "Löschung der Plattform",
        ),
    )
    record(
        "08 maritime interception mistranslations",
        all(phrase_caught("hk-12", language, "hk-12-evidence-1", phrase)
            for language, phrase in (
                ("no", "maritime avlyttingen"), ("zh", "海上傍受"),
                ("ko", "해상 감청"),
            )),
    )
    record(
        "09 Italian boarding mistranslation",
        phrase_caught(
            "xinjiang-tibet-forced-labour-2026", "it",
            "xinjiang-tibet-forced-labour-2026-evidence-1",
            "modalità di imbarco",
        ),
    )
    record(
        "10 French independent-workers mistranslation",
        phrase_caught(
            "xinjiang-tibet-forced-labour-2026", "fr",
            "xinjiang-tibet-forced-labour-2026-evidence-1",
            "travailleurs indépendants",
        ),
    )
    record(
        "11 Turkish-minority identity mistranslations",
        all(phrase_caught("xinjiang-camps", language, "xinjiang-camps-overview-2", phrase)
            for language, phrase in (
                ("en", "Turkish minority"), ("fr", "musulmans turcs"),
                ("de", "türkische Minderheit"), ("nl", "Turkse minderheid"),
            )),
    )
    record(
        "12 Korean return/report mistranslation",
        phrase_caught("chen-qiushi", "ko", "chen-qiushi-protection", "반환, 갱신된 보고"),
    )

    def fact_deletions_caught(slug, language, fact_id, tokens):
        caught = []
        for token in tokens:
            mutated = dict(pages)
            mutated[slug] = deepcopy(pages[slug])
            node = mutated[slug].select_one(
                f'[data-language-body="{language}"] [data-fact-id="{fact_id}"]'
            )
            visible = normalized_visible(node)
            node.clear()
            node.append(visible.replace(token, ""))
            caught.append(bool(audit_batch11_semantics(mutated)))
        return all(caught)

    record(
        "13 Hong Kong 85/89/11 deletion",
        fact_deletions_caught(
            "hong-kong-update-2026", "en",
            "hong-kong-update-2026-evidence-1", ("85", "89", "11"),
        ),
    )
    record(
        "14 Anna Kwok father/brother/only-father-charged deletion",
        fact_deletions_caught(
            "hong-kong-update-2026", "en",
            "hong-kong-update-2026-rights-analysis",
            ("father", "brother", "only her father"),
        ),
    )
    record(
        "15 press 178/180/50/7/34 deletion",
        fact_deletions_caught(
            "press-freedom-2026", "en", "press-freedom-2026-evidence-1",
            ("178", "180", "50", "7", "34"),
        ),
    )

    cards, card_issues = batch9_final2_report_cards()
    cards = batch14_baseline_card_view(cards)
    card_by_slug = {card.get("slug", ""): card for card in cards}
    xt_tokens = (
        "labour transfers", "boarding education", "family separation",
        "religion", "language", "monitoring", "return", "deportation",
        "non-refoulement",
    )
    xt_caught = []
    for token in xt_tokens:
        mutated_cards = deepcopy(cards)
        card = next(
            value for value in mutated_cards
            if value.get("slug") == "xinjiang-tibet-forced-labour-2026"
        )
        for field in ("title_en", "excerpt_en"):
            card[field] = re.sub(re.escape(token), "", card[field], flags=re.I)
        xt_caught.append(bool(audit_batch11_semantics(pages, mutated_cards)))
    record(
        "16 Xinjiang/Tibet labour/boarding/family/religion/return deletion",
        not card_issues and all(xt_caught),
    )

    protected_caught = []
    for field in ("title_en", "excerpt_en", "date", "url"):
        mutated_cards = deepcopy(cards)
        card = next(value for value in mutated_cards if value.get("slug") == "causeway-bay-books")
        card[field] += "-tampered"
        protected_caught.append(bool(audit_batch11_cards(report_cards=mutated_cards)))
    record(
        "17 non-target card title/excerpt/date/url tamper",
        not card_issues and all(protected_caught),
    )

    metadata_caught = []
    for mutation in ("id", "url", "type", "date", "order"):
        mutated = dict(pages)
        mutated["2024-report"] = deepcopy(pages["2024-report"])
        body = mutated["2024-report"].select_one('[data-language-body="zh"]')
        sources = body.select("ul.source-list > li[data-source-id]")
        if mutation == "id":
            sources[0]["data-source-id"] = "s1-tampered"
        elif mutation == "url":
            sources[0].find("a")["href"] += "?tampered=1"
        elif mutation == "type":
            sources[0]["data-source-type"] += " tampered"
        elif mutation == "date":
            sources[0]["data-source-date"] = "2099-01-01"
        else:
            sources[-1].extract()
            sources[0].insert_before(sources[-1])
        metadata_caught.append(bool(audit_batch11_sources(mutated)))
    record("18 source ID/URL/type/date/order tamper", all(metadata_caught))

    source_text = Path(__file__).read_text(encoding="utf-8")
    record(
        "19 mandatory batch11 wiring deletion",
        bool(audit_batch11_wiring(source_text.replace(
            "issues.extend(audit_batch11(pages))", "# batch11 call removed",
        ))),
    )

    mutated = dict(pages)
    mutated["press-freedom-2026"] = deepcopy(pages["press-freedom-2026"])
    shell = mutated["press-freedom-2026"].select_one(
        '[data-language-body="en"] [data-fact-id="press-freedom-2026-evidence-1"]'
    )
    shell.clear()
    shell.append("RSF CPJ Amnesty 178 180 50 7 34.")
    record(
        "20 institution-and-number shell without action/consequence",
        bool(audit_batch11_semantics(mutated)),
    )
    if len(names) != 20 or len(set(names)) != 20:
        misses.append(f"batch11 named suite cardinality is {len(names)}, expected 20")
    return len(names) - len(misses), len(names), misses


# ---------------------------------------------------------------------------
# Batch eleven final1: authenticated successor replay and live target surface.


def batch11_final1_dom_targets(pages):
    """Enumerate title, deck, leaf facts and source titles on the six pages."""
    targets = {}
    issues = []

    def add(key, kind, text, refs):
        if key in targets:
            issues.append(f"batch11-final1 duplicate target: {'/'.join(key)}")
            return
        targets[key] = {
            "target_kind": kind,
            "text": batch11_norm(text),
            "source_refs": batch11_norm(refs),
        }

    for slug in BATCH11_FINAL1_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"batch11-final1 page missing: {slug}")
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"batch11-final1 body missing: {slug}/{language}")
                continue
            source_nodes = body.select("ul.source-list > li[data-source-id]")
            source_ids = [node.get("data-source-id", "") for node in source_nodes]
            page_refs = "page-sources:" + " ".join(source_ids)
            for kind, target_id, selector in (
                ("article-title", "article-title", f".article-title .lang-{language}"),
                ("article-dek", "article-dek", f".article-dek .lang-{language}"),
            ):
                node = soup.select_one(selector)
                if node is None:
                    issues.append(f"batch11-final1 target missing: {slug}/{language}/{target_id}")
                else:
                    add((slug, language, kind, target_id), kind,
                        normalized_visible(node), page_refs)
            for node in body.select("[data-fact-id]"):
                if node.select_one("[data-fact-id]"):
                    continue
                target_id = node.get("data-fact-id", "")
                if not target_id or target_id.endswith("-sources"):
                    continue
                add((slug, language, "fact", target_id), "fact",
                    normalized_visible(node), node.get("data-source-ref", ""))
            for source in source_nodes:
                source_id = source.get("data-source-id", "")
                anchor = source.find("a")
                if not source_id or anchor is None:
                    issues.append(f"batch11-final1 malformed source: {slug}/{language}")
                    continue
                add((slug, language, "source-title", f"source-title:{source_id}"),
                    "source-title", normalized_visible(anchor), source_id)
    return targets, issues


def batch11_final1_target_node(pages, key4):
    slug, language, kind, target_id = key4
    soup = pages.get(slug)
    if soup is None:
        return None
    if kind == "article-title":
        return soup.select_one(f".article-title .lang-{language}")
    if kind == "article-dek":
        return soup.select_one(f".article-dek .lang-{language}")
    if kind == "source-title":
        source_id = target_id.split(":", 1)[1] if ":" in target_id else ""
        return soup.select_one(
            f'[data-language-body="{language}"] li[data-source-id="{source_id}"] a'
        )
    return soup.select_one(
        f'[data-language-body="{language}"] [data-fact-id="{target_id}"]'
    )


def batch11_final1_first_sentence(text):
    text = batch11_norm(text)
    endings = [text.find(mark) for mark in ".!?。！？" if text.find(mark) >= 0]
    return text[:min(endings) + 1] if endings else text


def batch11_final1_restore_text(node, kind, original):
    """Restore visible text without destroying the authenticated tag shape."""
    if node is None:
        return False
    if kind != "fact":
        node.clear()
        node.append(original)
        return True
    critical = node.select_one("[data-critical-case]")
    if critical is not None:
        critical.clear()
        critical.append(original)
        critical["data-critical-case"] = batch11_final1_first_sentence(original)
        return True
    # Timeline labels use either <b> or <strong> across historical batches;
    # preserve whichever authenticated tag is present while replacing only
    # the visible date-and-description stream.
    bold = node.find(["b", "strong"], recursive=False)
    if bold is not None:
        match = re.match(r"^(.{1,60}?(?:：|:))\s*(.*)$", original, re.S)
        if match is None:
            return False
        bold.extract()
        node.clear()
        bold.clear()
        bold.append(match.group(1))
        node.append(bold)
        if match.group(2):
            node.append(" " + match.group(2))
        return True
    node.clear()
    node.append(original)
    return True


def batch11_final1_legacy_pages(pages, reread_rows=None, source_rows=None):
    """Replay the exact pre-final1 state in memory; never write it to disk."""
    if reread_rows is None:
        reread_rows, _ = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11-final1 replay reread",
        )
    if source_rows is None:
        source_rows, _ = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11-final1 replay source",
        )
    legacy = dict(pages)
    for slug in BATCH11_FINAL1_SLUGS:
        if slug in pages:
            legacy[slug] = deepcopy(pages[slug])

    # Restore every relation/attribute from the last authenticated source row
    # at the completed batch11 boundary.  This is independent of final1 prose.
    source_tips = batch11_prefix_tips(
        source_rows[:BATCH11_FINAL1_SOURCE_ROWS], kind="source",
    )
    attr_fields = (
        ("data-source-ref", "data_source_ref"),
        ("data-timeline-subject", "timeline_subject"),
        ("data-timeline-action", "timeline_action"),
        ("data-timeline-consequence", "timeline_consequence"),
    )
    for (slug, language, fact_id), predecessor in source_tips.items():
        if slug not in BATCH11_FINAL1_SLUG_SET:
            continue
        node = legacy[slug].select_one(
            f'[data-language-body="{language}"] [data-fact-id="{fact_id}"]'
        )
        if node is None:
            continue
        for attribute, field in attr_fields:
            value = predecessor.get(field, "")
            if value:
                node[attribute] = value
            elif node.has_attr(attribute):
                del node[attribute]

    for row in reread_rows[
        BATCH11_FINAL1_REREAD_ROWS:BATCH11_FINAL2_REREAD_ROWS
    ]:
        key = batch10_final1_contract_key(row)
        if key[0] not in BATCH11_FINAL1_SLUG_SET:
            continue
        node = batch11_final1_target_node(legacy, key)
        batch11_final1_restore_text(
            node, row.get("target_kind", ""), row.get("original_text", ""),
        )

    # The final1 HK12 evidence-gap paragraph also narrows two pre-existing
    # machine-readable dispute-matrix fields.  The exact predecessor values
    # are fixed here and then authenticated by the full-page preimage hash;
    # the live values are independently required in the semantic audit.
    hk12 = legacy.get("hk-12")
    if hk12 is not None:
        for node in hk12.select('[data-fact-id="hk-12-evidence-official-gap"]'):
            node["data-official-response"] = (
                "coast-guard-shenzhen-police-procuratorate-and-yantian-court-border-crime-record"
            )
            node["data-response-gap"] = (
                "interception-files-custody-and-lawyer-waiver-records-open-hearings-"
                "consular-access-and-individual-remedy"
            )

    # HK12/s6 did not exist in the authenticated preimage.  Its ten localized
    # titles have empty originals in the successor ledger and the entire rows
    # are removed from the historical view here.
    hk12 = legacy.get("hk-12")
    if hk12 is not None:
        for node in list(hk12.select('li[data-source-id="s6"]')):
            node.decompose()
    return legacy


def batch11_final1_target_payload(targets):
    return "".join(
        json.dumps(
            [*key, targets[key]["text"], targets[key]["source_refs"]],
            ensure_ascii=False, separators=(",", ":"),
        ) + "\n"
        for key in targets
    ).encode("utf-8")


def batch11_final1_page_payload(soup):
    rows = []
    for index, node in enumerate(soup.find_all(True)):
        attributes = []
        for attribute, raw in sorted(node.attrs.items()):
            value = " ".join(raw) if isinstance(raw, list) else str(raw)
            attributes.append([attribute, value])
        direct = []
        for child in node.children:
            if isinstance(child, NavigableString):
                value = batch11_norm(str(child))
                if value:
                    direct.append(value)
        rows.append([index, node.name, attributes, direct])
    return ("\n".join(
        json.dumps(row, ensure_ascii=False, separators=(",", ":"))
        for row in rows
    ) + "\n").encode("utf-8")


def audit_batch11_final1_preimage(pages, reread_rows, source_rows):
    issues = []
    legacy = batch11_final1_legacy_pages(
        pages, reread_rows=reread_rows, source_rows=source_rows,
    )
    targets, target_issues = batch11_final1_dom_targets(legacy)
    issues.extend(target_issues)
    if len(targets) != BATCH11_FINAL1_PREIMAGE_TARGET_ROWS:
        issues.append(
            f"batch11-final1 reconstructed preimage has {len(targets)} targets, "
            f"expected {BATCH11_FINAL1_PREIMAGE_TARGET_ROWS}"
        )
    if hashlib.sha256(batch11_final1_target_payload(targets)).hexdigest() != (
        BATCH11_FINAL1_PREIMAGE_TARGET_SHA256
    ):
        issues.append("batch11-final1 ledger originals do not reconstruct the true preimage")
    for slug, expected in BATCH11_FINAL1_PREIMAGE_PAGE_SHA256.items():
        soup = legacy.get(slug)
        if soup is None:
            continue
        digest = hashlib.sha256(batch11_final1_page_payload(soup)).hexdigest()
        if digest != expected:
            issues.append(f"{slug}: batch11-final1 changed markup/attributes outside its recorded transition")
    return issues, legacy, targets


def audit_batch11_final1_frozen(overrides=None):
    overrides = overrides or {}
    records = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        if ".git" in relative_path.parts or path.name == ".DS_Store":
            continue
        if relative in BATCH11_FINAL1_ALLOWED_FILES:
            continue
        payload = overrides.get(relative, path.read_bytes())
        if batch11_final1_is_desktop_extra(relative, payload):
            continue
        records.append((relative, len(payload), hashlib.sha256(payload).hexdigest()))
    canonical = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(records)
    ).encode("utf-8")
    issues = []
    if len(records) != BATCH11_FINAL1_PROTECTED_FILES:
        issues.append(
            f"batch11-final1 protected manifest has {len(records)} files, "
            f"expected {BATCH11_FINAL1_PROTECTED_FILES}"
        )
    if hashlib.sha256(canonical).hexdigest() != BATCH11_FINAL1_PROTECTED_SHA256:
        issues.append("batch11-final1 changed a non-target or frozen file")
    script = overrides.get("script.js", (ROOT / "script.js").read_bytes())
    if isinstance(script, str):
        script = script.encode("utf-8")
    if hashlib.sha256(script).hexdigest() != BATCH11_FINAL1_SCRIPT_SHA256:
        issues.append("batch11-final1 changed script.js or a 54-card field")
    for relative in overrides:
        if relative in BATCH11_FINAL1_ALLOWED_FILES:
            issues.append(f"batch11-final1 freeze override targets an allowed file: {relative}")
    return issues


