def batch11_final1_target_action(target_id, kind):
    if kind == "article-title":
        return "identify-the-case-and-evidence-scope-without-generic-dossier-language"
    if kind == "article-dek":
        return "summarize-the-verified-state-action-source-role-consequence-and-remedy-chain"
    if kind == "source-title":
        if target_id == "source-title:s6":
            return "identify-the-HKFP-2021-eight-person-seven-month-transfer-report"
        return "name-the-cited-source-and-its-document-role-accurately"
    special = {
        "hk-12-timeline-3": "HRW-records-family-lawyer-denial-and-official-appointed-lawyer-claim-and-demands-access",
        "hk-12-timeline-5": "record-the-2020-12-30-sentences-and-minors-return-from-s4",
        "hk-12-timeline-6": "record-the-2021-03-22-eight-person-seven-month-transfer-and-Hong-Kong-police-processing-from-s6",
        "xinjiang-camps-timeline-4": "record-NYT-publication-of-internal-government-speeches-directives-and-implementation-reports",
        "press-freedom-2026-rights-analysis": "state-the-complete-journalist-control-source-risk-professional-harm-and-remedy-chain",
    }
    if target_id in special:
        return special[target_id]
    if "timeline-" in target_id:
        return "record-a-dated-actor-action-consequence-and-cited-source-without-role-reversal"
    if "overview" in target_id:
        return "describe-the-case-subject-state-action-and-evidence-boundary"
    if "evidence" in target_id:
        return "separate-source-findings-official-claims-response-gaps-and-accountability"
    if "state" in target_id:
        return "identify-the-responsible-state-machinery-and-pressure-path"
    if "rights-analysis" in target_id:
        return "connect-state-action-second-harm-accountability-and-effective-remedy"
    if "protection" in target_id:
        return "connect-identification-family-and-cross-border-pressure-to-individual-remedy"
    if "unresolved" in target_id:
        return "specify-missing-records-independent-investigation-and-effective-remedy"
    return "preserve-the-target-bound-case-fact-source-role-and-remedy"


def batch11_final1_contract_spec(key4):
    slug, language, kind, target_id = key4
    base = BATCH11_FINAL1_CONTRACT_BLUEPRINTS[slug]
    action = batch11_final1_target_action(target_id, kind)
    required = "||".join((
        "actor:" + base["actor"], "action:" + action,
        "consequence:" + base["consequence"], "source:" + base["source"],
        "remedy:" + base["remedy"],
    ))
    forbidden = "||".join("old-error:" + value for value in base["errors"])
    summary = (
        f"Target: {slug}/{language}/{kind}/{target_id}. "
        f"Subject: {base['actor']}. Action: {action}. Legal term: target-language "
        f"custody-expression-publication-and-remedy terminology must retain its "
        f"case-specific legal meaning. Source: {base['source']}. Consequence: "
        f"{base['consequence']}. Remedy: {base['remedy']}. Why more accurate: "
        f"the revision removes {base['errors'][0]} and {base['errors'][1]} while "
        "preserving attribution, chronology, source boundaries, state responsibility, "
        "and an independent effective remedy."
    )
    return required, forbidden, summary


