def batch11_final1_fact_text(pages, slug, language, fact_id):
    node = batch11_final1_target_node(pages, (slug, language, "fact", fact_id))
    return batch11_norm(normalized_visible(node))


def batch11_final1_body_text(pages, slug, language):
    soup = pages.get(slug)
    body = soup.select_one(f'[data-language-body="{language}"]') if soup else None
    return batch11_norm(normalized_visible(body))


def audit_batch11_final1_semantics(pages):
    issues = []
    public = []
    for slug in BATCH11_FINAL1_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"batch11-final1 page missing: {slug}")
            continue
        section_reference = None
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"batch11-final1 body missing: {slug}/{language}")
                continue
            public.append(normalized_visible(body))
            sections = tuple(node.get("data-section", "") for node in body.select("h2[data-section]"))
            if section_reference is None:
                section_reference = sections
            if sections != section_reference:
                issues.append(f"{slug}/{language}: batch11-final1 seven-part/source structure differs")
            for node in body.select("[data-critical-case]"):
                critical = batch11_norm(node.get("data-critical-case", ""))
                visible = batch11_norm(normalized_visible(node))
                if (not critical or not visible.startswith(critical)
                        or critical[-1] not in ".!?。！？"):
                    parent = node.find_parent(attrs={"data-fact-id": True})
                    issues.append(
                        f"{slug}/{language}/{parent.get('data-fact-id','') if parent else ''}: "
                        "batch11-final1 critical first sentence differs"
                    )

    folded = (" " + "\n".join(public) + " ").casefold()
    for phrase in BATCH11_FINAL1_FORBIDDEN:
        if phrase.casefold() in folded:
            issues.append(f"batch11-final1 rejected mistranslation returned: {phrase}")

    for language in BATCH5_LANGS:
        civic = batch11_final1_fact_text(
            pages, "2024-report", language, "2024-report-evidence-official-gap",
        )
        if re.search(BATCH11_FINAL1_CIVIC_TERMS[language], civic, re.I) is None:
            issues.append(f"2024-report/{language}: civic-space human-rights term missing")
        facts_2024 = " ".join(
            batch11_norm(normalized_visible(node))
            for node in pages["2024-report"].select(
                f'[data-language-body="{language}"] [data-fact-id]'
            )
        )
        if language == "ja" and re.search(r"(?:です|ます|でした|ません)(?:[。！？]|$)", facts_2024):
            issues.append("2024-report/ja: polite and formal written registers are mixed")
        if language == "ko" and re.search(r"(?:습니다|입니다|합니다|됩니다)(?:[.!?]|$)", facts_2024):
            issues.append("2024-report/ko: polite and formal written registers are mixed")
        unresolved_ko = batch11_final1_fact_text(
            pages, "2024-report", "ko", "2024-report-unresolved-questions",
        )
        if language == "ko" and (len(unresolved_ko) < 100 or not re.search(r"(?:다|한다|해야 한다)[.]?$", unresolved_ko)):
            issues.append("2024-report/ko: unresolved questions remain a fragment list")

        causeway = " ".join(
            batch11_final1_fact_text(pages, "causeway-bay-books", language, fact_id)
            for fact_id in (
                "causeway-bay-books-overview-1", "causeway-bay-books-overview-2",
                *(f"causeway-bay-books-timeline-{index}" for index in range(1, 8)),
                "causeway-bay-books-unresolved-questions",
                "causeway-bay-books-rights-analysis",
            )
        )
        if not batch11_markers_present(causeway, BATCH11_FINAL1_CAUSEWAY_MARKERS[language]):
            issues.append(f"causeway-bay-books/{language}: disappearance/removal/cross-border/publishing chain missing")
        if language == "ja" and re.search(r"(?:です|ます|でした|ません)(?:[。！？]|$)", causeway):
            issues.append("causeway-bay-books/ja: polite and formal written registers are mixed")
        if language == "ko" and re.search(r"(?:습니다|입니다|합니다|됩니다)(?:[.!?]|$)", causeway):
            issues.append("causeway-bay-books/ko: polite and formal written registers are mixed")

        feng = batch11_final1_body_text(pages, "feng-county-chained-woman", language)
        if not batch11_markers_present(feng, BATCH11_FINAL1_FENG_MARKERS[language]):
            issues.append(f"feng-county-chained-woman/{language}: video/notices/province/court/citizen/police-platform distinctions missing")

        timeline3 = batch11_final1_target_node(
            pages, ("hk-12", language, "fact", "hk-12-timeline-3"),
        )
        timeline5 = batch11_final1_target_node(
            pages, ("hk-12", language, "fact", "hk-12-timeline-5"),
        )
        timeline6 = batch11_final1_target_node(
            pages, ("hk-12", language, "fact", "hk-12-timeline-6"),
        )
        text3 = batch11_norm(normalized_visible(timeline3))
        if timeline3 is None or timeline3.get("data-timeline-subject") != (
            "human-rights-watch-chinese-detention-authorities-family-appointed-lawyers"
        ) or timeline3.get("data-timeline-action") != (
            "documented-counsel-denial-and-called-for-family-appointed-lawyer-access"
        ) or timeline3.get("data-timeline-consequence") != (
            "government-appointed-lawyer-claim-and-family-rejection-were-documented"
        ) or "hrw" not in text3.casefold():
            issues.append(f"hk-12/{language}: timeline-3 HRW actor/action is reversed or incomplete")
        if timeline3 is not None and timeline3.get("data-source-ref", "") != "s2":
            issues.append(f"hk-12/{language}: timeline-3 must cite only HRW s2")
        text5 = batch11_norm(normalized_visible(timeline5))
        if timeline5 is None or "2020-12-30" not in text5 or timeline5.get("data-source-ref", "") != "s4":
            issues.append(f"hk-12/{language}: timeline-5 date/source differs from 2020-12-30/s4")
        text6 = batch11_norm(normalized_visible(timeline6))
        if timeline6 is None or timeline6.get("data-source-ref", "") != "s6" or (
            "20210322" not in compact_digits(text6)
        ) or not batch11_markers_present(text6, BATCH11_FINAL1_HK6_MARKERS[language]):
            issues.append(f"hk-12/{language}: timeline-6 lacks 2021-03-22/eight/seven-month/s6 facts")
        if timeline6 is not None and timeline6.get("data-timeline-action") != (
            "transferred-eight-after-seven-month-sentences-at-shenzhen-bay-port"
        ):
            issues.append(f"hk-12/{language}: timeline-6 transfer action differs")
        if timeline6 is not None and (
            timeline6.get("data-timeline-subject") !=
            "eight-returnees-mainland-and-hong-kong-police"
            or timeline6.get("data-timeline-consequence") !=
            "hong-kong-police-custody-and-local-cases-continued"
        ):
            issues.append(f"hk-12/{language}: timeline-6 subject/consequence differs")

        xj4 = batch11_final1_target_node(
            pages, ("xinjiang-camps", language, "fact", "xinjiang-camps-timeline-4"),
        )
        xj_text = batch11_norm(normalized_visible(xj4))
        if xj4 is None or xj4.get("data-source-ref", "") != "s4" or (
            xj4.get("data-timeline-subject", "") !=
            "new-york-times-chinese-leadership-and-xinjiang-party-state-authorities"
        ) or not batch11_markers_present(xj_text, BATCH11_FINAL1_XJ_NYT_MARKERS[language]):
            issues.append(f"xinjiang-camps/{language}: s4 NYT internal-document role missing")

        press = batch11_final1_fact_text(
            pages, "press-freedom-2026", language,
            "press-freedom-2026-rights-analysis",
        )
        if not batch11_markers_present(press, BATCH11_FINAL1_PRESS_MARKERS[language]):
            issues.append(f"press-freedom-2026/{language}: complete journalist/source/control/remedy chain missing")
        if language == "zh" and "質疑" in press:
            issues.append("press-freedom-2026/zh: questioning was mistranslated as doubt")

        hk_gap = batch11_final1_target_node(
            pages, ("hk-12", language, "fact", "hk-12-evidence-official-gap"),
        )
        if hk_gap is None or hk_gap.get("data-official-response") != (
            "coast-guard-shenzhen-police-procuratorate-yantian-court-and-hong-kong-police-record"
        ) or hk_gap.get("data-response-gap") != (
            "interception-custody-lawyer-waiver-plea-open-hearing-transfer-and-local-case-records"
        ):
            issues.append(f"hk-12/{language}: evidence-gap dispute-matrix mapping differs")

    # A separately handwritten English contract proves that each of the six
    # case-specific rights conclusions retains its subject, state action,
    # consequence, cited-source boundary, and remedy.  These literals are not
    # extracted from the DOM and each is deleted independently in self-test.
    for slug, contract in BATCH11_FINAL1_RIGHTS_ENGLISH.items():
        node = batch11_final1_target_node(
            pages, (slug, "en", "fact", f"{slug}-rights-analysis"),
        )
        visible = batch11_norm(normalized_visible(node))
        for component in ("subject", "action", "consequence", "remedy"):
            if contract[component].casefold() not in visible.casefold():
                issues.append(f"{slug}/en: rights-analysis {component} chain missing")
        if node is None or batch11_norm(node.get("data-source-ref", "")) != contract["source_refs"]:
            issues.append(f"{slug}/en: rights-analysis source boundary differs")

    # Source metadata: five pages remain byte-authenticated by the reconstructed
    # page preimage; HK12 alone gains the exact ten-language s6 row at the end.
    for slug in BATCH11_FINAL1_SLUGS:
        soup = pages.get(slug)
        reference = None
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]') if soup else None
            signature = []
            for source in body.select("ul.source-list > li[data-source-id]") if body else ():
                anchor = source.find("a")
                signature.append((
                    source.get("data-source-id", ""), source.get("data-source-type", ""),
                    source.get("data-source-date", ""), anchor.get("href", "") if anchor else "",
                ))
            if reference is None:
                reference = signature
            elif signature != reference:
                issues.append(f"{slug}/{language}: final1 source ID/type/date/URL/order differs from zh")
        expected_count = 6 if slug == "hk-12" else BATCH11_SOURCE_COUNTS[slug]
        if len(reference or ()) != expected_count:
            issues.append(f"{slug}: final1 source count differs from {expected_count}")
    hk_signature = []
    hk = pages.get("hk-12")
    if hk is not None:
        for language in BATCH5_LANGS:
            sources = hk.select(f'[data-language-body="{language}"] ul.source-list > li[data-source-id]')
            s6 = sources[-1] if sources else None
            anchor = s6.find("a") if s6 else None
            ok = bool(
                s6 and s6.get("data-source-id") == "s6"
                and s6.get("data-source-type") == "independent-media overseas-media transfer-report"
                and s6.get("data-source-date") == "2021-03-22"
                and anchor and anchor.get("href") == "https://hongkongfp.com/2021/03/22/eight-hongkongers-return-from-china-after-7-months-in-jail-for-illegal-border-crossing/"
                and s6.find("time") and s6.find("time").get("datetime") == "2021-03-22"
                and normalized_visible(s6.find("time")) == "2021-03-22"
            )
            hk_signature.append(ok)
        if not all(hk_signature):
            issues.append("hk-12: ten-language s6 ID/type/date/URL/order signature differs")
    return issues


def audit_batch11_final1_ledgers(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    check_files=True,
):
    """Authenticate the full batch11 prefix and every genuine final1 change."""
    issues = []
    if check_files:
        issues.extend(batch10_final1_exact_prefix(
            BATCH9_REREAD_PATH, BATCH11_FINAL1_REREAD_ROWS,
            BATCH11_FINAL1_REREAD_SHA256, "batch11-final1 reread prefix",
        ))
        issues.extend(batch10_final1_exact_prefix(
            BATCH9_CONTRACT_PATH, BATCH11_FINAL1_CONTRACT_ROWS,
            BATCH11_FINAL1_CONTRACT_SHA256, "batch11-final1 contract prefix",
        ))
        issues.extend(batch10_final1_exact_prefix(
            BATCH9_SOURCE_LEDGER_PATH, BATCH11_FINAL1_SOURCE_ROWS,
            BATCH11_FINAL1_SOURCE_SHA256, "batch11-final1 source prefix",
        ))
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11-final1 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11-final1 contract ledger",
        )
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11-final1 source ledger",
        )
        issues.extend(load_issues)

    # Bound final1 to its completed successor state.  Later final2 evidence is
    # audited separately and must never be reclassified as part of final1.
    reread_suffix = reread_rows[
        BATCH11_FINAL1_REREAD_ROWS:BATCH11_FINAL2_REREAD_ROWS
    ]
    contract_suffix = contract_rows[
        BATCH11_FINAL1_CONTRACT_ROWS:BATCH11_FINAL2_CONTRACT_ROWS
    ]
    source_suffix = source_rows[
        BATCH11_FINAL1_SOURCE_ROWS:BATCH11_FINAL2_SOURCE_ROWS
    ]
    preimage_issues, legacy, legacy_targets = audit_batch11_final1_preimage(
        pages, reread_rows, source_rows,
    )
    issues.extend(preimage_issues)
    live_targets, live_issues = batch11_final1_dom_targets(pages)
    issues.extend(live_issues)
    if len(live_targets) != BATCH11_FINAL1_LIVE_TARGET_ROWS:
        issues.append(
            f"batch11-final1 live target inventory is {len(live_targets)}, "
            f"expected {BATCH11_FINAL1_LIVE_TARGET_ROWS}"
        )
    # Reread/contract rows describe prose transitions.  A source-ref-only
    # correction is a genuine source-ledger transition, but fabricating a
    # textual change for it would violate the requirement that old and new
    # prose be truthful and unequal.  Keep those two transition classes
    # separate and require both below.
    expected_changes = {
        key for key in set(legacy_targets) | set(live_targets)
        if key not in legacy_targets or key not in live_targets
        or legacy_targets[key]["text"] != live_targets[key]["text"]
    }
    expected_new = {
        ("hk-12", language, "source-title", "source-title:s6")
        for language in BATCH5_LANGS
    }
    if set(live_targets) - set(legacy_targets) != expected_new:
        issues.append("batch11-final1 live/preimage target delta is not exactly HK12/s6")
    if set(legacy_targets) - set(live_targets):
        issues.append("batch11-final1 deleted an authenticated visible target")

    def key4(row):
        return batch10_final1_contract_key(row)

    reread_keys = [key4(row) for row in reread_suffix]
    contract_keys = [key4(row) for row in contract_suffix]
    if len(reread_keys) != len(set(reread_keys)):
        issues.append("batch11-final1 reread suffix duplicates a target")
    if len(contract_keys) != len(set(contract_keys)):
        issues.append("batch11-final1 contract suffix duplicates a target")
    if set(reread_keys) != expected_changes:
        issues.append(
            "batch11-final1 reread coverage differs from true preimage-to-live changes: "
            f"missing={len(expected_changes-set(reread_keys))} "
            f"extra={len(set(reread_keys)-expected_changes)}"
        )
    if set(contract_keys) != expected_changes:
        issues.append(
            "batch11-final1 contract coverage differs from true preimage-to-live changes"
        )

    predecessor_tips = {}
    for row in reread_rows[:BATCH11_FINAL1_REREAD_ROWS]:
        predecessor_tips[key4(row)] = row
    historic_ids = {
        row.get("contract_id", "")
        for row in contract_rows[:BATCH11_FINAL1_CONTRACT_ROWS]
        if row.get("contract_id", "")
    }
    reread_by_key = {}
    reread_by_id = {}
    for row in reread_suffix:
        key = key4(row)
        label = "/".join(key)
        reread_by_key[key] = row
        contract_id = row.get("contract_id", "")
        expected_id_prefix = BATCH11_FINAL1_PREFIX + ":".join(key) + ":"
        if key[0] not in BATCH11_FINAL1_SLUG_SET or key[1] not in BATCH5_LANGS:
            issues.append(f"batch11-final1 reread is out of scope: {label}")
        if key[2] not in {"article-title", "article-dek", "fact", "source-title"}:
            issues.append(f"batch11-final1 reread target kind is unsupported: {label}")
        if row.get("target_kind", "") != key[2]:
            issues.append(f"batch11-final1 reread target kind/key differs: {label}")
        if not contract_id.startswith(expected_id_prefix):
            issues.append(f"batch11-final1 reread contract ID is not target-bound: {label}")
        if not contract_id or contract_id in historic_ids or contract_id in reread_by_id:
            issues.append(f"batch11-final1 reread contract ID is blank or duplicate: {label}")
        reread_by_id[contract_id] = row
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11-final1 reread is not PASS_AFTER_REVISION: {label}")
        if not row.get("issue_found", "").startswith("reread:batch11-final1"):
            issues.append(f"batch11-final1 reread lacks a specific issue record: {label}")
        if not row.get("review_basis", "").startswith("reread:batch11-final1"):
            issues.append(f"batch11-final1 reread lacks its manual-review basis: {label}")
        original = batch11_norm(row.get("original_text", ""))
        revised = batch11_norm(row.get("revised_text", ""))
        if original == revised:
            issues.append(f"batch11-final1 reread records no real text change: {label}")
        live = live_targets.get(key)
        legacy_value = legacy_targets.get(key)
        if live is None:
            issues.append(f"batch11-final1 reread has no live target: {label}")
        else:
            if revised != live["text"]:
                issues.append(f"batch11-final1 reread revised text differs from live DOM: {label}")
            if batch11_norm(row.get("source_refs", "")) != live["source_refs"]:
                issues.append(f"batch11-final1 reread source refs differ from live DOM: {label}")
        expected_original = legacy_value["text"] if legacy_value is not None else ""
        if original != expected_original:
            issues.append(f"batch11-final1 reread original differs from authenticated preimage: {label}")
        predecessor = predecessor_tips.get(key)
        if predecessor is not None and original != batch11_norm(predecessor.get("revised_text", "")):
            issues.append(f"batch11-final1 reread predecessor chain is broken: {label}")
        if predecessor is None and key not in expected_new and "authenticated-preimage" not in row.get("review_basis", ""):
            issues.append(f"batch11-final1 snapshot-backed row lacks preimage evidence: {label}")

    contract_by_key = {}
    contract_by_id = {}
    for row in contract_suffix:
        key = key4(row)
        label = "/".join(key)
        contract_by_key[key] = row
        contract_id = row.get("contract_id", "")
        if not contract_id.startswith(BATCH11_FINAL1_PREFIX + ":".join(key) + ":"):
            issues.append(f"batch11-final1 contract ID is not target-bound: {label}")
        if not contract_id or contract_id in historic_ids or contract_id in contract_by_id:
            issues.append(f"batch11-final1 contract ID is blank or duplicate: {label}")
        contract_by_id[contract_id] = row
        required, forbidden, summary = batch11_final1_contract_spec(key)
        if row.get("required_all", "") != required:
            issues.append(f"batch11-final1 independent required contract differs: {label}")
        if row.get("forbidden_any", "") != forbidden:
            issues.append(f"batch11-final1 independent forbidden contract differs: {label}")
        if row.get("fact_summary", "") != summary:
            issues.append(f"batch11-final1 independent fact summary differs: {label}")
    if set(reread_by_id) != set(contract_by_id):
        issues.append("batch11-final1 reread/contract IDs are not one-to-one")
    for contract_id in set(reread_by_id) & set(contract_by_id):
        if key4(reread_by_id[contract_id]) != key4(contract_by_id[contract_id]):
            issues.append(f"batch11-final1 paired contract points to another target: {contract_id}")

    source_prefix_tips = batch11_prefix_tips(
        source_rows[:BATCH11_FINAL1_SOURCE_ROWS], kind="source",
    )
    fact_projection_fields = (
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence",
    )
    expected_fact_keys = set()
    for slug in BATCH11_FINAL1_SLUGS:
        for language in BATCH5_LANGS:
            live_body = pages[slug].select_one(f'[data-language-body="{language}"]')
            legacy_body = legacy[slug].select_one(f'[data-language-body="{language}"]')
            for node in live_body.select("[data-fact-id]") if live_body else ():
                fact_id = node.get("data-fact-id", "")
                if node.select_one("[data-fact-id]") or fact_id.endswith("-sources"):
                    continue
                live_fields = batch11_live_fact_fields(pages, slug, language, fact_id)
                legacy_fields = batch11_live_fact_fields(legacy, slug, language, fact_id)
                if live_fields is None or legacy_fields is None:
                    continue
                if any(batch11_norm(live_fields[field]) != batch11_norm(legacy_fields[field])
                       for field in fact_projection_fields):
                    expected_fact_keys.add((slug, language, fact_id))
    source_keys = [
        (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        for row in source_suffix
    ]
    if len(source_keys) != len(set(source_keys)):
        issues.append("batch11-final1 source overlay duplicates a target")
    if set(source_keys) != expected_fact_keys:
        issues.append(
            "batch11-final1 source overlays differ from genuine changed facts: "
            f"missing={len(expected_fact_keys-set(source_keys))} "
            f"extra={len(set(source_keys)-expected_fact_keys)}"
        )
    mutable = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "baseline_issue",
        "resolution_action", "support_urls", "locatable_support",
        "source_roles", "final_issue", "audit_accessed_at", "audit_final_url",
        "audit_title", "audit_source_id", "audit_locator",
        "audit_support_summary", "audit_relationship", "audit_claim_compared",
        "audit_decision", "source_date_audit", "reread_h1_current",
        "reread_dek_current", "reread_timeline_current", "reread_rights_current",
        "reread_protection_current", "reread_source_titles_current",
        "reread_card_current", "reread_issue_found", "reread_revision_text",
        "reread_result", "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor", "visible_timeline_order",
        "visible_source_roles",
    }
    report_cards, card_issues = batch9_final2_report_cards()
    report_cards = batch14_baseline_card_view(report_cards)
    issues.extend(card_issues)
    report_by_slug = {card.get("slug", ""): card for card in report_cards}
    source_seen = set()
    for row in source_suffix:
        key = (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        label = "/".join(key)
        source_seen.add(key)
        predecessor = source_prefix_tips.get(key)
        reread = reread_by_key.get((key[0], key[1], "fact", key[2]))
        if predecessor is None:
            issues.append(f"batch11-final1 source overlay lacks predecessor: {label}")
        else:
            for field in BATCH9_FINAL2_SOURCE_COLUMNS:
                if field not in mutable and row.get(field, "") != predecessor.get(field, ""):
                    issues.append(f"batch11-final1 source overlay changed protected {field}: {label}")
                    break
        text_changed = (key[0], key[1], "fact", key[2]) in expected_changes
        if text_changed and reread is None:
            issues.append(f"batch11-final1 source overlay lacks fact reread: {label}")
        elif reread is not None:
            if row.get("baseline_issue", "") != reread.get("contract_id", ""):
                issues.append(f"batch11-final1 source baseline differs from contract: {label}")
            if row.get("reread_issue_found", "") != reread.get("issue_found", ""):
                issues.append(f"batch11-final1 source issue differs from reread: {label}")
            if batch11_norm(row.get("reread_revision_text", "")) != batch11_norm(
                reread.get("revised_text", "")
            ):
                issues.append(f"batch11-final1 source revision differs from reread: {label}")
        else:
            source_marker = f"{BATCH11_FINAL1_PREFIX}{key[0]}:{key[1]}:fact:{key[2]}:source-map:"
            if not row.get("baseline_issue", "").startswith(source_marker):
                issues.append(f"batch11-final1 source-only baseline is not target-bound: {label}")
            if not row.get("reread_issue_found", "").startswith(
                "reread:batch11-final1 source mapping correction"
            ):
                issues.append(f"batch11-final1 source-only issue evidence differs: {label}")
        live_fields = batch11_live_fact_fields(
            pages, *key, report_by_slug=report_by_slug,
        )
        if live_fields is None:
            issues.append(f"batch11-final1 source overlay live fact missing: {label}")
            continue
        for field, value in live_fields.items():
            if batch11_norm(row.get(field, "")) != batch11_norm(value):
                issues.append(f"batch11-final1 source {field} differs from live state: {label}")
        if row.get("audit_accessed_at", "") != "2026-07-22":
            issues.append(f"batch11-final1 source audit date differs: {label}")
        if row.get("audit_decision", "") != "PASS_FINAL1_SOURCE_MAPPING":
            issues.append(f"batch11-final1 source audit decision differs: {label}")
        if not all(row.get(field, "").strip() for field in (
            "audit_final_url", "audit_title", "audit_source_id", "audit_locator",
            "audit_support_summary", "audit_relationship", "audit_claim_compared",
        )):
            issues.append(f"batch11-final1 source audit evidence is incomplete: {label}")
        slug, language, _fact_id = key
        body = pages[slug].select_one(f'[data-language-body="{language}"]')
        node = body.select_one(f'[data-fact-id="{key[2]}"]') if body else None
        source_nodes = {
            source.get("data-source-id", ""): source
            for source in body.select("ul.source-list > li[data-source-id]")
        } if body else {}
        refs = node.get("data-source-ref", "").split() if node else []
        urls = " | ".join(source_nodes[ref].find("a").get("href", "") for ref in refs)
        locators = " | ".join(
            f"{ref}: {normalized_visible(source_nodes[ref].find('a'))}" for ref in refs
        )
        dates = " | ".join(
            f"{ref}={source_nodes[ref].get('data-source-date', '') or 'UNDATED'}" for ref in refs
        )
        roles = " | ".join(
            f"{ref}:{source_nodes[ref].get('data-source-type', '')}" for ref in refs
        )
        for field, expected in (
            ("support_urls", urls), ("locatable_support", locators),
            ("source_date_audit", dates), ("source_roles", roles),
            ("visible_source_roles", roles),
        ):
            if row.get(field, "") != expected:
                issues.append(f"batch11-final1 source {field} projection differs: {label}")
        if node is not None and node.has_attr("data-timeline-action"):
            visible_stream = final1_contiguous_stream(normalized_visible(node))
            for field in (
                "visible_subject_anchor", "visible_action_anchor",
                "visible_consequence_anchor",
            ):
                anchor = final1_contiguous_stream(row.get(field, ""))
                if not anchor or anchor not in visible_stream:
                    issues.append(f"batch11-final1 timeline {field} is unlocatable: {label}")
            if not row.get("visible_timeline_order", "").isdigit():
                issues.append(f"batch11-final1 timeline order is not explicit: {label}")
    return issues, {
        "changed_targets": len(expected_changes),
        "changed_facts": len(expected_fact_keys),
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "source_rows": len(source_suffix),
        "snapshot_backed": sum(key not in predecessor_tips for key in expected_changes),
    }


def audit_batch11_final1_wiring(source_text=None):
    if source_text is None:
        source_text = Path(__file__).read_text(encoding="utf-8")
    match = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    needle = "issues.extend(audit_batch11_final1(pages))"
    return [] if match is not None and match.group("body").count(needle) == 1 else [
        "batch11-final1 authoritative audit_live wiring is absent"
    ]


def audit_batch11_final1(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    frozen_overrides=None, check_files=True,
):
    issues = []
    issues.extend(audit_batch11_final1_semantics(pages))
    ledger_issues, _stats = audit_batch11_final1_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows, check_files=check_files,
    )
    issues.extend(ledger_issues)
    _prefix, source_date_issues = batch11_final1_source_date_successor()
    issues.extend(source_date_issues)
    issues.extend(audit_batch11_final1_frozen(frozen_overrides))
    issues.extend(audit_batch11_final1_wiring())
    return issues


def batch11_final1_negative_self_test(pages):
    """Exercise the sixteen final1 regression classes named by the brief."""
    names = []
    misses = []
    baseline = audit_batch11_final1_semantics(pages)

    def record(name, caught):
        names.append(name)
        if baseline or not caught:
            misses.append(name + (f" (baseline: {baseline[0]})" if baseline else ""))

    def inject(slug, language, fact_id, phrase):
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        node = mutated[slug].select_one(
            f'[data-language-body="{language}"] [data-fact-id="{fact_id}"]'
        )
        node.append(" " + phrase)
        return bool(audit_batch11_final1_semantics(mutated))

    record(
        "01 2024 civic-space mistranslations",
        all(inject("2024-report", language, "2024-report-evidence-official-gap", phrase)
            for language, phrase in (
                ("zh", "民用空間"), ("en", "civil space"),
                ("ja", "民間空間"), ("ko", "민간 공간"),
            )),
    )
    record(
        "02 2024 Japanese/Korean register mixing",
        inject("2024-report", "ja", "2024-report-unresolved-questions", "説明しています。")
        and inject("2024-report", "ko", "2024-report-unresolved-questions", "설명합니다."),
    )
    record(
        "03 Causeway lost-object vocabulary",
        all(inject("causeway-bay-books", language,
            "causeway-bay-books-unresolved-questions", phrase)
            for language, phrase in (
                ("en", "lost"), ("fr", "perdues"),
                ("es", "extraviadas"), ("no", "ble tapt"),
            )),
    )
    record(
        "04 Feng Japanese place/video/investigator mistranslations",
        all(inject("feng-county-chained-woman", "ja",
            "feng-county-chained-woman-unresolved-questions", phrase)
            for phrase in ("奉賢", "訪問の動画", "民間捜査官")),
    )
    record(
        "05 HK12 official-lawfulness phrase",
        inject("hk-12", "zh", "hk-12-overview-1", "依法处理"),
    )

    mutated = dict(pages)
    mutated["hk-12"] = deepcopy(pages["hk-12"])
    t3 = mutated["hk-12"].select_one(
        '[data-language-body="en"] [data-fact-id="hk-12-timeline-3"]'
    )
    t3["data-timeline-subject"] = "family-lawyers-and-detainees"
    t3["data-timeline-action"] = "recorded-the-lawyer-dispute"
    record("06 HK12 timeline-3 actor/action reversal", bool(audit_batch11_final1_semantics(mutated)))

    mutated = dict(pages)
    mutated["hk-12"] = deepcopy(pages["hk-12"])
    t5 = mutated["hk-12"].select_one(
        '[data-language-body="en"] [data-fact-id="hk-12-timeline-5"]'
    )
    t5.find("b").string = "2020-12-28:"
    record("07 HK12 timeline-5 wrong date", bool(audit_batch11_final1_semantics(mutated)))

    t6_cases = []
    for mutation in ("source", "date", "eight", "seven", "transfer"):
        mutated = dict(pages)
        mutated["hk-12"] = deepcopy(pages["hk-12"])
        node = mutated["hk-12"].select_one(
            '[data-language-body="en"] [data-fact-id="hk-12-timeline-6"]'
        )
        if mutation == "source":
            node["data-source-ref"] = "s5"
        elif mutation == "date":
            node.find("b").string = "2021-03-21:"
        else:
            text = normalized_visible(node)
            old = {"eight": "eight", "seven": "seven", "transfer": "handed to Hong Kong police"}[mutation]
            node.clear()
            node.append(re.sub(old, "", text, count=1, flags=re.I))
        t6_cases.append(bool(audit_batch11_final1_semantics(mutated)))
    record("08 HK12 timeline-6 source/date/eight/seven/transfer deletion", all(t6_cases))

    s6_cases = []
    for mutation in ("id", "type", "date", "url", "order"):
        mutated = dict(pages)
        mutated["hk-12"] = deepcopy(pages["hk-12"])
        body = mutated["hk-12"].select_one('[data-language-body="en"]')
        sources = body.select("ul.source-list > li[data-source-id]")
        s6 = sources[-1]
        if mutation == "id":
            s6["data-source-id"] = "s7"
        elif mutation == "type":
            s6["data-source-type"] = "independent-media"
        elif mutation == "date":
            s6["data-source-date"] = "2021-03-21"
        elif mutation == "url":
            s6.find("a")["href"] += "?wrong=1"
        else:
            s6.extract()
            sources[0].insert_before(s6)
        s6_cases.append(bool(audit_batch11_final1_semantics(mutated)))
    record("09 HK12 ten-language s6 signature/order", all(s6_cases))

    record(
        "10 Xinjiang ICIJ/China-Cables/telecom substitution",
        all(inject("xinjiang-camps", "en", "xinjiang-camps-timeline-4", phrase)
            for phrase in ("ICIJ", "China Cables", "中國電信")),
    )
    mutated = dict(pages)
    mutated["xinjiang-camps"] = deepcopy(pages["xinjiang-camps"])
    xj = mutated["xinjiang-camps"].select_one(
        '[data-language-body="en"] [data-fact-id="xinjiang-camps-timeline-4"]'
    )
    xj_text = normalized_visible(xj)
    xj.clear()
    xj.append(xj_text.replace("The New York Times", "A media outlet").replace("internal", "public"))
    record("11 Xinjiang NYT/internal-document role deletion", bool(audit_batch11_final1_semantics(mutated)))

    press_cases = (
        ("zh", "質疑"), ("ja", "機密報道"), ("ja", "独立メディアと認定を回復"),
        ("ko", "보도 혐의로"), ("no", "statlige medier"), ("no", "fysisk varetekt"),
        ("fr", "remises en question"), ("fr", "détention physique"),
        ("en", "restore accreditation"),
    )
    record(
        "12 press-freedom ten-language mistranslation phrases",
        all(inject("press-freedom-2026", language,
            "press-freedom-2026-rights-analysis", phrase)
            for language, phrase in press_cases),
    )

    deletion_caught = []
    for slug, contract in BATCH11_FINAL1_RIGHTS_ENGLISH.items():
        target_id = f"{slug}-rights-analysis"
        for component in ("subject", "action", "consequence", "remedy"):
            mutated = dict(pages)
            mutated[slug] = deepcopy(pages[slug])
            node = mutated[slug].select_one(
                f'[data-language-body="en"] [data-fact-id="{target_id}"]'
            )
            visible = normalized_visible(node)
            node.clear()
            node.append(visible.replace(contract[component], "", 1))
            deletion_caught.append(bool(audit_batch11_final1_semantics(mutated)))
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        node = mutated[slug].select_one(
            f'[data-language-body="en"] [data-fact-id="{target_id}"]'
        )
        node["data-source-ref"] = "s1"
        deletion_caught.append(bool(audit_batch11_final1_semantics(mutated)))
    record("13 case subject/action/consequence/source/remedy deletion", all(deletion_caught))

    script = (ROOT / "script.js").read_bytes() + b"\n// mutation"
    record("14 script.js/card-field mutation", bool(audit_batch11_final1_frozen({"script.js": script})))
    non_target = ROOT / "posts/chen-qiushi.html"
    record(
        "15 non-target page mutation",
        bool(audit_batch11_final1_frozen({
            "posts/chen-qiushi.html": non_target.read_bytes() + b"\nmutation",
        })),
    )
    source = Path(__file__).read_text(encoding="utf-8")
    record(
        "16 batch11-final1 validation entry deletion",
        bool(audit_batch11_final1_wiring(source.replace(
            "issues.extend(audit_batch11_final1(pages))", "# final1 call removed",
        ))),
    )
    if len(names) != 16 or len(set(names)) != 16:
        misses.append(f"batch11-final1 named suite cardinality is {len(names)}, expected 16")
    return len(names) - len(misses), len(names), misses


