def batch11_final2_target_node(pages, slug, language, kind, target_id):
    soup = pages.get(slug)
    if soup is None:
        return None
    body = soup.select_one(f'[data-language-body="{language}"]')
    if kind == "article-title":
        return soup.select_one(f".article-title .lang-{language}")
    if kind == "article-dek":
        return soup.select_one(f".article-dek .lang-{language}")
    if kind == "source-title":
        source_id = target_id.split(":", 1)[-1]
        source = body.select_one(f'li[data-source-id="{source_id}"]') if body else None
        return source.find("a") if source else None
    if kind == "source-category":
        source_id = target_id.split(":", 1)[-1]
        source = body.select_one(f'li[data-source-id="{source_id}"]') if body else None
        return source.find("b") if source else None
    return body.select_one(f'[data-fact-id="{target_id}"]') if body else None


def batch11_final2_phrase_missing(text, phrases):
    folded = batch11_norm(text).casefold()
    return [phrase for phrase in phrases if phrase.casefold() not in folded]


def audit_batch11_final2_semantics(pages):
    """Validate the five public final2 meanings without consulting TSV prose."""
    issues = []
    for slug in BATCH11_FINAL2_SLUGS:
        if pages.get(slug) is None:
            issues.append(f"batch11-final2 page missing: {slug}")
    if issues:
        return issues

    report = pages["2024-report"]
    for language, ordinance in BATCH11_FINAL2_2024_NAMES.items():
        body = report.select_one(f'[data-language-body="{language}"]')
        if body is None:
            issues.append(f"2024-report/{language}: language body missing")
            continue
        for fact_id in BATCH11_FINAL2_2024_NAME_FACTS:
            node = body.select_one(f'[data-fact-id="{fact_id}"]')
            node_text = normalized_visible(node)
            name_present = ordinance.casefold() in node_text.casefold()
            if language == "no":
                name_present = bool(re.search(
                    r"\bforordning(?:en)? om vern av nasjonal sikkerhet\b",
                    node_text, re.I,
                ))
            if node is None or not name_present:
                issues.append(
                    f"2024-report/{language}/{fact_id}: ordinance name is not the language's single canonical form"
                )
        s3 = body.select_one('li[data-source-id="s3"] a')
        if s3 is None or ordinance.casefold() not in normalized_visible(s3).casefold():
            issues.append(f"2024-report/{language}/s3: ordinance source title is inconsistent")
        state = body.select_one('[data-fact-id="2024-report-state-2"]')
        state_text = normalized_visible(state)
        missing = batch11_final2_phrase_missing(
            state_text, BATCH11_FINAL2_2024_ACTORS[language],
        )
        if missing:
            issues.append(
                f"2024-report/{language}/state-2: concrete institution chain missing {missing}"
            )
    report_text = normalized_visible(report)
    if BATCH11_FINAL2_2024_FORBIDDEN.search(report_text):
        issues.append("2024-report: an inconsistent ordinance name or abstract acting subject returned")
    fr_questions = normalized_visible(report.select_one(
        '[data-language-body="fr"] [data-fact-id="2024-report-unresolved-questions"]'
    ))
    fr_required = (
        "Restent à rendre publics les éléments suivants", "évaluations internes",
        "statistiques ventilées", "dossiers des plaintes", "pièces des affaires",
        "décisions relatives aux voies de recours", "parties", "avocats",
        "observateurs indépendants",
    )
    missing = batch11_final2_phrase_missing(fr_questions, fr_required)
    if missing:
        issues.append(f"2024-report/fr/unresolved: complete grammatical list missing {missing}")
    nl_questions = normalized_visible(report.select_one(
        '[data-language-body="nl"] [data-fact-id="2024-report-unresolved-questions"]'
    ))
    if "beslissingen over rechtsmiddelen" not in nl_questions.casefold() or re.search(
        r"\b(?:vonnissen|uitspraken)\b", nl_questions, re.I
    ):
        issues.append("2024-report/nl/unresolved: remedy decisions were narrowed to ordinary judgments")

    feng = pages["feng-county-chained-woman"]
    for language, required in BATCH11_FINAL2_FENG_REQUIRED.items():
        node = feng.select_one(
            f'[data-language-body="{language}"] '
            '[data-fact-id="feng-county-chained-woman-protection"]'
        )
        text = normalized_visible(node)
        missing = batch11_final2_phrase_missing(text, required)
        if missing:
            issues.append(
                f"feng-county-chained-woman/{language}/protection: factual state-responsibility chain missing {missing}"
            )
        if BATCH11_FINAL2_FENG_FORBIDDEN.search(text):
            issues.append(
                f"feng-county-chained-woman/{language}/protection: reader-facing risk instructions returned"
            )

    hk = pages["hk-12"]
    for language, expected in BATCH11_FINAL2_HK_S4_LABELS.items():
        node = batch11_final2_target_node(
            pages, "hk-12", language, "source-category", "s4",
        )
        if normalized_visible(node) != expected:
            issues.append(
                f"hk-12/{language}/s4: visible category is not the overseas-media sentencing-report role"
            )

    xinjiang = pages["xinjiang-camps"]
    ja_body = xinjiang.select_one('[data-language-body="ja"]')
    ja_text = normalized_visible(ja_body)
    if re.search(r"です|(?:し|示し|され|ござい)ます|ています|ました", ja_text):
        issues.append("xinjiang-camps/ja: polite desu/masu register is mixed into formal plain style")
    ko_body = xinjiang.select_one('[data-language-body="ko"]')
    ko_text = normalized_visible(ko_body)
    if re.search(r"합니다|됩니다|있습니다|했습니다|보여줍니다|밝혔습니다|발표했습니다", ko_text):
        issues.append("xinjiang-camps/ko: hamnida register is mixed into formal written plain style")
    no_body = xinjiang.select_one('[data-language-body="no"]')
    no_text = normalized_visible(no_body)
    if re.search(r"massefængsling|sammenhengende statlige poster|statlige poster", no_text, re.I):
        issues.append("xinjiang-camps/no: Danish spelling or state-posts mistranslation returned")
    no_protection = normalized_visible(no_body.select_one(
        '[data-fact-id="xinjiang-camps-protection"]'
    ))
    missing = batch11_final2_phrase_missing(no_protection, (
        "statlige administrative registre", "politi-", "reise-",
        "kommunikasjons-", "interneringsregistre",
    ))
    if missing:
        issues.append(
            f"xinjiang-camps/no/protection: linked administrative/police/travel/communication/detention registers missing {missing}"
        )
    no_s4 = normalized_visible(no_body.select_one('li[data-source-id="s4"] a'))
    if "massefengsling" not in no_s4.casefold():
        issues.append("xinjiang-camps/no/s4: corrected massefengsling title is absent")
    xj_files = {
        "zh": ("The New York Times", "洩漏的文件"),
        "en": ("The New York Times", "Leaked Files"),
        "ja": ("The New York Times", "流出ファイル"),
        "ko": ("The New York Times", "유출된 파일"),
        "es": ("The New York Times", "Archivos filtrados"),
        "de": ("The New York Times", "Durchgesickerte Dateien"),
        "fr": ("The New York Times", "fuites de fichiers"),
        "no": ("The New York Times", "Lekkede filer"),
        "nl": ("The New York Times", "gelekte bestanden"),
        "it": ("The New York Times", "file trapelati"),
    }
    for language, required in xj_files.items():
        title = normalized_visible(xinjiang.select_one(
            f'[data-language-body="{language}"] li[data-source-id="s4"] a'
        ))
        if batch11_final2_phrase_missing(title, required):
            issues.append(f"xinjiang-camps/{language}/s4: New York Times Xinjiang-files role is missing")
        if re.search(r"China Cables|ICIJ|中國電信|中国电信|중국전신", title, re.I):
            issues.append(f"xinjiang-camps/{language}/s4: Xinjiang Files were relabelled")

    press = pages["press-freedom-2026"]
    for language, required in BATCH11_FINAL2_PRESS_REQUIRED.items():
        node = press.select_one(
            f'[data-language-body="{language}"] '
            '[data-fact-id="press-freedom-2026-state-machinery-3"]'
        )
        text = normalized_visible(node)
        missing = batch11_final2_phrase_missing(text, required)
        if missing:
            issues.append(
                f"press-freedom-2026/{language}/state-machinery-3: case-specific state chain missing {missing}"
            )
        if BATCH11_FINAL2_PRESS_FORBIDDEN.search(text):
            issues.append(
                f"press-freedom-2026/{language}/state-machinery-3: cross-case school/may-miss template returned"
            )
    fr_dek = normalized_visible(press.select_one(".article-dek .lang-fr"))
    if "accusations liées à la sécurité nationale" not in fr_dek.casefold() or (
        "chefs de sécurité" in fr_dek.casefold()
    ):
        issues.append("press-freedom-2026/fr/dek: national-security charges are mistranslated")
    ja_overview = normalized_visible(press.select_one(
        '[data-language-body="ja"] [data-fact-id="press-freedom-2026-overview-1"]'
    ))
    if "市民の知る権利" not in ja_overview or "公衆の知る能力" in ja_overview:
        issues.append("press-freedom-2026/ja/overview-1: right-to-know wording regressed")
    for fact_id in (
        "press-freedom-2026-overview-2", "press-freedom-2026-state-machinery-2",
    ):
        nl_text = normalized_visible(press.select_one(
            f'[data-language-body="nl"] [data-fact-id="{fact_id}"]'
        ))
        if "volgen" not in nl_text.casefold() or re.search(r"\bschaduwen\b", nl_text, re.I):
            issues.append(f"press-freedom-2026/nl/{fact_id}: reporter-following wording is unnatural")
    return issues


def batch11_final2_inventory(pages):
    """Enumerate every visible title/dek/leaf fact/source title plus HK s4 role."""
    targets = {}
    issues = []

    def add(key, text, refs):
        if key in targets:
            issues.append(f"batch11-final2 duplicate target: {'/'.join(key)}")
        targets[key] = {
            "text": batch11_norm(text),
            "source_refs": batch11_norm(refs),
        }

    for slug in BATCH11_FINAL2_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"batch11-final2 inventory page missing: {slug}")
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"batch11-final2 inventory body missing: {slug}/{language}")
                continue
            sources = body.select("ul.source-list > li[data-source-id]")
            page_refs = "page-sources:" + " ".join(
                source.get("data-source-id", "") for source in sources
            )
            for kind, target_id, selector in (
                ("article-title", "article-title", f".article-title .lang-{language}"),
                ("article-dek", "article-dek", f".article-dek .lang-{language}"),
            ):
                node = soup.select_one(selector)
                if node is None:
                    issues.append(f"batch11-final2 inventory target missing: {slug}/{language}/{target_id}")
                else:
                    add((slug, language, kind, target_id), normalized_visible(node), page_refs)
            for node in body.select("[data-fact-id]"):
                fact_id = node.get("data-fact-id", "")
                if (
                    not fact_id or fact_id.endswith("-sources")
                    or node.select_one("[data-fact-id]") is not None
                ):
                    continue
                add(
                    (slug, language, "fact", fact_id),
                    normalized_visible(node), node.get("data-source-ref", ""),
                )
            for source in sources:
                source_id = source.get("data-source-id", "")
                anchor = source.find("a")
                if not source_id or anchor is None:
                    issues.append(f"batch11-final2 malformed source: {slug}/{language}")
                    continue
                add(
                    (slug, language, "source-title", f"source-title:{source_id}"),
                    normalized_visible(anchor), source_id,
                )
            if slug == "hk-12":
                source = body.select_one('li[data-source-id="s4"]')
                category = source.find("b") if source else None
                if category is None:
                    issues.append(f"batch11-final2 HK s4 category missing: {language}")
                else:
                    add(
                        (slug, language, "source-category", "s4"),
                        normalized_visible(category), "s4",
                    )
    return targets, issues


def batch11_final2_allowed_target(key):
    slug, language, kind, target_id = key
    if slug == "2024-report":
        if kind == "fact":
            return target_id in {
                *BATCH11_FINAL2_2024_NAME_FACTS, "2024-report-state-2",
            }
        return kind == "source-title" and target_id == "source-title:s3"
    if slug == "feng-county-chained-woman":
        return kind == "fact" and target_id == "feng-county-chained-woman-protection"
    if slug == "hk-12":
        return kind == "source-category" and target_id == "s4"
    if slug == "xinjiang-camps":
        return (
            language in {"ja", "ko"} and kind == "fact"
        ) or (
            language == "no" and (
                kind == "fact"
                or (kind == "source-title" and target_id == "source-title:s4")
            )
        )
    if slug == "press-freedom-2026":
        if kind == "fact" and target_id == "press-freedom-2026-state-machinery-3":
            return True
        if language == "ja" and kind == "fact":
            return target_id == "press-freedom-2026-overview-1"
        if language == "fr" and kind == "article-dek":
            return target_id == "article-dek"
        if language == "nl" and kind == "fact":
            return target_id in {
                "press-freedom-2026-overview-2",
                "press-freedom-2026-state-machinery-2",
            }
    return False


def batch11_final2_historical_state(
    live_pages=None, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Authenticate the completed-final1 ledgers and reconstruct its five pages."""
    disk_reread, reread_issues = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch11-final2 reread ledger",
    )
    disk_contract, contract_issues = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch11-final2 contract ledger",
    )
    disk_source, source_issues = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch11-final2 source ledger",
    )
    if reread_rows is None:
        reread_rows = disk_reread
    if contract_rows is None:
        contract_rows = disk_contract
    if source_rows is None:
        source_rows = disk_source
    issues = [*reread_issues, *contract_issues, *source_issues]
    for path, rows, digest, label in (
        (BATCH9_REREAD_PATH, BATCH11_FINAL2_REREAD_ROWS,
         BATCH11_FINAL2_REREAD_SHA256, "batch11-final2 reread predecessor"),
        (BATCH9_CONTRACT_PATH, BATCH11_FINAL2_CONTRACT_ROWS,
         BATCH11_FINAL2_CONTRACT_SHA256, "batch11-final2 contract predecessor"),
        (BATCH9_SOURCE_LEDGER_PATH, BATCH11_FINAL2_SOURCE_ROWS,
         BATCH11_FINAL2_SOURCE_SHA256, "batch11-final2 source predecessor"),
    ):
        issues.extend(batch9_final2_exact_prefix(path, rows, digest, label))
    source_date_path = ROOT / "tools/data/source-date-ledger.tsv"
    if not source_date_path.exists():
        issues.append("batch11-final2 frozen source-date ledger is missing")
    else:
        payload = batch14_source_date_prefix_bytes()
        if hashlib.sha256(payload).hexdigest() != BATCH11_FINAL2_SOURCE_DATE_SHA256:
            issues.append("batch11-final2 source-date ledger bytes changed")
        try:
            reader = csv.DictReader(io.StringIO(payload.decode("utf-8")), delimiter="\t")
            source_date_rows = list(reader)
        except UnicodeDecodeError:
            source_date_rows = []
            issues.append("batch11-final2 source-date ledger is not UTF-8")
        if len(source_date_rows) != BATCH11_FINAL2_SOURCE_DATE_ROWS:
            issues.append(
                f"batch11-final2 source-date ledger has {len(source_date_rows)} rows, expected 294"
            )

    if live_pages is None:
        live_pages = {
            slug: BeautifulSoup(
                (ROOT / "posts" / f"{slug}.html").read_text(encoding="utf-8"),
                "html.parser",
            )
            for slug in BATCH11_FINAL2_SLUGS
        }
    pre_pages = dict(live_pages)
    for slug in BATCH11_FINAL2_SLUGS:
        if slug in live_pages:
            pre_pages[slug] = deepcopy(live_pages[slug])
    for row in reread_rows[BATCH11_FINAL2_REREAD_ROWS:]:
        slug = row.get("slug", "")
        if slug not in BATCH11_FINAL2_SLUG_SET:
            continue
        key = (
            slug, row.get("language", ""), row.get("target_kind", ""),
            row.get("target_id", ""),
        )
        node = batch11_final2_target_node(pre_pages, *key)
        if node is None:
            issues.append(f"batch11-final2 cannot restore predecessor target: {'/'.join(key)}")
            continue
        if key[2] == "source-category":
            node.clear()
            node.append(row.get("original_text", ""))
        elif not batch11_final1_restore_text(
            node, key[2], row.get("original_text", ""),
        ):
            issues.append(f"batch11-final2 cannot restore labelled target: {'/'.join(key)}")

    source_prefix = source_rows[:BATCH11_FINAL2_SOURCE_ROWS]
    source_tips = {}
    for row in source_prefix:
        source_tips[(
            row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
        )] = row
    for (slug, language, fact_id), row in source_tips.items():
        if slug not in BATCH11_FINAL2_SLUG_SET:
            continue
        node = pre_pages[slug].select_one(
            f'[data-language-body="{language}"] [data-fact-id="{fact_id}"]'
        )
        if node is None or node.select_one("[data-fact-id]") is not None:
            continue
        for column, attribute in (
            ("data_source_ref", "data-source-ref"),
            ("timeline_subject", "data-timeline-subject"),
            ("timeline_action", "data-timeline-action"),
            ("timeline_consequence", "data-timeline-consequence"),
        ):
            value = row.get(column, "")
            if value:
                node[attribute] = value
            elif node.has_attr(attribute):
                del node[attribute]
    for slug, expected in BATCH11_FINAL2_PAGE_SHA256.items():
        soup = pre_pages.get(slug)
        if soup is None:
            continue
        digest = hashlib.sha256(batch11_final1_page_payload(soup)).hexdigest()
        if digest != expected:
            issues.append(
                f"{slug}: batch11-final2 completed-final1 canonical preimage did not reconstruct"
            )
    return (
        pre_pages,
        disk_reread[:BATCH11_FINAL2_REREAD_ROWS],
        disk_contract[:BATCH11_FINAL2_CONTRACT_ROWS],
        disk_source[:BATCH11_FINAL2_SOURCE_ROWS],
        issues,
    )


def audit_batch11_final2_sources(pages):
    """Freeze all source metadata and every non-authorized title/category."""
    metadata = []
    titles = []
    categories = []
    for slug in BATCH11_FINAL2_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                continue
            for order, source in enumerate(
                body.select("ul.source-list > li[data-source-id]")
            ):
                source_id = source.get("data-source-id", "")
                anchor = source.find("a")
                label = source.find("b")
                metadata.append(json.dumps([
                    slug, language, order, source_id,
                    source.get("data-source-type", ""),
                    source.get("data-source-date", ""),
                    anchor.get("href", "") if anchor else "",
                ], ensure_ascii=False, separators=(",", ":")) + "\n")
                if not (
                    (slug == "2024-report" and source_id == "s3")
                    or (slug == "xinjiang-camps" and language == "no" and source_id == "s4")
                ):
                    titles.append(json.dumps([
                        slug, language, order, source_id,
                        anchor.get_text(" ", strip=True) if anchor else "",
                    ], ensure_ascii=False, separators=(",", ":")) + "\n")
                if not (slug == "hk-12" and source_id == "s4"):
                    categories.append(json.dumps([
                        slug, language, order, source_id,
                        label.get_text(" ", strip=True) if label else "",
                    ], ensure_ascii=False, separators=(",", ":")) + "\n")
    issues = []
    for rows, count, digest, label in (
        (metadata, BATCH11_FINAL2_SOURCE_SIGNATURE_ROWS,
         BATCH11_FINAL2_SOURCE_SIGNATURE_SHA256, "source ID/type/date/URL/order metadata"),
        (titles, BATCH11_FINAL2_FROZEN_TITLE_ROWS,
         BATCH11_FINAL2_FROZEN_TITLE_SHA256, "frozen source titles"),
        (categories, BATCH11_FINAL2_FROZEN_CATEGORY_ROWS,
         BATCH11_FINAL2_FROZEN_CATEGORY_SHA256, "frozen source categories"),
    ):
        if len(rows) != count:
            issues.append(f"batch11-final2 {label} has {len(rows)} rows, expected {count}")
        if hashlib.sha256("".join(rows).encode("utf-8")).hexdigest() != digest:
            issues.append(f"batch11-final2 changed {label}")
    return issues


def audit_batch11_final2_frozen(overrides=None):
    """Authenticate every file outside the exact ten-file final2 scope."""
    # Replayed against the authenticated pre-batch13 bytes of the 49 revised
    # dossiers, so every digest below still runs; an explicit override wins.
    overrides = {**batch13_historical_bytes(), **(overrides or {})}
    records = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        if ".git" in relative_path.parts or path.name == ".DS_Store":
            continue
        if relative in BATCH11_FINAL2_ALLOWED_FILES:
            continue
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else path.read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if batch11_final1_is_desktop_extra(relative, payload):
            continue
        records.append((relative, len(payload), hashlib.sha256(payload).hexdigest()))
    canonical = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(records)
    ).encode("utf-8")
    issues = []
    if len(records) != BATCH11_FINAL2_PROTECTED_FILES:
        issues.append(
            f"batch11-final2 protected manifest has {len(records)} files, expected {BATCH11_FINAL2_PROTECTED_FILES}"
        )
    if hashlib.sha256(canonical).hexdigest() != BATCH11_FINAL2_PROTECTED_SHA256:
        issues.append("batch11-final2 changed a file outside its exact ten-file scope")
    for relative, digest in (
        ("script.js", BATCH11_FINAL1_SCRIPT_SHA256),
        ("tools/data/source-date-ledger.tsv", BATCH11_FINAL2_SOURCE_DATE_SHA256),
        ("posts/causeway-bay-books.html", "44aee8b5006082d470ac9e2b7eac07bd10a6817f736abe1b21075053f0a1cf08"),
    ):
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else (ROOT / relative).read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if hashlib.sha256(payload).hexdigest() != digest:
            issues.append(f"batch11-final2 changed frozen {relative}")
    return issues


def audit_batch11_final2_wiring(source_text=None):
    source_text = source_text or Path(__file__).read_text(encoding="utf-8")
    live = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    main = re.search(
        r"def main\(\):(?P<body>.*?)(?=\nif __name__ ==)", source_text, re.S,
    )
    issues = []
    live_calls = [] if live is None else re.findall(
        r"issues\.extend\(audit_batch11_final2\(", live.group("body")
    )
    self_calls = [] if main is None else re.findall(
        r"batch11_final2_self_test\s*=\s*batch11_final2_negative_self_test\(",
        main.group("body"),
    )
    if len(live_calls) != 1:
        issues.append("batch11-final2 authoritative audit_live wiring is absent")
    if len(self_calls) != 1:
        issues.append("batch11-final2 named negative suite is not wired into --self-test")
    return issues


def batch11_final2_fact_map(pages):
    facts = {}
    for slug in BATCH11_FINAL2_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                continue
            sources = {
                source.get("data-source-id", ""): source
                for source in body.select("ul.source-list > li[data-source-id]")
            }
            h1 = normalized_visible(soup.select_one(f".article-title .lang-{language}"))
            dek = normalized_visible(soup.select_one(f".article-dek .lang-{language}"))
            all_titles = " | ".join(
                f"{source_id}:{normalized_visible(source.find('a'))}"
                for source_id, source in sources.items()
            )
            for node in body.select("[data-fact-id]"):
                fact_id = node.get("data-fact-id", "")
                if (
                    not fact_id or fact_id.endswith("-sources")
                    or node.select_one("[data-fact-id]") is not None
                ):
                    continue
                refs = " ".join(node.get("data-source-ref", "").split())
                ref_ids = refs.split()
                urls = " | ".join(
                    sources[source_id].find("a").get("href", "")
                    for source_id in ref_ids
                    if source_id in sources and sources[source_id].find("a")
                )
                locators = " | ".join(
                    f"{source_id}: {normalized_visible(sources[source_id].find('a'))}"
                    for source_id in ref_ids if source_id in sources
                )
                dates = " | ".join(
                    f"{source_id}={sources[source_id].get('data-source-date', '') or 'UNDATED'}"
                    for source_id in ref_ids if source_id in sources
                ) or "NO_SOURCE_REF"
                roles = " | ".join(
                    f"{source_id}:{sources[source_id].get('data-source-type', '')}"
                    for source_id in ref_ids if source_id in sources
                )
                visible = normalized_visible(node)
                heading = node.find_previous("h2")
                facts[(slug, language, fact_id)] = {
                    "section_id": heading.get("data-section", "") if heading else "",
                    "current_visible_text": visible,
                    "data_source_ref": refs,
                    "timeline_subject": node.get("data-timeline-subject", ""),
                    "timeline_action": node.get("data-timeline-action", ""),
                    "timeline_consequence": node.get("data-timeline-consequence", ""),
                    "support_urls": urls,
                    "locatable_support": locators,
                    "source_roles": roles,
                    "source_date_audit": dates,
                    "visible_source_roles": roles,
                    "reread_h1_current": h1,
                    "reread_dek_current": dek,
                    "reread_timeline_current": (
                        visible if node.has_attr("data-timeline-action") else ""
                    ),
                    "reread_rights_current": (
                        visible if fact_id == f"{slug}-rights-analysis" else ""
                    ),
                    "reread_protection_current": (
                        visible if fact_id == f"{slug}-protection" else ""
                    ),
                    "reread_source_titles_current": all_titles,
                    "reread_card_current": f"{h1} | {dek}",
                    "reread_revision_text": visible,
                    "audit_final_url": urls,
                    "audit_title": locators,
                    "audit_source_id": refs,
                    "audit_locator": locators,
                    "audit_claim_compared": visible,
                }
    return facts


def audit_batch11_final2_contracts(rows, reread_by_key):
    """Reject contracts that lack independent invariant codes or copy prose."""
    issues = []
    for row in rows:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        label = "/".join(key)
        required = tuple(
            part.strip() for part in row.get("required_all", "").split("||")
            if part.strip()
        )
        forbidden = tuple(
            part.strip() for part in row.get("forbidden_any", "").split("||")
            if part.strip()
        )
        labels = [part.split(":", 1)[0] for part in required if ":" in part]
        if set(labels) != {"actor", "action", "source", "consequence", "remedy"}:
            issues.append(f"batch11-final2 contract lacks five named invariants: {label}")
        if len(labels) != 5 or any(not part.split(":", 1)[-1].strip() for part in required):
            issues.append(f"batch11-final2 contract invariant codes are blank or duplicated: {label}")
        if len(set(forbidden)) < 2 or any(
            not part.startswith("old-error:") for part in forbidden
        ):
            issues.append(f"batch11-final2 contract lacks two independent old-error codes: {label}")
        summary = row.get("fact_summary", "").casefold()
        if not all(
            marker in summary
            for marker in ("subject:", "action:", "source:", "consequence:", "remedy:")
        ):
            issues.append(f"batch11-final2 contract summary lacks the five factual roles: {label}")
        revised = batch11_norm(
            reread_by_key.get(key, {}).get("revised_text", "")
        )
        revised_stream = final1_contiguous_stream(revised)
        for invariant in required:
            code = invariant.split(":", 1)[-1]
            code_stream = final1_contiguous_stream(code)
            if len(code_stream) >= 80 and code_stream in revised_stream:
                issues.append(f"batch11-final2 contract copied a long revised-DOM answer: {label}")
                break
        if revised and final1_longest_common_fragment(
            row.get("fact_summary", ""), revised,
        ) >= min(180, max(100, len(final1_contiguous_stream(revised)) // 2)):
            issues.append(f"batch11-final2 contract summary is a DOM-derived paraphrase shell: {label}")
    return issues


def audit_batch11_final2_ledgers(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Derive every final2 delta from an authenticated final1 reconstruction."""
    issues = []
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11-final2 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11-final2 contract ledger",
        )
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11-final2 source ledger",
        )
        issues.extend(load_issues)
    historical = batch11_final2_historical_state(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    pre_pages, prefix_reread, _prefix_contract, prefix_source = historical[:4]
    issues.extend(historical[-1])
    pre_inventory, pre_inventory_issues = batch11_final2_inventory(pre_pages)
    live_inventory, live_inventory_issues = batch11_final2_inventory(pages)
    issues.extend(pre_inventory_issues)
    issues.extend(live_inventory_issues)
    if set(pre_inventory) != set(live_inventory):
        issues.append("batch11-final2 added or removed a public semantic target")
    expected_changes = {
        key for key in set(pre_inventory) & set(live_inventory)
        if pre_inventory[key] != live_inventory[key]
    }
    for key in set(pre_inventory) & set(live_inventory):
        if pre_inventory[key]["source_refs"] != live_inventory[key]["source_refs"]:
            issues.append(f"batch11-final2 changed frozen refs: {'/'.join(key)}")
    unauthorized = {key for key in expected_changes if not batch11_final2_allowed_target(key)}
    if unauthorized:
        issues.append(
            "batch11-final2 changed unauthorized visible targets: "
            + ", ".join("/".join(key) for key in sorted(unauthorized))
        )
    if not expected_changes:
        issues.append("batch11-final2 has no genuine public-text revisions")
    if reread_rows[:BATCH11_FINAL2_REREAD_ROWS] != prefix_reread:
        issues.append("batch11-final2 in-memory reread predecessor differs from authenticated bytes")
    if contract_rows[:BATCH11_FINAL2_CONTRACT_ROWS] != _prefix_contract:
        issues.append("batch11-final2 in-memory contract predecessor differs from authenticated bytes")
    if source_rows[:BATCH11_FINAL2_SOURCE_ROWS] != prefix_source:
        issues.append("batch11-final2 in-memory source predecessor differs from authenticated bytes")
    reread_suffix = reread_rows[BATCH11_FINAL2_REREAD_ROWS:]
    contract_suffix = contract_rows[BATCH11_FINAL2_CONTRACT_ROWS:]
    source_suffix = source_rows[BATCH11_FINAL2_SOURCE_ROWS:]

    def visible_key(row):
        return (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )

    reread_keys = [visible_key(row) for row in reread_suffix]
    contract_keys = [visible_key(row) for row in contract_suffix]
    if len(reread_keys) != len(set(reread_keys)):
        issues.append("batch11-final2 reread suffix duplicates a target")
    if len(contract_keys) != len(set(contract_keys)):
        issues.append("batch11-final2 contract suffix duplicates a target")
    if set(reread_keys) != expected_changes:
        issues.append(
            "batch11-final2 reread coverage differs from genuine changes: "
            f"missing={len(expected_changes - set(reread_keys))} "
            f"extra={len(set(reread_keys) - expected_changes)}"
        )
    if set(contract_keys) != expected_changes:
        issues.append(
            "batch11-final2 contract coverage differs from genuine changes: "
            f"missing={len(expected_changes - set(contract_keys))} "
            f"extra={len(set(contract_keys) - expected_changes)}"
        )
    reread_by_key = {visible_key(row): row for row in reread_suffix}
    contract_by_key = {visible_key(row): row for row in contract_suffix}
    predecessor_tips = {}
    for row in prefix_reread:
        predecessor_tips[visible_key(row)] = row
    reread_ids = set()
    for key, row in reread_by_key.items():
        label = "/".join(key)
        expected_prefix = f"{BATCH11_FINAL2_PREFIX}{':'.join(key)}:"
        contract_id = row.get("contract_id", "")
        if not contract_id.startswith(expected_prefix):
            issues.append(f"batch11-final2 reread ID is not target-bound: {label}")
        if not contract_id or contract_id in reread_ids:
            issues.append(f"batch11-final2 reread ID is blank or duplicate: {label}")
        reread_ids.add(contract_id)
        pre = pre_inventory.get(key, {"text": "", "source_refs": ""})
        live = live_inventory.get(key, {"text": "", "source_refs": ""})
        if row.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11-final2 reread is not a real revision: {label}")
        if "PASS_NO_CHANGE" in row.get("result", ""):
            issues.append(f"batch11-final2 reread records a forbidden no-change result: {label}")
        if not row.get("issue_found", "").strip():
            issues.append(f"batch11-final2 reread lacks a concrete defect: {label}")
        if "reread:batch11-final2" not in row.get("review_basis", ""):
            issues.append(f"batch11-final2 reread lacks manual review evidence: {label}")
        if batch11_norm(row.get("original_text", "")) != pre["text"]:
            issues.append(f"batch11-final2 original differs from authenticated final1: {label}")
        if batch11_norm(row.get("revised_text", "")) != live["text"]:
            issues.append(f"batch11-final2 revision differs from live DOM: {label}")
        if batch11_norm(row.get("source_refs", "")) != live["source_refs"]:
            issues.append(f"batch11-final2 reread refs differ from live DOM: {label}")
        if pre["text"] == live["text"]:
            issues.append(f"batch11-final2 reread records unchanged text: {label}")
        predecessor = predecessor_tips.get(key)
        if predecessor is not None and batch11_norm(
            predecessor.get("revised_text", "")
        ) != pre["text"]:
            issues.append(f"batch11-final2 predecessor chain is broken: {label}")
    contract_ids = [row.get("contract_id", "") for row in contract_suffix]
    if set(contract_ids) != reread_ids or len(contract_ids) != len(set(contract_ids)):
        issues.append("batch11-final2 contracts and rereads are not a one-to-one ID pair")
    for key, row in contract_by_key.items():
        expected_prefix = f"{BATCH11_FINAL2_PREFIX}{':'.join(key)}:"
        if not row.get("contract_id", "").startswith(expected_prefix):
            issues.append(f"batch11-final2 contract identity is not target-bound: {'/'.join(key)}")
    issues.extend(audit_batch11_final2_contracts(contract_suffix, reread_by_key))

    pre_facts = batch11_final2_fact_map(pre_pages)
    live_facts = batch11_final2_fact_map(pages)
    projection = (
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence",
    )
    expected_fact_changes = {
        key for key in set(pre_facts) & set(live_facts)
        if any(
            batch11_norm(pre_facts[key][field]) != batch11_norm(live_facts[key][field])
            for field in projection
        )
    }
    source_keys = [(
        row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
    ) for row in source_suffix]
    if len(source_keys) != len(set(source_keys)):
        issues.append("batch11-final2 source suffix duplicates a fact")
    if set(source_keys) != expected_fact_changes:
        issues.append(
            "batch11-final2 source coverage differs from genuine fact changes: "
            f"missing={len(expected_fact_changes - set(source_keys))} "
            f"extra={len(set(source_keys) - expected_fact_changes)}"
        )
    source_tips = {}
    for row in prefix_source:
        source_tips[(
            row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
        )] = row
    mutable = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "baseline_issue",
        "resolution_action", "support_urls", "locatable_support", "source_roles",
        "final_issue", "audit_accessed_at", "audit_final_url", "audit_title",
        "audit_source_id", "audit_locator", "audit_support_summary",
        "audit_relationship", "audit_claim_compared", "audit_decision",
        "source_date_audit", "reread_h1_current", "reread_dek_current",
        "reread_timeline_current", "reread_rights_current",
        "reread_protection_current", "reread_source_titles_current",
        "reread_card_current", "reread_issue_found", "reread_revision_text",
        "reread_result", "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor", "visible_timeline_order",
        "visible_source_roles",
    }
    for row in source_suffix:
        key = (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        label = "/".join(key)
        predecessor = source_tips.get(key)
        live = live_facts.get(key)
        if predecessor is None or live is None:
            issues.append(f"batch11-final2 source row lacks predecessor/live fact: {label}")
            continue
        for field in BATCH9_FINAL2_SOURCE_COLUMNS:
            if field not in mutable and row.get(field, "") != predecessor.get(field, ""):
                issues.append(f"batch11-final2 source row changed protected {field}: {label}")
                break
        for field, expected in live.items():
            if field not in BATCH9_FINAL2_SOURCE_COLUMNS:
                continue
            if field in {
                "locatable_support", "audit_locator", "reread_card_current",
                "source_roles",
            }:
                # These are deliberately richer, hand-authored locators in
                # the source ledger; exact DOM identity is checked through
                # the URL/title/ID projections immediately below.
                continue
            if batch11_norm(row.get(field, "")) != batch11_norm(expected):
                issues.append(f"batch11-final2 source {field} differs from live projection: {label}")
        visible = (key[0], key[1], "fact", key[2])
        paired = contract_by_key.get(visible)
        if paired is None or row.get("baseline_issue", "") != paired.get("contract_id", ""):
            issues.append(f"batch11-final2 source baseline is not its paired contract: {label}")
        for field in ("reread_card_current", "source_roles"):
            if row.get(field, "") != predecessor.get(field, ""):
                issues.append(f"batch11-final2 source changed frozen predecessor {field}: {label}")
        expected_values = {
            "resolution_action": (
                "reread:batch11-final2 corrected the visible semantics against the "
                "authenticated final1 predecessor and preserved cited source roles"
            ),
            "final_issue": (
                "reread:batch11-final2 visible claim and source mapping independently rechecked"
            ),
            "audit_decision": "PASS_FINAL2_SOURCE_MAPPING",
            "reread_result": "PASS_AFTER_REVISION",
            "audit_accessed_at": "2026-07-22",
        }
        for field, expected in expected_values.items():
            if row.get(field, "") != expected:
                issues.append(f"batch11-final2 source {field} marker differs: {label}")
        if not row.get("reread_issue_found", "").strip():
            issues.append(f"batch11-final2 source row lacks its concrete defect: {label}")
        for field in (
            "audit_final_url", "audit_title", "audit_source_id", "audit_locator",
            "audit_support_summary", "audit_relationship", "audit_claim_compared",
        ):
            if not row.get(field, "").strip():
                issues.append(f"batch11-final2 source evidence lacks {field}: {label}")
        if live["timeline_action"]:
            stream = final1_contiguous_stream(live["current_visible_text"])
            for field in (
                "visible_subject_anchor", "visible_action_anchor",
                "visible_consequence_anchor",
            ):
                anchor = final1_contiguous_stream(row.get(field, ""))
                if not anchor or anchor not in stream:
                    issues.append(f"batch11-final2 timeline {field} is unlocatable: {label}")
            if not row.get("visible_timeline_order", "").isdigit():
                issues.append(f"batch11-final2 timeline order is not explicit: {label}")
    return issues, {
        "changed_targets": len(expected_changes),
        "changed_facts": len(expected_fact_changes),
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "source_rows": len(source_suffix),
    }


def audit_batch11_final2(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    frozen_overrides=None, source_text=None,
):
    issues = []
    issues.extend(audit_batch11_final2_semantics(pages))
    issues.extend(audit_batch11_final2_sources(pages))
    ledger_issues, _stats = audit_batch11_final2_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    issues.extend(ledger_issues)
    issues.extend(audit_batch11_final2_frozen(frozen_overrides))
    issues.extend(audit_batch11_final2_wiring(source_text))
    return issues


def batch11_final2_negative_self_test(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Exercise seventeen named final2 DOM, attribute, chain and freeze failures."""
    names = []
    misses = []
    semantic_baseline = audit_batch11_final2_semantics(pages)
    source_baseline = audit_batch11_final2_sources(pages)

    def record(name, caught, baseline=()):
        names.append(name)
        if baseline or not caught:
            detail = f" (baseline: {baseline[0]})" if baseline else ""
            misses.append(name + detail)

    def mutated_page(slug):
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        return mutated

    # 1. One English node uses a different ordinance name.
    mutated = mutated_page("2024-report")
    node = mutated["2024-report"].select_one(
        '[data-language-body="en"] [data-fact-id="2024-report-timeline-2"]'
    )
    text = normalized_visible(node).replace(
        "Safeguarding National Security Ordinance",
        "Maintenance of National Security Ordinance",
    )
    node.clear(); node.append(text)
    record("01 inconsistent ordinance name", bool(audit_batch11_final2_semantics(mutated)), semantic_baseline)

    # 2. Concrete institutions are replaced by abstract concepts.
    mutated = mutated_page("2024-report")
    node = mutated["2024-report"].select_one(
        '[data-language-body="en"] [data-fact-id="2024-report-state-2"]'
    )
    node.clear(); node.append(
        "Cyberspace and public security took these measures, with no procedural explanation."
    )
    record("02 abstract cyberspace/public-security actors", bool(audit_batch11_final2_semantics(mutated)), semantic_baseline)

    # 3. Both specified remedy-list regressions are real target mutations.
    list_caught = []
    mutated = mutated_page("2024-report")
    node = mutated["2024-report"].select_one(
        '[data-language-body="fr"] [data-fact-id="2024-report-unresolved-questions"]'
    )
    node.clear(); node.append("Restent à rendre publics : statistiques ; dossiers ; et.")
    list_caught.append(bool(audit_batch11_final2_semantics(mutated)))
    mutated = mutated_page("2024-report")
    node = mutated["2024-report"].select_one(
        '[data-language-body="nl"] [data-fact-id="2024-report-unresolved-questions"]'
    )
    text = normalized_visible(node).replace("beslissingen over rechtsmiddelen", "vonnissen")
    node.clear(); node.append(text)
    list_caught.append(bool(audit_batch11_final2_semantics(mutated)))
    record("03 French broken list / Dutch ordinary judgments", all(list_caught), semantic_baseline)

    # 4. Reader-facing anonymisation instruction returns in the exact paragraph.
    mutated = mutated_page("feng-county-chained-woman")
    node = mutated["feng-county-chained-woman"].select_one(
        '[data-language-body="en"] [data-fact-id="feng-county-chained-woman-protection"]'
    )
    node.append(" The material must be anonymized and return risk individually assessed.")
    record("04 Feng reader-facing operational guidance", bool(audit_batch11_final2_semantics(mutated)), semantic_baseline)

    # 5. HK s4 visibly collapses to generic independent media.
    mutated = mutated_page("hk-12")
    node = batch11_final2_target_node(mutated, "hk-12", "en", "source-category", "s4")
    node.clear(); node.append("Independent-media report")
    record("05 HK s4 generic independent-media label", bool(audit_batch11_final2_semantics(mutated)), semantic_baseline)

    # 6. ID/type/date/URL/order are each mutated on the actual source element.
    metadata_caught = []
    for field in ("id", "type", "date", "url", "order"):
        mutated = mutated_page("hk-12")
        body = mutated["hk-12"].select_one('[data-language-body="en"]')
        sources = body.select("ul.source-list > li[data-source-id]")
        s4 = next(source for source in sources if source.get("data-source-id") == "s4")
        if field == "id":
            s4["data-source-id"] = "s4-tampered"
        elif field == "type":
            s4["data-source-type"] = "independent-media"
        elif field == "date":
            s4["data-source-date"] = "2099-01-01"
        elif field == "url":
            s4.find("a")["href"] += "?tampered=1"
        else:
            s4.extract(); sources[0].insert_before(s4)
        metadata_caught.append(bool(audit_batch11_final2_sources(mutated)))
    record("06 HK s4 ID/type/date/URL/order", all(metadata_caught), source_baseline)

    # 7-8. Formal Japanese/Korean registers are independently polluted.
    mutated = mutated_page("xinjiang-camps")
    node = mutated["xinjiang-camps"].select_one(
        '[data-language-body="ja"] [data-fact-id="xinjiang-camps-protection"]'
    )
    node.append(" これは示しています。")
    record("07 Xinjiang Japanese desu/masu mixing", bool(audit_batch11_final2_semantics(mutated)), semantic_baseline)
    mutated = mutated_page("xinjiang-camps")
    node = mutated["xinjiang-camps"].select_one(
        '[data-language-body="ko"] [data-fact-id="xinjiang-camps-protection"]'
    )
    node.append(" 이를 보여줍니다.")
    record("08 Xinjiang Korean hamnida mixing", bool(audit_batch11_final2_semantics(mutated)), semantic_baseline)

    # 9. Both Norwegian defects are reinserted in their real nodes.
    no_caught = []
    mutated = mutated_page("xinjiang-camps")
    node = mutated["xinjiang-camps"].select_one(
        '[data-language-body="no"] li[data-source-id="s4"] a'
    )
    node.append(" massefængsling")
    no_caught.append(bool(audit_batch11_final2_semantics(mutated)))
    mutated = mutated_page("xinjiang-camps")
    node = mutated["xinjiang-camps"].select_one(
        '[data-language-body="no"] [data-fact-id="xinjiang-camps-protection"]'
    )
    node.append(" sammenhengende statlige poster")
    no_caught.append(bool(audit_batch11_final2_semantics(mutated)))
    record("09 Norwegian massefængsling/state-posts", all(no_caught), semantic_baseline)

    # 10. The NYT Xinjiang Files source is replaced, not merely scanned globally.
    xj_caught = []
    for substitute in ("ICIJ — China Cables", "中國電信 — 新疆電纜"):
        mutated = mutated_page("xinjiang-camps")
        node = mutated["xinjiang-camps"].select_one(
            '[data-language-body="en"] li[data-source-id="s4"] a'
        )
        node.clear(); node.append(substitute)
        xj_caught.append(bool(audit_batch11_final2_semantics(mutated)))
    record("10 NYT Xinjiang Files substitution", all(xj_caught), semantic_baseline)

    # 11. The unrelated university/may-miss template returns in state-3.
    mutated = mutated_page("press-freedom-2026")
    node = mutated["press-freedom-2026"].select_one(
        '[data-language-body="en"] [data-fact-id="press-freedom-2026-state-machinery-3"]'
    )
    node.append(" Universities and platforms may miss the connection to an isolated case.")
    record("11 press university/may-miss template", bool(audit_batch11_final2_semantics(mutated)), semantic_baseline)

    # 12. Each of the three named mechanical translations is restored locally.
    auxiliary_caught = []
    for language, selector, phrase in (
        ("fr", ".article-dek .lang-fr", "chefs de sécurité"),
        ("ja", '[data-language-body="ja"] [data-fact-id="press-freedom-2026-overview-1"]', "公衆の知る能力"),
        ("nl", '[data-language-body="nl"] [data-fact-id="press-freedom-2026-state-machinery-2"]', "schaduwen"),
    ):
        mutated = mutated_page("press-freedom-2026")
        node = mutated["press-freedom-2026"].select_one(selector)
        node.append(" " + phrase)
        auxiliary_caught.append(bool(audit_batch11_final2_semantics(mutated)))
    record("12 French/Japanese/Dutch mechanical translations", all(auxiliary_caught), semantic_baseline)

    # 13. Delete case-specific actor/consequence/remedy anchors in three cases.
    deletion_caught = []
    for slug, language, fact_id, token in (
        ("2024-report", "en", "2024-report-state-2", "Hong Kong’s national-security institutions"),
        ("feng-county-chained-woman", "en", "feng-county-chained-woman-protection", "independent and effective remedies"),
        ("press-freedom-2026", "en", "press-freedom-2026-state-machinery-3", "second layer of harm"),
    ):
        mutated = mutated_page(slug)
        node = mutated[slug].select_one(
            f'[data-language-body="{language}"] [data-fact-id="{fact_id}"]'
        )
        text = normalized_visible(node).replace(token, "", 1)
        node.clear(); node.append(text)
        deletion_caught.append(bool(audit_batch11_final2_semantics(mutated)))
    record("13 case actor/consequence/remedy deletion", all(deletion_caught), semantic_baseline)

    # 14. Four frozen classes use byte overrides against the real manifest.
    frozen_caught = []
    for relative in (
        "posts/causeway-bay-books.html", "script.js",
        "tools/data/source-date-ledger.tsv", "posts/chen-qiushi.html",
    ):
        frozen_caught.append(bool(audit_batch11_final2_frozen({
            relative: (ROOT / relative).read_bytes() + b"\nfinal2 mutation",
        })))
    record("14 frozen causeway/script/source-date/non-target files", all(frozen_caught))

    # 15. Delete each mandatory entry point from the audit's own source.
    source = Path(__file__).read_text(encoding="utf-8")
    wiring_caught = []
    for needle in (
        "    issues.extend(audit_batch11_final2(\n        pages, reread_rows=final2_reread,",
        "        batch11_final2_self_test = batch11_final2_negative_self_test(\n"
        "            final2_pages, reread_rows=final2_reread,",
    ):
        wiring_caught.append(bool(audit_batch11_final2_wiring(
            source.replace(needle, "        # removed final2 entry", 1)
        )))
    record("15 final2 validation/self-test entry deletion", all(wiring_caught))

    # 16-17. Prefix and suffix evidence mutations exercise the real validators.
    if reread_rows is None:
        reread_rows, _ = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS, "final2 self-test reread",
        )
    if contract_rows is None:
        contract_rows, _ = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS, "final2 self-test contract",
        )
    if source_rows is None:
        source_rows, _ = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS, "final2 self-test source",
        )
    ledger_baseline, _ = audit_batch11_final2_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    altered = deepcopy(reread_rows)
    altered[0]["revised_text"] += " tampered"
    prefix_issues, _ = audit_batch11_final2_ledgers(
        pages, reread_rows=altered, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    record("16 authenticated predecessor row mutation", bool(prefix_issues), ledger_baseline)
    if len(reread_rows) > BATCH11_FINAL2_REREAD_ROWS:
        altered = reread_rows[:-1]
        suffix_issues, _ = audit_batch11_final2_ledgers(
            pages, reread_rows=altered, contract_rows=contract_rows,
            source_rows=source_rows,
        )
        caught = bool(suffix_issues)
    else:
        caught = False
    record("17 final2 append coverage deletion", caught, ledger_baseline)
    if len(names) != 17 or len(set(names)) != 17:
        misses.append(f"batch11-final2 named suite cardinality is {len(names)}, expected 17")
    return len(names) - len(misses), len(names), misses


# ---------------------------------------------------------------------------
# Batch eleven final3: the fixed seventeen-target closing review.
#
# The hashes below authenticate the *completed final2* state.  They were
# captured before any final3 page or ledger edit.  Correct meanings are fixed
# independently in the handwritten rules below; no DOM or TSV cell is used to
# manufacture a semantic answer.


BATCH11_FINAL3_PREFIX = "reread:batch11-final3:"
BATCH11_FINAL3_PRE_REREAD_ROWS = 15967
BATCH11_FINAL3_PRE_REREAD_SHA256 = (
    "810f18ee0e8b59e1394f54c73644c57be4856e9b3355d78fdaa9b669fbb34b93"
)
BATCH11_FINAL3_PRE_CONTRACT_ROWS = 7002
BATCH11_FINAL3_PRE_CONTRACT_SHA256 = (
    "1ffc410dc1947e9103d07e4312d2846bb9e06a81039f2a8b596dfb99fecda78d"
)
