def batch11_final3_target_node(pages, slug, language, kind, target_id):
    """Locate one final3 target by its public language and stable identifier."""
    soup = pages.get(slug)
    if soup is None:
        return None
    if kind == "article-dek":
        return soup.select_one(f".article-dek .lang-{language}")
    body = soup.select_one(f'[data-language-body="{language}"]')
    return body.select_one(f'[data-fact-id="{target_id}"]') if body else None


def audit_batch11_final3_semantics(pages):
    """Check the three closing meanings against handwritten language rules."""
    issues = []
    for slug in BATCH11_FINAL3_SLUGS:
        if pages.get(slug) is None:
            issues.append(f"batch11-final3 page missing: {slug}")
    if issues:
        return issues

    report = pages["2024-report"]
    ja_dek = normalized_visible(report.select_one(".article-dek .lang-ja"))
    if "執行手段" not in ja_dek or "救済手段の不足" not in ja_dek:
        issues.append("2024-report/ja/dek: natural enforcement/remedy-shortfall wording is incomplete")
    if "救済の欠落" in ja_dek:
        issues.append("2024-report/ja/dek: mechanical 救済の欠落 returned")
    ja_overview1 = normalized_visible(report.select_one(
        '[data-language-body="ja"] [data-fact-id="2024-report-overview-1"]'
    ))
    for anchor in (
        "中国本土のインターネット統制", "弁護士や市民記録者への圧力",
        "新疆・チベットの政策", "表現", "結社", "信教", "情報アクセスの権利",
        "狭めた",
    ):
        if anchor not in ja_overview1:
            issues.append(f"2024-report/ja/overview-1: rights-constriction anchor missing: {anchor}")
    if "情報へのアクセスの空間" in ja_overview1 or "影響を及ぼしている" in ja_overview1:
        issues.append("2024-report/ja/overview-1: mechanical influence/space wording returned")
    ja_overview2 = normalized_visible(report.select_one(
        '[data-language-body="ja"] [data-fact-id="2024-report-overview-2"]'
    ))
    for anchor in ("国家機関", "具体的な介入", "救済手段の不足", "共通の構造"):
        if anchor not in ja_overview2:
            issues.append(f"2024-report/ja/overview-2: intervention/remedy structure missing: {anchor}")
    if "国家機関の行為と救済の欠落に共通する特徴" in ja_overview2:
        issues.append("2024-report/ja/overview-2: mechanical common-feature wording returned")
    ja_body = normalized_visible(report.select_one('[data-language-body="ja"]'))
    if re.search(r"(?:です|ます|でした|ました)(?:[。！？]|$)", ja_body):
        issues.append("2024-report/ja: polite register is mixed into the formal plain style")

    feng = pages["feng-county-chained-woman"]
    zh_questions = normalized_visible(feng.select_one(
        '[data-language-body="zh"] '
        '[data-fact-id="feng-county-chained-woman-unresolved-questions"]'
    ))
    for anchor in (
        "每名參與者", "拐賣", "轉運", "購買", "調查", "責任追究",
        "案件處理結果", "民間調查者", "聲援者", "警方聯繫", "詢問",
        "傳喚", "平臺刪帖記錄",
    ):
        if anchor not in zh_questions:
            issues.append(f"Feng/zh/unresolved: accountability/pressure record missing: {anchor}")
    if "每名責任人的處理" in zh_questions or "民間調查者受壓記錄" in zh_questions:
        issues.append("Feng/zh/unresolved: vague responsibility/pressure wording returned")

    en_questions = normalized_visible(feng.select_one(
        '[data-language-body="en"] '
        '[data-fact-id="feng-county-chained-woman-unresolved-questions"]'
    ))
    for anchor in (
        "investigation", "attribution of responsibility", "case outcomes",
        "each participant", "trafficking", "transfer", "purchase",
        "records of police contact", "questioning", "summonses", "post removals",
        "citizen investigators", "supporters",
    ):
        if anchor.casefold() not in en_questions.casefold():
            issues.append(f"Feng/en/unresolved: accountability/pressure record missing: {anchor}")
    if re.search(
        r"treatment of each person responsible|civilian investigators|"
        r"record of pressure on (?:civilian|citizen) investigators",
        en_questions, re.I,
    ):
        issues.append("Feng/en/unresolved: vague treatment/civilian-investigator wording returned")

    timeline_text = []
    for language, required in BATCH11_FINAL3_FENG_TIMELINE_REQUIRED.items():
        node = feng.select_one(
            f'[data-language-body="{language}"] '
            '[data-fact-id="feng-county-chained-woman-timeline-3"]'
        )
        text = normalized_visible(node)
        timeline_text.append(text)
        missing = batch11_final2_phrase_missing(text, required)
        if missing:
            issues.append(
                f"Feng/{language}/timeline-3: correction/trafficking/handling chain missing {missing}"
            )
        expected_attrs = {
            "data-source-ref": "s2 s4",
            "data-timeline-subject": "xuzhou-government-investigation-team",
            "data-timeline-action": "revised-account-and-acknowledged-trafficking-and-official-handling",
            "data-timeline-consequence": "earlier-notices-lost-credibility",
        }
        for attribute, expected in expected_attrs.items():
            if node is None or " ".join(node.get(attribute, "").split()) != expected:
                issues.append(f"Feng/{language}/timeline-3: frozen {attribute} changed")
        if language == "ja" and "後続の通報で" in text:
            issues.append("Feng/ja/timeline-3: Chinese-order 後続の通報で calque returned")
    if BATCH11_FINAL3_FENG_WRONG_ACTOR.search("\n".join(timeline_text)):
        issues.append("Feng/timeline-3: investigation team was recast as merely raising doubts")

    press = pages["press-freedom-2026"]
    for fact_id, required in BATCH11_FINAL3_PRESS_RULES.items():
        node = press.select_one(
            f'[data-language-body="fr"] [data-fact-id="{fact_id}"]'
        )
        text = normalized_visible(node)
        missing = batch11_final2_phrase_missing(text, required)
        if missing:
            issues.append(f"press/fr/{fact_id}: CPJ count/charge attribution missing {missing}")
        if BATCH11_FINAL3_PRESS_FORBIDDEN.search(text):
            issues.append(f"press/fr/{fact_id}: mechanical or adjudicated-charge wording returned")
    return issues


def batch11_final3_source_signature(pages):
    """Serialize fixed source metadata and every leaf fact's source refs."""
    metadata = []
    refs = []
    for slug in BATCH11_FINAL3_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                continue
            for order, source in enumerate(
                body.select("ul.source-list > li[data-source-id]")
            ):
                anchor = source.find("a")
                metadata.append(json.dumps([
                    slug, language, order, source.get("data-source-id", ""),
                    source.get("data-source-type", ""),
                    source.get("data-source-date", ""),
                    anchor.get("href", "") if anchor else "",
                ], ensure_ascii=False, separators=(",", ":")) + "\n")
            for node in body.select("[data-fact-id]"):
                fact_id = node.get("data-fact-id", "")
                if (
                    not fact_id or fact_id.endswith("-sources")
                    or node.select_one("[data-fact-id]") is not None
                ):
                    continue
                refs.append(json.dumps([
                    slug, language, fact_id,
                    " ".join(node.get("data-source-ref", "").split()),
                ], ensure_ascii=False, separators=(",", ":")) + "\n")
    return metadata, refs


def audit_batch11_final3_sources(pages):
    metadata, refs = batch11_final3_source_signature(pages)
    issues = []
    for rows, count, digest, label in (
        (metadata, BATCH11_FINAL3_SOURCE_METADATA_ROWS,
         BATCH11_FINAL3_SOURCE_METADATA_SHA256,
         "source ID/type/date/URL/order metadata"),
        (refs, BATCH11_FINAL3_SOURCE_REF_ROWS,
         BATCH11_FINAL3_SOURCE_REF_SHA256, "data-source-ref map"),
    ):
        if len(rows) != count:
            issues.append(f"batch11-final3 {label} has {len(rows)} rows, expected {count}")
        actual = hashlib.sha256("".join(rows).encode("utf-8")).hexdigest()
        if actual != digest:
            issues.append(f"batch11-final3 changed frozen {label}")
    return issues


def audit_batch11_final3_frozen(overrides=None):
    """Authenticate every file outside the exact eight-file final3 scope."""
    # Replayed against the authenticated pre-batch13 bytes of the 49 revised
    # dossiers, so every digest below still runs; an explicit override wins.
    overrides = {**batch13_historical_bytes(), **(overrides or {})}
    records = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        if ".git" in relative_path.parts or path.name == ".DS_Store":
            continue
        if relative in BATCH11_FINAL3_ALLOWED_FILES:
            continue
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else path.read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if batch11_final1_is_desktop_extra(relative, payload):
            continue
        records.append((relative, len(payload), hashlib.sha256(payload).hexdigest()))
    canonical = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(records)
    ).encode("utf-8")
    issues = []
    if len(records) != BATCH11_FINAL3_PROTECTED_FILES:
        issues.append(
            f"batch11-final3 protected manifest has {len(records)} files, "
            f"expected {BATCH11_FINAL3_PROTECTED_FILES}"
        )
    if hashlib.sha256(canonical).hexdigest() != BATCH11_FINAL3_PROTECTED_SHA256:
        issues.append("batch11-final3 changed a file outside its exact eight-file scope")
    for relative, digest in BATCH11_FINAL3_FROZEN_SHA256.items():
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else (ROOT / relative).read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if hashlib.sha256(payload).hexdigest() != digest:
            issues.append(f"batch11-final3 changed frozen {relative}")
    return issues


def batch11_final3_inventory(pages):
    """Enumerate all public leaves on the three pages in stable DOM order."""
    targets = {}
    issues = []

    def add(key, text, refs):
        if key in targets:
            issues.append(f"batch11-final3 duplicate target: {'/'.join(key)}")
        targets[key] = {"text": batch11_norm(text), "source_refs": batch11_norm(refs)}

    for slug in BATCH11_FINAL3_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"batch11-final3 inventory page missing: {slug}")
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"batch11-final3 language body missing: {slug}/{language}")
                continue
            sources = body.select("ul.source-list > li[data-source-id]")
            page_refs = "page-sources:" + " ".join(
                source.get("data-source-id", "") for source in sources
            )
            for kind, target_id, selector in (
                ("article-title", "article-title", f".article-title .lang-{language}"),
                ("article-dek", "article-dek", f".article-dek .lang-{language}"),
            ):
                node = soup.select_one(selector)
                if node is None:
                    issues.append(f"batch11-final3 target missing: {slug}/{language}/{target_id}")
                else:
                    add((slug, language, kind, target_id), normalized_visible(node), page_refs)
            for node in body.select("[data-fact-id]"):
                fact_id = node.get("data-fact-id", "")
                if (
                    not fact_id or fact_id.endswith("-sources")
                    or node.select_one("[data-fact-id]") is not None
                ):
                    continue
                add(
                    (slug, language, "fact", fact_id), normalized_visible(node),
                    node.get("data-source-ref", ""),
                )
            for source in sources:
                source_id = source.get("data-source-id", "")
                anchor = source.find("a")
                label = source.find("b")
                if not source_id or anchor is None or label is None:
                    issues.append(f"batch11-final3 malformed source: {slug}/{language}")
                    continue
                add(
                    (slug, language, "source-title", f"source-title:{source_id}"),
                    normalized_visible(anchor), source_id,
                )
                add(
                    (slug, language, "source-category", f"source-category:{source_id}"),
                    normalized_visible(label), source_id,
                )
    return targets, issues


def batch11_final3_historical_state(
    live_pages=None, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Authenticate and reconstruct the completed-final2 predecessor."""
    disk_reread, reread_issues = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch11-final3 reread ledger",
    )
    disk_contract, contract_issues = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch11-final3 contract ledger",
    )
    disk_source, source_issues = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch11-final3 source ledger",
    )
    if reread_rows is None:
        reread_rows = disk_reread
    if contract_rows is None:
        contract_rows = disk_contract
    if source_rows is None:
        source_rows = disk_source
    issues = [*reread_issues, *contract_issues, *source_issues]
    for path, rows, digest, label in (
        (BATCH9_REREAD_PATH, BATCH11_FINAL3_PRE_REREAD_ROWS,
         BATCH11_FINAL3_PRE_REREAD_SHA256, "batch11-final3 reread predecessor"),
        (BATCH9_CONTRACT_PATH, BATCH11_FINAL3_PRE_CONTRACT_ROWS,
         BATCH11_FINAL3_PRE_CONTRACT_SHA256, "batch11-final3 contract predecessor"),
        (BATCH9_SOURCE_LEDGER_PATH, BATCH11_FINAL3_PRE_SOURCE_ROWS,
         BATCH11_FINAL3_PRE_SOURCE_SHA256, "batch11-final3 source predecessor"),
    ):
        issues.extend(batch9_final2_exact_prefix(path, rows, digest, label))
    source_date_path = ROOT / "tools/data/source-date-ledger.tsv"
    if not source_date_path.exists():
        issues.append("batch11-final3 frozen source-date ledger is missing")
    else:
        payload = batch14_source_date_prefix_bytes()
        if hashlib.sha256(payload).hexdigest() != BATCH11_FINAL3_SOURCE_DATE_SHA256:
            issues.append("batch11-final3 source-date ledger bytes changed")
        try:
            reader = csv.DictReader(io.StringIO(payload.decode("utf-8")), delimiter="\t")
            source_date_rows = list(reader)
        except UnicodeDecodeError:
            source_date_rows = []
            issues.append("batch11-final3 source-date ledger is not UTF-8")
        if len(source_date_rows) != BATCH11_FINAL3_SOURCE_DATE_ROWS:
            issues.append(
                f"batch11-final3 source-date ledger has {len(source_date_rows)} rows, expected 294"
            )

    if live_pages is None:
        live_pages = {
            slug: BeautifulSoup(
                (ROOT / "posts" / f"{slug}.html").read_text(encoding="utf-8"),
                "html.parser",
            )
            for slug in BATCH11_FINAL3_SLUGS
        }
    predecessor = dict(live_pages)
    for slug in BATCH11_FINAL3_SLUGS:
        if slug in live_pages:
            predecessor[slug] = deepcopy(live_pages[slug])
    for row in reread_rows[BATCH11_FINAL3_PRE_REREAD_ROWS:]:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        if key[0] not in BATCH11_FINAL3_SLUG_SET:
            continue
        node = batch11_final3_target_node(predecessor, *key)
        if node is None:
            issues.append(f"batch11-final3 cannot restore predecessor target: {'/'.join(key)}")
            continue
        if not batch11_final1_restore_text(
            node, key[2], row.get("original_text", ""),
        ):
            issues.append(f"batch11-final3 cannot restore labelled target: {'/'.join(key)}")
    for slug, expected in BATCH11_FINAL3_PRE_PAGE_SHA256.items():
        soup = predecessor.get(slug)
        if soup is None:
            continue
        actual = hashlib.sha256(batch11_final1_page_payload(soup)).hexdigest()
        if actual != expected:
            issues.append(f"{slug}: completed-final2 canonical preimage did not reconstruct")
    return (
        predecessor,
        disk_reread[:BATCH11_FINAL3_PRE_REREAD_ROWS],
        disk_contract[:BATCH11_FINAL3_PRE_CONTRACT_ROWS],
        disk_source[:BATCH11_FINAL3_PRE_SOURCE_ROWS],
        issues,
    )


def batch11_final3_fact_map(pages):
    return {
        key: value for key, value in batch11_final2_fact_map(pages).items()
        if key[0] in BATCH11_FINAL3_SLUG_SET
    }


def audit_batch11_final3_contracts(rows, reread_by_key):
    """Demand target-bound, independently authored five-duty contracts."""
    issues = []
    signatures = []
    for row in rows:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        label = "/".join(key)
        required = tuple(
            part.strip() for part in row.get("required_all", "").split("||")
            if part.strip()
        )
        forbidden = tuple(
            part.strip() for part in row.get("forbidden_any", "").split("||")
            if part.strip()
        )
        labels = [part.split(":", 1)[0] for part in required if ":" in part]
        fixed = {"actor", "action", "consequence", "remedy"}
        if len(required) != 5 or not fixed.issubset(set(labels)) or not (
            {"source", "legal"} & set(labels)
        ):
            issues.append(f"batch11-final3 contract lacks five independent duties: {label}")
        if len(labels) != 5 or len(set(labels)) != 5 or any(
            not part.split(":", 1)[-1].strip() for part in required
        ):
            issues.append(f"batch11-final3 contract duty codes are blank or duplicated: {label}")
        if len(forbidden) != 2 or len(set(forbidden)) != 2 or any(
            not part.startswith("old-error:") or not part.split(":", 1)[-1].strip()
            for part in forbidden
        ):
            issues.append(f"batch11-final3 contract lacks two target-specific old errors: {label}")
        summary = row.get("fact_summary", "")
        summary_folded = summary.casefold()
        if not all(
            marker in summary_folded
            for marker in ("subject:", "action:", "consequence:", "remedy:")
        ) or not ("source:" in summary_folded or "legal:" in summary_folded):
            issues.append(f"batch11-final3 contract summary lacks five factual roles: {label}")
        revised = batch11_norm(reread_by_key.get(key, {}).get("revised_text", ""))
        revised_stream = final1_contiguous_stream(revised)
        for invariant in required:
            code_stream = final1_contiguous_stream(invariant.split(":", 1)[-1])
            if len(code_stream) >= 80 and code_stream in revised_stream:
                issues.append(f"batch11-final3 contract copied a long revised-DOM answer: {label}")
                break
        if revised and final1_longest_common_fragment(summary, revised) >= min(
            180, max(100, len(revised_stream) // 2)
        ):
            issues.append(f"batch11-final3 contract summary is a DOM-derived prose shell: {label}")
        signatures.append((row.get("required_all", ""), row.get("fact_summary", "")))
    if len(signatures) != len(set(signatures)):
        issues.append("batch11-final3 contracts reuse a supposedly handwritten target specification")
    return issues


def audit_batch11_final3_ledgers(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Derive exact 17/17/16 coverage from the authenticated final2 DOM."""
    issues = []
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11-final3 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11-final3 contract ledger",
        )
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11-final3 source ledger",
        )
        issues.extend(load_issues)
    historical = batch11_final3_historical_state(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    pre_pages, prefix_reread, prefix_contract, prefix_source = historical[:4]
    issues.extend(historical[-1])
    pre_inventory, pre_inventory_issues = batch11_final3_inventory(pre_pages)
    live_inventory, live_inventory_issues = batch11_final3_inventory(pages)
    issues.extend(pre_inventory_issues)
    issues.extend(live_inventory_issues)
    if set(pre_inventory) != set(live_inventory):
        issues.append("batch11-final3 added or removed a public semantic target")
    actual_changes = {
        key for key in set(pre_inventory) & set(live_inventory)
        if pre_inventory[key] != live_inventory[key]
    }
    if actual_changes != BATCH11_FINAL3_TARGETS:
        issues.append(
            "batch11-final3 visible changes differ from the exact 17-target scope: "
            f"missing={len(BATCH11_FINAL3_TARGETS - actual_changes)} "
            f"extra={len(actual_changes - BATCH11_FINAL3_TARGETS)}"
        )
    for key in set(pre_inventory) & set(live_inventory):
        if pre_inventory[key]["source_refs"] != live_inventory[key]["source_refs"]:
            issues.append(f"batch11-final3 changed frozen refs: {'/'.join(key)}")
    if reread_rows[:BATCH11_FINAL3_PRE_REREAD_ROWS] != prefix_reread:
        issues.append("batch11-final3 in-memory reread predecessor differs from authenticated bytes")
    if contract_rows[:BATCH11_FINAL3_PRE_CONTRACT_ROWS] != prefix_contract:
        issues.append("batch11-final3 in-memory contract predecessor differs from authenticated bytes")
    if source_rows[:BATCH11_FINAL3_PRE_SOURCE_ROWS] != prefix_source:
        issues.append("batch11-final3 in-memory source predecessor differs from authenticated bytes")
    reread_suffix = reread_rows[BATCH11_FINAL3_PRE_REREAD_ROWS:]
    contract_suffix = contract_rows[BATCH11_FINAL3_PRE_CONTRACT_ROWS:]
    source_suffix = source_rows[BATCH11_FINAL3_PRE_SOURCE_ROWS:]

    def visible_key(row):
        return (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )

    reread_keys = [visible_key(row) for row in reread_suffix]
    contract_keys = [visible_key(row) for row in contract_suffix]
    if len(reread_keys) != len(set(reread_keys)):
        issues.append("batch11-final3 reread suffix duplicates a target")
    if len(contract_keys) != len(set(contract_keys)):
        issues.append("batch11-final3 contract suffix duplicates a target")
    if set(reread_keys) != BATCH11_FINAL3_TARGETS:
        issues.append("batch11-final3 reread suffix is not the exact 17-target set")
    if set(contract_keys) != BATCH11_FINAL3_TARGETS:
        issues.append("batch11-final3 contract suffix is not the exact 17-target set")
    reread_by_key = {visible_key(row): row for row in reread_suffix}
    contract_by_key = {visible_key(row): row for row in contract_suffix}
    predecessor_tips = {}
    for row in prefix_reread:
        predecessor_tips[visible_key(row)] = row
    reread_ids = set()
    for key, row in reread_by_key.items():
        label = "/".join(key)
        contract_id = row.get("contract_id", "")
        expected_prefix = f"{BATCH11_FINAL3_PREFIX}{':'.join(key)}:"
        if not contract_id.startswith(expected_prefix):
            issues.append(f"batch11-final3 reread ID is not target-bound: {label}")
        if not contract_id or contract_id in reread_ids:
            issues.append(f"batch11-final3 reread ID is blank or duplicate: {label}")
        reread_ids.add(contract_id)
        pre = pre_inventory.get(key, {"text": "", "source_refs": ""})
        live = live_inventory.get(key, {"text": "", "source_refs": ""})
        if row.get("result", "") != "PASS_AFTER_REVISION" or (
            "PASS_NO_CHANGE" in row.get("result", "")
        ):
            issues.append(f"batch11-final3 reread is not a genuine revision: {label}")
        issue_found = row.get("issue_found", "").strip()
        if not issue_found:
            issues.append(f"batch11-final3 reread lacks the concrete old defect: {label}")
        elif final1_longest_common_fragment(issue_found, row.get("original_text", "")) < 6:
            issues.append(f"batch11-final3 issue does not quote its real old wording: {label}")
        review_basis = row.get("review_basis", "")
        if "reread:batch11-final3" not in review_basis:
            issues.append(f"batch11-final3 reread lacks its manual-review marker: {label}")
        if len(review_basis.strip()) < 48:
            issues.append(f"batch11-final3 review basis is not substantive: {label}")
        if batch11_norm(row.get("original_text", "")) != pre["text"]:
            issues.append(f"batch11-final3 original differs from completed final2: {label}")
        if batch11_norm(row.get("revised_text", "")) != live["text"]:
            issues.append(f"batch11-final3 revision differs from live DOM: {label}")
        if batch11_norm(row.get("source_refs", "")) != live["source_refs"]:
            issues.append(f"batch11-final3 reread refs differ from live DOM: {label}")
        if pre["text"] == live["text"] or batch11_norm(
            row.get("original_text", "")
        ) == batch11_norm(row.get("revised_text", "")):
            issues.append(f"batch11-final3 reread records unchanged text: {label}")
        predecessor = predecessor_tips.get(key)
        if predecessor is not None and batch11_norm(
            predecessor.get("revised_text", "")
        ) != pre["text"]:
            issues.append(f"batch11-final3 predecessor chain is broken: {label}")
    contract_ids = [row.get("contract_id", "") for row in contract_suffix]
    if set(contract_ids) != reread_ids or len(contract_ids) != len(set(contract_ids)):
        issues.append("batch11-final3 contracts and rereads are not a one-to-one ID pair")
    for key, row in contract_by_key.items():
        expected_prefix = f"{BATCH11_FINAL3_PREFIX}{':'.join(key)}:"
        if not row.get("contract_id", "").startswith(expected_prefix):
            issues.append(f"batch11-final3 contract identity is not target-bound: {'/'.join(key)}")
    issues.extend(audit_batch11_final3_contracts(contract_suffix, reread_by_key))

    pre_facts = batch11_final3_fact_map(pre_pages)
    live_facts = batch11_final3_fact_map(pages)
    projection = (
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence",
    )
    changed_facts = {
        key for key in set(pre_facts) & set(live_facts)
        if any(
            batch11_norm(pre_facts[key][field]) != batch11_norm(live_facts[key][field])
            for field in projection
        )
    }
    if changed_facts != BATCH11_FINAL3_FACT_TARGETS:
        issues.append("batch11-final3 fact/source projection is not the exact 16-fact set")
    source_keys = [(
        row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
    ) for row in source_suffix]
    if len(source_keys) != len(set(source_keys)):
        issues.append("batch11-final3 source suffix duplicates a fact")
    if set(source_keys) != BATCH11_FINAL3_FACT_TARGETS:
        issues.append("batch11-final3 source suffix is not the exact 16-fact set")
    source_tips = {}
    for row in prefix_source:
        source_tips[(
            row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
        )] = row
    mutable = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "baseline_issue",
        "resolution_action", "support_urls", "locatable_support", "source_roles",
        "final_issue", "audit_accessed_at", "audit_final_url", "audit_title",
        "audit_source_id", "audit_locator", "audit_support_summary",
        "audit_relationship", "audit_claim_compared", "audit_decision",
        "source_date_audit", "reread_h1_current", "reread_dek_current",
        "reread_timeline_current", "reread_rights_current",
        "reread_protection_current", "reread_source_titles_current",
        "reread_card_current", "reread_issue_found", "reread_revision_text",
        "reread_result", "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor", "visible_timeline_order", "visible_source_roles",
    }
    for row in source_suffix:
        key = (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        label = "/".join(key)
        predecessor = source_tips.get(key)
        live = live_facts.get(key)
        if predecessor is None or live is None:
            issues.append(f"batch11-final3 source row lacks predecessor/live fact: {label}")
            continue
        for field in BATCH9_FINAL2_SOURCE_COLUMNS:
            if field not in mutable and row.get(field, "") != predecessor.get(field, ""):
                issues.append(f"batch11-final3 source row changed protected {field}: {label}")
                break
        exact_live_fields = {
            "current_visible_text", "data_source_ref", "timeline_subject",
            "timeline_action", "timeline_consequence", "support_urls",
            "source_date_audit", "reread_timeline_current",
            "reread_rights_current", "reread_protection_current",
            "reread_revision_text", "audit_final_url", "audit_source_id",
            "audit_claim_compared", "source_roles", "visible_source_roles",
        }
        for field in exact_live_fields:
            expected = live.get(field, "")
            if batch11_norm(row.get(field, "")) != batch11_norm(expected):
                issues.append(f"batch11-final3 source {field} differs from live DOM: {label}")
        # Context snapshots that this fact did not itself revise remain the
        # authenticated predecessor values.  The sole companion dek change
        # is carried into the two Japanese 2024 fact overlays explicitly.
        for field in (
            "reread_h1_current", "reread_source_titles_current",
            "reread_card_current",
        ):
            if row.get(field, "") != predecessor.get(field, ""):
                issues.append(f"batch11-final3 source changed frozen context {field}: {label}")
        expected_dek = (
            live.get("reread_dek_current", "")
            if key[0:2] == ("2024-report", "ja")
            else predecessor.get("reread_dek_current", "")
        )
        if batch11_norm(row.get("reread_dek_current", "")) != batch11_norm(expected_dek):
            issues.append(f"batch11-final3 source contextual dek differs: {label}")
        visible_key_value = (key[0], key[1], "fact", key[2])
        paired = contract_by_key.get(visible_key_value)
        reread = reread_by_key.get(visible_key_value)
        if paired is None or row.get("baseline_issue", "") != paired.get("contract_id", ""):
            issues.append(f"batch11-final3 source baseline is not its paired contract: {label}")
        if reread is None or row.get("reread_issue_found", "") != reread.get("issue_found", ""):
            issues.append(f"batch11-final3 source issue is not its paired reread defect: {label}")
        if "reread:batch11-final3" not in row.get("resolution_action", ""):
            issues.append(f"batch11-final3 source resolution marker is absent: {label}")
        if "reread:batch11-final3" not in row.get("final_issue", ""):
            issues.append(f"batch11-final3 source final-review marker is absent: {label}")
        if row.get("audit_decision", "") != "PASS_FINAL3_SOURCE_MAPPING":
            issues.append(f"batch11-final3 source audit decision differs: {label}")
        if row.get("reread_result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11-final3 source reread result differs: {label}")
        if row.get("audit_accessed_at", "") != "2026-07-22":
            issues.append(f"batch11-final3 source audit date differs: {label}")
        for field in (
            "audit_final_url", "audit_title", "audit_source_id", "audit_locator",
            "audit_support_summary", "audit_relationship", "audit_claim_compared",
        ):
            if not row.get(field, "").strip():
                issues.append(f"batch11-final3 source evidence lacks {field}: {label}")
        if live["timeline_action"]:
            stream = final1_contiguous_stream(live["current_visible_text"])
            for field in (
                "visible_subject_anchor", "visible_action_anchor",
                "visible_consequence_anchor",
            ):
                anchor = final1_contiguous_stream(row.get(field, ""))
                if not anchor or anchor not in stream:
                    issues.append(f"batch11-final3 timeline {field} is unlocatable: {label}")
            if not row.get("visible_timeline_order", "").isdigit():
                issues.append(f"batch11-final3 timeline order is not explicit: {label}")
    return issues, {
        "changed_targets": len(actual_changes),
        "changed_facts": len(changed_facts),
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "source_rows": len(source_suffix),
    }


def audit_batch11_final3_wiring(source_text=None):
    source_text = source_text or Path(__file__).read_text(encoding="utf-8")
    live = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    main = re.search(
        r"def main\(\):(?P<body>.*?)(?=\nif __name__ ==)", source_text, re.S,
    )
    issues = []
    live_calls = [] if live is None else re.findall(
        r"issues\.extend\(audit_batch11_final3\(", live.group("body"),
    )
    self_calls = [] if main is None else re.findall(
        r"batch11_final3_self_test\s*=\s*batch11_final3_negative_self_test\(",
        main.group("body"),
    )
    if len(live_calls) != 1:
        issues.append("batch11-final3 authoritative audit_live wiring is absent")
    if len(self_calls) != 1:
        issues.append("batch11-final3 named negative suite is not wired into --self-test")
    return issues


def audit_batch11_final3(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    frozen_overrides=None, source_text=None,
):
    issues = []
    issues.extend(audit_batch11_final3_semantics(pages))
    issues.extend(audit_batch11_final3_sources(pages))
    ledger_issues, _stats = audit_batch11_final3_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    issues.extend(ledger_issues)
    issues.extend(audit_batch11_final3_frozen(frozen_overrides))
    issues.extend(audit_batch11_final3_wiring(source_text))
    return issues


def batch11_final3_negative_self_test(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Exercise the brief's twelve concrete final3 failure classes."""
    names = []
    misses = []
    semantic_baseline = audit_batch11_final3_semantics(pages)
    source_baseline = audit_batch11_final3_sources(pages)

    def record(name, caught, baseline=()):
        names.append(name)
        if baseline or not caught:
            detail = f" (baseline: {baseline[0]})" if baseline else ""
            misses.append(name + detail)

    def mutated_page(slug):
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        return mutated

    # 1. Reinsert the exact Japanese remedy mistranslation in the real dek.
    mutated = mutated_page("2024-report")
    node = batch11_final3_target_node(
        mutated, "2024-report", "ja", "article-dek", "article-dek",
    )
    node.string = normalized_visible(node).replace("救済手段の不足", "救済の欠落")
    record("01 Japanese remedy-absence reinsertion",
           bool(audit_batch11_final3_semantics(mutated)), semantic_baseline)

    # 2. Reinsert the exact access-space calque in its overview paragraph.
    mutated = mutated_page("2024-report")
    node = batch11_final3_target_node(
        mutated, "2024-report", "ja", "fact", "2024-report-overview-1",
    )
    node.clear(); node.append(
        "中国本土のインターネット統制、弁護士や市民記録者への圧力、"
        "新疆・チベットの政策は、情報へのアクセスの空間に引き続き影響を及ぼしている。"
    )
    record("02 Japanese information-access-space reinsertion",
           bool(audit_batch11_final3_semantics(mutated)), semantic_baseline)

    # 3. Delete state intervention and remedy-shortfall meaning independently.
    caught = []
    for phrase in ("国家機関による具体的な介入", "救済手段の不足"):
        mutated = mutated_page("2024-report")
        node = batch11_final3_target_node(
            mutated, "2024-report", "ja", "fact", "2024-report-overview-2",
        )
        node.string = normalized_visible(node).replace(phrase, "")
        caught.append(bool(audit_batch11_final3_semantics(mutated)))
    record("03 Japanese state-intervention/remedy deletion", all(caught), semantic_baseline)

    # 4. Restore the vague Chinese responsibility wording in the real fact.
    mutated = mutated_page("feng-county-chained-woman")
    node = batch11_final3_target_node(
        mutated, "feng-county-chained-woman", "zh", "fact",
        "feng-county-chained-woman-unresolved-questions",
    )
    node.string = normalized_visible(node).replace(
        "對拐賣、轉運和購買網絡中每名參與者的調查、責任追究與案件處理結果",
        "拐賣、運輸和購買網絡中每名責任人的處理",
    )
    record("04 Chinese vague responsibility-treatment reinsertion",
           bool(audit_batch11_final3_semantics(mutated)), semantic_baseline)

    # 5-6. Restore each specified English mistranslation independently.
    mutated = mutated_page("feng-county-chained-woman")
    node = batch11_final3_target_node(
        mutated, "feng-county-chained-woman", "en", "fact",
        "feng-county-chained-woman-unresolved-questions",
    )
    node.string = normalized_visible(node).replace(
        "the investigation, attribution of responsibility, and case outcomes concerning each participant",
        "the treatment of each person responsible",
    )
    record("05 English treatment-of-each-person reinsertion",
           bool(audit_batch11_final3_semantics(mutated)), semantic_baseline)
    mutated = mutated_page("feng-county-chained-woman")
    node = batch11_final3_target_node(
        mutated, "feng-county-chained-woman", "en", "fact",
        "feng-county-chained-woman-unresolved-questions",
    )
    node.string = normalized_visible(node).replace("citizen investigators", "civilian investigators")
    record("06 English civilian-investigator reinsertion",
           bool(audit_batch11_final3_semantics(mutated)), semantic_baseline)

    # 7. Restore both the Japanese Chinese-order calque and the wrong
    # questioning actor relationship in the actual timeline node.
    caught = []
    mutated = mutated_page("feng-county-chained-woman")
    node = batch11_final3_target_node(
        mutated, "feng-county-chained-woman", "ja", "fact",
        "feng-county-chained-woman-timeline-3",
    )
    text = normalized_visible(node).replace("その後の発表で", "後続の通報で")
    batch11_final1_restore_text(node, "fact", text)
    caught.append(bool(audit_batch11_final3_semantics(mutated)))
    for language, bad in (
        ("zh", "2022-02-07： 徐州市調查組承認存在拐賣情節並對地方官員處理提出問題。"),
        ("ja", "2022-02-07： 徐州市の調査チームは人身売買を認め、地元当局による事件の対応に疑問を呈したと発表した。"),
    ):
        mutated = mutated_page("feng-county-chained-woman")
        node = batch11_final3_target_node(
            mutated, "feng-county-chained-woman", language, "fact",
            "feng-county-chained-woman-timeline-3",
        )
        batch11_final1_restore_text(node, "fact", bad)
        caught.append(bool(audit_batch11_final3_semantics(mutated)))
    record("07 Japanese calque / Chinese-Japanese wrong questioning actor",
           all(caught), semantic_baseline)

    # 8. Each French target receives its own specified mechanical expression.
    caught = []
    for fact_id, bad in (
        ("press-freedom-2026-timeline-2", "des chefs larges dirigés contre l’État"),
        ("press-freedom-2026-timeline-5", "les chefs contre l’État"),
        ("press-freedom-2026-evidence-1", "des chefs très larges dirigés contre l’État"),
        ("press-freedom-2026-evidence-2", "des chefs larges contre l’État"),
    ):
        mutated = mutated_page("press-freedom-2026")
        node = batch11_final3_target_node(
            mutated, "press-freedom-2026", "fr", "fact", fact_id,
        )
        node.append(" " + bad)
        caught.append(bool(audit_batch11_final3_semantics(mutated)))
    record("08 four French mechanical charge formulations", all(caught), semantic_baseline)

    # 9. Protect every relevant 50/7/34 count and both charge examples.
    caught = []
    metric_cases = {
        "press-freedom-2026-timeline-2": ("50", "7", "34", "subversion"),
        "press-freedom-2026-timeline-5": ("50", "7"),
        "press-freedom-2026-evidence-1": ("50", "7", "34", "subversion"),
        "press-freedom-2026-evidence-2": ("50", "7", "34"),
    }
    for fact_id, tokens in metric_cases.items():
        for token in tokens:
            mutated = mutated_page("press-freedom-2026")
            node = batch11_final3_target_node(
                mutated, "press-freedom-2026", "fr", "fact", fact_id,
            )
            text = normalized_visible(node)
            if token == "subversion":
                text = text.replace(
                    "la subversion ou l’incitation à la subversion", "une infraction vague",
                )
            else:
                text = re.sub(rf"\b{token}\b", "", text, count=1)
            batch11_final1_restore_text(node, "fact", text)
            caught.append(bool(audit_batch11_final3_semantics(mutated)))
    record("09 French 50/7/34/subversion anchors", all(caught), semantic_baseline)

    # 10. Mutate real source DOM attributes/ordering/refs and both ledger layers.
    caught = []
    for field in ("id", "type", "date", "url", "order", "ref"):
        mutated = mutated_page("press-freedom-2026")
        body = mutated["press-freedom-2026"].select_one('[data-language-body="fr"]')
        sources = body.select("ul.source-list > li[data-source-id]")
        source = next(item for item in sources if item.get("data-source-id") == "pf-s4")
        if field == "id":
            source["data-source-id"] = "pf-s4-tampered"
        elif field == "type":
            source["data-source-type"] = "independent-media"
        elif field == "date":
            source["data-source-date"] = "2099-01-01"
        elif field == "url":
            source.find("a")["href"] += "?tampered=1"
        elif field == "order":
            source.extract(); sources[0].insert_before(source)
        else:
            node = body.select_one('[data-fact-id="press-freedom-2026-timeline-2"]')
            node["data-source-ref"] = "pf-s1"
        caught.append(bool(audit_batch11_final3_sources(mutated)))
    if reread_rows is None:
        reread_rows, _ = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS, "final3 self-test reread",
        )
    if contract_rows is None:
        contract_rows, _ = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS, "final3 self-test contract",
        )
    if source_rows is None:
        source_rows, _ = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS, "final3 self-test source",
        )
    ledger_baseline, _ = audit_batch11_final3_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    altered = deepcopy(reread_rows)
    altered[0]["revised_text"] += " tampered"
    altered_issues, _ = audit_batch11_final3_ledgers(
        pages, reread_rows=altered, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    caught.append(bool(altered_issues))
    shortened = reread_rows[:-1]
    shortened_issues, _ = audit_batch11_final3_ledgers(
        pages, reread_rows=shortened, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    caught.append(bool(shortened_issues))
    record("10 source metadata/ref and ledger integrity", all(caught),
           (*source_baseline, *ledger_baseline))

    # 11. Mutate each expressly frozen file through the real byte manifest.
    caught = []
    for relative in BATCH11_FINAL3_FROZEN_SHA256:
        caught.append(bool(audit_batch11_final3_frozen({
            relative: (ROOT / relative).read_bytes() + b"\nfinal3 mutation",
        })))
    record("11 frozen HK12/Xinjiang/Causeway/script/source-date files", all(caught))

    # 12. Delete each mandatory final3 entry point from this audit's source.
    source = Path(__file__).read_text(encoding="utf-8")
    caught = []
    for needle in (
        "    issues.extend(audit_batch11_final3(\n",
        "        batch11_final3_self_test = batch11_final3_negative_self_test(\n",
    ):
        caught.append(bool(audit_batch11_final3_wiring(
            source.replace(needle, "        # removed final3 entry", 1)
        )))
    record("12 final3 audit/self-test entry deletion", all(caught))
    if len(names) != 12 or len(set(names)) != 12:
        misses.append(f"batch11-final3 named suite cardinality is {len(names)}, expected 12")
    return len(names) - len(misses), len(names), misses


