def batch11_final4_target_node(pages, slug, language, kind, target_id):
    """Locate one of the two final4 public targets."""
    soup = pages.get(slug)
    if soup is None:
        return None
    if kind == "article-title":
        return soup.select_one(f".article-title .lang-{language}")
    if kind == "article-dek":
        return soup.select_one(f".article-dek .lang-{language}")
    body = soup.select_one(f'[data-language-body="{language}"]')
    if kind in {"source-title", "source-category"}:
        source_id = target_id.split(":", 1)[-1]
        source = body.select_one(f'li[data-source-id="{source_id}"]') if body else None
        if source is None:
            return None
        return source.find("a" if kind == "source-title" else "b")
    return body.select_one(f'[data-fact-id="{target_id}"]') if body else None


def audit_batch11_final4_semantics(pages):
    """Validate the two final repairs without reading ledger prose."""
    issues = []
    for slug in BATCH11_FINAL4_SLUGS:
        if pages.get(slug) is None:
            issues.append(f"batch11-final4 page missing: {slug}")
    if issues:
        return issues

    feng_node = batch11_final4_target_node(
        pages, "feng-county-chained-woman", "en", "fact",
        "feng-county-chained-woman-unresolved-questions",
    )
    feng_text = normalized_visible(feng_node)
    if feng_node is None:
        issues.append("batch11-final4 Feng English unresolved-questions fact is missing")
    else:
        required = (
            BATCH11_FINAL4_EN_NEW,
            "the investigation, attribution of responsibility, and case outcomes",
            "each participant in the trafficking, transfer, and purchase network",
            "the explanation of the differences in each notification",
            "the independence of medical and mental health assessments",
            "records of police contact, questioning, summonses, and post removals",
            "citizen investigators and supporters",
            "the compensation, protection and judicial remedies available to victims",
        )
        missing = batch11_final2_phrase_missing(feng_text, required)
        if missing:
            issues.append(
                "batch11-final4 Feng/en evidentiary/accountability/remedy chain "
                f"is incomplete: {missing}"
            )
        if BATCH11_FINAL4_EN_OLD.casefold() in feng_text.casefold():
            issues.append("batch11-final4 Feng/en malformed evidence coordination returned")
        if "civilian investigators" in feng_text.casefold():
            issues.append("batch11-final4 Feng/en citizen investigators became civilian investigators")
        refs = " ".join(feng_node.get("data-source-ref", "").split())
        if refs != "s1 s2 s3 s4 s5":
            issues.append("batch11-final4 Feng/en source refs differ from exact s1 s2 s3 s4 s5")

    report_node = batch11_final4_target_node(
        pages, "2024-report", "ja", "fact", "2024-report-evidence-2",
    )
    report_text = normalized_visible(report_node)
    if report_node is None:
        issues.append("batch11-final4 2024-report Japanese evidence-2 fact is missing")
    else:
        required = (
            "ヒューマン・ライツ・ウォッチ",
            "チベット農村部の移住",
            "「大衆を教育して考えを変えさせる」政策",
            "国境なき記者団",
            "中国の報道自由度ランキング",
            "政治的圧力",
            "CECC年次報告",
            "弁護士資格への処分",
            "公安による圧力",
            "コンテンツ検閲",
            BATCH11_FINAL4_JA_NEW,
            "執行決定",
            "投稿削除・表示抑制の記録",
            "政策影響評価",
            "個別救済の結果",
            "なお一部しか公開されていない",
        )
        missing = batch11_final2_phrase_missing(report_text, required)
        if missing:
            issues.append(
                "batch11-final4 2024-report/ja actor/source/disclosure chain "
                f"is incomplete: {missing}"
            )
        for forbidden in (BATCH11_FINAL4_JA_OLD, "市民による圧力"):
            if forbidden in report_text:
                issues.append(
                    "batch11-final4 2024-report/ja citizens were recast as "
                    f"agents of pressure: {forbidden}"
                )
        refs = " ".join(report_node.get("data-source-ref", "").split())
        if refs != "s1 s2 s4":
            issues.append("batch11-final4 2024-report/ja source refs differ from exact s1 s2 s4")
    return issues


def batch11_final4_source_signature(pages):
    """Serialize every source record and leaf-fact ref on the two pages."""
    metadata = []
    refs = []
    for slug in BATCH11_FINAL4_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                continue
            for order, source in enumerate(
                body.select("ul.source-list > li[data-source-id]")
            ):
                anchor = source.find("a")
                metadata.append(json.dumps([
                    slug, language, order, source.get("data-source-id", ""),
                    source.get("data-source-type", ""),
                    source.get("data-source-date", ""),
                    anchor.get("href", "") if anchor else "",
                ], ensure_ascii=False, separators=(",", ":")) + "\n")
            for node in body.select("[data-fact-id]"):
                fact_id = node.get("data-fact-id", "")
                if (
                    not fact_id or fact_id.endswith("-sources")
                    or node.select_one("[data-fact-id]") is not None
                ):
                    continue
                refs.append(json.dumps([
                    slug, language, fact_id,
                    " ".join(node.get("data-source-ref", "").split()),
                ], ensure_ascii=False, separators=(",", ":")) + "\n")
    return metadata, refs


def audit_batch11_final4_sources(pages):
    metadata, refs = batch11_final4_source_signature(pages)
    issues = []
    for rows, count, digest, label in (
        (
            metadata, BATCH11_FINAL4_SOURCE_METADATA_ROWS,
            BATCH11_FINAL4_SOURCE_METADATA_SHA256,
            "source ID/type/date/URL/order metadata",
        ),
        (
            refs, BATCH11_FINAL4_SOURCE_REF_ROWS,
            BATCH11_FINAL4_SOURCE_REF_SHA256, "data-source-ref map",
        ),
    ):
        if len(rows) != count:
            issues.append(f"batch11-final4 {label} has {len(rows)} rows, expected {count}")
        actual = hashlib.sha256("".join(rows).encode("utf-8")).hexdigest()
        if actual != digest:
            issues.append(f"batch11-final4 changed frozen {label}")
    return issues


def batch11_final4_inventory(pages):
    """Enumerate all public leaves on both pages to bound the two edits."""
    targets = {}
    issues = []

    def add(key, text, refs):
        if key in targets:
            issues.append(f"batch11-final4 duplicate target: {'/'.join(key)}")
        targets[key] = {"text": batch11_norm(text), "source_refs": batch11_norm(refs)}

    for slug in BATCH11_FINAL4_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"batch11-final4 inventory page missing: {slug}")
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"batch11-final4 language body missing: {slug}/{language}")
                continue
            sources = body.select("ul.source-list > li[data-source-id]")
            page_refs = "page-sources:" + " ".join(
                source.get("data-source-id", "") for source in sources
            )
            for kind, target_id, selector in (
                ("article-title", "article-title", f".article-title .lang-{language}"),
                ("article-dek", "article-dek", f".article-dek .lang-{language}"),
            ):
                node = soup.select_one(selector)
                if node is None:
                    issues.append(f"batch11-final4 target missing: {slug}/{language}/{target_id}")
                else:
                    add((slug, language, kind, target_id), normalized_visible(node), page_refs)
            for node in body.select("[data-fact-id]"):
                fact_id = node.get("data-fact-id", "")
                if (
                    not fact_id or fact_id.endswith("-sources")
                    or node.select_one("[data-fact-id]") is not None
                ):
                    continue
                add(
                    (slug, language, "fact", fact_id), normalized_visible(node),
                    node.get("data-source-ref", ""),
                )
            for source in sources:
                source_id = source.get("data-source-id", "")
                anchor = source.find("a")
                label = source.find("b")
                if not source_id or anchor is None or label is None:
                    issues.append(f"batch11-final4 malformed source: {slug}/{language}")
                    continue
                add(
                    (slug, language, "source-title", f"source-title:{source_id}"),
                    normalized_visible(anchor), source_id,
                )
                add(
                    (slug, language, "source-category", f"source-category:{source_id}"),
                    normalized_visible(label), source_id,
                )
    return targets, issues


def batch11_final4_historical_state(
    live_pages=None, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Authenticate and reconstruct the exact completed-final3 predecessor."""
    disk_reread, reread_issues = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch11-final4 reread ledger",
    )
    disk_contract, contract_issues = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch11-final4 contract ledger",
    )
    disk_source, source_issues = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch11-final4 source ledger",
    )
    if reread_rows is None:
        reread_rows = disk_reread
    if contract_rows is None:
        contract_rows = disk_contract
    if source_rows is None:
        source_rows = disk_source
    issues = [*reread_issues, *contract_issues, *source_issues]
    for path, count, digest, label in (
        (
            BATCH9_REREAD_PATH, BATCH11_FINAL4_PRE_REREAD_ROWS,
            BATCH11_FINAL4_PRE_REREAD_SHA256, "batch11-final4 full final3 reread",
        ),
        (
            BATCH9_CONTRACT_PATH, BATCH11_FINAL4_PRE_CONTRACT_ROWS,
            BATCH11_FINAL4_PRE_CONTRACT_SHA256, "batch11-final4 full final3 contract",
        ),
        (
            BATCH9_SOURCE_LEDGER_PATH, BATCH11_FINAL4_PRE_SOURCE_ROWS,
            BATCH11_FINAL4_PRE_SOURCE_SHA256, "batch11-final4 full final3 source",
        ),
    ):
        issues.extend(batch9_final2_exact_prefix(path, count, digest, label))
    source_date = ROOT / "tools/data/source-date-ledger.tsv"
    if not source_date.exists():
        issues.append("batch11-final4 frozen source-date ledger is missing")
    else:
        payload = batch14_source_date_prefix_bytes()
        if hashlib.sha256(payload).hexdigest() != BATCH11_FINAL4_SOURCE_DATE_SHA256:
            issues.append("batch11-final4 source-date ledger bytes changed")
        try:
            rows = list(csv.DictReader(
                io.StringIO(payload.decode("utf-8")), delimiter="\t",
            ))
        except UnicodeDecodeError:
            rows = []
            issues.append("batch11-final4 source-date ledger is not UTF-8")
        if len(rows) != BATCH11_FINAL4_SOURCE_DATE_ROWS:
            issues.append(
                f"batch11-final4 source-date ledger has {len(rows)} rows, expected 294"
            )

    if live_pages is None:
        live_pages = {
            slug: BeautifulSoup(
                (ROOT / "posts" / f"{slug}.html").read_text(encoding="utf-8"),
                "html.parser",
            )
            for slug in BATCH11_FINAL4_SLUGS
        }
    predecessor = dict(live_pages)
    for slug in BATCH11_FINAL4_SLUGS:
        if slug in live_pages:
            predecessor[slug] = deepcopy(live_pages[slug])
    # Restore only final4.  A later successor may append another genuine
    # revision to the same page, but it is not part of the final4 boundary.
    for row in reread_rows[
        BATCH11_FINAL4_PRE_REREAD_ROWS:BATCH11_FINAL4_REREAD_ROWS
    ]:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        if key[0] not in BATCH11_FINAL4_SLUG_SET:
            continue
        node = batch11_final4_target_node(predecessor, *key)
        if node is None:
            issues.append(f"batch11-final4 cannot restore predecessor target: {'/'.join(key)}")
            continue
        if not batch11_final1_restore_text(node, key[2], row.get("original_text", "")):
            issues.append(f"batch11-final4 cannot restore labelled target: {'/'.join(key)}")
    for slug, expected in BATCH11_FINAL4_PRE_PAGE_SHA256.items():
        soup = predecessor.get(slug)
        if soup is None:
            continue
        actual = hashlib.sha256(batch11_final1_page_payload(soup)).hexdigest()
        if actual != expected:
            issues.append(f"{slug}: completed-final3 canonical preimage did not reconstruct")
    return (
        predecessor,
        disk_reread[:BATCH11_FINAL4_PRE_REREAD_ROWS],
        disk_contract[:BATCH11_FINAL4_PRE_CONTRACT_ROWS],
        disk_source[:BATCH11_FINAL4_PRE_SOURCE_ROWS],
        issues,
    )


def batch11_final4_fact_map(pages):
    return {
        key: value for key, value in batch11_final2_fact_map(pages).items()
        if key[0] in BATCH11_FINAL4_SLUG_SET
    }


def audit_batch11_final4_contracts(rows, reread_by_key):
    """Require independent five-duty contracts for both repaired facts."""
    issues = []
    signatures = []
    for row in rows:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        label = "/".join(key)
        required = tuple(
            part.strip() for part in row.get("required_all", "").split("||")
            if part.strip()
        )
        forbidden = tuple(
            part.strip() for part in row.get("forbidden_any", "").split("||")
            if part.strip()
        )
        labels = [part.split(":", 1)[0] for part in required if ":" in part]
        if len(required) != 5 or set(labels) != {
            "actor", "action", "consequence", "source", "remedy",
        }:
            issues.append(f"batch11-final4 contract lacks five independent duties: {label}")
        if any(not part.split(":", 1)[-1].strip() for part in required):
            issues.append(f"batch11-final4 contract has a blank duty: {label}")
        if len(forbidden) != 2 or len(set(forbidden)) != 2 or any(
            not part.startswith("old-error:") or not part.split(":", 1)[-1].strip()
            for part in forbidden
        ):
            issues.append(f"batch11-final4 contract lacks two concrete old errors: {label}")
        summary = row.get("fact_summary", "").casefold()
        if not all(marker in summary for marker in (
            "subject:", "action:", "legal term:", "consequence:", "source:", "remedy:",
        )):
            issues.append(f"batch11-final4 contract summary lacks six factual roles: {label}")
        revised = batch11_norm(reread_by_key.get(key, {}).get("revised_text", ""))
        revised_stream = final1_contiguous_stream(revised)
        for invariant in required:
            code_stream = final1_contiguous_stream(invariant.split(":", 1)[-1])
            if len(code_stream) >= 80 and code_stream in revised_stream:
                issues.append(f"batch11-final4 contract copied a long DOM answer: {label}")
                break
        if revised and final1_longest_common_fragment(
            row.get("fact_summary", ""), revised,
        ) >= min(180, max(100, len(revised_stream) // 2)):
            issues.append(f"batch11-final4 contract summary is a DOM prose shell: {label}")
        signatures.append((row.get("required_all", ""), row.get("fact_summary", "")))
    if len(signatures) != len(set(signatures)):
        issues.append("batch11-final4 contracts reuse a target specification")
    return issues


def audit_batch11_final4_ledgers(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Derive exact 2/2/2 final4 coverage from authenticated final3 state."""
    issues = []
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11-final4 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11-final4 contract ledger",
        )
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11-final4 source ledger",
        )
        issues.extend(load_issues)
    history = batch11_final4_historical_state(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    pre_pages, prefix_reread, prefix_contract, prefix_source = history[:4]
    issues.extend(history[-1])
    pre_inventory, pre_inventory_issues = batch11_final4_inventory(pre_pages)
    live_inventory, live_inventory_issues = batch11_final4_inventory(pages)
    issues.extend(pre_inventory_issues)
    issues.extend(live_inventory_issues)
    if set(pre_inventory) != set(live_inventory):
        issues.append("batch11-final4 added or removed a public semantic target")
    actual_changes = {
        key for key in set(pre_inventory) & set(live_inventory)
        if pre_inventory[key] != live_inventory[key]
    }
    if actual_changes != BATCH11_FINAL4_TARGETS:
        issues.append(
            "batch11-final4 visible changes differ from the exact two-target scope: "
            f"missing={len(BATCH11_FINAL4_TARGETS - actual_changes)} "
            f"extra={len(actual_changes - BATCH11_FINAL4_TARGETS)}"
        )
    for key in set(pre_inventory) & set(live_inventory):
        if pre_inventory[key]["source_refs"] != live_inventory[key]["source_refs"]:
            issues.append(f"batch11-final4 changed frozen refs: {'/'.join(key)}")
    if reread_rows[:BATCH11_FINAL4_PRE_REREAD_ROWS] != prefix_reread:
        issues.append("batch11-final4 in-memory reread predecessor differs from authenticated bytes")
    if contract_rows[:BATCH11_FINAL4_PRE_CONTRACT_ROWS] != prefix_contract:
        issues.append("batch11-final4 in-memory contract predecessor differs from authenticated bytes")
    if source_rows[:BATCH11_FINAL4_PRE_SOURCE_ROWS] != prefix_source:
        issues.append("batch11-final4 in-memory source predecessor differs from authenticated bytes")
    # Bound this historical audit to its own two-row append.  Successor rows
    # are authenticated by their own gate instead of being misclassified as
    # final4 scope expansion.
    reread_suffix = reread_rows[
        BATCH11_FINAL4_PRE_REREAD_ROWS:BATCH11_FINAL4_REREAD_ROWS
    ]
    contract_suffix = contract_rows[
        BATCH11_FINAL4_PRE_CONTRACT_ROWS:BATCH11_FINAL4_CONTRACT_ROWS
    ]
    source_suffix = source_rows[
        BATCH11_FINAL4_PRE_SOURCE_ROWS:BATCH11_FINAL4_SOURCE_ROWS
    ]

    def visible_key(row):
        return (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )

    reread_keys = [visible_key(row) for row in reread_suffix]
    contract_keys = [visible_key(row) for row in contract_suffix]
    if len(reread_keys) != len(set(reread_keys)):
        issues.append("batch11-final4 reread suffix duplicates a target")
    if len(contract_keys) != len(set(contract_keys)):
        issues.append("batch11-final4 contract suffix duplicates a target")
    if set(reread_keys) != BATCH11_FINAL4_TARGETS or len(reread_keys) != 2:
        issues.append("batch11-final4 reread suffix is not the exact two-target set")
    if set(contract_keys) != BATCH11_FINAL4_TARGETS or len(contract_keys) != 2:
        issues.append("batch11-final4 contract suffix is not the exact two-target set")
    reread_by_key = {visible_key(row): row for row in reread_suffix}
    contract_by_key = {visible_key(row): row for row in contract_suffix}
    predecessor_tips = {}
    for row in prefix_reread:
        predecessor_tips[visible_key(row)] = row
    reread_ids = set()
    for key, row in reread_by_key.items():
        label = "/".join(key)
        contract_id = row.get("contract_id", "")
        expected_prefix = f"{BATCH11_FINAL4_PREFIX}{':'.join(key)}:"
        if not contract_id.startswith(expected_prefix):
            issues.append(f"batch11-final4 reread ID is not target-bound: {label}")
        if not contract_id or contract_id in reread_ids:
            issues.append(f"batch11-final4 reread ID is blank or duplicate: {label}")
        reread_ids.add(contract_id)
        pre = pre_inventory.get(key, {"text": "", "source_refs": ""})
        live = live_inventory.get(key, {"text": "", "source_refs": ""})
        if row.get("result", "") != "PASS_AFTER_REVISION" or (
            "PASS_NO_CHANGE" in row.get("result", "")
        ):
            issues.append(f"batch11-final4 reread is not a genuine revision: {label}")
        issue_found = row.get("issue_found", "").strip()
        if not issue_found:
            issues.append(f"batch11-final4 reread lacks the concrete old defect: {label}")
        elif final1_longest_common_fragment(
            issue_found, row.get("original_text", ""),
        ) < 6:
            issues.append(f"batch11-final4 issue does not quote its real old wording: {label}")
        review_basis = row.get("review_basis", "")
        if "reread:batch11-final4" not in review_basis or len(review_basis.strip()) < 48:
            issues.append(f"batch11-final4 review basis is not substantive/target-bound: {label}")
        if batch11_norm(row.get("original_text", "")) != pre["text"]:
            issues.append(f"batch11-final4 original differs from completed final3: {label}")
        if batch11_norm(row.get("revised_text", "")) != live["text"]:
            issues.append(f"batch11-final4 revision differs from live DOM: {label}")
        if batch11_norm(row.get("source_refs", "")) != live["source_refs"]:
            issues.append(f"batch11-final4 reread refs differ from live DOM: {label}")
        if pre["text"] == live["text"] or batch11_norm(
            row.get("original_text", "")
        ) == batch11_norm(row.get("revised_text", "")):
            issues.append(f"batch11-final4 reread records unchanged text: {label}")
        predecessor = predecessor_tips.get(key)
        if predecessor is not None and batch11_norm(
            predecessor.get("revised_text", "")
        ) != pre["text"]:
            issues.append(f"batch11-final4 predecessor chain is broken: {label}")

    contract_ids = [row.get("contract_id", "") for row in contract_suffix]
    if set(contract_ids) != reread_ids or len(contract_ids) != len(set(contract_ids)):
        issues.append("batch11-final4 contracts and rereads are not a one-to-one ID pair")
    for key, row in contract_by_key.items():
        expected_prefix = f"{BATCH11_FINAL4_PREFIX}{':'.join(key)}:"
        if not row.get("contract_id", "").startswith(expected_prefix):
            issues.append(f"batch11-final4 contract identity is not target-bound: {'/'.join(key)}")
    issues.extend(audit_batch11_final4_contracts(contract_suffix, reread_by_key))

    pre_facts = batch11_final4_fact_map(pre_pages)
    live_facts = batch11_final4_fact_map(pages)
    projection = (
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence",
    )
    changed_facts = {
        key for key in set(pre_facts) & set(live_facts)
        if any(
            batch11_norm(pre_facts[key][field]) != batch11_norm(live_facts[key][field])
            for field in projection
        )
    }
    if changed_facts != BATCH11_FINAL4_FACT_TARGETS:
        issues.append("batch11-final4 fact/source projection is not the exact two-fact set")
    source_keys = [(
        row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
    ) for row in source_suffix]
    if len(source_keys) != len(set(source_keys)):
        issues.append("batch11-final4 source suffix duplicates a fact")
    if set(source_keys) != BATCH11_FINAL4_FACT_TARGETS or len(source_keys) != 2:
        issues.append("batch11-final4 source suffix is not the exact two-fact set")
    source_tips = {}
    for row in prefix_source:
        source_tips[(
            row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
        )] = row
    mutable = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "baseline_issue",
        "resolution_action", "support_urls", "locatable_support", "source_roles",
        "final_issue", "audit_accessed_at", "audit_final_url", "audit_title",
        "audit_source_id", "audit_locator", "audit_support_summary",
        "audit_relationship", "audit_claim_compared", "audit_decision",
        "source_date_audit", "reread_h1_current", "reread_dek_current",
        "reread_timeline_current", "reread_rights_current",
        "reread_protection_current", "reread_source_titles_current",
        "reread_card_current", "reread_issue_found", "reread_revision_text",
        "reread_result", "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor", "visible_timeline_order", "visible_source_roles",
    }
    exact_live_fields = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "support_urls",
        "source_date_audit", "reread_timeline_current",
        "reread_rights_current", "reread_protection_current",
        "reread_revision_text", "audit_final_url", "audit_source_id",
        "audit_claim_compared", "source_roles", "visible_source_roles",
    }
    for row in source_suffix:
        key = (row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""))
        label = "/".join(key)
        predecessor = source_tips.get(key)
        live = live_facts.get(key)
        pre = pre_facts.get(key)
        if predecessor is None or live is None or pre is None:
            issues.append(f"batch11-final4 source row lacks predecessor/live fact: {label}")
            continue
        for field in BATCH9_FINAL2_SOURCE_COLUMNS:
            if field not in mutable and row.get(field, "") != predecessor.get(field, ""):
                issues.append(f"batch11-final4 source row changed protected {field}: {label}")
                break
        for field in exact_live_fields:
            if batch11_norm(row.get(field, "")) != batch11_norm(live.get(field, "")):
                issues.append(f"batch11-final4 source {field} differs from live DOM: {label}")
        for field in (
            "reread_h1_current", "reread_dek_current",
            "reread_source_titles_current",
        ):
            if batch11_norm(row.get(field, "")) != batch11_norm(pre.get(field, "")):
                issues.append(f"batch11-final4 source final3 context {field} differs: {label}")
        if row.get("reread_card_current", "") != predecessor.get("reread_card_current", ""):
            issues.append(f"batch11-final4 source changed frozen card snapshot: {label}")
        visible = (key[0], key[1], "fact", key[2])
        paired = contract_by_key.get(visible)
        reread = reread_by_key.get(visible)
        if paired is None or row.get("baseline_issue", "") != paired.get("contract_id", ""):
            issues.append(f"batch11-final4 source baseline is not its paired contract: {label}")
        if reread is None or row.get("reread_issue_found", "") != reread.get("issue_found", ""):
            issues.append(f"batch11-final4 source issue is not its paired reread defect: {label}")
        if "reread:batch11-final4" not in row.get("resolution_action", ""):
            issues.append(f"batch11-final4 source resolution marker is absent: {label}")
        if "reread:batch11-final4" not in row.get("final_issue", ""):
            issues.append(f"batch11-final4 source final-review marker is absent: {label}")
        if row.get("audit_decision", "") != "PASS_FINAL4_SOURCE_MAPPING":
            issues.append(f"batch11-final4 source audit decision differs: {label}")
        if row.get("reread_result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11-final4 source reread result differs: {label}")
        if row.get("audit_accessed_at", "") != "2026-07-23":
            issues.append(f"batch11-final4 source audit date differs: {label}")
        for field in (
            "audit_final_url", "audit_title", "audit_source_id", "audit_locator",
            "audit_support_summary", "audit_relationship", "audit_claim_compared",
        ):
            if not row.get(field, "").strip():
                issues.append(f"batch11-final4 source evidence lacks {field}: {label}")
    return issues, {
        "changed_targets": len(actual_changes),
        "changed_facts": len(changed_facts),
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "source_rows": len(source_suffix),
    }


def audit_batch11_final4_frozen(overrides=None):
    """Authenticate every file outside the exact seven-file final4 scope."""
    # Replayed against the authenticated pre-batch13 bytes of the 49 revised
    # dossiers, so every digest below still runs; an explicit override wins.
    overrides = {**batch13_historical_bytes(), **(overrides or {})}
    records = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        if ".git" in relative_path.parts or path.name == ".DS_Store":
            continue
        if relative in BATCH11_FINAL4_ALLOWED_FILES:
            continue
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else path.read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if batch11_final1_is_desktop_extra(relative, payload):
            continue
        records.append((relative, len(payload), hashlib.sha256(payload).hexdigest()))
    canonical = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(records)
    ).encode("utf-8")
    issues = []
    if len(records) != BATCH11_FINAL4_PROTECTED_FILES:
        issues.append(
            f"batch11-final4 protected manifest has {len(records)} files, "
            f"expected {BATCH11_FINAL4_PROTECTED_FILES}"
        )
    if hashlib.sha256(canonical).hexdigest() != BATCH11_FINAL4_PROTECTED_SHA256:
        issues.append("batch11-final4 changed a file outside its exact seven-file scope")
    for relative, digest in BATCH11_FINAL4_FROZEN_SHA256.items():
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else (ROOT / relative).read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if hashlib.sha256(payload).hexdigest() != digest:
            issues.append(f"batch11-final4 changed frozen {relative}")
    return issues


def audit_batch11_final4_wiring(source_text=None):
    source_text = source_text or Path(__file__).read_text(encoding="utf-8")
    live = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    main = re.search(
        r"def main\(\):(?P<body>.*?)(?=\nif __name__ ==)", source_text, re.S,
    )
    issues = []
    live_call = "issues.extend(audit_batch11_final4(pages))"
    self_call = "batch11_final4_negative_self_test(pages)"
    if live is None or live.group("body").count(live_call) != 1:
        issues.append("batch11-final4 authoritative audit_live wiring is absent")
    if main is None or main.group("body").count(self_call) != 1:
        issues.append("batch11-final4 named negative suite is not wired into --self-test")
    return issues


def audit_batch11_final4(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    frozen_overrides=None, source_text=None,
):
    issues = []
    issues.extend(audit_batch11_final4_semantics(pages))
    issues.extend(audit_batch11_final4_sources(pages))
    ledger_issues, _stats = audit_batch11_final4_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    issues.extend(ledger_issues)
    issues.extend(audit_batch11_final4_frozen(frozen_overrides))
    issues.extend(audit_batch11_final4_wiring(source_text))
    return issues


def batch11_final4_negative_self_test(pages):
    """Exercise the brief's real DOM/attribute/byte/source failure classes."""
    names = []
    misses = []
    semantic_baseline = audit_batch11_final4_semantics(pages)
    source_baseline = audit_batch11_final4_sources(pages)
    freeze_baseline = audit_batch11_final4_frozen()
    wiring_baseline = audit_batch11_final4_wiring()

    def record(name, caught, baseline=()):
        names.append(name)
        if baseline or not caught:
            detail = f" (baseline: {baseline[0]})" if baseline else ""
            misses.append(name + detail)

    def mutated_page(slug):
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        return mutated

    def mutate_feng(replace_from, replace_to):
        mutated = mutated_page("feng-county-chained-woman")
        node = batch11_final4_target_node(
            mutated, "feng-county-chained-woman", "en", "fact",
            "feng-county-chained-woman-unresolved-questions",
        )
        text = normalized_visible(node).replace(replace_from, replace_to, 1)
        batch11_final1_restore_text(node, "fact", text)
        return mutated

    # 1. Reinsert the exact old malformed English first clause.
    mutated = mutate_feng(BATCH11_FINAL4_EN_NEW, BATCH11_FINAL4_EN_OLD)
    record("01 old full English reinsertion",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)

    # 2-4. Delete each component of the identity-evidence relation separately.
    mutated = mutate_feng("evidentiary chain", "")
    record("02 evidentiary-chain deletion",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)
    mutated = mutate_feng("DNA testing", "")
    record("03 DNA-testing deletion",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)
    mutated = mutate_feng("household-registration records", "")
    record("04 household-registration-record deletion",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)

    # 5. Restore the false military/civilian contrast.
    mutated = mutate_feng("citizen investigators", "civilian investigators")
    record("05 citizen-to-civilian investigator mutation",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)

    # 6. Reinsert the exact Japanese actor/patient reversal.
    mutated = mutated_page("2024-report")
    node = batch11_final4_target_node(
        mutated, "2024-report", "ja", "fact", "2024-report-evidence-2",
    )
    text = normalized_visible(node).replace(
        BATCH11_FINAL4_JA_NEW, BATCH11_FINAL4_JA_OLD, 1,
    )
    batch11_final1_restore_text(node, "fact", text)
    record("06 old full Japanese reinsertion",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)

    # 7. Delete the new affected-activity anchor in the actual DOM.
    mutated = mutated_page("2024-report")
    node = batch11_final4_target_node(
        mutated, "2024-report", "ja", "fact", "2024-report-evidence-2",
    )
    text = normalized_visible(node).replace(BATCH11_FINAL4_JA_NEW, "", 1)
    batch11_final1_restore_text(node, "fact", text)
    record("07 new Japanese anchor deletion",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)

    # 8. Make citizens the source of pressure in place of public security.
    mutated = mutated_page("2024-report")
    node = batch11_final4_target_node(
        mutated, "2024-report", "ja", "fact", "2024-report-evidence-2",
    )
    text = normalized_visible(node).replace("公安による圧力", "市民による圧力", 1)
    batch11_final1_restore_text(node, "fact", text)
    record("08 state/public-security pressure actor reversal",
           bool(audit_batch11_final4_semantics(mutated)), semantic_baseline)

    # 9. Change each target's real data-source-ref attribute.
    caught = []
    for slug, language, fact_id in BATCH11_FINAL4_FACT_TARGETS:
        mutated = mutated_page(slug)
        node = batch11_final4_target_node(
            mutated, slug, language, "fact", fact_id,
        )
        node["data-source-ref"] = "s1"
        caught.append(bool(
            audit_batch11_final4_semantics(mutated)
            or audit_batch11_final4_sources(mutated)
        ))
    record("09 either target source-ref mutation", all(caught),
           (*semantic_baseline, *source_baseline))

    # 10. Mutate all six explicit frozen byte targets via production freeze.
    caught = []
    for relative in BATCH11_FINAL4_FROZEN_SHA256:
        caught.append(bool(audit_batch11_final4_frozen({
            relative: (ROOT / relative).read_bytes() + b"\nfinal4 mutation",
        })))
    record("10 frozen file byte mutation", all(caught), freeze_baseline)

    # 11. Remove each mandatory final4 production entry from real source text.
    source = Path(__file__).read_text(encoding="utf-8")
    caught = []
    for needle in (
        "    issues.extend(audit_batch11_final4(pages))\n",
        "        batch11_final4_self_test = batch11_final4_negative_self_test(pages)\n",
    ):
        changed = source.replace(needle, "        # removed final4 entry\n", 1)
        caught.append(changed != source and bool(audit_batch11_final4_wiring(changed)))
    record("11 final4 audit/self-test production wiring deletion",
           all(caught), wiring_baseline)

    # 12. Mutate authenticated prefix rows and remove each real append tip.
    reread_rows, _ = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS, "final4 self-test reread",
    )
    contract_rows, _ = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS, "final4 self-test contract",
    )
    source_rows, _ = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS, "final4 self-test source",
    )
    # Exercise the completed final4 chain itself, not any successor append.
    reread_rows = reread_rows[:BATCH11_FINAL4_REREAD_ROWS]
    contract_rows = contract_rows[:BATCH11_FINAL4_CONTRACT_ROWS]
    source_rows = source_rows[:BATCH11_FINAL4_SOURCE_ROWS]
    ledger_baseline, _ = audit_batch11_final4_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    caught = []
    for kind in ("reread", "contract", "source"):
        changed_reread = deepcopy(reread_rows)
        changed_contract = deepcopy(contract_rows)
        changed_source = deepcopy(source_rows)
        selected = {
            "reread": changed_reread,
            "contract": changed_contract,
            "source": changed_source,
        }[kind]
        selected[0][next(iter(selected[0]))] += " tampered"
        found, _ = audit_batch11_final4_ledgers(
            pages, reread_rows=changed_reread, contract_rows=changed_contract,
            source_rows=changed_source,
        )
        caught.append(bool(found))
        shortened = selected[:-1]
        found, _ = audit_batch11_final4_ledgers(
            pages,
            reread_rows=shortened if kind == "reread" else reread_rows,
            contract_rows=shortened if kind == "contract" else contract_rows,
            source_rows=shortened if kind == "source" else source_rows,
        )
        caught.append(bool(found))
    record("12 final3-prefix and final4-suffix ledger mutation",
           all(caught), ledger_baseline)
    if len(names) != 12 or len(set(names)) != 12:
        misses.append(f"batch11-final4 named suite cardinality is {len(names)}, expected 12")
    return len(names) - len(misses), len(names), misses


