def batch11_final5_target_node(pages):
    soup = pages.get(BATCH11_FINAL5_SLUG)
    if soup is None:
        return None
    body = soup.select_one('[data-language-body="en"]')
    return body.select_one(
        '[data-fact-id="feng-county-chained-woman-rights-analysis"]'
    ) if body else None


def audit_batch11_final5_semantics(pages):
    """Enforce the supplied final prose and independently named meanings."""
    issues = []
    soup = pages.get(BATCH11_FINAL5_SLUG)
    if soup is None:
        return ["batch11-final5 Feng County page is missing"]
    node = batch11_final5_target_node(pages)
    if node is None:
        return ["batch11-final5 English rights-analysis target is missing"]
    text = normalized_visible(node)
    if text != BATCH11_FINAL5_NEW:
        issues.append("batch11-final5 English rights analysis differs from the exact approved text")
    missing = batch11_final2_phrase_missing(text, BATCH11_FINAL5_REQUIRED_TEXT)
    if missing:
        issues.append(
            "batch11-final5 English rights/evidence/accountability/remedy chain "
            f"is incomplete: {missing}"
        )
    for forbidden in BATCH11_FINAL5_FORBIDDEN:
        if forbidden.casefold() in text.casefold():
            issues.append(f"batch11-final5 rejected English construction returned: {forbidden[:80]}")
    refs = " ".join(node.get("data-source-ref", "").split())
    if refs != "s1 s2 s3 s4 s5":
        issues.append("batch11-final5 English rights-analysis refs differ from s1 s2 s3 s4 s5")
    critical = node.select_one("[data-critical-case]")
    if critical is None:
        issues.append("batch11-final5 English rights analysis lacks data-critical-case")
    else:
        critical_text = normalized_visible(critical)
        first_sentence = batch11_final1_first_sentence(critical_text)
        attribute = critical.get("data-critical-case", "")
        if first_sentence != BATCH11_FINAL5_NEW_FIRST_SENTENCE:
            issues.append("batch11-final5 visible critical first sentence differs")
        if attribute != first_sentence:
            issues.append("batch11-final5 data-critical-case does not exactly equal its visible first sentence")
        if critical_text != text:
            issues.append("batch11-final5 critical span does not contain the complete visible paragraph")
    english_targets = soup.select(
        '[data-language-body="en"] '
        '[data-fact-id="feng-county-chained-woman-rights-analysis"]'
    )
    if len(english_targets) != 1:
        issues.append(
            "batch11-final5 English rights-analysis target is not unique: "
            f"{len(english_targets)}"
        )
    return issues


def batch11_final5_source_signature(pages):
    """Serialize all Feng source metadata, visible dates, and leaf refs."""
    metadata = []
    refs = []
    soup = pages.get(BATCH11_FINAL5_SLUG)
    if soup is None:
        return metadata, refs
    for language in BATCH5_LANGS:
        body = soup.select_one(f'[data-language-body="{language}"]')
        if body is None:
            continue
        for order, source in enumerate(
            body.select("ul.source-list > li[data-source-id]")
        ):
            anchor = source.find("a")
            visible_date = source.find("time")
            metadata.append(json.dumps([
                BATCH11_FINAL5_SLUG,
                language,
                order,
                source.get("data-source-id", ""),
                source.get("data-source-type", ""),
                source.get("data-source-date", ""),
                anchor.get("href", "") if anchor else "",
                normalized_visible(anchor),
                visible_date.get("datetime", "") if visible_date else "",
                normalized_visible(visible_date),
            ], ensure_ascii=False, separators=(",", ":")) + "\n")
        for node in body.select("[data-fact-id]"):
            fact_id = node.get("data-fact-id", "")
            if (
                not fact_id or fact_id.endswith("-sources")
                or node.select_one("[data-fact-id]") is not None
            ):
                continue
            refs.append(json.dumps([
                BATCH11_FINAL5_SLUG,
                language,
                fact_id,
                " ".join(node.get("data-source-ref", "").split()),
            ], ensure_ascii=False, separators=(",", ":")) + "\n")
    return metadata, refs


def audit_batch11_final5_sources(pages):
    issues = []
    metadata, refs = batch11_final5_source_signature(pages)
    for rows, count, digest, label in (
        (
            metadata,
            BATCH11_FINAL5_SOURCE_METADATA_ROWS,
            BATCH11_FINAL5_SOURCE_METADATA_SHA256,
            "source ID/type/date/URL/title/visible-date/order metadata",
        ),
        (
            refs,
            BATCH11_FINAL5_SOURCE_REF_ROWS,
            BATCH11_FINAL5_SOURCE_REF_SHA256,
            "data-source-ref map",
        ),
    ):
        if len(rows) != count:
            issues.append(
                f"batch11-final5 {label} has {len(rows)} rows, expected {count}"
            )
        if hashlib.sha256("".join(rows).encode("utf-8")).hexdigest() != digest:
            issues.append(f"batch11-final5 changed frozen {label}")
    return issues


def batch11_final5_inventory(pages):
    """Enumerate every visible Feng leaf so only one fact may change."""
    targets = {}
    issues = []
    soup = pages.get(BATCH11_FINAL5_SLUG)
    if soup is None:
        return targets, ["batch11-final5 inventory page is missing"]

    def add(key, text, source_refs):
        if key in targets:
            issues.append(f"batch11-final5 duplicate inventory target: {'/'.join(key)}")
        targets[key] = {
            "text": batch11_norm(text),
            "source_refs": batch11_norm(source_refs),
        }

    for language in BATCH5_LANGS:
        body = soup.select_one(f'[data-language-body="{language}"]')
        if body is None:
            issues.append(f"batch11-final5 language body missing: {language}")
            continue
        sources = body.select("ul.source-list > li[data-source-id]")
        page_refs = "page-sources:" + " ".join(
            source.get("data-source-id", "") for source in sources
        )
        for kind, target_id, selector in (
            ("article-title", "article-title", f".article-title .lang-{language}"),
            ("article-dek", "article-dek", f".article-dek .lang-{language}"),
        ):
            node = soup.select_one(selector)
            if node is None:
                issues.append(f"batch11-final5 target missing: {language}/{target_id}")
            else:
                add(
                    (BATCH11_FINAL5_SLUG, language, kind, target_id),
                    normalized_visible(node), page_refs,
                )
        for node in body.select("[data-fact-id]"):
            fact_id = node.get("data-fact-id", "")
            if (
                not fact_id or fact_id.endswith("-sources")
                or node.select_one("[data-fact-id]") is not None
            ):
                continue
            add(
                (BATCH11_FINAL5_SLUG, language, "fact", fact_id),
                normalized_visible(node), node.get("data-source-ref", ""),
            )
        for source in sources:
            source_id = source.get("data-source-id", "")
            anchor = source.find("a")
            label = source.find("b")
            if not source_id or anchor is None or label is None:
                issues.append(f"batch11-final5 malformed source: {language}")
                continue
            add(
                (
                    BATCH11_FINAL5_SLUG, language, "source-title",
                    f"source-title:{source_id}",
                ),
                normalized_visible(anchor), source_id,
            )
            add(
                (
                    BATCH11_FINAL5_SLUG, language, "source-category",
                    f"source-category:{source_id}",
                ),
                normalized_visible(label), source_id,
            )
    return targets, issues


def batch11_final5_historical_state(
    live_pages=None, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Authenticate and reconstruct the exact completed-final4 predecessor."""
    disk_reread, reread_issues = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch11-final5 reread ledger",
    )
    disk_contract, contract_issues = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch11-final5 contract ledger",
    )
    disk_source, source_issues = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch11-final5 source ledger",
    )
    if reread_rows is None:
        reread_rows = disk_reread
    if contract_rows is None:
        contract_rows = disk_contract
    if source_rows is None:
        source_rows = disk_source
    issues = [*reread_issues, *contract_issues, *source_issues]
    for path, count, digest, label in (
        (
            BATCH9_REREAD_PATH,
            BATCH11_FINAL5_PRE_REREAD_ROWS,
            BATCH11_FINAL5_PRE_REREAD_SHA256,
            "batch11-final5 completed-final4 reread prefix",
        ),
        (
            BATCH9_CONTRACT_PATH,
            BATCH11_FINAL5_PRE_CONTRACT_ROWS,
            BATCH11_FINAL5_PRE_CONTRACT_SHA256,
            "batch11-final5 completed-final4 contract prefix",
        ),
        (
            BATCH9_SOURCE_LEDGER_PATH,
            BATCH11_FINAL5_PRE_SOURCE_ROWS,
            BATCH11_FINAL5_PRE_SOURCE_SHA256,
            "batch11-final5 completed-final4 source prefix",
        ),
    ):
        issues.extend(batch9_final2_exact_prefix(path, count, digest, label))
    source_date = ROOT / "tools/data/source-date-ledger.tsv"
    if not source_date.exists():
        issues.append("batch11-final5 frozen source-date ledger is missing")
    else:
        payload = batch14_source_date_prefix_bytes()
        if hashlib.sha256(payload).hexdigest() != BATCH11_FINAL5_SOURCE_DATE_SHA256:
            issues.append("batch11-final5 source-date ledger bytes changed")
        try:
            date_rows = list(csv.DictReader(
                io.StringIO(payload.decode("utf-8")), delimiter="\t",
            ))
        except UnicodeDecodeError:
            date_rows = []
            issues.append("batch11-final5 source-date ledger is not UTF-8")
        if len(date_rows) != BATCH11_FINAL5_SOURCE_DATE_ROWS:
            issues.append(
                "batch11-final5 source-date ledger has "
                f"{len(date_rows)} rows, expected {BATCH11_FINAL5_SOURCE_DATE_ROWS}"
            )
    if live_pages is None:
        live_pages = {
            BATCH11_FINAL5_SLUG: BeautifulSoup(
                (ROOT / "posts" / f"{BATCH11_FINAL5_SLUG}.html").read_text(
                    encoding="utf-8"
                ),
                "html.parser",
            )
        }
    predecessor = dict(live_pages)
    if BATCH11_FINAL5_SLUG in live_pages:
        predecessor[BATCH11_FINAL5_SLUG] = deepcopy(
            live_pages[BATCH11_FINAL5_SLUG]
        )
    append = reread_rows[
        BATCH11_FINAL5_PRE_REREAD_ROWS:BATCH11_FINAL5_REREAD_ROWS
    ]
    for row in append:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        if key != BATCH11_FINAL5_TARGET:
            issues.append(
                f"batch11-final5 cannot replay out-of-scope row: {'/'.join(key)}"
            )
            continue
        node = batch11_final5_target_node(predecessor)
        if not batch11_final1_restore_text(
            node, "fact", row.get("original_text", ""),
        ):
            issues.append("batch11-final5 cannot restore completed-final4 target")
    pre_soup = predecessor.get(BATCH11_FINAL5_SLUG)
    if pre_soup is not None:
        digest = hashlib.sha256(batch11_final1_page_payload(pre_soup)).hexdigest()
        if digest != BATCH11_FINAL5_PRE_PAGE_SHA256:
            issues.append(
                "batch11-final5 completed-final4 Feng page did not reconstruct"
            )
    return (
        predecessor,
        disk_reread[:BATCH11_FINAL5_PRE_REREAD_ROWS],
        disk_contract[:BATCH11_FINAL5_PRE_CONTRACT_ROWS],
        disk_source[:BATCH11_FINAL5_PRE_SOURCE_ROWS],
        issues,
    )


def batch11_final5_fact_map(pages):
    return {
        key: value for key, value in batch11_final2_fact_map(pages).items()
        if key[0] == BATCH11_FINAL5_SLUG
    }


def audit_batch11_final5_contract(row, reread_row):
    """Validate a manual contract without treating it as the prose oracle."""
    issues = []
    required = tuple(
        part.strip() for part in row.get("required_all", "").split("||")
        if part.strip()
    )
    forbidden = tuple(
        part.strip() for part in row.get("forbidden_any", "").split("||")
        if part.strip()
    )
    if len(required) < 15:
        issues.append(
            f"batch11-final5 contract has {len(required)} anchors, expected at least 15"
        )
    required_stream = final1_contiguous_stream(" ".join(required))
    for anchor in BATCH11_FINAL5_CONTRACT_ANCHORS:
        if final1_contiguous_stream(anchor) not in required_stream:
            issues.append(f"batch11-final5 contract lacks independent anchor: {anchor}")
    forbidden_values = tuple(
        part.split(":", 1)[-1] if ":" in part else "" for part in forbidden
    )
    if len(forbidden) < 4 or any(
        not part.startswith("old-error:") for part in forbidden
    ):
        issues.append("batch11-final5 contract lacks four old-error prohibitions")
    for rejected in BATCH11_FINAL5_FORBIDDEN:
        if rejected not in forbidden_values:
            issues.append(
                "batch11-final5 contract lacks rejected wording: "
                f"{rejected[:80]}"
            )
    summary = row.get("fact_summary", "").casefold()
    for role in (
        "subject:", "action:", "legal term:", "consequence:", "source:", "remedy:",
    ):
        if role not in summary:
            issues.append(f"batch11-final5 contract summary lacks role {role}")
    revised = batch11_norm(reread_row.get("revised_text", ""))
    if revised and final1_longest_common_fragment(
        row.get("fact_summary", ""), revised,
    ) >= min(180, max(100, len(final1_contiguous_stream(revised)) // 2)):
        issues.append("batch11-final5 contract summary is copied from the revised DOM")
    return issues


def audit_batch11_final5_ledgers(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Require the exact 1/1/1 append over authenticated final4 bytes."""
    issues = []
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11-final5 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11-final5 contract ledger",
        )
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11-final5 source ledger",
        )
        issues.extend(load_issues)
    history = batch11_final5_historical_state(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    pre_pages, prefix_reread, prefix_contract, prefix_source = history[:4]
    issues.extend(history[-1])
    pre_inventory, pre_inventory_issues = batch11_final5_inventory(pre_pages)
    live_inventory, live_inventory_issues = batch11_final5_inventory(pages)
    issues.extend(pre_inventory_issues)
    issues.extend(live_inventory_issues)
    if set(pre_inventory) != set(live_inventory):
        issues.append("batch11-final5 added or removed a public semantic target")
    actual_changes = {
        key for key in set(pre_inventory) & set(live_inventory)
        if pre_inventory[key] != live_inventory[key]
    }
    if actual_changes != {BATCH11_FINAL5_TARGET}:
        issues.append(
            "batch11-final5 visible changes differ from the exact one-target scope: "
            f"missing={len({BATCH11_FINAL5_TARGET} - actual_changes)} "
            f"extra={len(actual_changes - {BATCH11_FINAL5_TARGET})}"
        )
    for key in set(pre_inventory) & set(live_inventory):
        if pre_inventory[key]["source_refs"] != live_inventory[key]["source_refs"]:
            issues.append(f"batch11-final5 changed frozen refs: {'/'.join(key)}")
    if reread_rows[:BATCH11_FINAL5_PRE_REREAD_ROWS] != prefix_reread:
        issues.append("batch11-final5 in-memory final4 reread prefix differs")
    if contract_rows[:BATCH11_FINAL5_PRE_CONTRACT_ROWS] != prefix_contract:
        issues.append("batch11-final5 in-memory final4 contract prefix differs")
    if source_rows[:BATCH11_FINAL5_PRE_SOURCE_ROWS] != prefix_source:
        issues.append("batch11-final5 in-memory final4 source prefix differs")
    reread_suffix = reread_rows[BATCH11_FINAL5_PRE_REREAD_ROWS:]
    contract_suffix = contract_rows[BATCH11_FINAL5_PRE_CONTRACT_ROWS:]
    source_suffix = source_rows[BATCH11_FINAL5_PRE_SOURCE_ROWS:]
    if len(reread_suffix) != 1:
        issues.append(
            f"batch11-final5 reread append has {len(reread_suffix)} rows, expected 1"
        )
    if len(contract_suffix) != 1:
        issues.append(
            f"batch11-final5 contract append has {len(contract_suffix)} rows, expected 1"
        )
    if len(source_suffix) != 1:
        issues.append(
            f"batch11-final5 source append has {len(source_suffix)} rows, expected 1"
        )

    def visible_key(row):
        return (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )

    reread = reread_suffix[0] if len(reread_suffix) == 1 else {}
    contract = contract_suffix[0] if len(contract_suffix) == 1 else {}
    if visible_key(reread) != BATCH11_FINAL5_TARGET:
        issues.append("batch11-final5 reread append is not the exact target")
    if visible_key(contract) != BATCH11_FINAL5_TARGET:
        issues.append("batch11-final5 contract append is not the exact target")
    contract_id = reread.get("contract_id", "")
    expected_id_prefix = (
        f"{BATCH11_FINAL5_PREFIX}{':'.join(BATCH11_FINAL5_TARGET)}:"
    )
    if not contract_id.startswith(expected_id_prefix):
        issues.append("batch11-final5 reread ID is not target-bound")
    if contract.get("contract_id", "") != contract_id:
        issues.append("batch11-final5 contract and reread are not a one-to-one ID pair")
    pre = pre_inventory.get(
        BATCH11_FINAL5_TARGET, {"text": "", "source_refs": ""}
    )
    live = live_inventory.get(
        BATCH11_FINAL5_TARGET, {"text": "", "source_refs": ""}
    )
    if reread.get("result", "") != "PASS_AFTER_REVISION":
        issues.append("batch11-final5 reread result is not PASS_AFTER_REVISION")
    if "PASS_NO_CHANGE" in reread.get("result", ""):
        issues.append("batch11-final5 reread improperly records PASS_NO_CHANGE")
    if batch11_norm(reread.get("original_text", "")) != pre["text"]:
        issues.append("batch11-final5 reread original is not the true final4 DOM")
    if batch11_norm(reread.get("revised_text", "")) != live["text"]:
        issues.append("batch11-final5 reread revision differs from the live DOM")
    if batch11_norm(reread.get("source_refs", "")) != live["source_refs"]:
        issues.append("batch11-final5 reread refs differ from the live DOM")
    if pre["text"] == live["text"] or batch11_norm(
        reread.get("original_text", "")
    ) == batch11_norm(reread.get("revised_text", "")):
        issues.append("batch11-final5 reread does not record a genuine revision")
    issue_found = reread.get("issue_found", "")
    for rejected in BATCH11_FINAL5_FORBIDDEN[:3]:
        if rejected not in issue_found:
            issues.append(
                f"batch11-final5 issue_found omits the real defect: {rejected}"
            )
    review_basis = reread.get("review_basis", "")
    for anchor in (
        "reread:batch11-final5", "held in chains",
        "prolonged unlawful confinement", "purchasers and transporters",
        "independent effective legal remedies",
    ):
        if anchor.casefold() not in review_basis.casefold():
            issues.append(f"batch11-final5 review basis lacks: {anchor}")
    predecessor_tips = {}
    for row in prefix_reread:
        predecessor_tips[visible_key(row)] = row
    predecessor = predecessor_tips.get(BATCH11_FINAL5_TARGET)
    if predecessor is not None and batch11_norm(
        predecessor.get("revised_text", "")
    ) != pre["text"]:
        issues.append("batch11-final5 reread predecessor chain is broken")
    if contract:
        issues.extend(audit_batch11_final5_contract(contract, reread))

    pre_facts = batch11_final5_fact_map(pre_pages)
    live_facts = batch11_final5_fact_map(pages)
    projection = (
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence",
    )
    changed_facts = {
        key for key in set(pre_facts) & set(live_facts)
        if any(
            batch11_norm(pre_facts[key][field]) != batch11_norm(live_facts[key][field])
            for field in projection
        )
    }
    if changed_facts != {BATCH11_FINAL5_FACT_TARGET}:
        issues.append("batch11-final5 fact/source projection is not the exact target")
    source_row = source_suffix[0] if len(source_suffix) == 1 else {}
    source_key = (
        source_row.get("slug", ""),
        source_row.get("language", ""),
        source_row.get("fact_id", ""),
    )
    if source_key != BATCH11_FINAL5_FACT_TARGET:
        issues.append("batch11-final5 source append is not the exact target")
    source_tips = {}
    for row in prefix_source:
        source_tips[(
            row.get("slug", ""), row.get("language", ""), row.get("fact_id", ""),
        )] = row
    source_predecessor = source_tips.get(BATCH11_FINAL5_FACT_TARGET)
    live_fact = live_facts.get(BATCH11_FINAL5_FACT_TARGET)
    mutable = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "baseline_issue",
        "resolution_action", "support_urls", "locatable_support", "source_roles",
        "final_issue", "audit_accessed_at", "audit_final_url", "audit_title",
        "audit_source_id", "audit_locator", "audit_support_summary",
        "audit_relationship", "audit_claim_compared", "audit_decision",
        "source_date_audit", "reread_h1_current", "reread_dek_current",
        "reread_timeline_current", "reread_rights_current",
        "reread_protection_current", "reread_source_titles_current",
        "reread_card_current", "reread_issue_found", "reread_revision_text",
        "reread_result", "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor", "visible_timeline_order",
        "visible_source_roles",
    }
    if source_predecessor is None or live_fact is None:
        issues.append("batch11-final5 source append lacks predecessor or live fact")
    else:
        for field in BATCH9_FINAL2_SOURCE_COLUMNS:
            if (
                field not in mutable
                and source_row.get(field, "") != source_predecessor.get(field, "")
            ):
                issues.append(
                    f"batch11-final5 source append changed protected field {field}"
                )
        exact_live_fields = {
            "current_visible_text", "data_source_ref", "timeline_subject",
            "timeline_action", "timeline_consequence", "support_urls",
            "source_roles", "source_date_audit", "visible_source_roles",
            "reread_h1_current", "reread_dek_current",
            "reread_timeline_current", "reread_rights_current",
            "reread_protection_current", "reread_source_titles_current",
            "reread_revision_text", "audit_final_url",
            "audit_title", "audit_source_id", "audit_claim_compared",
        }
        for field in exact_live_fields:
            if batch11_norm(source_row.get(field, "")) != batch11_norm(
                live_fact.get(field, "")
            ):
                issues.append(
                    f"batch11-final5 source {field} differs from the live DOM"
                )
        if source_row.get("reread_card_current", "") != (
            source_predecessor.get("reread_card_current", "")
        ):
            issues.append("batch11-final5 source changed the frozen final4 card snapshot")
        report_cards, card_issues = batch9_final2_report_cards()
        report_cards = batch14_baseline_card_view(report_cards)
        issues.extend(
            f"batch11-final5 card parse: {issue}" for issue in card_issues
        )
        card = next(
            (
                candidate for candidate in report_cards
                if candidate.get("slug", "") == BATCH11_FINAL5_SLUG
            ),
            None,
        )
        expected_card = "" if card is None else (
            f"{card.get('title_en', '')} | {card.get('excerpt_en', '')}"
        )
        if card is None:
            issues.append("batch11-final5 frozen Feng report card is missing")
        elif source_row.get("reread_card_current", "") != expected_card:
            issues.append(
                "batch11-final5 source card snapshot differs from frozen script.js"
            )
    if source_row.get("baseline_issue", "") != contract_id:
        issues.append("batch11-final5 source baseline is not its paired contract")
    if source_row.get("reread_issue_found", "") != issue_found:
        issues.append("batch11-final5 source issue differs from its paired reread")
    for field, expected in (
        ("audit_decision", "PASS_FINAL5_SOURCE_MAPPING"),
        ("reread_result", "PASS_AFTER_REVISION"),
        ("audit_accessed_at", "2026-07-24"),
        ("data_source_ref", "s1 s2 s3 s4 s5"),
        ("audit_source_id", "s1 s2 s3 s4 s5"),
    ):
        if source_row.get(field, "") != expected:
            issues.append(f"batch11-final5 source {field} differs")
    for field in (
        "resolution_action", "final_issue", "audit_final_url", "audit_title",
        "audit_locator", "audit_support_summary", "audit_relationship",
        "locatable_support", "source_roles", "source_date_audit",
    ):
        if not source_row.get(field, "").strip():
            issues.append(f"batch11-final5 source evidence lacks {field}")
    for field in ("resolution_action", "final_issue"):
        if BATCH11_FINAL5_PREFIX.rstrip(":") not in source_row.get(field, ""):
            issues.append(f"batch11-final5 source {field} lacks the batch marker")
    return issues, {
        "changed_targets": len(actual_changes),
        "changed_facts": len(changed_facts),
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "source_rows": len(source_suffix),
    }


def batch11_final5_manifest(overrides=None):
    """Recompute total/whitelist/protected counts and the protected byte set."""
    overrides = overrides or {}
    all_records = []
    protected = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        if ".git" in relative_path.parts or path.name == ".DS_Store":
            continue
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else path.read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if batch11_final1_is_desktop_extra(relative, payload):
            continue
        record = (relative, len(payload), hashlib.sha256(payload).hexdigest())
        all_records.append(record)
        if relative not in BATCH11_FINAL5_ALLOWED_FILES:
            protected.append(record)
    protected_payload = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(protected)
    ).encode("utf-8")
    allowed_present = {
        relative for relative, _size, _digest in all_records
        if relative in BATCH11_FINAL5_ALLOWED_FILES
    }
    return all_records, protected, allowed_present, protected_payload


def audit_batch11_final5_frozen(overrides=None):
    """Authenticate all files outside the dynamic six-file final5 whitelist."""
    # Replayed against the authenticated pre-batch13 bytes of the 49 revised
    # dossiers, so every digest below still runs; an explicit override wins.
    overrides = {**batch13_historical_bytes(), **(overrides or {})}
    all_records, protected, allowed_present, protected_payload = (
        batch11_final5_manifest(overrides)
    )
    issues = []
    missing_allowed = BATCH11_FINAL5_ALLOWED_FILES - allowed_present
    if missing_allowed:
        issues.append(
            "batch11-final5 whitelist file missing: "
            + ", ".join(sorted(missing_allowed))
        )
    expected_protected = len(all_records) - len(BATCH11_FINAL5_ALLOWED_FILES)
    if len(protected) != expected_protected:
        issues.append(
            "batch11-final5 dynamic protected count mismatch: "
            f"{len(protected)} != {len(all_records)} - "
            f"{len(BATCH11_FINAL5_ALLOWED_FILES)}"
        )
    if hashlib.sha256(protected_payload).hexdigest() != (
        BATCH11_FINAL5_PROTECTED_SHA256
    ):
        issues.append("batch11-final5 changed, added, or removed a non-whitelist file")
    for relative, digest in BATCH11_FINAL5_FROZEN_SHA256.items():
        path = ROOT / relative
        if not path.exists() and relative not in overrides:
            issues.append(f"batch11-final5 frozen file is missing: {relative}")
            continue
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else path.read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if hashlib.sha256(payload).hexdigest() != digest:
            issues.append(f"batch11-final5 changed frozen {relative}")
    return issues


def batch11_final5_freeze_stats():
    all_records, protected, allowed_present, _payload = batch11_final5_manifest()
    return {
        "total_files": len(all_records),
        "allowed_files": len(allowed_present),
        "protected_files": len(protected),
    }


def audit_batch11_final5_wiring(source_text=None):
    source_text = source_text or Path(__file__).read_text(encoding="utf-8")
    live = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    main = re.search(
        r"def main\(\):(?P<body>.*?)(?=\nif __name__ ==)", source_text, re.S,
    )
    issues = []
    live_calls = [] if live is None else re.findall(
        r"issues\.extend\(audit_batch11_final5\(", live.group("body")
    )
    self_calls = [] if main is None else re.findall(
        r"batch11_final5_self_test\s*=\s*"
        r"batch11_final5_negative_self_test\(final5_pages\)",
        main.group("body"),
    )
    if (
        len(live_calls) != 1
        or live is None
        or "final5_pages" not in live.group("body")
    ):
        issues.append("batch11-final5 authoritative audit_live wiring is absent")
    if len(self_calls) != 1:
        issues.append("batch11-final5 named negative suite is not wired into --self-test")
    return issues


def audit_batch11_final5(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    frozen_overrides=None, source_text=None,
):
    issues = []
    issues.extend(audit_batch11_final5_semantics(pages))
    issues.extend(audit_batch11_final5_sources(pages))
    ledger_issues, _stats = audit_batch11_final5_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    issues.extend(ledger_issues)
    issues.extend(audit_batch11_final5_frozen(frozen_overrides))
    issues.extend(audit_batch11_final5_wiring(source_text))
    return issues


def batch11_final5_negative_self_test(pages):
    """Exercise eighteen real DOM/attribute/ledger/freeze/wiring classes."""
    names = []
    misses = []
    semantic_baseline = audit_batch11_final5_semantics(pages)
    source_baseline = audit_batch11_final5_sources(pages)
    freeze_baseline = audit_batch11_final5_frozen()
    wiring_baseline = audit_batch11_final5_wiring()

    def record(name, caught, baseline=()):
        names.append(name)
        if baseline or not caught:
            detail = f" (baseline: {baseline[0]})" if baseline else ""
            misses.append(name + detail)

    def mutated_page():
        mutated = dict(pages)
        mutated[BATCH11_FINAL5_SLUG] = deepcopy(pages[BATCH11_FINAL5_SLUG])
        return mutated

    def mutate_text(old, new=""):
        mutated = mutated_page()
        node = batch11_final5_target_node(mutated)
        text = normalized_visible(node)
        if old not in text:
            return mutated, False
        batch11_final1_restore_text(node, "fact", text.replace(old, new, 1))
        return mutated, True

    # 1-3. Reinsert each exact rejected construction in the real target.
    mutated, changed = mutate_text("Her being held in chains", "The chain restraint")
    record(
        "01 The-chain-restraint reinsertion",
        changed and bool(audit_batch11_final5_semantics(mutated)),
        semantic_baseline,
    )
    mutated, changed = mutate_text(
        "records concerning her identity, marriage, health and prolonged unlawful confinement",
        "identity and prolonged-control records",
    )
    record(
        "02 prolonged-control-records reinsertion",
        changed and bool(audit_batch11_final5_semantics(mutated)),
        semantic_baseline,
    )
    mutated, changed = mutate_text(
        "investigate every person involved in purchasing or transporting her and "
        "every act of unlawful confinement or pressure",
        "investigate every purchaser, transporter, unlawful confinement, and act of pressure",
    )
    record(
        "03 malformed purchaser/transporter/confinement coordination",
        changed and bool(audit_batch11_final5_semantics(mutated)),
        semantic_baseline,
    )

    # 4-11. Remove independently required meanings from actual BeautifulSoup DOM.
    for number, phrase, label in (
        ("04", "held in chains", "held-in-chains deletion"),
        ("05", "Jiangsu provincial investigation", "Jiangsu investigation deletion"),
        ("06", "prolonged unlawful confinement", "prolonged confinement deletion"),
        ("07", "police interference", "police interference deletion"),
        ("08", "removal of posts", "post-removal deletion"),
        (
            "09", "safeguards for the woman’s and children’s privacy",
            "woman-and-children privacy deletion",
        ),
        (
            "10", "every person involved in purchasing or transporting her",
            "purchaser/transporter accountability deletion",
        ),
        (
            "11", "independent, effective legal remedies",
            "independent effective remedies deletion",
        ),
    ):
        mutated, changed = mutate_text(phrase)
        record(
            f"{number} {label}",
            changed and bool(audit_batch11_final5_semantics(mutated)),
            semantic_baseline,
        )

    # 12. Break only the real critical-case attribute.
    mutated = mutated_page()
    node = batch11_final5_target_node(mutated)
    critical = node.select_one("[data-critical-case]")
    critical["data-critical-case"] = "Tampered first sentence."
    record(
        "12 data-critical-case/visible-first-sentence mismatch",
        bool(audit_batch11_final5_semantics(mutated)),
        semantic_baseline,
    )

    # 13. Change the live target's real source-ref attribute.
    mutated = mutated_page()
    node = batch11_final5_target_node(mutated)
    node["data-source-ref"] = "s1"
    record(
        "13 target data-source-ref mutation",
        bool(
            audit_batch11_final5_semantics(mutated)
            or audit_batch11_final5_sources(mutated)
        ),
        (*semantic_baseline, *source_baseline),
    )

    reread_rows, _ = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "final5 self-test reread",
    )
    contract_rows, _ = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "final5 self-test contract",
    )
    source_rows, _ = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "final5 self-test source",
    )
    # Final5 is now a completed predecessor.  Exercise its own one-row append,
    # never the two-row final6 tail.
    reread_rows = reread_rows[:BATCH11_FINAL5_REREAD_ROWS]
    contract_rows = contract_rows[:BATCH11_FINAL5_CONTRACT_ROWS]
    source_rows = source_rows[:BATCH11_FINAL5_SOURCE_ROWS]
    ledger_baseline, _ = audit_batch11_final5_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )

    # 14. Remove each actual final5 append row and rerun production validation.
    caught = []
    for kind in ("reread", "contract", "source"):
        changed_reread = deepcopy(reread_rows)
        changed_contract = deepcopy(contract_rows)
        changed_source = deepcopy(source_rows)
        if kind == "reread":
            changed_reread.pop()
        elif kind == "contract":
            changed_contract.pop()
        else:
            changed_source.pop()
        found, _ = audit_batch11_final5_ledgers(
            pages, reread_rows=changed_reread, contract_rows=changed_contract,
            source_rows=changed_source,
        )
        caught.append(bool(found))
    record(
        "14 final5 reread/contract/source append deletion",
        all(caught), ledger_baseline,
    )

    # 15. Mutate each explicit frozen file through the production byte gate.
    caught = []
    for relative in BATCH11_FINAL5_FROZEN_SHA256:
        caught.append(bool(audit_batch11_final5_frozen({
            relative: (ROOT / relative).read_bytes() + b"\nfinal5 mutation",
        })))
    record("15 non-whitelist frozen-file mutation", all(caught), freeze_baseline)

    # 16. Rewrite a completed-final4 prefix row in each in-memory ledger.
    caught = []
    for kind in ("reread", "contract", "source"):
        changed_reread = deepcopy(reread_rows)
        changed_contract = deepcopy(contract_rows)
        changed_source = deepcopy(source_rows)
        selected, boundary = {
            "reread": (changed_reread, BATCH11_FINAL5_PRE_REREAD_ROWS),
            "contract": (changed_contract, BATCH11_FINAL5_PRE_CONTRACT_ROWS),
            "source": (changed_source, BATCH11_FINAL5_PRE_SOURCE_ROWS),
        }[kind]
        selected[boundary - 1][next(iter(selected[boundary - 1]))] += " tampered"
        found, _ = audit_batch11_final5_ledgers(
            pages, reread_rows=changed_reread, contract_rows=changed_contract,
            source_rows=changed_source,
        )
        caught.append(bool(found))
    record("16 completed-final4 prefix-row rewrite", all(caught), ledger_baseline)

    # 17. Mutate real source metadata, visible date, and order in the DOM.
    caught = []
    for field in ("id", "type", "date", "url", "visible-date", "order"):
        mutated = mutated_page()
        body = mutated[BATCH11_FINAL5_SLUG].select_one(
            '[data-language-body="en"]'
        )
        sources = body.select("ul.source-list > li[data-source-id]")
        source = sources[0]
        if field == "id":
            source["data-source-id"] = "s1-tampered"
        elif field == "type":
            source["data-source-type"] = "tampered-source-type"
        elif field == "date":
            source["data-source-date"] = "2099-01-01"
        elif field == "url":
            source.find("a")["href"] += "?tampered=1"
        elif field == "visible-date":
            source.find("time").string = "2099-01-01"
        else:
            source.extract()
            sources[1].insert_after(source)
        caught.append(bool(audit_batch11_final5_sources(mutated)))
    record("17 source metadata/visible-date/order mutation", all(caught), source_baseline)

    # 18. Delete both mandatory production entry points from real source text.
    source_text = Path(__file__).read_text(encoding="utf-8")
    caught = []
    for needle in (
        "    issues.extend(audit_batch11_final5(\n",
        "        batch11_final5_self_test = "
        "batch11_final5_negative_self_test(final5_pages)\n",
    ):
        changed = source_text.replace(needle, "        # removed final5 entry\n", 1)
        caught.append(
            changed != source_text
            and bool(audit_batch11_final5_wiring(changed))
        )
    record("18 final5 audit/self-test wiring deletion", all(caught), wiring_baseline)
    if len(names) != 18 or len(set(names)) != 18:
        misses.append(
            f"batch11-final5 named suite cardinality is {len(names)}, expected 18"
        )
    return len(names) - len(misses), len(names), misses


