def batch11_final6_target_node(pages, fact_id):
    soup = pages.get(BATCH11_FINAL6_SLUG)
    if soup is None:
        return None
    body = soup.select_one('[data-language-body="en"]')
    return body.select_one(f'[data-fact-id="{fact_id}"]') if body else None


def audit_batch11_final6_semantics(pages):
    """Enforce both supplied paragraphs and independently named meanings."""
    soup = pages.get(BATCH11_FINAL6_SLUG)
    if soup is None:
        return ["batch11-final6 Feng County page is missing"]
    issues = []
    for fact_id, spec in BATCH11_FINAL6_TARGET_SPECS.items():
        nodes = soup.select(
            f'[data-language-body="en"] [data-fact-id="{fact_id}"]'
        )
        if len(nodes) != 1:
            issues.append(
                f"batch11-final6 {fact_id} target count is {len(nodes)}, expected 1"
            )
            continue
        node = nodes[0]
        text = normalized_visible(node)
        if text != spec["new"]:
            issues.append(f"batch11-final6 {fact_id} differs from the approved prose")
        missing = batch11_final2_phrase_missing(text, spec["required"])
        if missing:
            issues.append(
                f"batch11-final6 {fact_id} loses actor/action/evidence meaning: {missing}"
            )
        for rejected in spec["forbidden"]:
            if rejected.casefold() in text.casefold():
                issues.append(
                    f"batch11-final6 {fact_id} restored rejected wording: "
                    f"{rejected[:80]}"
                )
        refs = " ".join(node.get("data-source-ref", "").split())
        if refs != spec["refs"]:
            issues.append(
                f"batch11-final6 {fact_id} refs are {refs!r}, expected {spec['refs']!r}"
            )
    return issues


def batch11_final6_source_signature(pages):
    """Serialize the complete Feng source graph without consulting a ledger."""
    metadata = []
    refs = []
    soup = pages.get(BATCH11_FINAL6_SLUG)
    if soup is None:
        return metadata, refs
    for language in BATCH5_LANGS:
        body = soup.select_one(f'[data-language-body="{language}"]')
        if body is None:
            continue
        for order, source in enumerate(
            body.select("ul.source-list > li[data-source-id]")
        ):
            anchor = source.find("a")
            visible_date = source.find("time")
            metadata.append(json.dumps([
                BATCH11_FINAL6_SLUG,
                language,
                order,
                source.get("data-source-id", ""),
                source.get("data-source-type", ""),
                source.get("data-source-date", ""),
                anchor.get("href", "") if anchor else "",
                normalized_visible(anchor),
                visible_date.get("datetime", "") if visible_date else "",
                normalized_visible(visible_date),
            ], ensure_ascii=False, separators=(",", ":")) + "\n")
        for node in body.select("[data-fact-id]"):
            fact_id = node.get("data-fact-id", "")
            if (
                not fact_id or fact_id.endswith("-sources")
                or node.select_one("[data-fact-id]") is not None
            ):
                continue
            refs.append(json.dumps([
                BATCH11_FINAL6_SLUG,
                language,
                fact_id,
                " ".join(node.get("data-source-ref", "").split()),
            ], ensure_ascii=False, separators=(",", ":")) + "\n")
    return metadata, refs


def audit_batch11_final6_sources(pages):
    issues = []
    metadata, refs = batch11_final6_source_signature(pages)
    for rows, count, digest, label in (
        (
            metadata,
            BATCH11_FINAL6_SOURCE_METADATA_ROWS,
            BATCH11_FINAL6_SOURCE_METADATA_SHA256,
            "source ID/type/date/URL/title/visible-date/order metadata",
        ),
        (
            refs,
            BATCH11_FINAL6_SOURCE_REF_ROWS,
            BATCH11_FINAL6_SOURCE_REF_SHA256,
            "data-source-ref map",
        ),
    ):
        if len(rows) != count:
            issues.append(
                f"batch11-final6 {label} has {len(rows)} rows, expected {count}"
            )
        if hashlib.sha256("".join(rows).encode("utf-8")).hexdigest() != digest:
            issues.append(f"batch11-final6 changed frozen {label}")
    return issues


def batch11_final6_inventory(pages):
    """Enumerate every visible Feng leaf so exactly two facts may change."""
    targets = {}
    issues = []
    soup = pages.get(BATCH11_FINAL6_SLUG)
    if soup is None:
        return targets, ["batch11-final6 inventory page is missing"]

    def add(key, text, source_refs):
        if key in targets:
            issues.append(f"batch11-final6 duplicate target: {'/'.join(key)}")
        targets[key] = {
            "text": batch11_norm(text),
            "source_refs": batch11_norm(source_refs),
        }

    for language in BATCH5_LANGS:
        body = soup.select_one(f'[data-language-body="{language}"]')
        if body is None:
            issues.append(f"batch11-final6 language body missing: {language}")
            continue
        sources = body.select("ul.source-list > li[data-source-id]")
        page_refs = "page-sources:" + " ".join(
            source.get("data-source-id", "") for source in sources
        )
        for kind, target_id, selector in (
            ("article-title", "article-title", f".article-title .lang-{language}"),
            ("article-dek", "article-dek", f".article-dek .lang-{language}"),
        ):
            node = soup.select_one(selector)
            if node is None:
                issues.append(f"batch11-final6 target missing: {language}/{target_id}")
            else:
                add(
                    (BATCH11_FINAL6_SLUG, language, kind, target_id),
                    normalized_visible(node), page_refs,
                )
        for node in body.select("[data-fact-id]"):
            fact_id = node.get("data-fact-id", "")
            if (
                not fact_id or fact_id.endswith("-sources")
                or node.select_one("[data-fact-id]") is not None
            ):
                continue
            add(
                (BATCH11_FINAL6_SLUG, language, "fact", fact_id),
                normalized_visible(node), node.get("data-source-ref", ""),
            )
        for source in sources:
            source_id = source.get("data-source-id", "")
            anchor = source.find("a")
            label = source.find("b")
            if not source_id or anchor is None or label is None:
                issues.append(f"batch11-final6 malformed source: {language}")
                continue
            add(
                (
                    BATCH11_FINAL6_SLUG, language, "source-title",
                    f"source-title:{source_id}",
                ),
                normalized_visible(anchor), source_id,
            )
            add(
                (
                    BATCH11_FINAL6_SLUG, language, "source-category",
                    f"source-category:{source_id}",
                ),
                normalized_visible(label), source_id,
            )
    return targets, issues


def batch11_final6_historical_state(
    live_pages=None, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Authenticate and reconstruct the exact completed-final5 predecessor."""
    disk_reread, reread_issues = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch11-final6 reread ledger",
    )
    disk_contract, contract_issues = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch11-final6 contract ledger",
    )
    disk_source, source_issues = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch11-final6 source ledger",
    )
    if reread_rows is None:
        reread_rows = disk_reread
    if contract_rows is None:
        contract_rows = disk_contract
    if source_rows is None:
        source_rows = disk_source
    issues = [*reread_issues, *contract_issues, *source_issues]
    for path, count, digest, label in (
        (
            BATCH9_REREAD_PATH,
            BATCH11_FINAL6_PRE_REREAD_ROWS,
            BATCH11_FINAL6_PRE_REREAD_SHA256,
            "batch11-final6 completed-final5 reread prefix",
        ),
        (
            BATCH9_CONTRACT_PATH,
            BATCH11_FINAL6_PRE_CONTRACT_ROWS,
            BATCH11_FINAL6_PRE_CONTRACT_SHA256,
            "batch11-final6 completed-final5 contract prefix",
        ),
        (
            BATCH9_SOURCE_LEDGER_PATH,
            BATCH11_FINAL6_PRE_SOURCE_ROWS,
            BATCH11_FINAL6_PRE_SOURCE_SHA256,
            "batch11-final6 completed-final5 source prefix",
        ),
    ):
        issues.extend(batch9_final2_exact_prefix(path, count, digest, label))
    source_date = ROOT / "tools/data/source-date-ledger.tsv"
    if not source_date.exists():
        issues.append("batch11-final6 frozen source-date ledger is missing")
    else:
        payload = batch14_source_date_prefix_bytes()
        if hashlib.sha256(payload).hexdigest() != BATCH11_FINAL6_SOURCE_DATE_SHA256:
            issues.append("batch11-final6 source-date ledger bytes changed")
        try:
            date_rows = list(csv.DictReader(
                io.StringIO(payload.decode("utf-8")), delimiter="\t",
            ))
        except UnicodeDecodeError:
            date_rows = []
            issues.append("batch11-final6 source-date ledger is not UTF-8")
        if len(date_rows) != BATCH11_FINAL6_SOURCE_DATE_ROWS:
            issues.append(
                "batch11-final6 source-date ledger has "
                f"{len(date_rows)} rows, expected {BATCH11_FINAL6_SOURCE_DATE_ROWS}"
            )
    if live_pages is None:
        live_pages = {
            BATCH11_FINAL6_SLUG: BeautifulSoup(
                (ROOT / "posts" / f"{BATCH11_FINAL6_SLUG}.html").read_text(
                    encoding="utf-8"
                ),
                "html.parser",
            )
        }
    predecessor = dict(live_pages)
    if BATCH11_FINAL6_SLUG in live_pages:
        predecessor[BATCH11_FINAL6_SLUG] = deepcopy(
            live_pages[BATCH11_FINAL6_SLUG]
        )
    append = reread_rows[
        BATCH11_FINAL6_PRE_REREAD_ROWS:BATCH11_FINAL6_REREAD_ROWS
    ]
    seen = set()
    for row in append:
        key = (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )
        if key not in BATCH11_FINAL6_TARGETS:
            issues.append(
                f"batch11-final6 cannot replay out-of-scope row: {'/'.join(key)}"
            )
            continue
        if key in seen:
            issues.append(f"batch11-final6 duplicate replay row: {'/'.join(key)}")
            continue
        seen.add(key)
        node = batch11_final6_target_node(predecessor, key[-1])
        if not batch11_final1_restore_text(
            node, "fact", row.get("original_text", ""),
        ):
            issues.append(f"batch11-final6 cannot restore target: {key[-1]}")
    if seen != BATCH11_FINAL6_TARGETS:
        issues.append("batch11-final6 cannot reconstruct both completed-final5 targets")
    pre_soup = predecessor.get(BATCH11_FINAL6_SLUG)
    if pre_soup is not None:
        digest = hashlib.sha256(batch11_final1_page_payload(pre_soup)).hexdigest()
        if digest != BATCH11_FINAL6_PRE_PAGE_SHA256:
            issues.append(
                "batch11-final6 completed-final5 Feng page did not reconstruct"
            )
    return (
        predecessor,
        disk_reread[:BATCH11_FINAL6_PRE_REREAD_ROWS],
        disk_contract[:BATCH11_FINAL6_PRE_CONTRACT_ROWS],
        disk_source[:BATCH11_FINAL6_PRE_SOURCE_ROWS],
        issues,
    )


def batch11_final6_fact_map(pages):
    return {
        key: value for key, value in batch11_final2_fact_map(pages).items()
        if key[0] == BATCH11_FINAL6_SLUG
    }


def audit_batch11_final6_contract(row, reread_row, spec):
    """Validate one handwritten contract without using it as a prose oracle."""
    issues = []
    required = tuple(
        part.strip() for part in row.get("required_all", "").split("||")
        if part.strip()
    )
    forbidden = tuple(
        part.strip() for part in row.get("forbidden_any", "").split("||")
        if part.strip()
    )
    if len(required) < len(spec["contract_anchors"]):
        issues.append(
            "batch11-final6 contract lacks independently named semantic anchors"
        )
    required_stream = final1_contiguous_stream(" ".join(required))
    for anchor in spec["contract_anchors"]:
        if final1_contiguous_stream(anchor) not in required_stream:
            issues.append(
                f"batch11-final6 contract lacks independent anchor: {anchor}"
            )
    forbidden_values = tuple(
        part.split(":", 1)[-1] if ":" in part else "" for part in forbidden
    )
    if len(forbidden) < 4 or any(
        not part.startswith("old-error:") for part in forbidden
    ):
        issues.append("batch11-final6 contract lacks four old-error prohibitions")
    for rejected in spec["forbidden"]:
        if rejected not in forbidden_values:
            issues.append(
                "batch11-final6 contract lacks rejected wording: "
                f"{rejected[:80]}"
            )
    summary = row.get("fact_summary", "").casefold()
    for role in spec["summary_roles"]:
        if role not in summary:
            issues.append(f"batch11-final6 contract summary lacks role: {role}")
    revised = batch11_norm(reread_row.get("revised_text", ""))
    if revised and final1_longest_common_fragment(
        row.get("fact_summary", ""), revised,
    ) >= min(180, max(100, len(final1_contiguous_stream(revised)) // 2)):
        issues.append("batch11-final6 contract summary is copied from revised DOM")
    return issues


def audit_batch11_final6_ledgers(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Require exactly two true rereads, contracts, and source mappings."""
    issues = []
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch11-final6 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch11-final6 contract ledger",
        )
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch11-final6 source ledger",
        )
        issues.extend(load_issues)
    history = batch11_final6_historical_state(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    pre_pages, prefix_reread, prefix_contract, prefix_source = history[:4]
    issues.extend(history[-1])
    pre_inventory, pre_inventory_issues = batch11_final6_inventory(pre_pages)
    live_inventory, live_inventory_issues = batch11_final6_inventory(pages)
    issues.extend(pre_inventory_issues)
    issues.extend(live_inventory_issues)
    if set(pre_inventory) != set(live_inventory):
        issues.append("batch11-final6 added or removed a public semantic target")
    actual_changes = {
        key for key in set(pre_inventory) & set(live_inventory)
        if pre_inventory[key] != live_inventory[key]
    }
    if actual_changes != BATCH11_FINAL6_TARGETS:
        issues.append(
            "batch11-final6 visible changes differ from the exact two-target scope: "
            f"missing={len(BATCH11_FINAL6_TARGETS - actual_changes)} "
            f"extra={len(actual_changes - BATCH11_FINAL6_TARGETS)}"
        )
    for key in set(pre_inventory) & set(live_inventory):
        if pre_inventory[key]["source_refs"] != live_inventory[key]["source_refs"]:
            issues.append(f"batch11-final6 changed frozen refs: {'/'.join(key)}")
    if reread_rows[:BATCH11_FINAL6_PRE_REREAD_ROWS] != prefix_reread:
        issues.append("batch11-final6 in-memory final5 reread prefix differs")
    if contract_rows[:BATCH11_FINAL6_PRE_CONTRACT_ROWS] != prefix_contract:
        issues.append("batch11-final6 in-memory final5 contract prefix differs")
    if source_rows[:BATCH11_FINAL6_PRE_SOURCE_ROWS] != prefix_source:
        issues.append("batch11-final6 in-memory final5 source prefix differs")
    reread_suffix = reread_rows[BATCH11_FINAL6_PRE_REREAD_ROWS:]
    contract_suffix = contract_rows[BATCH11_FINAL6_PRE_CONTRACT_ROWS:]
    source_suffix = source_rows[BATCH11_FINAL6_PRE_SOURCE_ROWS:]
    for suffix, expected, label in (
        (reread_suffix, 2, "reread"),
        (contract_suffix, 2, "contract"),
        (source_suffix, 2, "source"),
    ):
        if len(suffix) != expected:
            issues.append(
                f"batch11-final6 {label} append has {len(suffix)} rows, expected 2"
            )

    def visible_key(row):
        return (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_kind", ""), row.get("target_id", ""),
        )

    reread_by_key = {visible_key(row): row for row in reread_suffix}
    contract_by_key = {visible_key(row): row for row in contract_suffix}
    if (
        len(reread_by_key) != len(reread_suffix)
        or set(reread_by_key) != BATCH11_FINAL6_TARGETS
    ):
        issues.append("batch11-final6 reread rows are not unique exact targets")
    if (
        len(contract_by_key) != len(contract_suffix)
        or set(contract_by_key) != BATCH11_FINAL6_TARGETS
    ):
        issues.append("batch11-final6 contract rows are not unique exact targets")
    predecessor_tips = {}
    for row in prefix_reread:
        predecessor_tips[visible_key(row)] = row
    for fact_id, spec in BATCH11_FINAL6_TARGET_SPECS.items():
        key = spec["target"]
        reread = reread_by_key.get(key, {})
        contract = contract_by_key.get(key, {})
        pre = pre_inventory.get(key, {"text": "", "source_refs": ""})
        live = live_inventory.get(key, {"text": "", "source_refs": ""})
        contract_id = reread.get("contract_id", "")
        expected_id_prefix = f"{BATCH11_FINAL6_PREFIX}{':'.join(key)}:"
        if not contract_id.startswith(expected_id_prefix):
            issues.append(f"batch11-final6 {fact_id} reread ID is not target-bound")
        if contract.get("contract_id", "") != contract_id:
            issues.append(f"batch11-final6 {fact_id} contract/reread ID pair differs")
        if reread.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch11-final6 {fact_id} is not PASS_AFTER_REVISION")
        if "PASS_NO_CHANGE" in reread.get("result", ""):
            issues.append(f"batch11-final6 {fact_id} improperly records PASS_NO_CHANGE")
        if batch11_norm(reread.get("original_text", "")) != pre["text"]:
            issues.append(f"batch11-final6 {fact_id} original is not final5 DOM")
        if batch11_norm(reread.get("revised_text", "")) != live["text"]:
            issues.append(f"batch11-final6 {fact_id} revision differs from live DOM")
        if batch11_norm(reread.get("source_refs", "")) != live["source_refs"]:
            issues.append(f"batch11-final6 {fact_id} reread refs differ from DOM")
        if (
            pre["text"] == live["text"]
            or batch11_norm(reread.get("original_text", ""))
            == batch11_norm(reread.get("revised_text", ""))
        ):
            issues.append(f"batch11-final6 {fact_id} is not a genuine revision")
        issue_found = reread.get("issue_found", "")
        for anchor in spec["issue_anchors"]:
            if anchor.casefold() not in issue_found.casefold():
                issues.append(
                    f"batch11-final6 {fact_id} issue_found lacks: {anchor}"
                )
        review_basis = reread.get("review_basis", "")
        for anchor in spec["review_anchors"]:
            if anchor.casefold() not in review_basis.casefold():
                issues.append(
                    f"batch11-final6 {fact_id} review basis lacks: {anchor}"
                )
        predecessor = predecessor_tips.get(key)
        if predecessor is not None and batch11_norm(
            predecessor.get("revised_text", "")
        ) != pre["text"]:
            issues.append(f"batch11-final6 {fact_id} reread chain is broken")
        if contract:
            issues.extend(audit_batch11_final6_contract(contract, reread, spec))

    pre_facts = batch11_final6_fact_map(pre_pages)
    live_facts = batch11_final6_fact_map(pages)
    projection = (
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence",
    )
    changed_facts = {
        key for key in set(pre_facts) & set(live_facts)
        if any(
            batch11_norm(pre_facts[key][field])
            != batch11_norm(live_facts[key][field])
            for field in projection
        )
    }
    if changed_facts != BATCH11_FINAL6_FACT_TARGETS:
        issues.append("batch11-final6 fact/source projection is not two exact targets")
    source_by_key = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("fact_id", ""),
        ): row
        for row in source_suffix
    }
    if (
        len(source_by_key) != len(source_suffix)
        or set(source_by_key) != BATCH11_FINAL6_FACT_TARGETS
    ):
        issues.append("batch11-final6 source rows are not unique exact targets")
    source_tips = {}
    for row in prefix_source:
        source_tips[(
            row.get("slug", ""), row.get("language", ""),
            row.get("fact_id", ""),
        )] = row
    report_cards, card_issues = batch9_final2_report_cards()
    report_cards = batch14_baseline_card_view(report_cards)
    issues.extend(f"batch11-final6 card parse: {issue}" for issue in card_issues)
    card = next(
        (
            candidate for candidate in report_cards
            if candidate.get("slug", "") == BATCH11_FINAL6_SLUG
        ),
        None,
    )
    expected_card = "" if card is None else (
        f"{card.get('title_en', '')} | {card.get('excerpt_en', '')}"
    )
    if card is None:
        issues.append("batch11-final6 frozen Feng report card is missing")
    mutable = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "baseline_issue",
        "resolution_action", "support_urls", "locatable_support", "source_roles",
        "final_issue", "audit_accessed_at", "audit_final_url", "audit_title",
        "audit_source_id", "audit_locator", "audit_support_summary",
        "audit_relationship", "audit_claim_compared", "audit_decision",
        "verification_status", "source_date_audit",
        "reread_h1_current", "reread_dek_current",
        "reread_timeline_current", "reread_rights_current",
        "reread_protection_current", "reread_source_titles_current",
        "reread_card_current", "reread_issue_found", "reread_revision_text",
        "reread_result", "visible_subject_anchor", "visible_action_anchor",
        "visible_consequence_anchor", "visible_timeline_order",
        "visible_source_roles",
    }
    exact_live_fields = {
        "current_visible_text", "data_source_ref", "timeline_subject",
        "timeline_action", "timeline_consequence", "support_urls",
        "source_roles", "source_date_audit", "visible_source_roles",
        "reread_h1_current", "reread_dek_current",
        "reread_timeline_current", "reread_rights_current",
        "reread_protection_current",
        "reread_revision_text", "audit_final_url", "audit_title",
        "audit_source_id", "audit_claim_compared",
    }
    for fact_id, spec in BATCH11_FINAL6_TARGET_SPECS.items():
        key = spec["target"]
        fact_key = spec["fact_target"]
        source_row = source_by_key.get(fact_key, {})
        predecessor = source_tips.get(fact_key)
        live_fact = live_facts.get(fact_key)
        reread = reread_by_key.get(key, {})
        if predecessor is None or live_fact is None:
            issues.append(f"batch11-final6 {fact_id} source chain is missing")
            continue
        for field in BATCH9_FINAL2_SOURCE_COLUMNS:
            if (
                field not in mutable
                and source_row.get(field, "") != predecessor.get(field, "")
            ):
                issues.append(
                    f"batch11-final6 {fact_id} changed protected source field {field}"
                )
        for field in exact_live_fields:
            if batch11_norm(source_row.get(field, "")) != batch11_norm(
                live_fact.get(field, "")
            ):
                issues.append(
                    f"batch11-final6 {fact_id} source {field} differs from DOM"
                )
        body = pages[BATCH11_FINAL6_SLUG].select_one(
            '[data-language-body="en"]'
        )
        dom_sources = {
            source.get("data-source-id", ""): source
            for source in body.select("ul.source-list > li[data-source-id]")
        }
        expected_ref_titles = " | ".join(
            f"{source_id}:{normalized_visible(dom_sources[source_id].find('a'))}"
            for source_id in spec["refs"].split()
            if source_id in dom_sources
        )
        if source_row.get("reread_source_titles_current", "") != expected_ref_titles:
            issues.append(
                f"batch11-final6 {fact_id} referenced source-title snapshot differs"
            )
        if source_row.get("reread_card_current", "") != expected_card:
            issues.append(
                f"batch11-final6 {fact_id} card snapshot differs from frozen script.js"
            )
        if source_row.get("baseline_issue", "") != reread.get("contract_id", ""):
            issues.append(f"batch11-final6 {fact_id} source/contract pair differs")
        source_issue = source_row.get("reread_issue_found", "")
        for anchor in spec["issue_anchors"]:
            if anchor.casefold() not in source_issue.casefold():
                issues.append(
                    f"batch11-final6 {fact_id} source issue lacks: {anchor}"
                )
        for field, expected in (
            ("audit_decision", "PASS_FINAL6_SOURCE_MAPPING"),
            ("reread_result", "PASS_AFTER_REVISION"),
            ("verification_status", "VERIFIED_RETROSPECTIVE"),
            ("audit_accessed_at", "2026-07-24"),
            ("data_source_ref", spec["refs"]),
            ("audit_source_id", spec["refs"]),
        ):
            if source_row.get(field, "") != expected:
                issues.append(f"batch11-final6 {fact_id} source {field} differs")
        for field in (
            "resolution_action", "final_issue", "audit_final_url", "audit_title",
            "audit_locator", "audit_support_summary", "audit_relationship",
            "locatable_support", "source_roles", "source_date_audit",
        ):
            if not source_row.get(field, "").strip():
                issues.append(
                    f"batch11-final6 {fact_id} source evidence lacks {field}"
                )
        for field in ("resolution_action", "final_issue"):
            if BATCH11_FINAL6_PREFIX.rstrip(":") not in source_row.get(field, ""):
                issues.append(
                    f"batch11-final6 {fact_id} source {field} lacks batch marker"
                )
    return issues, {
        "changed_targets": len(actual_changes),
        "changed_facts": len(changed_facts),
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "source_rows": len(source_suffix),
    }


def batch11_final6_manifest(overrides=None):
    """Recompute the complete logical file set and six-file protection boundary."""
    overrides = overrides or {}
    all_records = []
    protected = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        if ".git" in relative_path.parts or path.name == ".DS_Store":
            continue
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else path.read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if batch11_final1_is_desktop_extra(relative, payload):
            continue
        record = (relative, len(payload), hashlib.sha256(payload).hexdigest())
        all_records.append(record)
        if relative not in BATCH11_FINAL6_ALLOWED_FILES:
            protected.append(record)
    protected_payload = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(protected)
    ).encode("utf-8")
    allowed_present = {
        relative for relative, _size, _digest in all_records
        if relative in BATCH11_FINAL6_ALLOWED_FILES
    }
    return all_records, protected, allowed_present, protected_payload


def audit_batch11_final6_frozen(overrides=None):
    """Authenticate all 354 files outside the exact six-file final6 scope."""
    # Replayed against the authenticated pre-batch13 bytes of the 49 revised
    # dossiers, so every digest below still runs; an explicit override wins.
    overrides = {**batch13_historical_bytes(), **(overrides or {})}
    all_records, protected, allowed_present, protected_payload = (
        batch11_final6_manifest(overrides)
    )
    issues = []
    if len(all_records) != BATCH11_FINAL6_TOTAL_FILES:
        issues.append(
            "batch11-final6 logical file count changed: "
            f"{len(all_records)} != {BATCH11_FINAL6_TOTAL_FILES}"
        )
    if allowed_present != BATCH11_FINAL6_ALLOWED_FILES:
        issues.append("batch11-final6 whitelist membership changed")
    expected_protected = len(all_records) - len(BATCH11_FINAL6_ALLOWED_FILES)
    if (
        len(protected) != expected_protected
        or len(protected) != BATCH11_FINAL6_PROTECTED_FILES
    ):
        issues.append(
            "batch11-final6 protected count mismatch: "
            f"{len(protected)} != {len(all_records)} - "
            f"{len(BATCH11_FINAL6_ALLOWED_FILES)} != "
            f"{BATCH11_FINAL6_PROTECTED_FILES}"
        )
    if hashlib.sha256(protected_payload).hexdigest() != (
        BATCH11_FINAL6_PROTECTED_SHA256
    ):
        issues.append("batch11-final6 changed, added, or removed a non-whitelist file")
    for relative, digest in BATCH11_FINAL6_FROZEN_SHA256.items():
        path = ROOT / relative
        if not path.exists() and relative not in overrides:
            issues.append(f"batch11-final6 frozen file is missing: {relative}")
            continue
        payload = overrides.get(
            relative,
            batch14_source_date_prefix_bytes()
            if relative == "tools/data/source-date-ledger.tsv"
            else path.read_bytes(),
        )
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if hashlib.sha256(payload).hexdigest() != digest:
            issues.append(f"batch11-final6 changed frozen {relative}")
    return issues


def batch11_final6_freeze_stats():
    all_records, protected, allowed_present, _payload = batch11_final6_manifest()
    return {
        "total_files": len(all_records),
        "allowed_files": len(allowed_present),
        "protected_files": len(protected),
    }


def audit_batch11_final6_wiring(source_text=None):
    source_text = source_text or Path(__file__).read_text(encoding="utf-8")
    live = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    main = re.search(
        r"def main\(\):(?P<body>.*?)(?=\nif __name__ ==)", source_text, re.S,
    )
    issues = []
    live_call = (
        "issues.extend(audit_batch11_final6(\n"
        "        final6_pages, reread_rows=final6_reread,"
    )
    self_call = (
        "batch11_final6_self_test = "
        "batch11_final6_negative_self_test(final6_pages)"
    )
    if live is None or live.group("body").count(live_call) != 1:
        issues.append("batch11-final6 authoritative audit_live wiring is absent")
    if main is None or main.group("body").count(self_call) != 1:
        issues.append("batch11-final6 named negative suite is not wired into --self-test")
    return issues


def audit_batch11_final6(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
    frozen_overrides=None, source_text=None,
):
    issues = []
    issues.extend(audit_batch11_final6_semantics(pages))
    issues.extend(audit_batch11_final6_sources(pages))
    ledger_issues, _stats = audit_batch11_final6_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    issues.extend(ledger_issues)
    issues.extend(audit_batch11_final6_frozen(frozen_overrides))
    issues.extend(audit_batch11_final6_wiring(source_text))
    return issues


def batch11_final6_negative_self_test(pages):
    """Exercise twenty-one named real DOM/attribute/ledger/freeze/wiring cases."""
    names = []
    misses = []
    semantic_baseline = audit_batch11_final6_semantics(pages)
    source_baseline = audit_batch11_final6_sources(pages)
    freeze_baseline = audit_batch11_final6_frozen()
    wiring_baseline = audit_batch11_final6_wiring()

    def record(name, caught, baseline=()):
        names.append(name)
        if baseline or not caught:
            detail = f" (baseline: {baseline[0]})" if baseline else ""
            misses.append(name + detail)

    def mutated_page():
        mutated = dict(pages)
        mutated[BATCH11_FINAL6_SLUG] = deepcopy(pages[BATCH11_FINAL6_SLUG])
        return mutated

    def mutate_text(fact_id, old, new=""):
        mutated = mutated_page()
        node = batch11_final6_target_node(mutated, fact_id)
        text = normalized_visible(node)
        if old not in text:
            return mutated, False
        batch11_final1_restore_text(node, "fact", text.replace(old, new, 1))
        return mutated, True

    # 1-2. Reinsert the two expressly rejected machine constructions.
    mutated, changed = mutate_text(
        BATCH11_FINAL6_EVIDENCE_ID, "held in chains", "held by a chain",
    )
    record(
        "01 held-by-a-chain reinsertion",
        changed and bool(audit_batch11_final6_semantics(mutated)),
        semantic_baseline,
    )
    mutated, changed = mutate_text(
        BATCH11_FINAL6_STATE_ID,
        "authorities at the county, municipal and provincial levels became "
        "involved in handling",
        "bodies entered a case",
    )
    record(
        "02 bodies-entered-a-case reinsertion",
        changed and bool(audit_batch11_final6_semantics(mutated)),
        semantic_baseline,
    )

    # 3-8. Mutate actual evidence prose, including place and attribution.
    for number, phrase, replacement, label in (
        ("03", "held in chains", "", "held-in-chains deletion"),
        ("04", "Feng County", "Another County", "Feng County relocation"),
        ("05", "Freedom House", "", "Freedom House deletion"),
        ("06", "deletion of posts", "", "post-deletion removal"),
        ("07", "restriction of accounts", "", "account-restriction removal"),
        ("08", "police interference", "", "police-interference removal"),
    ):
        mutated, changed = mutate_text(
            BATCH11_FINAL6_EVIDENCE_ID, phrase, replacement,
        )
        record(
            f"{number} {label}",
            changed and bool(audit_batch11_final6_semantics(mutated)),
            semantic_baseline,
        )

    # 9-13. Remove each level or authority class from the real state DOM.
    for number, phrase, label in (
        ("09", "county", "county-level deletion"),
        ("10", "municipal", "municipal-level deletion"),
        ("11", "provincial", "provincial-level deletion"),
        ("12", "Public-security", "public-security deletion"),
        ("13", "civil-affairs", "civil-affairs deletion"),
    ):
        mutated, changed = mutate_text(BATCH11_FINAL6_STATE_ID, phrase)
        record(
            f"{number} {label}",
            changed and bool(audit_batch11_final6_semantics(mutated)),
            semantic_baseline,
        )

    # 14. Recast the woman/citizen investigators as the handling authorities.
    caught = []
    for subject in ("The woman", "Citizen investigators"):
        mutated, changed = mutate_text(
            BATCH11_FINAL6_STATE_ID,
            "Public-security, civil-affairs and other administrative authorities",
            subject,
        )
        caught.append(
            changed and bool(audit_batch11_final6_semantics(mutated))
        )
    record("14 victim/citizen state-actor substitution", all(caught), semantic_baseline)

    # 15-16. Change each real data-source-ref attribute.
    for number, fact_id, replacement in (
        ("15", BATCH11_FINAL6_EVIDENCE_ID, "s1"),
        ("16", BATCH11_FINAL6_STATE_ID, "s2"),
    ):
        mutated = mutated_page()
        node = batch11_final6_target_node(mutated, fact_id)
        node["data-source-ref"] = replacement
        record(
            f"{number} {fact_id} data-source-ref mutation",
            bool(
                audit_batch11_final6_semantics(mutated)
                or audit_batch11_final6_sources(mutated)
            ),
            (*semantic_baseline, *source_baseline),
        )

    reread_rows, _ = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "final6 self-test reread",
    )
    contract_rows, _ = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "final6 self-test contract",
    )
    source_rows, _ = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "final6 self-test source",
    )
    # Final6 is an authenticated predecessor of final7.  Its negative suite
    # must exercise only the completed-final6 ledger view, never the seven
    # successor rows.
    reread_rows = reread_rows[:BATCH11_FINAL6_REREAD_ROWS]
    contract_rows = contract_rows[:BATCH11_FINAL6_CONTRACT_ROWS]
    source_rows = source_rows[:BATCH11_FINAL6_SOURCE_ROWS]
    ledger_baseline, _ = audit_batch11_final6_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )

    # 17. Delete either final6 row from each real append ledger.
    caught = []
    for kind in ("reread", "contract", "source"):
        for offset in (0, 1):
            changed_reread = deepcopy(reread_rows)
            changed_contract = deepcopy(contract_rows)
            changed_source = deepcopy(source_rows)
            selected, boundary = {
                "reread": (changed_reread, BATCH11_FINAL6_PRE_REREAD_ROWS),
                "contract": (changed_contract, BATCH11_FINAL6_PRE_CONTRACT_ROWS),
                "source": (changed_source, BATCH11_FINAL6_PRE_SOURCE_ROWS),
            }[kind]
            selected.pop(boundary + offset)
            found, _ = audit_batch11_final6_ledgers(
                pages, reread_rows=changed_reread, contract_rows=changed_contract,
                source_rows=changed_source,
            )
            caught.append(bool(found))
    record("17 either final6 append-row deletion", all(caught), ledger_baseline)

    # 18. Mutate every explicitly frozen non-whitelist file.
    caught = []
    for relative in BATCH11_FINAL6_FROZEN_SHA256:
        caught.append(bool(audit_batch11_final6_frozen({
            relative: (ROOT / relative).read_bytes() + b"\nfinal6 mutation",
        })))
    record("18 non-whitelist frozen-file mutation", all(caught), freeze_baseline)

    # 19. Rewrite a completed-final5 prefix row in every in-memory ledger.
    caught = []
    for kind in ("reread", "contract", "source"):
        changed_reread = deepcopy(reread_rows)
        changed_contract = deepcopy(contract_rows)
        changed_source = deepcopy(source_rows)
        selected, boundary = {
            "reread": (changed_reread, BATCH11_FINAL6_PRE_REREAD_ROWS),
            "contract": (changed_contract, BATCH11_FINAL6_PRE_CONTRACT_ROWS),
            "source": (changed_source, BATCH11_FINAL6_PRE_SOURCE_ROWS),
        }[kind]
        selected[boundary - 1][next(iter(selected[boundary - 1]))] += " tampered"
        found, _ = audit_batch11_final6_ledgers(
            pages, reread_rows=changed_reread, contract_rows=changed_contract,
            source_rows=changed_source,
        )
        caught.append(bool(found))
    record("19 completed-final5 prefix-row rewrite", all(caught), ledger_baseline)

    # 20. Mutate real source identity/type/date/URL/visible date/order.
    caught = []
    for field in ("id", "type", "date", "url", "visible-date", "order"):
        mutated = mutated_page()
        body = mutated[BATCH11_FINAL6_SLUG].select_one(
            '[data-language-body="en"]'
        )
        sources = body.select("ul.source-list > li[data-source-id]")
        source = sources[0]
        if field == "id":
            source["data-source-id"] = "s1-tampered"
        elif field == "type":
            source["data-source-type"] = "tampered-source-type"
        elif field == "date":
            source["data-source-date"] = "2099-01-01"
        elif field == "url":
            source.find("a")["href"] += "?tampered=1"
        elif field == "visible-date":
            source.find("time").string = "2099-01-01"
        else:
            source.extract()
            sources[1].insert_after(source)
        caught.append(bool(audit_batch11_final6_sources(mutated)))
    record("20 source metadata/visible-date/order mutation", all(caught), source_baseline)

    # 21. Delete both mandatory production entry points from real source text.
    source_text = Path(__file__).read_text(encoding="utf-8")
    caught = []
    for needle in (
        "    issues.extend(audit_batch11_final6(\n"
        "        final6_pages, reread_rows=final6_reread,\n",
        "        batch11_final6_self_test = "
        "batch11_final6_negative_self_test(final6_pages)\n",
    ):
        changed = source_text.replace(needle, "        # removed final6 entry\n", 1)
        caught.append(
            changed != source_text
            and bool(audit_batch11_final6_wiring(changed))
        )
    record("21 final6 audit/self-test wiring deletion", all(caught), wiring_baseline)
    if len(names) != 21 or len(set(names)) != 21:
        misses.append(
            f"batch11-final6 named suite cardinality is {len(names)}, expected 21"
        )
    return len(names) - len(misses), len(names), misses


