def batch11_final7_visible(node):
    """Canonicalize timeline tags without inventing a post-</b> space."""
    return batch11_norm("".join(node.stripped_strings)) if node else ""


def batch11_final7_canonical_text(value):
    """Remove only BeautifulSoup's synthetic gap after an ISO timeline label."""
    return re.sub(
        r"^(\d{4}-\d{2}-\d{2}[：:])\s+", r"\1", batch11_norm(value),
    )


def batch11_final7_attributes(node):
    if node is None:
        return {}
    return {
        name: " ".join(value) if isinstance(value, list) else str(value)
        for name, value in sorted(node.attrs.items())
    }


def batch11_final7_target_node(pages, target_id):
    soup = pages.get(BATCH11_FINAL7_SLUG)
    if soup is None:
        return None
    if target_id == BATCH11_FINAL7_DEK_ID:
        return soup.select_one(".article-dek .lang-en")
    body = soup.select_one('[data-language-body="en"]')
    return (
        body.select_one(f'[data-fact-id="{target_id}"]')
        if body is not None else None
    )


def batch11_final7_restore(node, target_id, text):
    """Restore final6 while retaining the exact timeline tag/direct-text shape."""
    if node is None:
        return False
    bold = node.find(["b", "strong"], recursive=False)
    if bold is None:
        node.clear()
        node.append(text)
        return True
    match = re.match(r"^(.{1,60}?(?:：|:))(.*)$", text, re.S)
    if match is None:
        return False
    bold.clear()
    bold.append(match.group(1))
    direct_text = next(
        (
            child for child in node.children
            if isinstance(child, NavigableString) and str(child).strip()
        ),
        None,
    )
    if direct_text is None:
        node.append(match.group(2))
    else:
        direct_text.replace_with(match.group(2))
    return True


def audit_batch11_final7_semantics(pages):
    """Enforce the seven handwritten final texts, meanings, refs, and attrs."""
    soup = pages.get(BATCH11_FINAL7_SLUG)
    if soup is None:
        return ["batch11-final7 Feng County page is missing"]
    issues = []
    for target_id, spec in BATCH11_FINAL7_TARGET_SPECS.items():
        if target_id == BATCH11_FINAL7_DEK_ID:
            nodes = soup.select(".article-dek .lang-en")
        else:
            nodes = soup.select(
                f'[data-language-body="en"] [data-fact-id="{target_id}"]'
            )
        if len(nodes) != 1:
            issues.append(
                f"batch11-final7 {target_id} target count is {len(nodes)}, expected 1"
            )
            continue
        node = nodes[0]
        text = batch11_final7_visible(node)
        if text != spec["new"]:
            issues.append(
                f"batch11-final7 {target_id} differs from the approved prose"
            )
        missing = batch11_final2_phrase_missing(text, spec["required"])
        if missing:
            issues.append(
                f"batch11-final7 {target_id} loses actor/action/evidence meaning: "
                f"{missing}"
            )
        for rejected in spec["forbidden"]:
            if rejected.casefold() in text.casefold():
                issues.append(
                    f"batch11-final7 {target_id} restored rejected wording: "
                    f"{rejected[:80]}"
                )
        if batch11_final7_attributes(node) != spec["attributes"]:
            issues.append(
                f"batch11-final7 {target_id} changed a protected DOM attribute"
            )
        bold = node.find(["b", "strong"], recursive=False)
        if target_id in {
            BATCH11_FINAL7_TIMELINE3_ID, BATCH11_FINAL7_TIMELINE4_ID,
        }:
            date = spec["new"].split("：", 1)[0] + "："
            if bold is None or bold.name != "b" or bold.get_text() != date:
                issues.append(
                    f"batch11-final7 {target_id} changed its <b> date structure"
                )
            direct_after = (
                bold.next_sibling
                if bold is not None and isinstance(
                    bold.next_sibling, NavigableString
                )
                else None
            )
            if (
                direct_after is None or not str(direct_after)
                or str(direct_after)[0].isspace()
            ):
                issues.append(
                    f"batch11-final7 {target_id} inserted whitespace after </b>"
                )
        elif target_id == BATCH11_FINAL7_TIMELINE1_ID and bold is not None:
            issues.append(
                "batch11-final7 timeline-1 changed its direct-text structure"
            )
    return issues


def batch11_final7_source_signature(pages):
    return batch11_final6_source_signature(pages)


def audit_batch11_final7_sources(pages):
    issues = []
    metadata, refs = batch11_final7_source_signature(pages)
    for rows, count, digest, label in (
        (
            metadata, BATCH11_FINAL7_SOURCE_METADATA_ROWS,
            BATCH11_FINAL7_SOURCE_METADATA_SHA256,
            "source ID/type/date/URL/title/visible-date/order metadata",
        ),
        (
            refs, BATCH11_FINAL7_SOURCE_REF_ROWS,
            BATCH11_FINAL7_SOURCE_REF_SHA256, "data-source-ref map",
        ),
    ):
        if len(rows) != count:
            issues.append(
                f"batch11-final7 {label} has {len(rows)} rows, expected {count}"
            )
        if hashlib.sha256("".join(rows).encode("utf-8")).hexdigest() != digest:
            issues.append(f"batch11-final7 changed frozen {label}")
    return issues


def batch11_final7_inventory(pages):
    """Enumerate all Feng public leaves with canonical text, refs, and attrs."""
    targets = {}
    issues = []
    soup = pages.get(BATCH11_FINAL7_SLUG)
    if soup is None:
        return targets, ["batch11-final7 inventory page is missing"]

    def add(key, node, refs):
        if key in targets:
            issues.append(f"batch11-final7 duplicate target: {'/'.join(key)}")
            return
        targets[key] = {
            "text": batch11_final7_visible(node),
            "source_refs": batch11_norm(refs),
            "attributes": batch11_final7_attributes(node),
        }

    for language in BATCH5_LANGS:
        body = soup.select_one(f'[data-language-body="{language}"]')
        if body is None:
            issues.append(f"batch11-final7 language body missing: {language}")
            continue
        sources = body.select("ul.source-list > li[data-source-id]")
        page_refs = "page-sources:" + " ".join(
            source.get("data-source-id", "") for source in sources
        )
        for kind, target_id, selector in (
            ("article-title", "article-title", f".article-title .lang-{language}"),
            ("article-dek", "article-dek", f".article-dek .lang-{language}"),
        ):
            node = soup.select_one(selector)
            if node is None:
                issues.append(f"batch11-final7 target missing: {language}/{target_id}")
            else:
                add(
                    (BATCH11_FINAL7_SLUG, language, kind, target_id),
                    node, page_refs,
                )
        for node in body.select("[data-fact-id]"):
            fact_id = node.get("data-fact-id", "")
            if (
                not fact_id or fact_id.endswith("-sources")
                or node.select_one("[data-fact-id]") is not None
            ):
                continue
            add(
                (BATCH11_FINAL7_SLUG, language, "fact", fact_id),
                node, node.get("data-source-ref", ""),
            )
        for source in sources:
            source_id = source.get("data-source-id", "")
            anchor = source.find("a")
            label = source.find("b")
            if not source_id or anchor is None or label is None:
                issues.append(f"batch11-final7 malformed source: {language}")
                continue
            add(
                (
                    BATCH11_FINAL7_SLUG, language, "source-title",
                    f"source-title:{source_id}",
                ),
                anchor, source_id,
            )
            add(
                (
                    BATCH11_FINAL7_SLUG, language, "source-category",
                    f"source-category:{source_id}",
                ),
                label, source_id,
            )
    return targets, issues


def batch11_final7_historical_state(
    live_pages=None, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Authenticate and reconstruct the exact completed-final6 predecessor."""
    disk_reread, reread_issues = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch11-final7 reread ledger",
    )
    disk_contract, contract_issues = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch11-final7 contract ledger",
    )
    disk_source, source_issues = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch11-final7 source ledger",
    )
    if reread_rows is None:
        reread_rows = disk_reread
    if contract_rows is None:
        contract_rows = disk_contract
    if source_rows is None:
        source_rows = disk_source
    issues = [*reread_issues, *contract_issues, *source_issues]
    for path, count, digest, label in (
        (
            BATCH9_REREAD_PATH, BATCH11_FINAL7_PRE_REREAD_ROWS,
            BATCH11_FINAL7_PRE_REREAD_SHA256,
            "batch11-final7 completed-final6 reread prefix",
        ),
        (
            BATCH9_CONTRACT_PATH, BATCH11_FINAL7_PRE_CONTRACT_ROWS,
            BATCH11_FINAL7_PRE_CONTRACT_SHA256,
            "batch11-final7 completed-final6 contract prefix",
        ),
        (
            BATCH9_SOURCE_LEDGER_PATH, BATCH11_FINAL7_PRE_SOURCE_ROWS,
            BATCH11_FINAL7_PRE_SOURCE_SHA256,
            "batch11-final7 completed-final6 source prefix",
        ),
    ):
        issues.extend(batch9_final2_exact_prefix(path, count, digest, label))
    source_date = ROOT / "tools/data/source-date-ledger.tsv"
    if not source_date.exists():
        issues.append("batch11-final7 frozen source-date ledger is missing")
    else:
        payload = batch14_source_date_prefix_bytes()
        if hashlib.sha256(payload).hexdigest() != BATCH11_FINAL7_SOURCE_DATE_SHA256:
            issues.append("batch11-final7 source-date ledger bytes changed")
        try:
            date_rows = list(csv.DictReader(
                io.StringIO(payload.decode("utf-8")), delimiter="\t",
            ))
        except UnicodeDecodeError:
            date_rows = []
            issues.append("batch11-final7 source-date ledger is not UTF-8")
        if len(date_rows) != BATCH11_FINAL7_SOURCE_DATE_ROWS:
            issues.append(
                "batch11-final7 source-date ledger has "
                f"{len(date_rows)} rows, expected {BATCH11_FINAL7_SOURCE_DATE_ROWS}"
            )
    if live_pages is None:
        live_pages = {
            BATCH11_FINAL7_SLUG: BeautifulSoup(
                (ROOT / "posts" / f"{BATCH11_FINAL7_SLUG}.html").read_text(
                    encoding="utf-8"
                ),
                "html.parser",
            )
        }
    predecessor = dict(live_pages)
    if BATCH11_FINAL7_SLUG in live_pages:
        predecessor[BATCH11_FINAL7_SLUG] = deepcopy(
            live_pages[BATCH11_FINAL7_SLUG]
        )
    restored = set()
    for target_id, spec in BATCH11_FINAL7_TARGET_SPECS.items():
        node = batch11_final7_target_node(predecessor, target_id)
        if not batch11_final7_restore(node, target_id, spec["old"]):
            issues.append(f"batch11-final7 cannot restore target: {target_id}")
        else:
            restored.add(spec["target"])
    if restored != BATCH11_FINAL7_TARGETS:
        issues.append("batch11-final7 cannot reconstruct all seven final6 targets")
    pre_soup = predecessor.get(BATCH11_FINAL7_SLUG)
    if pre_soup is not None:
        digest = hashlib.sha256(batch11_final1_page_payload(pre_soup)).hexdigest()
        if digest != BATCH11_FINAL7_PRE_PAGE_SHA256:
            issues.append(
                "batch11-final7 completed-final6 Feng page did not reconstruct"
            )
    return (
        predecessor,
        disk_reread[:BATCH11_FINAL7_PRE_REREAD_ROWS],
        disk_contract[:BATCH11_FINAL7_PRE_CONTRACT_ROWS],
        disk_source[:BATCH11_FINAL7_PRE_SOURCE_ROWS],
        issues,
    )


