    def replace_final2_phrase(soup, slug, language, target_id, old, new, *, sync_critical=True):
        node = fact(soup, slug, language, target_id)
        if node is None:
            raise AssertionError("target node missing")
        holder = node.select_one("[data-critical-case]") or node
        visible = normalized_visible(holder)
        if old not in visible:
            raise AssertionError(f"mutation source absent: {old}")
        holder.clear()
        holder.append(visible.replace(old, new, 1))
        if sync_critical and holder.has_attr("data-critical-case"):
            anchor = holder.get("data-critical-case", "")
            if old in anchor:
                holder["data-critical-case"] = anchor.replace(old, new, 1)

    def replace_final2_first_sentence(soup, language, replacement):
        node = fact(soup, "hong-kong-nsl", language, "hong-kong-nsl-rights-analysis")
        holder = node.select_one("[data-critical-case]") if node else None
        if holder is None:
            raise AssertionError("critical target missing")
        anchor = " ".join(holder.get("data-critical-case", "").split())
        visible = normalized_visible(holder)
        if not anchor or not visible.startswith(anchor):
            raise AssertionError("critical first sentence is not aligned")
        holder.clear()
        holder.append(replacement + visible[len(anchor):])
        holder["data-critical-case"] = replacement

