def _batch12_static_literal_maps():
    semantic = {}
    targets = {}
    issues = []
    for line_number, line in enumerate(
        BATCH12_STATIC_SEMANTIC_RULE_DATA.splitlines(), 1
    ):
        if not line.strip():
            continue
        try:
            slug, target_id, required = json.loads(line)
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            issues.append(
                f"batch12 static semantic literal line {line_number} "
                f"cannot be parsed: {exc}"
            )
            continue
        key = (slug, target_id)
        if key in semantic:
            issues.append(f"batch12 static semantic literal duplicates {key!r}")
        semantic[key] = tuple(required)
    for line_number, line in enumerate(
        BATCH12_STATIC_TARGET_RULE_DATA.splitlines(), 1
    ):
        if not line.strip():
            continue
        try:
            (
                slug, language, target_id, source_ref, text_sha256,
                anchors, forbidden,
            ) = json.loads(line)
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            issues.append(
                f"batch12 static target literal line {line_number} "
                f"cannot be parsed: {exc}"
            )
            continue
        key = (slug, language, target_id)
        if key in targets:
            issues.append(f"batch12 static target literal duplicates {key!r}")
        targets[key] = {
            "source_ref": source_ref,
            "text_sha256": text_sha256,
            "anchors": tuple(anchors),
            "forbidden": tuple(forbidden),
        }
    return semantic, targets, tuple(issues)


(
    BATCH12_STATIC_SEMANTIC_RULES,
    BATCH12_STATIC_TARGET_RULES,
    BATCH12_STATIC_LITERAL_ISSUES,
) = _batch12_static_literal_maps()



def batch12_text(node):
    return batch11_norm(" ".join(node.stripped_strings)) if node else ""


def batch12_language_pattern(concept, language):
    index = BATCH5_LANGS.index(language)
    return BATCH12_CONCEPT_PATTERNS[concept][index]


def batch12_target_node(pages, slug, language, target_id):
    soup = pages.get(slug)
    body = (
        soup.select_one(f'[data-language-body="{language}"]')
        if soup is not None else None
    )
    return (
        body.select_one(f'[data-fact-id="{target_id}"]')
        if body is not None else None
    )


def audit_batch12_static_targets(pages):
    """Validate all 567 reviewed targets against module-owned answers."""
    issues = list(BATCH12_STATIC_LITERAL_ISSUES)
    expected_keys = BATCH12_EXPECTED_LEDGER_KEYS
    actual_keys = frozenset(BATCH12_STATIC_TARGET_RULES)
    if actual_keys != expected_keys:
        issues.append(
            "batch12 static target-rule coverage differs: "
            f"{len(expected_keys - actual_keys)} missing, "
            f"{len(actual_keys - expected_keys)} extra"
        )
    expected_semantic_keys = {
        (slug, target_id)
        for slug, _language, target_id in expected_keys
    }
    actual_semantic_keys = frozenset(BATCH12_STATIC_SEMANTIC_RULES)
    if actual_semantic_keys != expected_semantic_keys:
        issues.append(
            "batch12 static semantic-rule coverage differs: "
            f"{len(expected_semantic_keys - actual_semantic_keys)} missing, "
            f"{len(actual_semantic_keys - expected_semantic_keys)} extra"
        )
    for semantic_key, required in BATCH12_STATIC_SEMANTIC_RULES.items():
        if len(required) < 4 or len(set(required)) < 4:
            issues.append(
                f"batch12 static semantic rule {semantic_key!r} has fewer "
                "than four independent meanings"
            )
        if any(not meaning.strip() for meaning in required):
            issues.append(
                f"batch12 static semantic rule {semantic_key!r} has a blank "
                "meaning"
            )
    for key, rule in BATCH12_STATIC_TARGET_RULES.items():
        slug, language, target_id = key
        if (slug, target_id) not in BATCH12_STATIC_SEMANTIC_RULES:
            issues.append(f"batch12 static target {key!r} lacks semantics")
        live = batch12_live_target_text(pages, *key)
        if hashlib.sha256(live.encode("utf-8")).hexdigest() != (
            rule["text_sha256"]
        ):
            issues.append(
                f"batch12 static target {key!r} differs from the independently "
                "reviewed localized text"
            )
        anchors = rule["anchors"]
        if len(anchors) < 4 or len(set(anchors)) < 4:
            issues.append(
                f"batch12 static target {key!r} has fewer than four localized "
                "anchors"
            )
        for anchor in anchors:
            if not anchor or anchor not in live:
                issues.append(
                    f"batch12 static target {key!r} lacks localized anchor: "
                    f"{anchor}"
                )
        forbidden = rule["forbidden"]
        if len(forbidden) < 2 or len(set(forbidden)) < 2:
            issues.append(
                f"batch12 static target {key!r} has fewer than two genuine "
                "old errors"
            )
        for old_error in forbidden:
            if old_error and old_error.casefold() in live.casefold():
                issues.append(
                    f"batch12 static target {key!r} restored old error: "
                    f"{old_error}"
                )
        expected_ref = rule["source_ref"]
        if target_id == "article-dek" or target_id.startswith("source-entry:"):
            if expected_ref:
                issues.append(
                    f"batch12 static non-fact target {key!r} unexpectedly "
                    "declares a source-ref"
                )
            continue
        node = batch12_target_node(pages, slug, language, target_id)
        actual_ref = (
            " ".join(node.get("data-source-ref", "").split())
            if node is not None else ""
        )
        if actual_ref != expected_ref:
            issues.append(
                f"batch12 static target {key!r} source-ref {actual_ref!r} "
                f"!= {expected_ref!r}"
            )
    return issues


def batch12_all_source_refs(pages):
    rows = []
    for slug in BATCH12_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                continue
            for node in body.select("[data-fact-id][data-source-ref]"):
                rows.append(json.dumps(
                    [
                        slug, language, node.get("data-fact-id", ""),
                        node.get("data-source-ref", ""),
                    ],
                    ensure_ascii=False, separators=(",", ":"),
                ))
    return rows


def batch12_all_timeline_attrs(pages):
    """Serialize the reviewed order and six semantic attrs of every event."""
    rows = []
    for slug in BATCH12_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                continue
            for index, node in enumerate(body.select("ol.timeline-list > li")):
                rows.append(json.dumps(
                    [
                        slug, language, index,
                        node.get("data-fact-id", ""),
                        node.get("data-source-ref", ""),
                        node.get("data-timeline-date", ""),
                        node.get("data-timeline-subject", ""),
                        node.get("data-timeline-action", ""),
                        node.get("data-timeline-consequence", ""),
                    ],
                    ensure_ascii=False, separators=(",", ":"),
                ))
    return rows


def audit_batch12_pages(pages):
    issues = []
    for slug in BATCH12_SLUGS:
        soup = pages.get(slug)
        if soup is None:
            issues.append(f"batch12/{slug}: target page missing")
            continue
        article = soup.select_one("article")
        public_text = batch12_text(article)
        for phrase in BATCH12_PUBLIC_FORBIDDEN:
            if phrase.casefold() in public_text.casefold():
                issues.append(
                    f"batch12/{slug}: rejected public wording present: {phrase}"
                )
        bodies = soup.select("[data-language-body]")
        body_languages = [body.get("data-language-body", "") for body in bodies]
        if (
            len(body_languages) != len(BATCH5_LANGS)
            or set(body_languages) != set(BATCH5_LANGS)
        ):
            issues.append(
                f"batch12/{slug}: language-body order/inventory differs: "
                f"{body_languages!r}"
            )
        for language in BATCH5_LANGS:
            matching = soup.select(f'[data-language-body="{language}"]')
            if len(matching) != 1:
                issues.append(
                    f"batch12/{slug}/{language}: language body count is "
                    f"{len(matching)}, expected 1"
                )
                continue
            body = matching[0]
            localized_text = batch12_text(body)
            for pattern in BATCH12_LOCALIZED_META_PATTERNS[language]:
                if re.search(pattern, localized_text, flags=re.IGNORECASE):
                    issues.append(
                        f"batch12/{slug}/{language}: localized editorial "
                        f"meta-language remains: {pattern}"
                    )
            sections = tuple(
                heading.get("data-section", "")
                for heading in body.select("h2")
                if heading.get("data-section") in BATCH12_CORE_SECTIONS
            )
            if sections != BATCH12_CORE_SECTIONS:
                issues.append(
                    f"batch12/{slug}/{language}: seven-section order differs: "
                    f"{sections!r}"
                )
            extras = tuple(
                heading.get("data-section", "")
                for heading in body.select("h2")
                if heading.get("data-section") not in BATCH12_CORE_SECTIONS
            )
            if any(extra != "unresolved-questions" for extra in extras):
                issues.append(
                    f"batch12/{slug}/{language}: unapproved extra section {extras!r}"
                )
            if any(len(batch12_text(heading)) < 2 for heading in body.select("h2")):
                issues.append(
                    f"batch12/{slug}/{language}: localized section heading missing"
                )
            for heading in body.select("h2[data-section]"):
                section = heading.get("data-section", "")
                if section not in BATCH12_CORE_SECTIONS:
                    continue
                segment = []
                sibling = heading.find_next_sibling()
                while sibling is not None and sibling.name != "h2":
                    segment.append(sibling)
                    sibling = sibling.find_next_sibling()
                segment_text = batch11_norm(
                    " ".join(batch12_text(node) for node in segment)
                )
                if not segment or not segment_text:
                    issues.append(
                        f"batch12/{slug}/{language}: {section} section is empty"
                    )
                    continue
                if section == "timeline":
                    events = [
                        event for node in segment
                        for event in (
                            [node] if node.name == "li" else
                            node.select("ol.timeline-list > li")
                        )
                    ]
                    if not events or any(
                        not event.get("data-fact-id", "")
                        or not event.get("data-source-ref", "")
                        or not event.get("data-timeline-subject", "")
                        or not event.get("data-timeline-action", "")
                        or not event.get("data-timeline-consequence", "")
                        for event in events
                    ):
                        issues.append(
                            f"batch12/{slug}/{language}: timeline lacks a "
                            "reviewed actor/action/consequence/source tuple"
                        )
                elif section == "sources":
                    if not any(
                        node.select("ul.source-list > li[data-source-id]")
                        for node in segment
                    ):
                        issues.append(
                            f"batch12/{slug}/{language}: source section is empty"
                        )
                else:
                    facts = []
                    for node in segment:
                        if node.has_attr("data-fact-id"):
                            facts.append(node)
                        facts.extend(node.select("[data-fact-id]"))
                    if not facts or any(
                        len(batch12_text(fact)) < 10
                        or not fact.get("data-source-ref", "")
                        for fact in facts
                    ):
                        issues.append(
                            f"batch12/{slug}/{language}: {section} lacks a "
                            "substantive fact/source chain"
                        )
            text = localized_text
            digits = compact_digits(text)
            for number in BATCH12_PAGE_REQUIRED_NUMBERS[slug]:
                if compact_digits(number) not in digits:
                    issues.append(
                        f"batch12/{slug}/{language}: required fact number "
                        f"missing: {number}"
                    )
            for concept in BATCH12_PAGE_CONCEPTS[slug]:
                if not re.search(
                    batch12_language_pattern(concept, language),
                    text, flags=re.IGNORECASE,
                ):
                    issues.append(
                        f"batch12/{slug}/{language}: page actor/action/remedy "
                        f"concept missing: {concept}"
                    )
            if language != "zh" and "線下" in text:
                issues.append(
                    f"batch12/{slug}/{language}: Chinese 線下 remains in a "
                    "non-Chinese block"
                )
            for kind in ("rights-analysis", "protection"):
                nodes = body.select(
                    f'[data-fact-id="{slug}-{kind}"], '
                    f'[data-fact-id="{slug}-state-machinery-{kind}"]'
                )
                if not nodes:
                    nodes = [
                        node for node in body.select("[data-fact-id]")
                        if node.get("data-fact-id", "").endswith(f"-{kind}")
                    ]
                if len(nodes) != 1:
                    issues.append(
                        f"batch12/{slug}/{language}: {kind} node count is "
                        f"{len(nodes)}, expected 1"
                    )
                    continue
                node = nodes[0]
                span = node.find(
                    "span", attrs={"data-critical-case": True}, recursive=False,
                )
                if span is None:
                    issues.append(
                        f"batch12/{slug}/{language}: {kind} lacks "
                        "data-critical-case"
                    )
                    continue
                visible = batch12_text(span)
                first = batch11_final1_first_sentence(visible)
                critical = batch11_norm(span.get("data-critical-case", ""))
                if not critical or critical != first:
                    issues.append(
                        f"batch12/{slug}/{language}: {kind} data-critical-case "
                        "does not equal the visible first sentence"
                    )

    for (slug, target_id), expected_ref in BATCH12_TARGET_REFS.items():
        for language in BATCH5_LANGS:
            node = batch12_target_node(pages, slug, language, target_id)
            if node is None:
                issues.append(
                    f"batch12/{slug}/{language}/{target_id}: target missing"
                )
                continue
            actual_ref = " ".join(node.get("data-source-ref", "").split())
            if actual_ref != expected_ref:
                issues.append(
                    f"batch12/{slug}/{language}/{target_id}: source-ref "
                    f"{actual_ref!r} != {expected_ref!r}"
                )
    for (slug, target_id), phrases in BATCH12_ENGLISH_RULES.items():
        node = batch12_target_node(pages, slug, "en", target_id)
        text = batch12_text(node)
        for phrase in phrases:
            if phrase.casefold() not in text.casefold():
                issues.append(
                    f"batch12/{slug}/en/{target_id}: independent meaning "
                    f"missing: {phrase}"
                )

    # Case-specific errors that a broad public scan must not over-generalize.
    henan = batch12_target_node(
        pages, "henan-bank-depositor-protests", "en",
        "henan-bank-depositor-protests-state-2",
    )
    if henan is not None and re.search(
        r"\bplainclothes\b(?!\s+(?:or\s+white-clad\s+)?personnel)",
        batch12_text(henan), flags=re.IGNORECASE,
    ):
        issues.append("batch12/Henan/en: plainclothes lacks a personnel subject")
    for language, bad in (
        ("de", r"(?:^|\W)Zivil(?:\W|$)"),
        ("fr", r"\bles civils\b"),
        ("nl", r"\bde burgerkleding\b"),
    ):
        node = batch12_target_node(
            pages, "henan-bank-depositor-protests", language,
            "henan-bank-depositor-protests-state-2",
        )
        if node is not None and re.search(bad, batch12_text(node), re.I):
            issues.append(
                f"batch12/Henan/{language}: isolated plainclothes mistranslation"
            )
    terminus = batch12_target_node(
        pages, "terminus2049-chen-mei-cai-wei", "en",
        "terminus2049-chen-mei-cai-wei-evidence-1",
    )
    if terminus is not None and re.search(
        r"GitHub.{0,40}(?:detention|RSDL|sentenc|release)",
        batch12_text(terminus), flags=re.I,
    ):
        issues.append(
            "batch12/Terminus/en: GitHub was assigned detention or sentencing facts"
        )
    zhang_en = batch12_text(
        pages.get("zhang-zhan").select_one('[data-language-body="en"]')
        if pages.get("zhang-zhan") is not None else None
    )
    if re.search(r"\b(?:he|him|his)\b", zhang_en, flags=re.I):
        issues.append("batch12/Zhang/en: male pronoun applied to Zhang Zhan")
    zhang_ko = batch12_text(
        pages.get("zhang-zhan").select_one('[data-language-body="ko"]')
        if pages.get("zhang-zhan") is not None else None
    )
    if re.search(r"(?:그는|그가|그의|남성)", zhang_ko):
        issues.append("batch12/Zhang/ko: male reference applied to Zhang Zhan")
    tnr26_ja = batch12_text(
        pages.get("transnational-repression-2026").select_one(
            '[data-language-body="ja"]'
        ) if pages.get("transnational-repression-2026") is not None else None
    )
    if "中国公安省" in tnr26_ja:
        issues.append("batch12/TNR2026/ja: 中国公安省 mistranslation returned")
    tnr26_en = batch12_text(
        batch12_target_node(
            pages, "transnational-repression-2026", "en",
            "transnational-repression-2026-state-machinery-1",
        )
    )
    if "technical evidence to attribute" not in tnr26_en:
        issues.append(
            "batch12/TNR2026/en: UK technical attribution was weakened"
        )

    ref_rows = batch12_all_source_refs(pages)
    digest = hashlib.sha256("\n".join(ref_rows).encode("utf-8")).hexdigest()
    if len(ref_rows) != BATCH12_ALL_SOURCE_REF_ROWS:
        issues.append(
            f"batch12 source-ref inventory is {len(ref_rows)}, expected "
            f"{BATCH12_ALL_SOURCE_REF_ROWS}"
        )
    if digest != BATCH12_ALL_SOURCE_REF_SHA256:
        issues.append("batch12 changed a reviewed fact/source relationship")
    timeline_rows = batch12_all_timeline_attrs(pages)
    timeline_digest = hashlib.sha256(
        "\n".join(timeline_rows).encode("utf-8")
    ).hexdigest()
    if len(timeline_rows) != BATCH12_ALL_TIMELINE_ATTR_ROWS:
        issues.append(
            f"batch12 timeline attribute inventory is {len(timeline_rows)}, "
            f"expected {BATCH12_ALL_TIMELINE_ATTR_ROWS}"
        )
    if timeline_digest != BATCH12_ALL_TIMELINE_ATTR_SHA256:
        issues.append("batch12 changed reviewed timeline order or attributes")
    issues.extend(audit_batch12_tnr_timeline(pages))
    issues.extend(audit_batch12_static_targets(pages))
    return issues


def audit_batch12_tnr_timeline(pages):
    issues = []
    soup = pages.get("transnational-repression")
    if soup is None:
        return ["batch12/TNR: page missing"]
    for language in BATCH5_LANGS:
        body = soup.select_one(f'[data-language-body="{language}"]')
        if body is None:
            continue
        nodes = body.select("ol.timeline-list > li")
        if [node.get("data-fact-id", "") for node in nodes] != [
            spec[0] for spec in BATCH12_TNR_TIMELINE
        ]:
            issues.append(
                f"batch12/TNR/{language}: seven-event timeline order differs"
            )
            continue
        for index, (node, spec) in enumerate(
            zip(nodes, BATCH12_TNR_TIMELINE)
        ):
            fact_id, ref, date, subject, action, consequence = spec
            expected = {
                "data-fact-id": fact_id,
                "data-source-ref": ref,
                "data-timeline-date": date,
                "data-timeline-subject": subject,
                "data-timeline-action": action,
                "data-timeline-consequence": consequence,
            }
            for attribute, value in expected.items():
                if " ".join(node.get(attribute, "").split()) != value:
                    issues.append(
                        f"batch12/TNR/{language}/{fact_id}: {attribute} differs"
                    )
            bold = node.find("b", recursive=False)
            if index < 2:
                visible_date = BATCH12_TNR_VISIBLE_DATES[language][index]
            else:
                visible_date = date + "："
            if bold is None or bold.get_text(strip=True) != visible_date:
                issues.append(
                    f"batch12/TNR/{language}/{fact_id}: visible date differs"
                )
    english_rules = {
        "transnational-repression-timeline-1": (
            "Mid-October 2015", "Gui Minhai", "Thailand",
            "five booksellers", "cross-border abduction",
        ),
        "transnational-repression-timeline-2": (
            "Early 2017", "Freedom House’s 2025 Canada case study",
            "retrospectively", "Amnesty International Canada",
        ),
        "transnational-repression-timeline-3": (
            "2020-06-30", "Article 38", "extraterritorial application",
            "political expression abroad",
        ),
        "transnational-repression-timeline-4": (
            "2021-02-04", "first global survey", "608", "since 2014",
            "proxy coercion", "passport controls", "digital threats",
        ),
        "transnational-repression-timeline-5": (
            "superseding indictment", "nine defendants", "illegal agents",
            "interstate and international stalking", "Operation Fox Hunt",
            "Chinese prosecutor", "evidence was destroyed",
        ),
        "transnational-repression-timeline-6": (
            "The U.S. Department of Justice", "two New York residents",
            "Lower Manhattan", "Fuzhou branch",
            "locate a dissident", "deleting communications",
        ),
        "transnational-repression-timeline-7": (
            "2025-05-29", "surveillance", "intimidation of relatives",
            "punitive denial of consular services", "Hogue inquiry",
        ),
    }
    for fact_id, required in english_rules.items():
        text = batch12_text(
            batch12_target_node(
                pages, "transnational-repression", "en", fact_id,
            )
        )
        for phrase in required:
            if phrase.casefold() not in text.casefold():
                issues.append(
                    f"batch12/TNR/en/{fact_id}: timeline fact missing: {phrase}"
                )
        if re.search(r"\b(?:convicted|found guilty)\b", text, flags=re.I):
            issues.append(
                f"batch12/TNR/en/{fact_id}: DOJ allegation upgraded to conviction"
            )
    return issues


def audit_batch12_sources(pages):
    issues = []
    metadata_rows = 0
    for slug, expected in BATCH12_SOURCE_SIGNATURES.items():
        soup = pages.get(slug)
        if soup is None:
            continue
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            sources = (
                body.select("ul.source-list > li[data-source-id]")
                if body is not None else []
            )
            actual = []
            for source in sources:
                anchor = source.find("a")
                actual.append((
                    source.get("data-source-id", ""),
                    source.get("data-source-type", ""),
                    source.get("data-source-date", ""),
                    anchor.get("href", "") if anchor else "",
                ))
                date = source.get("data-source-date", "")
                time = source.find("time")
                if date:
                    if (
                        time is None
                        or time.get("datetime", "") != date
                        or batch12_text(time) != date
                    ):
                        issues.append(
                            f"batch12/{slug}/{language}/"
                            f"{source.get('data-source-id', '')}: visible date differs"
                        )
                elif time is not None:
                    issues.append(
                        f"batch12/{slug}/{language}/"
                        f"{source.get('data-source-id', '')}: undated source gained time"
                    )
            metadata_rows += len(actual)
            if tuple(actual) != expected:
                issues.append(
                    f"batch12/{slug}/{language}: source id/type/date/URL/order "
                    "contract differs"
                )
    if BATCH12_SOURCE_COUNT != 59 or metadata_rows != 590:
        issues.append(
            f"batch12 source contract count is {metadata_rows}/590 "
            f"({BATCH12_SOURCE_COUNT} identities expected)"
        )

    tnr = pages.get("transnational-repression")
    if tnr is not None:
        title_required = {
            "zh": {"s2": "釋放", "s5": "替代起訴書", "s6": "非法海外警務站"},
            "en": {
                "s1": "Freedom House — New Report: Transnational Repression Is a Growing Threat to Global Democracy",
                "s2": "Free “Disappeared” Booksellers",
                "s5": "Superseding Indictment", "s6": "Illegal Overseas Police Station",
            },
            "ja": {"s2": "釈放", "s5": "追加起訴", "s6": "違法な海外警察拠点"},
            "ko": {"s2": "석방", "s5": "추가 기소", "s6": "불법 해외 경찰 거점"},
            "es": {"s2": "liberen", "s5": "Acusación sustitutiva", "s6": "comisaría ilegal"},
            "de": {"s2": "freilassen", "s5": "Erweiterte Anklageschrift", "s6": "illegalen Auslandspolizeistation"},
            "fr": {"s2": "libérer", "s5": "Acte d’accusation supplétif", "s6": "poste de police illégal"},
            "no": {"s2": "Løslat", "s5": "Utvidet tiltale", "s6": "ulovlig kinesisk politistasjon"},
            "nl": {"s2": "vrij", "s5": "Vervangende aanklacht", "s6": "illegaal buitenlands politiebureau"},
            "it": {"s2": "liberare", "s5": "Atto d’accusa sostitutivo", "s6": "stazione illegale di polizia"},
        }
        wrong_free = {
            "ja": r"無料", "ko": r"무료", "es": r"\bgratis\b",
            "de": r"kostenlos", "fr": r"gratuit", "no": r"\bgratis\b",
            "nl": r"\bgratis\b", "it": r"gratuit",
        }
        for language, source_rules in title_required.items():
            body = tnr.select_one(f'[data-language-body="{language}"]')
            for source_id, phrase in source_rules.items():
                node = (
                    body.select_one(f'[data-source-id="{source_id}"] a')
                    if body is not None else None
                )
                title = batch12_text(node)
                if phrase.casefold() not in title.casefold():
                    issues.append(
                        f"batch12/TNR/{language}/{source_id}: localized source "
                        f"title meaning missing: {phrase}"
                    )
            if language in wrong_free:
                s2 = body.select_one('[data-source-id="s2"] a') if body else None
                if s2 is not None and re.search(
                    wrong_free[language], batch12_text(s2), re.I,
                ):
                    issues.append(
                        f"batch12/TNR/{language}/s2: release mistranslated as free"
                    )
    return issues

