def batch12_card_payload(cards, *, non_target=True):
    rows = []
    for index, card in enumerate(cards):
        if (card.get("slug", "") not in BATCH12_CARD_SLUGS) != non_target:
            continue
        for field in BATCH9_FINAL2_CARD_FIELDS:
            rows.append((
                str(index), card.get("slug", ""), field, card.get(field, ""),
            ))
    return "\x1e".join("\x1f".join(row) for row in rows).encode("utf-8"), rows


def audit_batch12_cards(script_text=None, delta_rows=None):
    issues = []
    cards, card_issues = batch9_final2_report_cards(script_text)
    cards = batch14_baseline_card_view(cards)
    issues.extend(
        issue.replace("final2", "batch12") for issue in card_issues
    )
    payload, non_target_rows = batch12_card_payload(cards, non_target=True)
    if len(non_target_rows) != BATCH12_NON_TARGET_CARD_FIELDS:
        issues.append(
            f"batch12 non-target card inventory is {len(non_target_rows)}, "
            f"expected {BATCH12_NON_TARGET_CARD_FIELDS}"
        )
    if hashlib.sha256(payload).hexdigest() != BATCH12_NON_TARGET_CARD_SHA256:
        issues.append("batch12 changed one of the 49 frozen report cards")
    by_slug = {card.get("slug", ""): card for card in cards}
    for slug, (expected_date, expected_url) in BATCH12_CARD_DATE_URL.items():
        card = by_slug.get(slug)
        if card is None:
            issues.append(f"batch12 card missing: {slug}")
            continue
        if card.get("date", "") != expected_date:
            issues.append(f"batch12 card date changed: {slug}")
        if card.get("url", "") != expected_url:
            issues.append(f"batch12 card URL changed: {slug}")
        english = ""
        for language in BATCH5_LANGS:
            title = card.get(f"title_{language}", "")
            excerpt = card.get(f"excerpt_{language}", "")
            combined = f"{title} {excerpt}".strip()
            if not title or len(excerpt) < 80:
                issues.append(
                    f"batch12 card {slug}/{language}: title or fact chain too short"
                )
            if language == "en":
                english = combined
            elif combined == english:
                issues.append(
                    f"batch12 card {slug}/{language}: English fallback remains"
                )
            for phrase in BATCH12_PUBLIC_FORBIDDEN:
                if phrase.casefold() in combined.casefold():
                    issues.append(
                        f"batch12 card {slug}/{language}: rejected wording "
                        f"present: {phrase}"
                    )
            for concept in BATCH12_CARD_CONCEPTS[slug]:
                if not re.search(
                    batch12_language_pattern(concept, language),
                    combined, flags=re.I,
                ):
                    issues.append(
                        f"batch12 card {slug}/{language}: fact-chain concept "
                        f"missing: {concept}"
                    )
            name_pattern = BATCH12_CARD_NAMES[slug][
                BATCH5_LANGS.index(language)
            ]
            if not re.search(name_pattern, combined, flags=re.I):
                issues.append(
                    f"batch12 card {slug}/{language}: case subject missing"
                )
            digits = compact_digits(combined)
            for number in BATCH12_CARD_REQUIRED_NUMBERS[slug]:
                if compact_digits(number) not in digits:
                    issues.append(
                        f"batch12 card {slug}/{language}: required number "
                        f"missing: {number}"
                    )
    if delta_rows is None:
        delta_rows, delta_issues = batch9_final2_load_tsv(
            BATCH12_CARD_DELTA_PATH, BATCH12_CARD_DELTA_COLUMNS,
            "batch12 card delta",
        )
        issues.extend(delta_issues)
    if len(delta_rows) != 54 * len(BATCH9_FINAL2_CARD_FIELDS):
        issues.append(
            f"batch12 card delta has {len(delta_rows)} rows, expected "
            f"{54 * len(BATCH9_FINAL2_CARD_FIELDS)}"
        )
    keyed = {}
    changed = 0
    frozen_target = 0
    non_target = 0
    expected_keys = {
        (card.get("slug", ""), field)
        for card in cards
        for field in BATCH9_FINAL2_CARD_FIELDS
    }
    card_positions = {
        card.get("slug", ""): str(index)
        for index, card in enumerate(cards, 1)
    }
    for row in delta_rows:
        key = (row.get("slug", ""), row.get("field", ""))
        if key in keyed:
            issues.append(f"batch12 card delta duplicates {key!r}")
        keyed[key] = row
        before = row.get("before_value", "")
        after = row.get("after_value", "")
        flag = row.get("changed", "")
        scope = row.get("scope", "")
        should_change = before != after
        if (flag == "YES") != should_change:
            issues.append(f"batch12 card delta change flag differs: {key!r}")
        expected_scope = (
            "target" if row.get("slug", "") in BATCH12_CARD_SLUGS
            else "non-target"
        )
        if scope != expected_scope:
            issues.append(f"batch12 card delta scope differs: {key!r}")
        if row.get("card_index", "") != card_positions.get(
            row.get("slug", ""), ""
        ):
            issues.append(f"batch12 card delta index differs: {key!r}")
        expected_integrity = (
            "PASS_CHANGED" if should_change else "PASS_UNCHANGED"
        )
        if row.get("integrity_result", "") != expected_integrity:
            issues.append(f"batch12 card delta integrity result differs: {key!r}")
        if row.get("batch_tag", "") != BATCH12_PREFIX:
            issues.append(f"batch12 card delta tag differs: {key!r}")
        card = by_slug.get(row.get("slug", ""))
        if card is not None and after != card.get(row.get("field", ""), ""):
            issues.append(f"batch12 card delta live value differs: {key!r}")
        if scope == "target" and should_change:
            changed += 1
        elif scope == "target":
            frozen_target += 1
        else:
            non_target += 1
            if should_change:
                issues.append(
                    f"batch12 non-target card delta changed {key!r}"
                )
    if frozenset(keyed) != frozenset(expected_keys):
        issues.append("batch12 card delta 54-card/23-field coverage differs")
    if (changed, frozen_target, non_target) != (100, 15, 1127):
        issues.append(
            "batch12 card delta counts differ: "
            f"{changed}/100 changed, {frozen_target}/15 target-frozen, "
            f"{non_target}/1127 non-target"
        )
    return issues


def batch12_expected_ledger_keys():
    keys = {
        (slug, language, target_id)
        for slug, target_id in BATCH12_TARGET_REFS
        if target_id != "transnational-repression-sources"
        for language in BATCH5_LANGS
    }
    keys.update(
        (slug, language, "article-dek")
        for slug in (
            "transnational-repression", "transnational-repression-2026",
        )
        for language in BATCH5_LANGS
    )
    for language in BATCH5_LANGS:
        for source_id in ("s1", "s2", "s4", "s5", "s6"):
            if (language, source_id) in {
                ("en", "s2"), ("en", "s5"), ("fr", "s2"),
            }:
                continue
            keys.add((
                "transnational-repression", language,
                f"source-entry:{source_id}",
            ))
    return frozenset(keys)


BATCH12_EXPECTED_LEDGER_KEYS = batch12_expected_ledger_keys()
BATCH12_LEDGER_ROWS = 567
BATCH12_FINAL_REREAD_ROWS = 16563
BATCH12_FINAL_CONTRACT_ROWS = 7598
BATCH12_FINAL_SOURCE_ROWS = 10630
BATCH12_CANONICAL_PREFIX_SHA256 = (
    "81504cae967125b96be2901be127054fcf13aded15d2d43de843ed38755180f2",
    "2f4fb2426a47d734d1cbd38a262e5c4df43535abb6ac309dd34cee610ffbc594",
    "b856c6269312b79ca0c488e87735156bc25d2a0c47e3d929b503a98c9d6af0b5",
)


def batch12_live_target_text(pages, slug, language, target_id):
    soup = pages.get(slug)
    if soup is None:
        return ""
    if target_id == "article-dek":
        return batch12_text(soup.select_one(f".article-dek .lang-{language}"))
    if target_id.startswith("source-entry:"):
        source_id = target_id.split(":", 1)[1]
        body = soup.select_one(f'[data-language-body="{language}"]')
        return batch12_text(
            body.select_one(f'[data-source-id="{source_id}"]')
            if body is not None else None
        )
    return batch12_text(
        batch12_target_node(pages, slug, language, target_id)
    )


def batch12_rows_prefix_digest(rows, columns, count):
    output = io.StringIO(newline="")
    writer = csv.DictWriter(
        output, fieldnames=columns, delimiter="\t", lineterminator="\n",
    )
    writer.writeheader()
    writer.writerows(rows[:count])
    return hashlib.sha256(output.getvalue().encode("utf-8")).hexdigest()


def audit_batch12_ledgers(
    pages, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    issues = []
    for path, count, digest, label in (
        (
            BATCH9_REREAD_PATH, BATCH12_PRE_REREAD_ROWS,
            BATCH12_PRE_REREAD_SHA256, "batch12 final7 reread prefix",
        ),
        (
            BATCH9_CONTRACT_PATH, BATCH12_PRE_CONTRACT_ROWS,
            BATCH12_PRE_CONTRACT_SHA256, "batch12 final7 contract prefix",
        ),
        (
            BATCH9_SOURCE_LEDGER_PATH, BATCH12_PRE_SOURCE_ROWS,
            BATCH12_PRE_SOURCE_SHA256, "batch12 final7 source prefix",
        ),
    ):
        issues.extend(batch9_final2_exact_prefix(path, count, digest, label))
    # Batch thirteen appended 446 rows after batch12 completed.  Without an
    # explicit override batch12 audits its own 16563 / 7598 / 10630-row state;
    # the successor append is authenticated by audit_batch13_ledgers.
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch12 reread ledger",
        )
        reread_rows = reread_rows[:BATCH12_FINAL_REREAD_ROWS]
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch12 contract ledger",
        )
        contract_rows = contract_rows[:BATCH12_FINAL_CONTRACT_ROWS]
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch12 source ledger",
        )
        source_rows = source_rows[:BATCH12_FINAL_SOURCE_ROWS]
        issues.extend(load_issues)
    suffixes = (
        reread_rows[BATCH12_PRE_REREAD_ROWS:],
        contract_rows[BATCH12_PRE_CONTRACT_ROWS:],
        source_rows[BATCH12_PRE_SOURCE_ROWS:],
    )
    for rows, columns, count, expected, kind in zip(
        (reread_rows, contract_rows, source_rows),
        (
            BATCH9_FINAL2_REREAD_COLUMNS, BATCH9_FINAL2_CONTRACT_COLUMNS,
            BATCH9_FINAL2_SOURCE_COLUMNS,
        ),
        (
            BATCH12_PRE_REREAD_ROWS, BATCH12_PRE_CONTRACT_ROWS,
            BATCH12_PRE_SOURCE_ROWS,
        ),
        BATCH12_CANONICAL_PREFIX_SHA256,
        ("reread", "contract", "source"),
    ):
        if batch12_rows_prefix_digest(rows, columns, count) != expected:
            issues.append(f"batch12 in-memory {kind} final7 prefix differs")
    expected_totals = (
        BATCH12_FINAL_REREAD_ROWS,
        BATCH12_FINAL_CONTRACT_ROWS,
        BATCH12_FINAL_SOURCE_ROWS,
    )
    for rows, total, kind in zip(
        (reread_rows, contract_rows, source_rows),
        expected_totals, ("reread", "contract", "source"),
    ):
        if len(rows) != total:
            issues.append(
                f"batch12 {kind} total is {len(rows)}, expected {total}"
            )
    for suffix, kind in zip(
        suffixes, ("reread", "contract", "source"),
    ):
        if len(suffix) != BATCH12_LEDGER_ROWS:
            issues.append(
                f"batch12 {kind} append has {len(suffix)} rows, expected "
                f"{BATCH12_LEDGER_ROWS}"
            )
    reread_suffix, contract_suffix, source_suffix = suffixes
    reread_keyed = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_id", ""),
        ): row
        for row in reread_suffix
    }
    contract_keyed = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("target_id", ""),
        ): row
        for row in contract_suffix
    }
    source_keyed = {
        (
            row.get("slug", ""), row.get("language", ""),
            row.get("fact_id", ""),
        ): row
        for row in source_suffix
    }
    for label, keyed, rows in (
        ("reread", reread_keyed, reread_suffix),
        ("contract", contract_keyed, contract_suffix),
        ("source", source_keyed, source_suffix),
    ):
        if len(keyed) != len(rows):
            issues.append(f"batch12 {label} append has duplicate target keys")
        if frozenset(keyed) != BATCH12_EXPECTED_LEDGER_KEYS:
            missing = BATCH12_EXPECTED_LEDGER_KEYS - frozenset(keyed)
            extra = frozenset(keyed) - BATCH12_EXPECTED_LEDGER_KEYS
            issues.append(
                f"batch12 {label} append coverage differs: "
                f"{len(missing)} missing, {len(extra)} extra"
            )
    for key in BATCH12_EXPECTED_LEDGER_KEYS:
        reread = reread_keyed.get(key)
        contract = contract_keyed.get(key)
        source = source_keyed.get(key)
        if reread is None or contract is None or source is None:
            continue
        live = batch12_live_target_text(pages, *key)
        original = batch11_norm(reread.get("original_text", ""))
        revised = batch11_norm(reread.get("revised_text", ""))
        if not original or original == revised:
            issues.append(f"batch12 {key}: reread lacks a genuine transition")
        for field in ("issue_found", "review_basis"):
            if not reread.get(field, "").strip():
                issues.append(f"batch12 {key}: reread lacks {field}")
        if revised != live:
            issues.append(f"batch12 {key}: reread revision differs from live DOM")
        if reread.get("result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch12 {key}: reread result differs")
        contract_id = reread.get("contract_id", "")
        if (
            not contract_id.startswith(BATCH12_PREFIX + ":")
            or contract.get("contract_id", "") != contract_id
            or source.get("baseline_issue", "") != contract_id
        ):
            issues.append(f"batch12 {key}: three-ledger contract chain differs")
        required = batch9_final2_contract_literals(
            contract.get("required_all", "")
        )
        forbidden = batch9_final2_contract_literals(
            contract.get("forbidden_any", "")
        )
        if len(required) < 4 or len(set(required)) < 4:
            issues.append(f"batch12 {key}: contract has fewer than four anchors")
        if (
            len(forbidden) < 2 or len(set(forbidden)) < 2
            or any(
                not part.strip().casefold().startswith("old-error:")
                for part in contract.get("forbidden_any", "").split("||")
                if part.strip()
            )
        ):
            issues.append(f"batch12 {key}: contract has fewer than two old errors")
        summary = contract.get("fact_summary", "").casefold()
        for marker in (
            "subject", "action", "consequence", "source",
            "remedy", "accountability",
        ):
            if marker not in summary:
                issues.append(
                    f"batch12 {key}: contract summary lacks {marker}"
                )
        if batch11_norm(source.get("current_visible_text", "")) != live:
            issues.append(f"batch12 {key}: source mapping differs from live DOM")
        if " ".join(reread.get("source_refs", "").split()) != " ".join(
            source.get("data_source_ref", "").split()
        ):
            issues.append(f"batch12 {key}: reread/source reference chain differs")
        if source.get("reread_result", "") != "PASS_AFTER_REVISION":
            issues.append(f"batch12 {key}: source reread result differs")
        if source.get("audit_decision", "") != "PASS_BATCH12_SOURCE_MAPPING":
            issues.append(f"batch12 {key}: source audit decision differs")
        if BATCH12_PREFIX not in source.get("resolution_action", ""):
            issues.append(f"batch12 {key}: source resolution lacks batch tag")
        for field in (
            "audit_locator", "audit_support_summary", "audit_relationship",
            "visible_subject_anchor", "visible_action_anchor",
            "visible_source_roles",
        ):
            if not source.get(field, "").strip():
                issues.append(f"batch12 {key}: source evidence lacks {field}")
        node = batch12_target_node(pages, *key)
        if node is not None and node.has_attr("data-timeline-action"):
            for field, attribute in (
                ("timeline_subject", "data-timeline-subject"),
                ("timeline_action", "data-timeline-action"),
                ("timeline_consequence", "data-timeline-consequence"),
            ):
                if " ".join(source.get(field, "").split()) != " ".join(
                    node.get(attribute, "").split()
                ):
                    issues.append(
                        f"batch12 {key}: source {field} differs from DOM"
                    )
    return issues, {
        "reread_rows": len(reread_suffix),
        "contract_rows": len(contract_suffix),
        "source_rows": len(source_suffix),
    }


def batch12_load_generic_tsv(path):
    if not path.exists():
        return [], [f"batch12 artifact missing: {path.relative_to(ROOT)}"]
    with path.open(encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = list(reader)
        fields = tuple(reader.fieldnames or ())
    return rows, ([] if fields else [f"batch12 artifact has no header: {path}"])


def audit_batch12_source_artifacts(
    *, reaccess_rows=None, correction_rows=None, source_date_payload=None,
):
    issues = []
    source_date_path = ROOT / "tools/data/source-date-ledger.tsv"
    payload = (
        source_date_payload
        if source_date_payload is not None
        else batch14_source_date_prefix_bytes()
    )
    if hashlib.sha256(payload).hexdigest() != BATCH12_SOURCE_DATE_SHA256:
        issues.append("batch12 rewrote the 294-row source-date ledger")
    try:
        date_rows = list(csv.DictReader(
            io.StringIO(payload.decode("utf-8")), delimiter="\t",
        ))
    except (UnicodeDecodeError, csv.Error):
        date_rows = []
        issues.append("batch12 source-date ledger is not valid UTF-8 TSV")
    if len(date_rows) != BATCH12_SOURCE_DATE_ROWS:
        issues.append(
            f"batch12 source-date ledger has {len(date_rows)} rows, expected "
            f"{BATCH12_SOURCE_DATE_ROWS}"
        )
    if correction_rows is None:
        correction_rows, load_issues = batch12_load_generic_tsv(
            BATCH12_DATE_CORRECTION_PATH
        )
        issues.extend(load_issues)
    if len(correction_rows) != 1:
        issues.append(
            f"batch12 source-date correction trail has {len(correction_rows)} "
            "rows, expected 1"
        )
    correction = correction_rows[0] if correction_rows else {}
    expected_correction = {
        "batch_tag": BATCH12_PREFIX,
        "slug": "transnational-repression",
        "source_id": "s1",
        "old_url": "https://freedomhouse.org/report/transnational-repression",
        "old_audited_date": "2021-01-15",
        "old_verification_status": "VERIFIED_SOURCE_DATE",
        "new_url": "https://freedomhouse.org/article/new-report-transnational-repression-growing-threat-global-democracy",
        "new_title_en": "Freedom House — New Report: Transnational Repression Is a Growing Threat to Global Democracy",
        "new_audited_date": "2021-02-04",
        "new_precision": "day",
        "new_verification_status": "CORRECTED_VERIFIED_SOURCE_DATE",
        "accessed_at": "2026-07-24",
        "supersedes": "source-date-ledger.tsv:transnational-repression:s1",
    }
    for field, expected in expected_correction.items():
        if correction.get(field, "") != expected:
            issues.append(
                f"batch12 TNR/s1 correction {field} differs"
            )
    for field in (
        "authority_locator", "correction_reason", "old_title_zh",
        "new_source_type",
    ):
        if not correction.get(field, "").strip():
            issues.append(f"batch12 TNR/s1 correction lacks {field}")
    if reaccess_rows is None:
        reaccess_rows, load_issues = batch12_load_generic_tsv(
            BATCH12_REACCESS_PATH
        )
        issues.extend(load_issues)
    expected_pairs = {
        (slug, source_id)
        for slug, sources in BATCH12_SOURCE_SIGNATURES.items()
        for source_id, _type, _date, _url in sources
    }
    keyed = {
        (row.get("slug", ""), row.get("source_id", "")): row
        for row in reaccess_rows
    }
    if len(reaccess_rows) != 59 or frozenset(keyed) != frozenset(expected_pairs):
        issues.append(
            f"batch12 source reaccess coverage is {len(reaccess_rows)}/59"
        )
    expected_decisions = {
        ("china-dissent-monitor-2025", "cdm25-s1"): "UNDATED_CONFIRMED",
        ("henan-bank-depositor-protests", "hbd-s1"): "MANUAL_REVIEW_REQUIRED",
        ("terminus2049-chen-mei-cai-wei", "tm-s4"): "UNDATED_CONFIRMED",
        ("transnational-repression", "s1"): "CORRECTED_AND_VERIFIED",
        ("zhang-zhan", "zz-s2"): "MANUAL_REVIEW_REQUIRED",
    }
    signature_map = {
        (slug, source_id): (date, url)
        for slug, sources in BATCH12_SOURCE_SIGNATURES.items()
        for source_id, _type, date, url in sources
    }
    for key in expected_pairs:
        row = keyed.get(key)
        if row is None:
            continue
        if row.get("batch_tag", "") != "batch12":
            issues.append(f"batch12 reaccess {key}: batch tag differs")
        date, url = signature_map[key]
        if row.get("expected_url", "") != url:
            issues.append(f"batch12 reaccess {key}: expected URL differs")
        expected_declared = date if date else "UNDATED"
        if row.get("declared_date", "") != expected_declared:
            issues.append(f"batch12 reaccess {key}: declared date differs")
        expected_decision = expected_decisions.get(key, "VERIFIED")
        if row.get("decision", "") != expected_decision:
            issues.append(f"batch12 reaccess {key}: decision differs")
        if key == ("henan-bank-depositor-protests", "hbd-s1"):
            if (
                row.get("actual_status", "") != "403"
                or row.get("actual_title", "") != "UNAVAILABLE_HTTP_403"
                or row.get("observed_date", "") != "NOT_OBSERVED_HTTP_403"
            ):
                issues.append("batch12 hbd-s1 must retain honest HTTP 403")
        elif key == ("zhang-zhan", "zz-s2"):
            if (
                row.get("actual_status", "") != "TLS_ERROR"
                or row.get("actual_title", "") != "UNAVAILABLE_TLS_ERROR"
                or row.get("observed_date", "") != "NOT_OBSERVED_TLS_ERROR"
            ):
                issues.append("batch12 zz-s2 must retain honest TLS error")
        elif row.get("actual_status", "") != "200":
            issues.append(f"batch12 reaccess {key}: unexpected status")
        required_fields = [
            "actual_title", "observed_date", "source_locator", "fact_scope",
            "accessed_at",
        ]
        if key != ("zhang-zhan", "zz-s2"):
            required_fields.append("final_url")
        for field in required_fields:
            if not row.get(field, "").strip():
                issues.append(f"batch12 reaccess {key}: lacks {field}")
    return issues


def batch12_manifest(overrides=None):
    overrides = overrides or {}
    all_records = []
    protected = []
    seen = set()

    def include(relative, payload):
        if payload is None:
            return
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if batch11_final1_is_desktop_extra(relative, payload):
            return
        record = (
            relative, len(payload), hashlib.sha256(payload).hexdigest(),
        )
        all_records.append(record)
        if relative not in BATCH12_ALLOWED_FILES:
            protected.append(record)

    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        # The batch13-only audit artifact is outside the batch12 manifest, so
        # BATCH12_TOTAL_FILES / BATCH12_PROTECTED_FILES keep their original
        # values.  Its bytes are frozen by BATCH13_PAGE_PREIMAGE_SHA256.
        if (
            ".git" in relative_path.parts
            or path.name == ".DS_Store"
            or batch13_successor_artifact(relative)
        ):
            continue
        if relative in BATCH14_NEW_AUDIT_FILES or fnmatch.fnmatch(
            relative, "tools/data/batch14-*.tsv"
        ):
            # First written in batch fourteen: outside this freeze's path set.
            continue
        seen.add(relative)
        include(
            relative,
            overrides.get(
                relative,
                batch13_historical_bytes().get(relative)
                or batch14_historical_bytes().get(relative)
                or path.read_bytes(),
            ),
        )
    for relative, payload in overrides.items():
        relative_path = Path(relative)
        if (
            relative in seen or ".git" in relative_path.parts
            or relative_path.name == ".DS_Store"
            or batch13_successor_artifact(relative)
        ):
            continue
        include(relative, payload)
    protected_payload = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(protected)
    ).encode("utf-8")
    allowed_present = {
        relative for relative, _size, _digest in all_records
        if relative in BATCH12_ALLOWED_FILES
    }
    return all_records, protected, allowed_present, protected_payload


def audit_batch12_frozen(overrides=None):
    # The batch12 340-path manifest is unchanged; it is recomputed over the
    # authenticated pre-batch13 bytes of the 49 revised dossiers.  An explicit
    # override still wins so the batch12 negative tests keep working.
    overrides = {**batch13_historical_bytes(), **(overrides or {})}
    all_records, protected, allowed_present, payload = batch12_manifest(overrides)
    issues = []
    if len(all_records) != BATCH12_TOTAL_FILES:
        issues.append(
            f"batch12 logical file count is {len(all_records)}, expected "
            f"{BATCH12_TOTAL_FILES}"
        )
    if allowed_present != BATCH12_ALLOWED_FILES:
        issues.append("batch12 whitelist membership changed")
    if len(protected) != BATCH12_PROTECTED_FILES:
        issues.append(
            f"batch12 protected file count is {len(protected)}, expected "
            f"{BATCH12_PROTECTED_FILES}"
        )
    if hashlib.sha256(payload).hexdigest() != BATCH12_PROTECTED_SHA256:
        issues.append("batch12 changed, added, or removed a non-whitelist file")
    return issues


def batch12_browser_independent_payload(relative, overrides=None):
    """Read one browser ledger, honouring in-memory negative-test overrides."""
    value = (overrides or {}).get(relative)
    if isinstance(value, str):
        return value.encode("utf-8")
    if isinstance(value, bytes):
        return value
    path = ROOT / relative
    if not path.is_file():
        return None
    return path.read_bytes()


def batch12_browser_independent_table(payload):
    """Parse one browser ledger into (columns, rows) without touching disk."""
    if payload is None:
        return (), []
    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError:
        return (), []
    reader = csv.DictReader(io.StringIO(text, newline=""), delimiter="\t")
    rows = list(reader)
    return tuple(reader.fieldnames or ()), rows


def batch12_browser_independent_pages():
    """Re-parse the twelve dossiers for this module's own cross-check.

    The batch12 browser run measured the completed-batch12 markup, so the
    cross-check is replayed against the authenticated pre-batch13 preimage.
    """
    return {
        page: BeautifulSoup(batch13_historical_markup(page), "html.parser")
        for page in BATCH12_BROWSER_ARTICLE_PAGES
    }


def batch12_browser_independent_dom_issues(soup, row):
    """Recompute one article row's structural claims from re-parsed markup."""
    if soup is None:
        return ["page has no live DOM to cross-check"]
    language = row.get("lang", "")
    body = soup.select_one(f'[data-language-body="{language}"]')
    if body is None:
        return [f"live DOM has no visible {language!r} language body"]
    issues = []
    if row.get("visible_language_bodies") != language:
        issues.append(
            "visible_language_bodies is "
            f"{row.get('visible_language_bodies')!r}, expected {language!r}"
        )
    sections = ">".join(
        heading.get("data-section", "")
        for heading in body.select("h2[data-section]")
    )
    if sections != row.get("section_order", ""):
        issues.append(
            f"section_order {row.get('section_order')!r} is not the live DOM "
            f"order {sections!r}"
        )
    timeline = [
        node for node in body.select("li[data-fact-id]")
        if BATCH12_BROWSER_TIMELINE_ID.search(node.get("data-fact-id", ""))
    ]
    if row.get("timeline_nodes", "") != str(len(timeline)):
        issues.append(
            f"timeline_nodes {row.get('timeline_nodes')!r} is not the live "
            f"DOM count {len(timeline)}"
        )
    source_ids = ",".join(
        node.get("data-source-id", "")
        for node in body.select("[data-source-id]")
    )
    if source_ids != row.get("source_ids", ""):
        issues.append(
            f"source_ids {row.get('source_ids')!r} are not the live DOM ids "
            f"{source_ids!r}"
        )
    heading = soup.select_one(f"h1.article-title .lang-{language}")
    title = " ".join(heading.stripped_strings) if heading else ""
    if title[:BATCH12_BROWSER_H1_PREFIX] != row.get("h1_text", ""):
        issues.append(
            f"h1_text {row.get('h1_text')!r} is not the live DOM title "
            f"{title[:BATCH12_BROWSER_H1_PREFIX]!r}"
        )
    if row.get("critical_case_matches_first_sentence") != "yes":
        issues.append(
            "critical_case_matches_first_sentence is "
            f"{row.get('critical_case_matches_first_sentence')!r}, expected "
            "yes on a dossier page"
        )
    if row.get("card_fields_checked") != "n/a":
        issues.append(
            "card_fields_checked must be n/a on a dossier page, found "
            f"{row.get('card_fields_checked')!r}"
        )
    return issues


def batch12_browser_independent_issues(overrides=None, pages=None):
    """Independently re-derive the batch-twelve browser acceptance run.

    This gate shares nothing with tools/check_languages.py: the page,
    language, viewport and column vocabularies above are handwritten in this
    module, the three digests are handwritten here, and the DOM is re-parsed
    from disk with this module's own selectors.  A row is accepted only when
    the served markup still reproduces every structural column it claims.
    """
    issues = []
    payloads = {}
    for relative, digest in zip(
        BATCH12_BROWSER_RELATIVES,
        (
            BATCH12_BROWSER_SHA256,
            BATCH12_BROWSER_FIXES_SHA256,
            BATCH12_OBSERVATIONS_SHA256,
        ),
    ):
        payload = batch12_browser_independent_payload(relative, overrides)
        payloads[relative] = payload
        if payload is None:
            issues.append(
                f"independent batch12 browser ledger is missing: {relative}"
            )
            continue
        if hashlib.sha256(payload).hexdigest() != digest:
            issues.append(
                f"independent batch12 browser ledger digest changed: "
                f"{relative}"
            )
    for relative in sorted(set(overrides or {}) - set(payloads)):
        issues.append(
            "independent batch12 browser override targets an unknown ledger: "
            f"{relative}"
        )

    columns, rows = batch12_browser_independent_table(
        payloads[BATCH12_BROWSER_RELATIVES[0]]
    )
    if columns and columns != BATCH12_BROWSER_COLUMNS:
        issues.append(
            "independent batch12 browser acceptance columns or column order "
            "changed"
        )
    elif columns:
        if len(rows) != BATCH12_BROWSER_ROWS:
            issues.append(
                f"independent batch12 browser acceptance has {len(rows)} data "
                f"rows, expected {BATCH12_BROWSER_ROWS}"
            )
        expected_units = {
            f"{page}|{language}|{viewport}"
            for page in BATCH12_BROWSER_PAGES
            for language in BATCH12_BROWSER_LANGS
            for viewport in BATCH12_BROWSER_VIEWPORTS
        }
        seen_units = set()
        real_navigation = set()
        if pages is None:
            pages = batch12_browser_independent_pages()
        for number, row in enumerate(rows, start=2):
            page = row.get("page", "")
            language = row.get("lang", "")
            viewport = row.get("viewport", "")
            unit = row.get("unit_id", "")
            where = f"independent batch12 browser line {number} [{unit}]"
            if unit in seen_units:
                issues.append(f"{where}: duplicate unit_id")
            seen_units.add(unit)
            if unit != f"{page}|{language}|{viewport}":
                issues.append(
                    f"{where}: unit_id is not page|lang|viewport "
                    f"({page}|{language}|{viewport})"
                )
            if row.get("batch_tag") != BATCH12_BROWSER_TAG:
                issues.append(
                    f"{where}: batch_tag is {row.get('batch_tag')!r}"
                )
            if page not in BATCH12_BROWSER_PAGES:
                issues.append(f"{where}: unknown page {page!r}")
            if language not in BATCH12_BROWSER_LANGS:
                issues.append(f"{where}: unknown language {language!r}")
            if viewport not in BATCH12_BROWSER_VIEWPORTS:
                issues.append(f"{where}: illegal viewport {viewport!r}")
            if row.get("result") != "PASS":
                issues.append(
                    f"{where}: result is {row.get('result')!r}, expected PASS"
                )
            for column in BATCH12_BROWSER_ZERO_COLUMNS:
                if row.get(column) != "0":
                    issues.append(
                        f"{where}: {column} is {row.get(column)!r}, expected 0"
                    )
            reload_method = row.get("reload_method", "")
            if reload_method not in BATCH12_BROWSER_RELOAD_METHODS:
                issues.append(
                    f"{where}: illegal reload_method {reload_method!r}"
                )
            elif reload_method == BATCH12_BROWSER_REAL_NAVIGATION:
                real_navigation.add(language)
            persisted = row.get("persisted_lang", "")
            # Either the language observed after the reload, or the literal
            # confirmation token.  A different language is a persistence bug.
            if persisted not in {language, "OK"}:
                issues.append(
                    f"{where}: persisted_lang is {persisted!r}, expected "
                    f"{language!r} or OK"
                )
            if viewport == BATCH12_BROWSER_MOBILE_VIEWPORT:
                if not row.get("mobile_menu", "").startswith(
                    BATCH12_BROWSER_MOBILE_MENU_PREFIX
                ):
                    issues.append(
                        f"{where}: mobile_menu is {row.get('mobile_menu')!r}"
                    )
                if not row.get("escape_focus_restore", "").startswith(
                    BATCH12_BROWSER_FOCUS_PREFIX
                ):
                    issues.append(
                        f"{where}: escape_focus_restore is "
                        f"{row.get('escape_focus_restore')!r}"
                    )
            if page in BATCH12_BROWSER_PUBLIC_PAGES:
                if row.get("visible_language_bodies") != language:
                    issues.append(
                        f"{where}: visible_language_bodies is "
                        f"{row.get('visible_language_bodies')!r}"
                    )
                for column in (
                    "section_order", "timeline_nodes", "source_ids",
                ):
                    if row.get(column) != "n/a":
                        issues.append(
                            f"{where}: {column} must be n/a on a public page, "
                            f"found {row.get(column)!r}"
                        )
                if row.get("card_fields_checked") != (
                    BATCH12_BROWSER_PUBLIC_CARD_FIELDS
                ):
                    issues.append(
                        f"{where}: card_fields_checked must be "
                        f"{BATCH12_BROWSER_PUBLIC_CARD_FIELDS!r}, found "
                        f"{row.get('card_fields_checked')!r}"
                    )
            else:
                issues.extend(
                    f"{where}: {issue}"
                    for issue in batch12_browser_independent_dom_issues(
                        pages.get(page), row
                    )
                )
        missing_units = sorted(expected_units - seen_units)
        extra_units = sorted(seen_units - expected_units)
        if missing_units:
            issues.append(
                f"independent batch12 browser acceptance is missing "
                f"{len(missing_units)} of {len(expected_units)} units, first "
                f"{missing_units[0]}"
            )
        if extra_units:
            issues.append(
                f"independent batch12 browser acceptance records "
                f"{len(extra_units)} units outside the matrix, first "
                f"{extra_units[0]}"
            )
        uncovered = [
            language for language in BATCH12_BROWSER_LANGS
            if language not in real_navigation
        ]
        if uncovered:
            issues.append(
                "independent batch12 browser real-navigation reload never "
                "covered: " + ",".join(uncovered)
            )

    fix_columns, fix_rows = batch12_browser_independent_table(
        payloads[BATCH12_BROWSER_RELATIVES[1]]
    )
    if fix_columns and fix_columns != BATCH12_BROWSER_FIX_COLUMNS:
        issues.append(
            "independent batch12 browser fix ledger columns or column order "
            "changed"
        )
    elif fix_columns:
        if len(fix_rows) != BATCH12_BROWSER_FIX_ROWS:
            issues.append(
                f"independent batch12 browser fix ledger has {len(fix_rows)} "
                f"rows, expected {BATCH12_BROWSER_FIX_ROWS}"
            )
        repaired = sorted(row.get("file", "") for row in fix_rows)
        if repaired != sorted(BATCH12_BROWSER_FIXED_FILES):
            issues.append(
                "independent batch12 browser fix ledger does not cover "
                f"exactly the listed repaired files: {repaired}"
            )
        shell_rows = [
            row
            for row in fix_rows
            if row.get("fix_id", "") == SHELL_REPAIRED_FIX_ID
        ]
        if len(shell_rows) != 1:
            issues.append(
                "independent batch12 browser fix ledger must carry exactly "
                f"one {SHELL_REPAIRED_FIX_ID} row repairing "
                f"{SHELL_REPAIRED_PAGE}, found {len(shell_rows)}"
            )
        for row in shell_rows:
            if row.get("file", "") != SHELL_REPAIRED_PAGE:
                issues.append(
                    "independent batch12 browser fix "
                    f"{SHELL_REPAIRED_FIX_ID} repairs "
                    f"{row.get('file', '')!r}, expected "
                    f"{SHELL_REPAIRED_PAGE!r}"
                )
            elif row.get("sha256_after") != SHELL_REPAIRED_PAGE_SHA256:
                issues.append(
                    "independent batch12 browser fix "
                    f"{SHELL_REPAIRED_FIX_ID}: sha256_after disagrees with "
                    "this module's handwritten digest for the repaired "
                    f"{SHELL_REPAIRED_PAGE}"
                )
        for row in fix_rows:
            relative = row.get("file", "")
            label = (
                "independent batch12 browser fix "
                f"{row.get('fix_id', '?')}"
            )
            if row.get("batch_tag") != BATCH12_BROWSER_TAG:
                issues.append(f"{label}: batch_tag is not batch12-browser")
            path = ROOT / relative
            if not path.is_file():
                issues.append(f"{label}: repaired file is missing {relative}")
                continue
            current = hashlib.sha256(
                batch13_historical_bytes().get(relative) or path.read_bytes()
            ).hexdigest()
            if row.get("sha256_after") != current:
                issues.append(
                    f"{label}: sha256_after does not match the repaired "
                    f"{relative}"
                )
            if row.get("sha256_before") == current:
                issues.append(
                    f"{label}: sha256_before equals the current {relative}, "
                    "so no repair was actually applied"
                )

    observation_columns, observation_rows = (
        batch12_browser_independent_table(
            payloads[BATCH12_BROWSER_RELATIVES[2]]
        )
    )
    if observation_columns and observation_columns != (
        BATCH12_OBSERVATION_COLUMNS
    ):
        issues.append(
            "independent batch12 browser observation ledger columns or "
            "column order changed"
        )
    elif observation_columns:
        if len(observation_rows) != BATCH12_OBSERVATION_ROWS:
            issues.append(
                "independent batch12 browser observation ledger has "
                f"{len(observation_rows)} rows, expected "
                f"{BATCH12_OBSERVATION_ROWS}"
            )
        identifiers = [
            row.get("observation_id", "") for row in observation_rows
        ]
        if len(set(identifiers)) != len(identifiers):
            issues.append(
                "independent batch12 browser observation ids are not unique"
            )
        for row in observation_rows:
            if row.get("batch_tag") != BATCH12_BROWSER_TAG:
                issues.append(
                    "independent batch12 browser observation "
                    f"{row.get('observation_id', '?')}: batch_tag is not "
                    "batch12-browser"
                )
    return issues


def batch12_browser_independent_statistics():
    """Summarize the accepted browser run for the independent report line."""
    _columns, rows = batch12_browser_independent_table(
        batch12_browser_independent_payload(BATCH12_BROWSER_RELATIVES[0])
    )
    _fix_columns, fix_rows = batch12_browser_independent_table(
        batch12_browser_independent_payload(BATCH12_BROWSER_RELATIVES[1])
    )
    _observation_columns, observation_rows = (
        batch12_browser_independent_table(
            batch12_browser_independent_payload(BATCH12_BROWSER_RELATIVES[2])
        )
    )

    def total(column):
        return sum(
            int(row[column]) for row in rows
            if (row.get(column) or "").isdigit()
        )

    return {
        "units": len(rows),
        "pages": len(BATCH12_BROWSER_PAGES),
        "languages": len(BATCH12_BROWSER_LANGS),
        "viewports": len(BATCH12_BROWSER_VIEWPORTS),
        "console_errors": total("console_errors"),
        "overflow": total("overflow_px") + total("long_source_title_overflow"),
        "real_navigation": sum(
            row.get("reload_method") == BATCH12_BROWSER_REAL_NAVIGATION
            for row in rows
        ),
        "fixes": len(fix_rows),
        "observations": len(observation_rows),
    }


def shell_article_paths():
    """Every published dossier, re-globbed by this module."""
    return tuple(
        sorted(
            path
            for path in (ROOT / "posts").glob("*.html")
            if path.name != SHELL_TEMPLATE_FILENAME
        )
    )


def shell_article_pages(page_overrides=None):
    """Parse all dossiers with this module's own parser configuration."""
    pages = {}
    for path in shell_article_paths():
        override = (page_overrides or {}).get(path.stem)
        pages[path.stem] = (
            override
            if override is not None
            else BeautifulSoup(
                path.read_text(encoding="utf-8"), "html.parser"
            )
        )
    for slug in sorted(set(page_overrides or {}) - set(pages)):
        pages[slug] = page_overrides[slug]
    return pages


def shell_is_grid(node):
    return node is not None and SHELL_GRID_CLASS in (node.get("class") or [])


def shell_language_bodies(article):
    return article.select(f"[{SHELL_BODY_ATTRIBUTE}]")


def shell_prose(article):
    """Visible dossier prose with scripts and localized source titles removed.

    Source titles reproduce foreign institutional strings verbatim and are the
    only legitimate place for them, so they are excluded; nothing else is.
    """
    clone = deepcopy(article)
    for node in clone.find_all(["script", "style", "template"]):
        node.decompose()
    for item in clone.find_all("li"):
        if item.find_parent(
            ["ul", "ol"], class_=SHELL_SOURCE_LIST_CLASS
        ) is None and not item.get("data-source-id"):
            continue
        for anchor in item.find_all("a"):
            anchor.decompose()
    return clone.get_text(" ", strip=True)


def shell_unowned_prose(article):
    """Visible text under <article> owned by no header and no language body."""
    clone = deepcopy(article)
    for node in clone.find_all(["script", "style", "template", "header"]):
        node.decompose()
    for node in clone.find_all(attrs={SHELL_BODY_ATTRIBUTE: True}):
        node.decompose()
    return clone.get_text(" ", strip=True)


def shell_tail_signature(body):
    """(ends with a grid, grid count, cards per grid) for one language body."""
    grids = [
        node for node in body.find_all("div")
        if SHELL_GRID_CLASS in (node.get("class") or [])
    ]
    elements = body.find_all(recursive=False)
    return (
        bool(elements) and shell_is_grid(elements[-1]),
        len(grids),
        tuple(
            len([
                card for card in grid.find_all("div")
                if SHELL_CARD_CLASS in (card.get("class") or [])
            ])
            for grid in grids
        ),
    )


def audit_zero21_article_shell_page(soup, slug):
    """Independent five-rule shell contract for one dossier."""
    issues = []
    article = soup.find("article")
    if article is None:
        return [f"posts/{slug}.html: independent shell: no <article> element"]
    where = f"posts/{slug}.html: independent shell"
    bodies = shell_language_bodies(article)
    languages = [body.get(SHELL_BODY_ATTRIBUTE) for body in bodies]
    if sorted(filter(None, languages)) != sorted(SHELL_LANGUAGES):
        issues.append(
            f"{where}: <article> must carry exactly the ten language bodies, "
            f"found {languages}"
        )

    # 1.  Nothing visible may hang directly off <article> outside a body.
    for child in article.find_all(recursive=False):
        if child.name == "header":
            continue
        if child.get(SHELL_BODY_ATTRIBUTE):
            continue
        if child.find(attrs={SHELL_BODY_ATTRIBUTE: True}) is not None:
            continue
        text = child.get_text(" ", strip=True)
        if text:
            issues.append(
                f"{where}: <{child.name}> hangs directly off <article> "
                "outside every language body, so all ten languages render it "
                f"at once: {text[:60]!r}"
            )
    unowned = shell_unowned_prose(article)
    if unowned:
        issues.append(
            f"{where}: visible prose under <article> is owned by no language "
            f"body and is never hidden by language.js: {unowned[:80]!r}"
        )

    # 2.  All ten bodies must hang off one and the same element.
    if len({id(body.parent) for body in bodies}) > 1:
        layout = sorted(
            "{}[{}]".format(
                ".".join([body.parent.name, *(body.parent.get("class") or [])]),
                body.get(SHELL_BODY_ATTRIBUTE),
            )
            for body in bodies
        )
        issues.append(
            f"{where}: the ten language bodies hang off more than one parent "
            f"element, so their layout container is not shared: {layout}"
        )

    # 3.  No visible heading inside a body may escape the section contract.
    for body in bodies:
        language = body.get(SHELL_BODY_ATTRIBUTE)
        for heading in body.find_all(SHELL_HEADING_TAGS):
            text = heading.get_text(" ", strip=True)
            if not text or heading.get(SHELL_SECTION_ATTRIBUTE):
                continue
            if any(
                shell_is_grid(parent) for parent in heading.parents
            ):
                continue
            issues.append(
                f"{where}: the {language} body carries a visible "
                f"<{heading.name}> with no {SHELL_SECTION_ATTRIBUTE}, which "
                f"no section contract can see: {text[:60]!r}"
            )

    # 4.  No reader instruction and no source-precedence disclaimer.
    prose = shell_prose(article)
    lowered = prose.lower()
    for language, phrase in SHELL_READER_INSTRUCTIONS:
        if phrase.lower() in lowered:
            issues.append(
                f"{where}: visible dossier prose contains the {language} "
                f"reader-instruction phrase {phrase!r}"
            )
    precedence = SHELL_PRECEDENCE_PATTERN.search(prose)
    if precedence is not None:
        issues.append(
            f"{where}: visible dossier prose subordinates itself to another "
            f"document: {precedence.group(0)!r}"
        )

    # 5.  The statistics tail must be identical in all ten languages.
    tails = {
        body.get(SHELL_BODY_ATTRIBUTE): shell_tail_signature(body)
        for body in bodies
    }
    if len(set(tails.values())) > 1:
        issues.append(
            f"{where}: the closing .fact-grid/.fact-card structure differs "
            f"between languages: {tails}"
        )
    expected = SHELL_STATISTIC_CARDS.get(slug, SHELL_STATISTIC_CARDS_DEFAULT)
    for language, (_tail, _grids, cards) in sorted(tails.items()):
        if sum(cards) != expected:
            issues.append(
                f"{where}: the {language} body ends with {sum(cards)} "
                f".fact-card statistics, expected {expected}"
            )
    return issues


def audit_zero21_article_shell(page_overrides=None):
    """Run the independent shell contract across every dossier."""
    issues = []
    pages = shell_article_pages(page_overrides)
    for slug in sorted(pages):
        issues.extend(audit_zero21_article_shell_page(pages[slug], slug))
    if not page_overrides:
        repaired = ROOT / SHELL_REPAIRED_PAGE
        if not repaired.is_file():
            issues.append(
                f"independent shell: {SHELL_REPAIRED_PAGE} is missing"
            )
        elif hashlib.sha256(
            batch13_historical_bytes().get(SHELL_REPAIRED_PAGE)
            or repaired.read_bytes()
        ).hexdigest() != (
            SHELL_REPAIRED_PAGE_SHA256
        ):
            issues.append(
                f"independent shell: the repaired {SHELL_REPAIRED_PAGE} no "
                "longer matches this module's handwritten bf-04 digest"
            )
    return issues


def zero21_article_shell_statistics():
    """Counts for the passing independent shell summary."""
    pages = shell_article_pages()
    bodies = grids = cards = 0
    for slug in sorted(pages):
        article = pages[slug].find("article")
        if article is None:
            continue
        for body in shell_language_bodies(article):
            bodies += 1
            _tail, grid_count, card_counts = shell_tail_signature(body)
            grids += grid_count
            cards += sum(card_counts)
    return {
        "pages": len(pages),
        "bodies": bodies,
        "grids": grids,
        "cards": cards,
        "phrases": len(SHELL_READER_INSTRUCTIONS) + 1,
    }


ZERO21_SHELL_SELF_TEST_PAGES = (
    "2026-report", "liu-xiaobo", "tiananmen-1989", "xinjiang-camps",
)


def zero21_article_shell_negative_self_test():
    """Eight named, real in-memory shell mutations.  Returns (ok, total, misses)."""
    misses = []
    total = 0

    def page(slug):
        return BeautifulSoup(
            (ROOT / "posts" / f"{slug}.html").read_text(encoding="utf-8"),
            "html.parser",
        )

    clean = {
        slug: not audit_zero21_article_shell_page(page(slug), slug)
        for slug in ZERO21_SHELL_SELF_TEST_PAGES
    }

    def graft(markup, parent):
        for node in list(BeautifulSoup(markup, "html.parser").contents):
            parent.append(node.extract())

    def record(label, slug, soup, needles):
        nonlocal total
        total += 1
        found = audit_zero21_article_shell_page(soup, slug)
        if clean[slug] and all(
            any(needle in issue for issue in found) for needle in needles
        ):
            return
        misses.append(label)

    def record_ledger(label, overrides, needles):
        nonlocal total
        total += 1
        found = [
            issue
            for issue in batch12_browser_independent_issues(overrides)
            if "digest changed" not in issue
        ]
        if all(any(needle in issue for issue in found) for needle in needles):
            return
        misses.append(label)

    # z1 - a loose legacy block back under <article>.
    mutated = page("2026-report")
    graft(
        "<h2>如何使用本頁</h2><p>本頁適合快速查閱的讀者。</p>",
        mutated.find("article"),
    )
    record(
        "z1 loose how-to-use block restored under <article>",
        "2026-report", mutated,
        ("hangs directly off <article>", "owned by no language body",
         "如何使用本頁"),
    )

    # z2 - one language loses its whole statistics grid.
    mutated = page("2026-report")
    grid = mutated.select_one(
        f'[{SHELL_BODY_ATTRIBUTE}="fr"] div.{SHELL_GRID_CLASS}'
    )
    assert grid is not None
    grid.decompose()
    record(
        "z2 one language's .fact-grid deleted",
        "2026-report", mutated,
        ("closing .fact-grid/.fact-card structure differs",
         "the fr body ends with 0 .fact-card"),
    )

    # z3 - a section-less visible heading inside a language body.
    mutated = page("liu-xiaobo")
    body = mutated.select_one(f'[{SHELL_BODY_ATTRIBUTE}="nl"]')
    assert body is not None
    graft("<h2>Aanvullende opmerking</h2><p>Losse alinea.</p>", body)
    record(
        "z3 section-less visible <h2> inserted into a language body",
        "liu-xiaobo", mutated,
        (f"with no {SHELL_SECTION_ATTRIBUTE}",),
    )

    # z4 - one language body reparented out of the shared container.
    mutated = page("2026-report")
    body = mutated.select_one(f'[{SHELL_BODY_ATTRIBUTE}="ja"]')
    article = mutated.find("article")
    assert body is not None and article is not None
    article.append(body.extract())
    record(
        "z4 one language body reparented out of the shared container",
        "2026-report", mutated,
        ("hang off more than one parent element",),
    )

    # z5 - Chinese source-precedence disclaimer in the prose.
    mutated = page("tiananmen-1989")
    target = mutated.select_one(f'[{SHELL_BODY_ATTRIBUTE}="zh"] p')
    assert target is not None
    target.append("本頁僅整理公開來源，具體個案以原始報告為準")
    record(
        "z5 Chinese 本頁僅整理…以原始報告為準 disclaimer injected",
        "tiananmen-1989", mutated,
        ("本頁僅整理", "以原始報告為準"),
    )

    # z6 - English reader instruction in the prose.
    mutated = page("xinjiang-camps")
    target = mutated.select_one(f'[{SHELL_BODY_ATTRIBUTE}="en"] p')
    assert target is not None
    target.append(" This page summarizes public sources only.")
    record(
        "z6 English 'summarizes public sources only' instruction injected",
        "xinjiang-camps", mutated,
        ("summarizes public sources only",),
    )

    # z7/z8 - fix-ledger mutations, rejected without the byte freeze.
    fixes_text = BATCH12_BROWSER_FIXES_PATH.read_text(encoding="utf-8")
    header, _newline, body_text = fixes_text.partition("\n")
    rows = [line.split("\t") for line in body_text.rstrip("\n").split("\n")]
    id_column = BATCH12_BROWSER_FIX_COLUMNS.index("fix_id")
    after_column = BATCH12_BROWSER_FIX_COLUMNS.index("sha256_after")

    def override(cells):
        payload = "\n".join("\t".join(row) for row in cells)
        return {
            BATCH12_BROWSER_RELATIVES[1]:
                f"{header}\n{payload}\n".encode("utf-8"),
        }

    forged = [list(row) for row in rows]
    for row in forged:
        if row[id_column] == SHELL_REPAIRED_FIX_ID:
            row[after_column] = "f" * 64
    record_ledger(
        "z7 bf-04 sha256_after forged away from the repaired 2026-report",
        override(forged),
        ("sha256_after disagrees with this module's handwritten digest",
         "sha256_after does not match the repaired posts/2026-report.html"),
    )
    rolled_back = [
        list(row) for row in rows if row[id_column] != SHELL_REPAIRED_FIX_ID
    ]
    record_ledger(
        "z8 fix ledger rolled back so the article-shell repair row is gone",
        override(rolled_back),
        (f"rows, expected {BATCH12_BROWSER_FIX_ROWS}",
         "does not cover exactly the listed repaired files",
         f"must carry exactly one {SHELL_REPAIRED_FIX_ID} row"),
    )
    return total - len(misses), total, misses


def audit_batch12_wiring(source_text=None):
    source_text = (
        source_text
        if source_text is not None
        else Path(__file__).read_text(encoding="utf-8")
    )
    live = re.search(
        r"def audit_live\(pages\):(?P<body>.*?)(?=\ndef mutation_self_test\()",
        source_text, re.S,
    )
    main = re.search(
        r"def main\(\):(?P<body>.*?)(?=\nif __name__ ==)", source_text, re.S,
    )
    audit = re.search(
        r"\ndef audit_batch12\(\n(?P<body>.*?)"
        r"(?=\ndef batch12_negative_self_test\()",
        source_text, re.S,
    )
    issues = []
    live_call = "issues.extend(audit_batch12(live_pages))"
    self_call = "batch12_self_test = batch12_negative_self_test(live_pages)"
    browser_call = (
        "issues.extend(batch12_browser_independent_issues(browser_overrides))"
    )
    shell_call = (
        "issues.extend(audit_zero21_article_shell(shell_overrides))"
    )
    shell_self_call = (
        "shell_self_test = zero21_article_shell_negative_self_test()"
    )
    if live is None or live.group("body").count(live_call) != 1:
        issues.append("batch12 authoritative audit_live wiring is absent")
    if main is None or main.group("body").count(self_call) != 1:
        issues.append("batch12 named self-test wiring is absent")
    if audit is None or audit.group("body").count(browser_call) != 1:
        issues.append(
            "batch12 independent browser acceptance wiring is absent"
        )
    if audit is None or audit.group("body").count(shell_call) != 1:
        issues.append(
            "independent article-shell gate wiring is absent from audit_batch12"
        )
    if main is None or main.group("body").count(shell_self_call) != 1:
        issues.append("independent article-shell self-test wiring is absent")
    return issues


def audit_batch12(
    pages, *, script_text=None, reread_rows=None, contract_rows=None,
    source_rows=None, card_delta_rows=None, reaccess_rows=None,
    correction_rows=None, source_date_payload=None, frozen_overrides=None,
    browser_overrides=None, shell_overrides=None, source_text=None,
):
    issues = []
    issues.extend(audit_batch12_pages(pages))
    issues.extend(audit_batch12_sources(pages))
    issues.extend(audit_batch12_cards(script_text, card_delta_rows))
    ledger_issues, _stats = audit_batch12_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    issues.extend(ledger_issues)
    issues.extend(audit_batch12_source_artifacts(
        reaccess_rows=reaccess_rows, correction_rows=correction_rows,
        source_date_payload=source_date_payload,
    ))
    issues.extend(audit_batch12_frozen(frozen_overrides))
    issues.extend(batch12_browser_independent_issues(browser_overrides))
    issues.extend(audit_zero21_article_shell(shell_overrides))
    issues.extend(audit_batch12_wiring(source_text))
    return issues


def batch12_negative_self_test(pages):
    """Run named, real DOM/card/ledger/source/freeze successor mutations.

    Batch thirteen revised 49 dossiers after batch12 completed, so the
    mutations are applied to the reconstructed completed-batch12 DOM rather
    than to the served pages.
    """
    pages, _batch13_rewind_issues = batch13_historical_state(pages)
    names = []
    misses = []
    page_baseline = audit_batch12_pages(pages)
    source_baseline = audit_batch12_sources(pages)
    card_baseline = audit_batch12_cards()
    artifact_baseline = audit_batch12_source_artifacts()
    freeze_baseline = audit_batch12_frozen()
    wiring_baseline = audit_batch12_wiring()
    # Batch12 mutations are applied to its own completed ledger state.
    reread_rows, _ = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch12 self-test reread",
    )
    reread_rows = reread_rows[:BATCH12_FINAL_REREAD_ROWS]
    contract_rows, _ = batch9_final2_load_tsv(
        BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
        "batch12 self-test contract",
    )
    contract_rows = contract_rows[:BATCH12_FINAL_CONTRACT_ROWS]
    source_rows, _ = batch9_final2_load_tsv(
        BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
        "batch12 self-test source",
    )
    source_rows = source_rows[:BATCH12_FINAL_SOURCE_ROWS]
    ledger_baseline, _ = audit_batch12_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    )
    card_delta_rows, _ = batch9_final2_load_tsv(
        BATCH12_CARD_DELTA_PATH, BATCH12_CARD_DELTA_COLUMNS,
        "batch12 self-test card delta",
    )
    reaccess_rows, _ = batch12_load_generic_tsv(BATCH12_REACCESS_PATH)
    correction_rows, _ = batch12_load_generic_tsv(
        BATCH12_DATE_CORRECTION_PATH
    )

    def record(name, caught, baseline=()):
        names.append(name)
        if baseline or not caught:
            detail = f" (baseline: {baseline[0]})" if baseline else ""
            misses.append(name + detail)

    def clone_page(slug):
        mutated = dict(pages)
        mutated[slug] = deepcopy(pages[slug])
        return mutated

    def replace_node_text(node, old, new=""):
        if node is None:
            return False
        for child in node.find_all(string=True):
            value = str(child)
            if old in value:
                child.replace_with(value.replace(old, new, 1))
                return True
        return False

    def inject(phrase, slug="2026-report", target_id="2026-report-overview-1"):
        mutated = clone_page(slug)
        node = batch12_target_node(mutated, slug, "en", target_id)
        node.append(" " + phrase)
        return bool(audit_batch12_pages(mutated))

    # 01-07. Every generic editorial/disclaimer category is inserted into a
    # real BeautifulSoup target, not a fixture string.
    for number, phrase, label in (
        ("01", "This dossier assembles records.", "This dossier"),
        ("02", "These records cannot substitute for case evidence.", "cannot substitute"),
        ("03", "The sources have different evidentiary roles.", "different evidentiary roles"),
        ("04", "Resident materials are not official conclusions.", "not official conclusions"),
        ("05", "Silence cannot prove that risk ended.", "silence cannot prove"),
        ("06", "Original links and timestamps must be supplied.", "original links/timestamps"),
        ("07", "Git commits and web archives must be supplied.", "Git/web archive checklist"),
    ):
        record(
            f"{number} generic {label} injection",
            inject(phrase), page_baseline,
        )

    # 08. Delete a case actor while leaving institutional and numerical text.
    mutated = clone_page("transnational-repression")
    node = batch12_target_node(
        mutated, "transnational-repression", "en",
        "transnational-repression-timeline-6",
    )
    changed = replace_node_text(node, "The U.S. Department of Justice", "")
    record(
        "08 TNR case-actor deletion",
        changed and bool(audit_batch12_pages(mutated)), page_baseline,
    )

    # 09. Exchange the two actual critical nodes, including their prose.
    mutated = clone_page("2026-report")
    rights = batch12_target_node(
        mutated, "2026-report", "en", "2026-report-rights-analysis",
    )
    protection = batch12_target_node(
        mutated, "2026-report", "en", "2026-report-protection",
    )
    rights_span = rights.select_one("[data-critical-case]")
    protection_span = protection.select_one("[data-critical-case]")
    right_text, protection_text = (
        batch12_text(rights_span), batch12_text(protection_span),
    )
    rights_span.clear()
    rights_span.append(protection_text)
    protection_span.clear()
    protection_span.append(right_text)
    record(
        "09 rights/protection DOM swap",
        bool(audit_batch12_pages(mutated)), page_baseline,
    )

    # 10-12. Delete state action, remedy, and a reviewed source-ref.
    mutated = clone_page("henan-bank-depositor-protests")
    node = batch12_target_node(
        mutated, "henan-bank-depositor-protests", "en",
        "henan-bank-depositor-protests-state-2",
    )
    changed = replace_node_text(node, "Police deployed at the protest", "")
    record(
        "10 state-actor/action deletion",
        changed and bool(audit_batch12_pages(mutated)), page_baseline,
    )
    mutated = clone_page("zhang-zhan")
    node = batch12_target_node(
        mutated, "zhang-zhan", "en", "zhang-zhan-protection",
    )
    changed = replace_node_text(node, "effective independent remedy", "")
    record(
        "11 effective-remedy deletion",
        changed and bool(audit_batch12_pages(mutated)), page_baseline,
    )
    mutated = clone_page("shanghai-lockdown")
    node = batch12_target_node(
        mutated, "shanghai-lockdown", "en", "shanghai-lockdown-evidence-1",
    )
    node["data-source-ref"] = "s1"
    record(
        "12 target data-source-ref mutation",
        bool(audit_batch12_pages(mutated)), page_baseline,
    )

    # 13-21. Named page-specific regressions.
    for number, slug, language, target_id, phrase, label in (
        (
            "13", "2026-report", "de", "2026-report-evidence-3",
            "außeronline Behandlung", "2026 German außeronline",
        ),
        (
            "14", "2026-report", "ja", "2026-report-evidence-3",
            "線下", "2026 Japanese Chinese residue",
        ),
        (
            "15", "henan-bank-depositor-protests", "de",
            "henan-bank-depositor-protests-state-2", " Zivil ",
            "Henan isolated Zivil",
        ),
        (
            "16", "ningbo-xiaoluoxi-medical-case", "en",
            "ningbo-xiaoluoxi-medical-case-protection",
            " Silence cannot prove that risk ended.",
            "Ningbo silence disclaimer",
        ),
        (
            "17", "shanghai-lockdown", "en",
            "shanghai-lockdown-evidence-2",
            " Resident videos are not official conclusions.",
            "Shanghai official-conclusion disclaimer",
        ),
        (
            "18", "terminus2049-chen-mei-cai-wei", "en",
            "terminus2049-chen-mei-cai-wei-evidence-1",
            " GitHub records detention and sentencing.",
            "Terminus GitHub overclaim",
        ),
        (
            "19", "zhang-zhan", "en", "zhang-zhan-protection",
            " He and his lawyers remained at risk.", "Zhang male pronoun",
        ),
        (
            "20", "zhang-zhan", "en", "zhang-zhan-evidence-1",
            " Updated case profile.", "Zhang Updated case profile",
        ),
        (
            "21", "transnational-repression-2026", "ja",
            "transnational-repression-2026-state-machinery-1",
            " 中国公安省", "TNR2026 中国公安省",
        ),
    ):
        if number == "15":
            caught = []
            for variant_language, variant in (
                ("en", " plainclothes "),
                ("de", " Zivil "),
                ("fr", " les civils "),
                ("nl", " de burgerkleding "),
            ):
                variant_pages = clone_page(slug)
                variant_node = batch12_target_node(
                    variant_pages, slug, variant_language, target_id,
                )
                variant_node.append(variant)
                caught.append(bool(audit_batch12_pages(variant_pages)))
            record(
                "15 Henan isolated plainclothes/Zivil/les civils/"
                "de burgerkleding injection",
                all(caught), page_baseline,
            )
            continue
        mutated = clone_page(slug)
        node = batch12_target_node(mutated, slug, language, target_id)
        node.append(phrase)
        record(
            f"{number} {label} injection",
            bool(audit_batch12_pages(mutated)), page_baseline,
        )

    caught = []
    for language, phrase in (
        ("ja", "無料の手続き"), ("ko", "무료 프로세스"),
        ("de", "kostenloses Verfahren"), ("fr", "processus gratuit"),
    ):
        mutated = clone_page("jiang-tianyong")
        node = batch12_target_node(
            mutated, "jiang-tianyong", language,
            "jiang-tianyong-timeline-3",
        )
        node.append(" " + phrase)
        caught.append(bool(audit_batch12_pages(mutated)))
    record(
        "22 Jiang four-language free-procedure mistranslation",
        all(caught), page_baseline,
    )

    mutated = clone_page("transnational-repression-2026")
    node = batch12_target_node(
        mutated, "transnational-repression-2026", "en",
        "transnational-repression-2026-state-machinery-1",
    )
    changed = replace_node_text(
        node, "technical evidence to attribute", "a statement to condemn",
    )
    record(
        "23 UK technical-attribution weakened to condemnation",
        changed and bool(audit_batch12_pages(mutated)), page_baseline,
    )

    # 24-27. Each forbidden old TNR date is placed in a real timeline node.
    for number, index, wrong in (
        ("24", 3, "2014-01-01"),
        ("25", 0, "2015-10-17"),
        ("26", 2, "2020-07-01"),
        ("27", 6, "2024-05-09"),
    ):
        mutated = clone_page("transnational-repression")
        body = mutated["transnational-repression"].select_one(
            '[data-language-body="en"]'
        )
        node = body.select("ol.timeline-list > li")[index]
        node["data-timeline-date"] = wrong
        if number == "27":
            node["data-source-ref"] = "s1"
        node.find("b", recursive=False).string = wrong + "："
        record(
            f"{number} old TNR date {wrong}",
            bool(audit_batch12_pages(mutated)), page_baseline,
        )

    # 28. Restore the old s1 dynamic URL/date in actual source DOM.
    mutated = clone_page("transnational-repression")
    for body in mutated["transnational-repression"].select(
        "[data-language-body]"
    ):
        source = body.select_one('[data-source-id="s1"]')
        source["data-source-date"] = "2021-01-15"
        source.a["href"] = "https://freedomhouse.org/report/transnational-repression"
        source.time["datetime"] = "2021-01-15"
        source.time.string = "2021-01-15"
    record(
        "28 TNR s1 old URL/date restoration",
        bool(audit_batch12_sources(mutated)), source_baseline,
    )

    # 29-30. Mutate real localized s2/s5 source anchors.
    caught = []
    for language, wrong in (
        ("ja", "無料の「失踪」書店"), ("ko", "무료 서점"),
        ("es", "libreros gratis"), ("de", "kostenlose Buchhändler"),
        ("fr", "libraires gratuits"), ("no", "gratis bokhandlere"),
        ("nl", "gratis boekverkopers"), ("it", "librai gratuiti"),
    ):
        mutated = clone_page("transnational-repression")
        anchor = mutated["transnational-repression"].select_one(
            f'[data-language-body="{language}"] [data-source-id="s2"] a'
        )
        anchor.string = "Human Rights Watch — " + wrong
        caught.append(bool(audit_batch12_sources(mutated)))
    record(
        "29 TNR s2 release-to-free mistranslation",
        all(caught), source_baseline,
    )
    mutated = clone_page("transnational-repression")
    anchor = mutated["transnational-repression"].select_one(
        '[data-language-body="en"] [data-source-id="s5"] a'
    )
    anchor.string = (
        "U.S. Department of Justice — Nine Defendants Replaced"
    )
    record(
        "30 TNR superseding-indictment mistranslation",
        bool(audit_batch12_sources(mutated)), source_baseline,
    )

    # 31-33. Delete DOJ-specific allegations or upgrade them to conviction.
    mutated = clone_page("transnational-repression")
    node = batch12_target_node(
        mutated, "transnational-repression", "en",
        "transnational-repression-timeline-5",
    )
    caught = all(
        replace_node_text(node, phrase, "")
        for phrase in ("nine defendants", "Operation Fox Hunt")
    )
    record(
        "31 TNR DOJ nine-defendant/Fox-Hunt deletion",
        caught and bool(audit_batch12_pages(mutated)), page_baseline,
    )
    mutated = clone_page("transnational-repression")
    node = batch12_target_node(
        mutated, "transnational-repression", "en",
        "transnational-repression-timeline-6",
    )
    caught = all(
        replace_node_text(node, phrase, "")
        for phrase in ("Fuzhou branch", "deleting communications")
    )
    record(
        "32 TNR Fuzhou/deleted-communications deletion",
        caught and bool(audit_batch12_pages(mutated)), page_baseline,
    )
    mutated = clone_page("transnational-repression")
    node = batch12_target_node(
        mutated, "transnational-repression", "en",
        "transnational-repression-timeline-5",
    )
    node.append(" The nine defendants were convicted.")
    record(
        "33 TNR DOJ allegation upgraded to conviction",
        bool(audit_batch12_pages(mutated)), page_baseline,
    )

    # 34. Add a seventh source to all ten TNR bodies.
    mutated = clone_page("transnational-repression")
    for body in mutated["transnational-repression"].select(
        "[data-language-body]"
    ):
        source_list = body.select_one("ul.source-list")
        extra = deepcopy(source_list.select_one("li[data-source-id]"))
        extra["data-source-id"] = "s7"
        source_list.append(extra)
    record(
        "34 TNR unauthorized seventh source",
        bool(audit_batch12_sources(mutated)), source_baseline,
    )

    # 35. Break a real data-critical-case attribute only.
    mutated = clone_page("2026-report")
    span = batch12_target_node(
        mutated, "2026-report", "en", "2026-report-rights-analysis",
    ).select_one("[data-critical-case]")
    span["data-critical-case"] = "Tampered first sentence."
    record(
        "35 critical-case/visible-first-sentence mismatch",
        bool(audit_batch12_pages(mutated)), page_baseline,
    )

    def mutate_card_field(script, slug, field, replacement):
        match = re.search(
            rf'\{{[^{{}}]*?url:\s*"posts/{re.escape(slug)}\.html"'
            r"[^{}]*?\}", script, re.S,
        )
        if match is None:
            return script
        block = match.group(0)
        changed = re.sub(
            rf'({re.escape(field)}:\s*")[^"]*(")',
            rf"\g<1>{replacement}\g<2>", block, count=1,
        )
        return script[:match.start()] + changed + script[match.end():]

    script_text = (ROOT / "script.js").read_text(encoding="utf-8")
    changed_script = mutate_card_field(
        script_text, "transnational-repression", "excerpt_en",
        "Article 38 and institutions only.",
    )
    record(
        "36 target-card fact-chain deletion",
        changed_script != script_text
        and bool(audit_batch12_cards(changed_script)),
        card_baseline,
    )
    cards, _ = batch9_final2_report_cards(script_text)
    cards = batch14_baseline_card_view(cards)
    non_target_slug = next(
        card["slug"] for card in cards
        if card["slug"] not in BATCH12_CARD_SLUGS
    )
    changed_script = mutate_card_field(
        script_text, non_target_slug, "title_en", "Tampered frozen card",
    )
    record(
        "37 non-target-card field mutation",
        changed_script != script_text
        and bool(audit_batch12_cards(changed_script)),
        card_baseline,
    )
    changed_delta = deepcopy(card_delta_rows)
    changed_delta.pop(0)
    record(
        "38 card-delta row deletion",
        bool(audit_batch12_cards(delta_rows=changed_delta)),
        card_baseline,
    )

    # 39-40. Delete each kind of append row and rewrite every old prefix.
    caught = []
    for kind in ("reread", "contract", "source"):
        changed_reread = deepcopy(reread_rows)
        changed_contract = deepcopy(contract_rows)
        changed_source = deepcopy(source_rows)
        selected, boundary = {
            "reread": (changed_reread, BATCH12_PRE_REREAD_ROWS),
            "contract": (changed_contract, BATCH12_PRE_CONTRACT_ROWS),
            "source": (changed_source, BATCH12_PRE_SOURCE_ROWS),
        }[kind]
        selected.pop(boundary)
        found, _ = audit_batch12_ledgers(
            pages, reread_rows=changed_reread,
            contract_rows=changed_contract, source_rows=changed_source,
        )
        caught.append(bool(found))
    record(
        "39 reread/contract/source append-row deletion",
        all(caught), ledger_baseline,
    )
    caught = []
    for kind in ("reread", "contract", "source"):
        changed_reread = deepcopy(reread_rows)
        changed_contract = deepcopy(contract_rows)
        changed_source = deepcopy(source_rows)
        selected, boundary = {
            "reread": (changed_reread, BATCH12_PRE_REREAD_ROWS),
            "contract": (changed_contract, BATCH12_PRE_CONTRACT_ROWS),
            "source": (changed_source, BATCH12_PRE_SOURCE_ROWS),
        }[kind]
        first_field = next(iter(selected[boundary - 1]))
        selected[boundary - 1][first_field] += " tampered"
        found, _ = audit_batch12_ledgers(
            pages, reread_rows=changed_reread,
            contract_rows=changed_contract, source_rows=changed_source,
        )
        caught.append(bool(found))
    record(
        "40 final7 ledger-prefix rewrite",
        all(caught), ledger_baseline,
    )

    # 41-42. Remove reaccess and explicit source-date correction evidence.
    changed_reaccess = deepcopy(reaccess_rows)
    changed_reaccess.pop(0)
    record(
        "41 one-of-59 source-reaccess row deletion",
        bool(audit_batch12_source_artifacts(reaccess_rows=changed_reaccess)),
        artifact_baseline,
    )
    record(
        "42 TNR s1 correction-trail deletion",
        bool(audit_batch12_source_artifacts(correction_rows=[])),
        artifact_baseline,
    )

    # 43-45. Exercise frozen bytes, additions, and deletions.
    frozen_path = "docs/EDITORIAL_CONTROL_STANDARD.md"
    record(
        "43 non-whitelist frozen-file mutation",
        bool(audit_batch12_frozen({
            frozen_path: (ROOT / frozen_path).read_bytes() + b"\nmutation",
        })),
        freeze_baseline,
    )
    record(
        "44 unapproved file addition",
        bool(audit_batch12_frozen({"batch12-unapproved.txt": b"mutation"})),
        freeze_baseline,
    )
    record(
        "45 non-whitelist file deletion",
        bool(audit_batch12_frozen({frozen_path: None})),
        freeze_baseline,
    )

    # 46. Remove both production entry points from real checker source.
    source_text = Path(__file__).read_text(encoding="utf-8")
    caught = []
    for needle in (
        "    issues.extend(audit_batch12(live_pages))\n",
        "        batch12_self_test = batch12_negative_self_test(live_pages)\n",
    ):
        changed = source_text.replace(needle, "        # removed batch12 entry\n", 1)
        caught.append(
            changed != source_text and bool(audit_batch12_wiring(changed))
        )
    record(
        "46 batch12 audit/self-test wiring deletion",
        all(caught), wiring_baseline,
    )

    # 47. Change the real DOM and all three successor ledgers together.  The
    # historical checker accepted this coordinated forgery because it used the
    # ledgers only for synchronization and did not own an independent answer.
    # Exercise ordinary fact, article-dek, source-entry, timeline, and critical
    # rights/protection nodes.  In every case the forged ledgers must pass their
    # structural checks while the module-owned 567-target rule rejects the DOM.
    def coordinated_target_forgery(slug, language, target_id, false_text):
        mutated = clone_page(slug)
        if target_id == "article-dek":
            node = mutated[slug].select_one(
                f".article-dek .lang-{language}"
            )
        elif target_id.startswith("source-entry:"):
            source_id = target_id.split(":", 1)[1]
            body = mutated[slug].select_one(
                f'[data-language-body="{language}"]'
            )
            node = (
                body.select_one(f'[data-source-id="{source_id}"]')
                if body is not None else None
            )
        else:
            node = batch12_target_node(
                mutated, slug, language, target_id,
            )
        if node is None:
            return False
        node.clear()
        node.append(false_text)
        forged_live = batch12_live_target_text(
            mutated, slug, language, target_id,
        )
        forged_reread = deepcopy(reread_rows)
        forged_contract = deepcopy(contract_rows)
        forged_source = deepcopy(source_rows)
        key = (slug, language, target_id)
        reread_found = False
        contract_found = False
        source_found = False
        for row in forged_reread[BATCH12_PRE_REREAD_ROWS:]:
            if (
                row.get("slug", ""), row.get("language", ""),
                row.get("target_id", ""),
            ) == key:
                row["revised_text"] = forged_live
                reread_found = True
                break
        for row in forged_contract[BATCH12_PRE_CONTRACT_ROWS:]:
            if (
                row.get("slug", ""), row.get("language", ""),
                row.get("target_id", ""),
            ) == key:
                row["required_all"] = (
                    "required:forged subject || required:forged action || "
                    "required:forged consequence || required:forged remedy"
                )
                row["forbidden_any"] = (
                    "old-error:forged old error one || "
                    "old-error:forged old error two"
                )
                contract_found = True
                break
        for row in forged_source[BATCH12_PRE_SOURCE_ROWS:]:
            if (
                row.get("slug", ""), row.get("language", ""),
                row.get("fact_id", ""),
            ) == key:
                row["current_visible_text"] = forged_live
                source_found = True
                break
        if not (reread_found and contract_found and source_found):
            return False
        forged_ledger_issues, _stats = audit_batch12_ledgers(
            mutated, reread_rows=forged_reread,
            contract_rows=forged_contract, source_rows=forged_source,
        )
        return (
            not forged_ledger_issues
            and bool(audit_batch12_static_targets(mutated))
        )

    coordinated_cases = (
        (
            "fang-bin-citizen-journalist", "ja",
            "fang-bin-citizen-journalist-evidence-2",
            "当局はすべての裁判記録を公開し、家族には完全な司法救済が提供された。",
        ),
        (
            "transnational-repression", "es", "article-dek",
            "Todas las autoridades publicaron los expedientes y no quedó "
            "ningún riesgo transnacional ni falta de reparación.",
        ),
        (
            "transnational-repression", "it", "source-entry:s1",
            "Documento ufficiale completo che prova una tutela già conclusa.",
        ),
        (
            "transnational-repression", "de",
            "transnational-repression-timeline-5",
            "Ein Gericht stellte endgültig fest, dass keine Überwachung und "
            "keine Rückführungsoperation stattgefunden hatte.",
        ),
        (
            "zhang-zhan", "ko", "zhang-zhan-rights-analysis",
            "모든 절차와 의료 기록이 공개되었고 독립적인 구제가 이미 완전히 제공되었다.",
        ),
    )
    record(
        "47 coordinated DOM/reread/contract/source-ledger forgery across "
        "fact/dek/source/timeline/critical targets",
        all(coordinated_target_forgery(*case) for case in coordinated_cases),
        ledger_baseline,
    )

    # 48-60.  Independent browser-acceptance mutations.  Each one rewrites the
    # real ledger bytes in memory and must produce a *semantic* rejection, so
    # no case can be satisfied by the SHA-256 freeze alone.
    browser_baseline = batch12_browser_independent_issues()
    browser_pages = batch12_browser_independent_pages()
    acceptance_text = BATCH12_BROWSER_ACCEPTANCE_PATH.read_text(
        encoding="utf-8"
    )
    fixes_text = BATCH12_BROWSER_FIXES_PATH.read_text(encoding="utf-8")
    observations_text = BATCH12_OBSERVATIONS_PATH.read_text(encoding="utf-8")
    acceptance_header, _newline, acceptance_body = acceptance_text.partition(
        "\n"
    )
    acceptance_lines = acceptance_body.rstrip("\n").split("\n")
    fixes_header, _fixes_newline, fixes_body = fixes_text.partition("\n")
    fixes_lines = fixes_body.rstrip("\n").split("\n")

    def browser_column(name):
        return BATCH12_BROWSER_COLUMNS.index(name)

    def browser_cells():
        return [line.split("\t") for line in acceptance_lines]

    def browser_override(cell_rows):
        body = "\n".join("\t".join(cells) for cells in cell_rows)
        return {
            BATCH12_BROWSER_RELATIVES[0]:
                f"{acceptance_header}\n{body}\n".encode("utf-8"),
        }

    def browser_edit(index, column, value):
        cell_rows = browser_cells()
        cell_rows[index][browser_column(column)] = value
        return browser_override(cell_rows)

    def fixes_override(cell_rows):
        body = "\n".join("\t".join(cells) for cells in cell_rows)
        return {
            BATCH12_BROWSER_RELATIVES[1]:
                f"{fixes_header}\n{body}\n".encode("utf-8"),
        }

    def browser_semantic_caught(browser_overrides):
        return any(
            "digest changed" not in issue
            for issue in batch12_browser_independent_issues(
                browser_overrides, browser_pages
            )
        )

    def browser_digest_caught(browser_overrides):
        return any(
            "digest changed" in issue
            for issue in batch12_browser_independent_issues(
                browser_overrides, browser_pages
            )
        )

    def browser_index(predicate):
        for index, cells in enumerate(browser_cells()):
            if predicate(cells):
                return index
        return -1

    article_index = browser_index(
        lambda cells: cells[browser_column("page")]
        not in BATCH12_BROWSER_PUBLIC_PAGES
    )
    public_index = browser_index(
        lambda cells: cells[browser_column("page")]
        in BATCH12_BROWSER_PUBLIC_PAGES
    )
    mobile_index = browser_index(
        lambda cells: cells[browser_column("viewport")]
        == BATCH12_BROWSER_MOBILE_VIEWPORT
    )
    article_language = (
        browser_cells()[article_index][browser_column("lang")]
        if article_index >= 0 else ""
    )
    deleted_rows = browser_cells()
    if mobile_index >= 0:
        del deleted_rows[mobile_index]
    record(
        "48 independent browser acceptance unit row deleted",
        mobile_index >= 0
        and browser_semantic_caught(browser_override(deleted_rows)),
        browser_baseline,
    )
    record(
        "49 independent browser acceptance verdict flipped to FAIL",
        browser_semantic_caught(
            browser_edit(article_index, "result", "FAIL")
        ),
        browser_baseline,
    )
    record(
        "50 independent browser acceptance verdict replaced by an unknown "
        "value",
        browser_semantic_caught(
            browser_edit(public_index, "result", "PASS_ASSUMED")
        ),
        browser_baseline,
    )
    duplicated_rows = browser_cells()
    duplicated_rows[1][browser_column("unit_id")] = (
        duplicated_rows[0][browser_column("unit_id")]
    )
    record(
        "51 independent browser acceptance duplicate unit_id forged",
        browser_semantic_caught(browser_override(duplicated_rows)),
        browser_baseline,
    )
    record(
        "52 independent browser acceptance illegal viewport recorded",
        browser_semantic_caught(
            browser_edit(article_index, "viewport", "1280x901")
        ),
        browser_baseline,
    )
    downgraded_rows = browser_cells()
    reload_column = browser_column("reload_method")
    for cells in downgraded_rows:
        if cells[reload_column] == BATCH12_BROWSER_REAL_NAVIGATION:
            cells[reload_column] = "same_origin_iframe"
    record(
        "53 independent browser acceptance ten-language real-navigation "
        "coverage removed",
        browser_semantic_caught(browser_override(downgraded_rows)),
        browser_baseline,
    )
    record(
        "54 independent browser acceptance console error recorded as passing",
        browser_semantic_caught(
            browser_edit(article_index, "console_errors", "1")
        ),
        browser_baseline,
    )
    record(
        "55 independent browser acceptance overflow/header-occlusion recorded "
        "as passing",
        browser_semantic_caught(
            browser_edit(article_index, "overflow_px", "13")
        )
        and browser_semantic_caught(
            browser_edit(mobile_index, "header_occlusion_px", "7")
        )
        and browser_semantic_caught(
            browser_edit(article_index, "long_source_title_overflow", "13")
        ),
        browser_baseline,
    )
    record(
        "56 independent browser acceptance source_ids/timeline_nodes/"
        "section_order/h1 contradict the re-parsed DOM",
        browser_semantic_caught(
            browser_edit(article_index, "source_ids", "q26-s1,q26-s2")
        )
        and browser_semantic_caught(
            browser_edit(article_index, "timeline_nodes", "99")
        )
        and browser_semantic_caught(
            browser_edit(
                article_index, "section_order",
                "overview>timeline>evidence>sources",
            )
        )
        and browser_semantic_caught(
            browser_edit(article_index, "h1_text", "Forged headline")
        ),
        browser_baseline,
    )
    record(
        "57 independent browser acceptance persistence/mobile-menu evidence "
        "forged",
        browser_semantic_caught(
            browser_edit(
                article_index, "persisted_lang",
                "de" if article_language != "de" else "fr",
            )
        )
        and browser_semantic_caught(
            browser_edit(mobile_index, "mobile_menu", "n/a")
        )
        and browser_semantic_caught(
            browser_edit(mobile_index, "escape_focus_restore", "n/a")
        ),
        browser_baseline,
    )
    fix_cells = [line.split("\t") for line in fixes_lines]
    forged_fix = [list(cells) for cells in fix_cells]
    forged_fix[0][BATCH12_BROWSER_FIX_COLUMNS.index("sha256_after")] = (
        "0" * 64
    )
    record(
        "58 independent browser fix ledger no longer matches the repaired "
        "files",
        browser_semantic_caught(fixes_override(forged_fix))
        and browser_semantic_caught(
            fixes_override([list(cells) for cells in fix_cells][1:])
        ),
        browser_baseline,
    )
    record(
        "59 independent browser ledger bytes tampered below the semantic "
        "gates",
        browser_digest_caught(
            browser_edit(article_index, "checked_at", "2026-07-26")
        )
        and browser_digest_caught(
            {BATCH12_BROWSER_RELATIVES[1]: fixes_text.rstrip("\n") + " \n"}
        )
        and browser_digest_caught(
            {
                BATCH12_BROWSER_RELATIVES[2]:
                    observations_text.rstrip("\n") + " \n",
            }
        ),
        browser_baseline,
    )
    browser_wiring_source = Path(__file__).read_text(encoding="utf-8")
    # The needle spans two real source lines so that it matches only the
    # production call inside audit_batch12(), never the literal that
    # audit_batch12_wiring() or this suite carries as an escaped string.
    browser_wiring_needle = (
        "issues.extend(audit_batch12_frozen(frozen_overrides))\n"
        "    issues.extend(batch12_browser_independent_issues("
        "browser_overrides))"
    )
    browser_wiring_position = browser_wiring_source.find(
        browser_wiring_needle
    )
    browser_wiring_mutation = (
        browser_wiring_source[:browser_wiring_position]
        + "issues.extend(audit_batch12_frozen(frozen_overrides))\n"
        + "    issues.extend([])"
        + browser_wiring_source[
            browser_wiring_position + len(browser_wiring_needle):
        ]
        if browser_wiring_position >= 0
        else browser_wiring_source
    )
    record(
        "60 independent browser acceptance gate deleted from the batch12 "
        "audit wiring",
        browser_wiring_mutation != browser_wiring_source
        and bool(audit_batch12_wiring(browser_wiring_mutation)),
        wiring_baseline,
    )
    if len(names) != 60 or len(set(names)) != 60:
        misses.append(
            f"batch12 named suite cardinality is {len(names)}, expected 60"
        )
    return len(names) - len(misses), len(names), misses


# ---------------------------------------------------------------------------
# Independent batch-thirteen duty-subject successor.
#
# Everything below is handwritten inside this module.  The slug list, the ten
# duty-subject patterns, the allowed-compound list, the named-authority list,
# every digest and every row count are NOT imported from
# tools/check_languages.py and are not derived from anything it owns, so the
# two gates can disagree.  The DOM is re-parsed here with this module's own
# ``data-language-body`` selector.
#
# Batch thirteen replaced bare "the state" duty subjects in the visible
# rights-analysis and protection columns with a named authority on 446 fact
# nodes across 49 dossiers.  History is not rewritten: the 16563 / 7598 /
# 10630-row predecessor prefixes are asserted byte-for-byte, every historical
# gate keeps its own assertions and is replayed against a reconstructed
# pre-batch13 preimage, and the reconstruction is proved by the recorded
# per-page SHA-256 digests.
# ---------------------------------------------------------------------------
