def batch13_successor_artifact(relative):
    """True for batch13-only audit artifacts frozen by their own digest."""
    return (
        relative.startswith("tools/data/batch13-")
        and relative.endswith(".tsv")
    )


def batch13_visible(value):
    """Normalize visible text without depending on NBSP or line wrapping."""
    return " ".join((value or "").replace(" ", " ").split())


# ---------------------------------------------------------------------------
# Batch fourteen: ten new overseas-protest dossiers.
#
# Batch fourteen changed already-frozen files in three reversible ways, so the
# pre-batch-14 bytes are reconstructed from the live bytes and each
# reconstruction is proved against a digest captured before the edit.  This
# module derives that state independently of check_languages.py.
BATCH14_NEW_SLUGS = (
    "zhang-yadi-tibet-advocacy",
    "hu-yang-leiden-student",
    "sydney-student-secession-case",
    "yuen-ching-ting-japan-posts",
    "fu-cha-gusa-publisher",
    "yang-zewei-ban-gfw",
    "luo-daiqing-twitter-case",
    "jiang-yefei-thailand-deportation",
    "dong-guangping-thailand-deportation",
    "yiu-man-tin-morning-bell",
)
BATCH14_NEW_SLUG_SET = frozenset(BATCH14_NEW_SLUGS)
BATCH14_NEW_FILENAMES = frozenset(f"{slug}.html" for slug in BATCH14_NEW_SLUGS)
BATCH14_NEW_POST_FILES = frozenset(f"posts/{slug}.html" for slug in BATCH14_NEW_SLUGS)
BATCH14_PAGE_PREIMAGE_RELATIVE = "tools/data/batch14-page-preimage.tsv"
BATCH14_PAGE_PREIMAGE_PATH = ROOT / BATCH14_PAGE_PREIMAGE_RELATIVE
BATCH14_NEW_AUDIT_FILES = frozenset(
    {BATCH14_PAGE_PREIMAGE_RELATIVE} | set(BATCH14_NEW_POST_FILES)
)
BATCH14_STYLE_VERSION_AFTER = "?v=20260727-header-fix"
BATCH14_STYLE_RULE = (
    "\n.site-title h1 {\n"
    "    font-size: clamp(1.05rem, 1.9vw, 1.8rem);\n"
    "    line-height: 1.2;\n"
    "    white-space: nowrap;\n"
    "    margin: 0;\n"
    "}\n"
)
_BATCH14_PREIMAGE_BYTES = None


def batch14_preimage_text(relative, current, style_version_before, restores_timeline_class):
    """Reverse the three batch-14 edits on one file."""
    text = current
    if relative == "style.css":
        text = text.replace(BATCH14_STYLE_RULE, "", 1)
    elif relative == "script.js":
        text = "\n".join(
            line for line in text.split("\n")
            if not any(
                f'url: "posts/{slug}.html"' in line for slug in BATCH14_NEW_SLUGS
            )
        )
    if restores_timeline_class:
        text = text.replace('class="timeline-list"', 'class="timeline timeline-list"')
    return text.replace(
        "style.css" + BATCH14_STYLE_VERSION_AFTER,
        "style.css" + style_version_before,
    )


def batch14_historical_bytes():
    """Pre-batch14 bytes keyed by repository-relative path, digest-authenticated."""
    global _BATCH14_PREIMAGE_BYTES
    if _BATCH14_PREIMAGE_BYTES is None:
        payloads = {}
        if BATCH14_PAGE_PREIMAGE_PATH.exists():
            with BATCH14_PAGE_PREIMAGE_PATH.open(encoding="utf-8", newline="") as handle:
                for row in csv.DictReader(handle, delimiter="\t"):
                    relative = row.get("relative_path", "")
                    path = ROOT / relative
                    if not relative or not path.exists():
                        continue
                    rebuilt = batch14_preimage_text(
                        relative,
                        path.read_text(encoding="utf-8"),
                        row.get("style_version_before", ""),
                        row.get("restores_timeline_class", "") == "yes",
                    ).encode("utf-8")
                    if hashlib.sha256(rebuilt).hexdigest() == row.get("sha256_before", ""):
                        payloads[relative] = rebuilt
        # The source-date ledger is protected by batch thirteen and appended to
        # by batch fourteen; its pre-append bytes are the authenticated 294-row
        # prefix, rebuilt here independently of check_languages.py.
        sdl = ROOT / "tools/data/source-date-ledger.tsv"
        if sdl.exists():
            lines = sdl.read_text(encoding="utf-8").split("\n")
            prefix = "\n".join(lines[:295]).encode("utf-8") + b"\n"
            if hashlib.sha256(prefix).hexdigest() == (
                "767bae5c731e075ff2f66561134354e70207c51e77e9cc04df9ac62f45c5f7e8"
            ):
                payloads["tools/data/source-date-ledger.tsv"] = prefix
        _BATCH14_PREIMAGE_BYTES = payloads
    return _BATCH14_PREIMAGE_BYTES


BATCH12_SOURCE_DATE_BASE_ROWS = 294
BATCH12_SOURCE_DATE_BASE_SHA256 = (
    "767bae5c731e075ff2f66561134354e70207c51e77e9cc04df9ac62f45c5f7e8"
)
BATCH13_SOURCE_LEDGER_FINAL_ROWS = 11076


def batch14_source_date_prefix_bytes():
    """The source-date ledger as every pre-batch14 gate froze it.

    Batch fourteen appends the 51 sources first cited by its ten dossiers.  The
    294-row base stays a byte-authenticated prefix, so a predecessor gate is
    replayed against that prefix rather than relaxed.  If the prefix ever stops
    authenticating, the live bytes are returned and the gate fires as before.
    """
    path = ROOT / "tools/data/source-date-ledger.tsv"
    if not path.exists():
        return b""
    raw = path.read_bytes()
    prefix = "\n".join(
        raw.decode("utf-8").split("\n")[:1 + BATCH12_SOURCE_DATE_BASE_ROWS]
    ).encode("utf-8") + b"\n"
    if hashlib.sha256(prefix).hexdigest() == BATCH12_SOURCE_DATE_BASE_SHA256:
        return prefix
    return raw


def batch14_baseline_card_view(cards):
    """The report-card list as every pre-batch14 gate knew it.

    Batch fourteen inserted ten cards at source position 45.  Removing exactly
    those ten restores the 54-card sequence the older baselines were captured
    against, so each historical gate replays unchanged rather than relaxed.
    """
    return [
        card for card in cards
        if card.get("slug", "") not in BATCH14_NEW_SLUG_SET
    ]


def batch13_live_text(slug):
    """The dossier as it stood at the end of batch thirteen.

    Batch thirteen's preimage is defined against its own successor state.  Batch
    fourteen advanced the style.css token on every page and removed a stray
    timeline class from three of them, so those edits are rewound first and
    batch thirteen's own rewind then runs on the text it was authenticated
    against.  With no batch-14 preimage for the file this is the live text.
    """
    payload = batch14_historical_bytes().get(f"posts/{slug}.html")
    if payload is not None:
        return payload.decode("utf-8")
    return (ROOT / "posts" / f"{slug}.html").read_bytes().decode("utf-8")


def batch13_append_rows(path, columns, label, base_rows):
    rows, issues = batch9_final2_load_tsv(path, columns, label)
    return rows, rows[base_rows:], issues


def batch13_reread_append(rows=None):
    if rows is None:
        rows, _issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch13 reread ledger",
        )
    return rows[BATCH13_PRE_REREAD_ROWS:]


def batch13_body_language(node):
    for parent in node.parents:
        language = parent.get("data-language-body", "")
        if language:
            return language
        for name in parent.get("class", []) or []:
            if name.startswith("lang-"):
                return name[len("lang-"):]
    return ""


def batch13_changed_window(original, revised):
    head = 0
    while (
        head < len(original) and head < len(revised)
        and original[head] == revised[head]
    ):
        head += 1
    tail = 0
    while (
        tail < len(original) - head and tail < len(revised) - head
        and original[len(original) - 1 - tail]
        == revised[len(revised) - 1 - tail]
    ):
        tail += 1
    return head, len(original) - tail, len(revised) - tail


def batch13_preimage_markup(slug, live_text=None, rows=None):
    """Rebuild the byte-exact completed-batch12 markup of one dossier."""
    text = live_text if live_text is not None else batch13_live_text(slug)
    targets = [
        row for row in batch13_reread_append(rows)
        if row.get("slug", "") == slug
    ]
    issues = []
    soup = BeautifulSoup(text, "html.parser")
    for row in targets:
        target_id = row.get("target_id", "")
        language = row.get("language", "")
        label = f"{slug}/{language}/{target_id}"
        order = [
            batch13_body_language(node)
            for node in soup.select(f'[data-fact-id="{target_id}"]')
        ]
        marker = f'data-fact-id="{target_id}"'
        found = [m.start() for m in re.finditer(re.escape(marker), text)]
        if language not in order or len(found) != len(order):
            issues.append(f"batch13 preimage target is not addressable: {label}")
            continue
        position = found[order.index(language)]
        start = text.rfind("<", 0, position)
        opening = re.match(r"<([A-Za-z0-9]+)", text[start:]) if start >= 0 else None
        if opening is None:
            issues.append(f"batch13 preimage element start is missing: {label}")
            continue
        closing = f"</{opening.group(1)}>"
        end = text.find(closing, position)
        if end < 0:
            issues.append(f"batch13 preimage element end is missing: {label}")
            continue
        end += len(closing)
        region = text[start:end]
        original = row.get("original_text", "")
        revised = row.get("revised_text", "")
        head, original_end, revised_end = batch13_changed_window(
            original, revised
        )
        rewound = None
        for grow in range(0, 240, 4):
            left = max(0, head - grow)
            new_fragment = revised[left:min(len(revised), revised_end + grow)]
            old_fragment = original[left:min(len(original), original_end + grow)]
            if revised.count(new_fragment) == 1 and region.count(new_fragment):
                rewound = region.replace(new_fragment, old_fragment)
                break
        if rewound is None:
            issues.append(f"batch13 preimage fragment is not locatable: {label}")
            continue
        text = text[:start] + rewound + text[end:]
    return text, issues


def batch13_historical_markup(slug):
    if slug not in BATCH13_SLUG_SET:
        return batch13_live_text(slug)
    if slug not in _BATCH13_PREIMAGE_CACHE:
        text, issues = batch13_preimage_markup(slug)
        _BATCH13_PREIMAGE_CACHE[slug] = text
        _BATCH13_PREIMAGE_ISSUES[slug] = issues
    return _BATCH13_PREIMAGE_CACHE[slug]


def batch13_historical_bytes():
    """Completed-batch12 bytes keyed by repository-relative path."""
    return {
        f"posts/{slug}.html": batch13_historical_markup(slug).encode("utf-8")
        for slug in BATCH13_SLUGS
    }


def batch13_historical_state(live_pages):
    """Replace every batch13-revised page with its authenticated preimage."""
    issues = []
    predecessor = dict(live_pages or {})
    for slug in BATCH13_SLUGS:
        markup = batch13_historical_markup(slug)
        issues.extend(_BATCH13_PREIMAGE_ISSUES.get(slug, []))
        if slug in predecessor:
            predecessor[slug] = BeautifulSoup(markup, "html.parser")
    return predecessor, issues


def batch13_historical_pages(slugs):
    return {
        slug: BeautifulSoup(batch13_historical_markup(slug), "html.parser")
        for slug in slugs
    }


def audit_batch13_preimage(page_bytes=None):
    """Prove the 49 recorded transitions really are this repository's."""
    issues = []
    if not BATCH13_PAGE_PREIMAGE_PATH.is_file():
        return [
            "batch13 page preimage manifest is missing: "
            f"{BATCH13_PAGE_PREIMAGE_RELATIVE}"
        ]
    payload = BATCH13_PAGE_PREIMAGE_PATH.read_bytes()
    if hashlib.sha256(payload).hexdigest() != BATCH13_PAGE_PREIMAGE_SHA256:
        issues.append("batch13 page preimage manifest bytes changed")
    rows, load_issues = batch9_final2_load_tsv(
        BATCH13_PAGE_PREIMAGE_PATH, BATCH13_PAGE_PREIMAGE_COLUMNS,
        "batch13 page preimage manifest",
    )
    issues.extend(load_issues)
    if len(rows) != len(BATCH13_SLUGS):
        issues.append(
            f"batch13 page preimage has {len(rows)} rows, expected "
            f"{len(BATCH13_SLUGS)}"
        )
    listed = sorted(row.get("relative_path", "") for row in rows)
    if listed != sorted(f"posts/{slug}.html" for slug in BATCH13_SLUGS):
        issues.append("batch13 page preimage does not list the 49 revised dossiers")
        return issues
    revised = {row.get("slug", "") for row in batch13_reread_append()}
    if revised != BATCH13_SLUG_SET:
        issues.append(
            "batch13 revised dossiers differ from the reread append"
        )
    for row in rows:
        relative = row.get("relative_path", "")
        slug = Path(relative).stem
        before = row.get("sha256_before", "")
        after = row.get("sha256_after", "")
        if (
            not re.fullmatch(r"[0-9a-f]{64}", before)
            or not re.fullmatch(r"[0-9a-f]{64}", after)
            or before == after
        ):
            issues.append(f"batch13 page preimage row is invalid: {relative}")
            continue
        live = (page_bytes or {}).get(relative)
        if live is None:
            live = batch13_live_text(slug).encode("utf-8")
        if hashlib.sha256(live).hexdigest() != after:
            issues.append(
                f"batch13 revised dossier no longer matches sha256_after: {relative}"
            )
        markup, rewind_issues = batch13_preimage_markup(
            slug, live_text=live.decode("utf-8")
        )
        issues.extend(rewind_issues)
        if hashlib.sha256(markup.encode("utf-8")).hexdigest() != before:
            issues.append(
                f"batch13 preimage does not reconstruct sha256_before: {relative}"
            )
    return issues


def batch13_target_node(soup, language, target_id):
    body = soup.select_one(f'[data-language-body="{language}"]')
    if body is None:
        return None
    nodes = body.select(f'[data-fact-id="{target_id}"]')
    return nodes[0] if len(nodes) == 1 else None


def batch13_authority_spans(text, language):
    folded = text.casefold()
    spans = []
    for name in BATCH13_NAMED_AUTHORITIES[language]:
        needle = name.casefold()
        start = folded.find(needle)
        while start >= 0:
            spans.append((start, start + len(needle)))
            start = folded.find(needle, start + 1)
    return spans


def batch13_code_values(value, role):
    return tuple(
        item[len(role):]
        for item in (part.strip() for part in value.split("||"))
        if item.startswith(role)
    )


def batch13_code_clauses(code):
    return [
        batch13_visible(part).casefold()
        for part in code.split("|")
        if batch13_visible(part)
    ]


def batch13_live_map(pages=None, rows=None):
    live_pages = pages or {}
    parsed_live = {}
    parsed_pre = {}
    inventory = {}
    for row in batch13_reread_append(rows):
        slug = row.get("slug", "")
        language = row.get("language", "")
        target_id = row.get("target_id", "")
        if slug not in parsed_live:
            soup = live_pages.get(slug)
            parsed_live[slug] = (
                soup if soup is not None
                else BeautifulSoup(batch13_live_text(slug), "html.parser")
            )
            parsed_pre[slug] = BeautifulSoup(
                batch13_historical_markup(slug), "html.parser"
            )
        node = batch13_target_node(parsed_live[slug], language, target_id)
        earlier = batch13_target_node(parsed_pre[slug], language, target_id)
        if node is None or earlier is None:
            continue
        inventory[(slug, language, target_id)] = {
            "text": batch13_visible(node.get_text(" ", strip=True)),
            "previous": batch13_visible(earlier.get_text(" ", strip=True)),
            "refs": node.get("data-source-ref", ""),
            "column": next(
                (
                    name for name in BATCH13_COLUMNS
                    if target_id.endswith(f"-{name}")
                ),
                "",
            ),
        }
    return inventory


def audit_batch13_ledgers(
    pages=None, *, reread_rows=None, contract_rows=None, source_rows=None,
):
    """Authenticate the batch12 prefixes and exactly 446 linked batch13 rows."""
    issues = []
    for path, count, digest, label in (
        (
            BATCH9_REREAD_PATH, BATCH13_PRE_REREAD_ROWS,
            BATCH13_PRE_REREAD_SHA256, "batch13 completed-batch12 reread prefix",
        ),
        (
            BATCH9_CONTRACT_PATH, BATCH13_PRE_CONTRACT_ROWS,
            BATCH13_PRE_CONTRACT_SHA256,
            "batch13 completed-batch12 contract prefix",
        ),
        (
            BATCH9_SOURCE_LEDGER_PATH, BATCH13_PRE_SOURCE_ROWS,
            BATCH13_PRE_SOURCE_SHA256, "batch13 completed-batch12 source prefix",
        ),
    ):
        issues.extend(batch9_final2_exact_prefix(path, count, digest, label))
    for path, digest, label in zip(
        (BATCH9_REREAD_PATH, BATCH9_CONTRACT_PATH, BATCH9_SOURCE_LEDGER_PATH),
        BATCH13_FINAL_SHA256,
        ("reread", "contract", "source"),
    ):
        if not path.is_file():
            issues.append(f"batch13 full {label} ledger bytes changed")
            continue
        payload = path.read_bytes()
        if label == "source" and hashlib.sha256(payload).hexdigest() != digest:
            # Batch fourteen appends after batch thirteen's final state; replay
            # this digest against that state's prefix.  Anything else fires.
            payload = "\n".join(
                payload.decode("utf-8").split("\n")[
                    :1 + BATCH13_SOURCE_LEDGER_FINAL_ROWS
                ]
            ).encode("utf-8") + b"\n"
        if hashlib.sha256(payload).hexdigest() != digest:
            issues.append(f"batch13 full {label} ledger bytes changed")
    if reread_rows is None:
        reread_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
            "batch13 reread ledger",
        )
        issues.extend(load_issues)
    if contract_rows is None:
        contract_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_CONTRACT_PATH, BATCH9_FINAL2_CONTRACT_COLUMNS,
            "batch13 contract ledger",
        )
        issues.extend(load_issues)
    if source_rows is None:
        source_rows, load_issues = batch9_final2_load_tsv(
            BATCH9_SOURCE_LEDGER_PATH, BATCH9_FINAL2_SOURCE_COLUMNS,
            "batch13 source ledger",
        )
        issues.extend(load_issues)
    for rows, columns, count, digest, kind in zip(
        (reread_rows, contract_rows, source_rows),
        (
            BATCH9_FINAL2_REREAD_COLUMNS, BATCH9_FINAL2_CONTRACT_COLUMNS,
            BATCH9_FINAL2_SOURCE_COLUMNS,
        ),
        (
            BATCH13_PRE_REREAD_ROWS, BATCH13_PRE_CONTRACT_ROWS,
            BATCH13_PRE_SOURCE_ROWS,
        ),
        BATCH13_CANONICAL_PREFIX_SHA256,
        ("reread", "contract", "source"),
    ):
        if batch12_rows_prefix_digest(rows, columns, count) != digest:
            issues.append(
                f"batch13 in-memory {kind} completed-batch12 prefix differs"
            )
    # Batch fourteen appends 1,750 source-ledger rows for its ten new dossiers
    # after batch thirteen's 11,076-row final state.  Every batch13 assertion
    # below is replayed against that final state; the appended rows must all
    # belong to a batch14 dossier, so the append cannot alter a batch13 node.
    if len(source_rows) > BATCH13_FINAL_SOURCE_ROWS:
        stray = sorted({
            r.get("slug", "")
            for r in source_rows[BATCH13_FINAL_SOURCE_ROWS:]
            if r.get("slug", "") not in BATCH14_NEW_SLUG_SET
        })
        if stray:
            issues.append(
                "batch13 source ledger gained rows outside batch14: "
                + ", ".join(stray)
            )
        source_rows = source_rows[:BATCH13_FINAL_SOURCE_ROWS]
    for rows, expected, kind in zip(
        (reread_rows, contract_rows, source_rows),
        (
            BATCH13_FINAL_REREAD_ROWS, BATCH13_FINAL_CONTRACT_ROWS,
            BATCH13_FINAL_SOURCE_ROWS,
        ),
        ("reread", "contract", "source"),
    ):
        if len(rows) != expected:
            issues.append(
                f"batch13 {kind} total is {len(rows)}, expected {expected}"
            )
    reread = reread_rows[BATCH13_PRE_REREAD_ROWS:]
    contracts = contract_rows[BATCH13_PRE_CONTRACT_ROWS:]
    sources = source_rows[BATCH13_PRE_SOURCE_ROWS:]
    reread_keys = [
        (r.get("slug", ""), r.get("language", ""), r.get("target_id", ""))
        for r in reread
    ]
    contract_keys = [
        (r.get("slug", ""), r.get("language", ""), r.get("target_id", ""))
        for r in contracts
    ]
    source_keys = [
        (r.get("slug", ""), r.get("language", ""), r.get("fact_id", ""))
        for r in sources
    ]
    for kind, keys in (
        ("reread", reread_keys),
        ("contract", contract_keys),
        ("source", source_keys),
    ):
        if len(keys) != BATCH13_APPEND_ROWS:
            issues.append(
                f"batch13 {kind} append has {len(keys)} rows, expected "
                f"{BATCH13_APPEND_ROWS}"
            )
        if len(set(keys)) != len(keys):
            issues.append(f"batch13 {kind} append repeats a target")
    if set(reread_keys) != set(contract_keys) or set(reread_keys) != set(
        source_keys
    ):
        issues.append("batch13 three appends do not cover the same 446 nodes")
    chain_tip = {}
    for row in reread_rows[:BATCH13_PRE_REREAD_ROWS]:
        chain_tip[
            (row.get("slug", ""), row.get("language", ""), row.get("target_id", ""))
        ] = row
    live_map = batch13_live_map(pages, reread_rows)
    contract_by_key = dict(zip(contract_keys, contracts))
    source_by_key = dict(zip(source_keys, sources))
    seen_ids = set()
    for key, row in zip(reread_keys, reread):
        slug, language, target_id = key
        label = "/".join(key)
        contract_id = row.get("contract_id", "")
        wanted = f"{BATCH13_PREFIX}{slug}:{language}:fact:{target_id}:"
        if not contract_id.startswith(wanted) or contract_id in seen_ids:
            issues.append(f"batch13 contract id is missing or reused: {label}")
        seen_ids.add(contract_id)
        original = batch13_visible(row.get("original_text", ""))
        revised = batch13_visible(row.get("revised_text", ""))
        if (
            row.get("target_kind", "") != "fact"
            or row.get("result", "") != "PASS_AFTER_REVISION"
            or original == revised
            or "reread:batch13" not in row.get("review_basis", "")
            or len(row.get("issue_found", "").strip()) < 40
            or len(row.get("review_basis", "").strip()) < 100
        ):
            issues.append(f"batch13 reread row is not a real revision: {label}")
        live = live_map.get(key)
        if live is None:
            issues.append(f"batch13 target has no live DOM node: {label}")
        else:
            if revised != live["text"]:
                issues.append(
                    f"batch13 revised text differs from the live DOM: {label}"
                )
            if original != live["previous"]:
                issues.append(
                    f"batch13 original text differs from the preimage DOM: {label}"
                )
            if row.get("source_refs", "") != live["refs"]:
                issues.append(f"batch13 source refs differ from the DOM: {label}")
            if live["column"] not in BATCH13_COLUMNS:
                issues.append(
                    f"batch13 revised a node outside the two columns: {label}"
                )
            names = batch13_authority_spans(live["text"], language)
            before_names = batch13_authority_spans(live["previous"], language)
            if not names:
                issues.append(
                    f"batch13 revision names no qualified authority: {label}"
                )
            elif len(names) <= len(before_names):
                issues.append(
                    f"batch13 revision added no qualified authority: {label}"
                )
        earlier = chain_tip.get(key)
        if earlier is None:
            issues.append(f"batch13 row has no authenticated predecessor: {label}")
        elif batch13_visible(earlier.get("revised_text", "")) != original:
            issues.append(f"batch13 predecessor chain is broken: {label}")

        contract_row = contract_by_key.get(key, {})
        if contract_row.get("contract_id", "") != contract_id or not contract_id:
            issues.append(f"batch13 contract and reread rows disagree: {label}")
        if contract_row.get("target_kind", "") != "fact":
            issues.append(f"batch13 contract target kind is not fact: {label}")
        required = batch13_code_values(
            contract_row.get("required_all", ""), "required:"
        )
        forbidden = batch13_code_values(
            contract_row.get("forbidden_any", ""), "old-error:"
        )
        literals = [
            part.strip()
            for part in contract_row.get("required_all", "").split("||")
        ]
        if (
            len(required) < 3
            or len(required) != len(literals)
            or len({code for code in required if code.strip()}) < 2
        ):
            issues.append(
                f"batch13 contract lacks three required role codes: {label}"
            )
        if len(set(forbidden)) < 1 or len(forbidden) != len(
            [
                part.strip()
                for part in contract_row.get("forbidden_any", "").split("||")
            ]
        ):
            issues.append(f"batch13 contract lacks an old-error code: {label}")
        summary = batch13_visible(contract_row.get("fact_summary", "")).casefold()
        if not all(
            marker in summary
            for marker in ("duty subject", "obligations", "source")
        ):
            issues.append(
                f"batch13 contract summary lacks its three roles: {label}"
            )
        if live is not None:
            visible = live["text"].casefold()
            previous = live["previous"].casefold()
            spans = batch13_authority_spans(live["text"], language)
            for code in required:
                clauses = batch13_code_clauses(code)
                if clauses and any(item not in visible for item in clauses):
                    issues.append(
                        f"batch13 required concept is not visible: {label}"
                    )
                    break
            for code in forbidden:
                needle = batch13_visible(code).casefold()
                if not needle:
                    issues.append(f"batch13 old-error code is empty: {label}")
                    break
                if needle not in previous:
                    issues.append(
                        f"batch13 old-error code was never in the preimage: {label}"
                    )
                    break
                start = visible.find(needle)
                standalone = False
                while start >= 0:
                    if not any(
                        start < end and begin < start + len(needle)
                        for begin, end in spans
                    ):
                        standalone = True
                        break
                    start = visible.find(needle, start + 1)
                if standalone:
                    issues.append(
                        f"batch13 old bare subject is still visible: {label}"
                    )
                    break

        source_row = source_by_key.get(key, {})
        column = source_row.get("section_id", "")
        snapshot = {
            "protection": "reread_protection_current",
            "rights-analysis": "reread_rights_current",
        }.get(column, "")
        if not snapshot or not target_id.endswith(f"-{column}"):
            issues.append(f"batch13 source row column is wrong: {label}")
        elif live is not None:
            if (
                source_row.get("current_visible_text", "")
                != row.get("revised_text", "")
                or source_row.get("reread_revision_text", "")
                != row.get("revised_text", "")
                or source_row.get("reread_result", "") != "PASS_AFTER_REVISION"
                or source_row.get("data_source_ref", "") != live["refs"]
                or not source_row.get("resolution_action", "").startswith(
                    "reread:batch13"
                )
            ):
                issues.append(
                    f"batch13 source row is not wired to the revision: {label}"
                )
            if batch13_visible(source_row.get(snapshot, "")) != original:
                issues.append(
                    f"batch13 source snapshot is not the preimage text: {label}"
                )
            anchor = batch13_visible(source_row.get("visible_subject_anchor", ""))
            if anchor and (
                anchor.casefold() not in live["text"].casefold()
                or not any(
                    anchor.casefold() == name.casefold()
                    for name in BATCH13_NAMED_AUTHORITIES[language]
                )
            ):
                issues.append(
                    f"batch13 source anchor is not a visible authority: {label}"
                )
            if not source_row.get("reread_issue_found", "").strip():
                issues.append(f"batch13 source row lacks its issue detail: {label}")
    return issues


def batch13_column_text(body, column):
    parts = []
    for heading in body.select(f'h2[data-section="{column}"]'):
        for sibling in heading.next_siblings:
            if isinstance(sibling, Tag):
                if sibling.name == "h2":
                    break
                parts.append(sibling.get_text(" ", strip=True))
    return " ".join(parts)


def batch13_bare_duty_spans(text, language):
    allowed = []
    for phrase in BATCH13_DUTY_ALLOWED.get(language, ()):
        start = text.find(phrase)
        while start >= 0:
            allowed.append((start, start + len(phrase)))
            start = text.find(phrase, start + 1)
    spans = []
    for match in BATCH13_DUTY_PATTERNS[language].finditer(text):
        if any(
            match.start() < end and begin < match.end()
            for begin, end in allowed
        ):
            continue
        spans.append((match.start(), match.end()))
    return spans


def audit_batch13_duty_subjects(pages=None):
    """No duty in either audited column may rest on a bare state subject."""
    issues = []
    documents = shell_article_pages(pages)
    if len(documents) != 64:
        issues.append(
            f"batch13 duty-subject scope is {len(documents)} dossiers, expected 64"
        )
    for slug in sorted(documents):
        soup = documents[slug]
        for language in BATCH5_LANGS:
            body = soup.select_one(f'[data-language-body="{language}"]')
            if body is None:
                issues.append(f"{slug}/{language}: batch13 language body is missing")
                continue
            for column in BATCH13_COLUMNS:
                if not body.select(f'h2[data-section="{column}"]'):
                    issues.append(
                        f"{slug}/{language}: batch13 column {column} is missing"
                    )
                    continue
                text = batch13_column_text(body, column)
                for start, end in batch13_bare_duty_spans(text, language):
                    issues.append(
                        f"{slug}/{language}/{column}: duty rests on an "
                        f"unqualified state subject: "
                        f"{text[max(0, start - 20):end + 20]!r}"
                    )
    return issues


def batch13_duty_statistics():
    documents = shell_article_pages()
    violations = 0
    for slug in sorted(documents):
        body_count = 0
        for language in BATCH5_LANGS:
            body = documents[slug].select_one(f'[data-language-body="{language}"]')
            if body is None:
                continue
            body_count += 1
            for column in BATCH13_COLUMNS:
                violations += len(
                    batch13_bare_duty_spans(
                        batch13_column_text(body, column), language
                    )
                )
    return {
        "dossiers": len(documents),
        "languages": len(BATCH5_LANGS),
        "violations": violations,
        "nodes": BATCH13_APPEND_ROWS,
        "revised_dossiers": len(BATCH13_SLUGS),
    }


def batch13_manifest(overrides=None):
    overrides = overrides or {}
    all_records = []
    protected = []
    seen = set()

    def include(relative, payload):
        if payload is None:
            return
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        if batch11_final1_is_desktop_extra(relative, payload):
            return
        record = (relative, len(payload), hashlib.sha256(payload).hexdigest())
        all_records.append(record)
        if relative not in BATCH13_ALLOWED_FILES:
            protected.append(record)

    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative_path = path.relative_to(ROOT)
        relative = relative_path.as_posix()
        if ".git" in relative_path.parts or path.name == ".DS_Store":
            continue
        if relative in BATCH14_NEW_AUDIT_FILES or fnmatch.fnmatch(
            relative, "tools/data/batch14-*.tsv"
        ):
            # First written in batch fourteen: outside this freeze's path set.
            continue
        seen.add(relative)
        include(
            relative,
            overrides.get(
                relative,
                batch13_historical_bytes().get(relative)
                or batch14_historical_bytes().get(relative)
                or path.read_bytes(),
            ),
        )
    for relative, payload in overrides.items():
        relative_path = Path(relative)
        if (
            relative in seen or ".git" in relative_path.parts
            or relative_path.name == ".DS_Store"
        ):
            continue
        include(relative, payload)
    payload = "".join(
        f"{relative}\t{size}\t{digest}\n"
        for relative, size, digest in sorted(protected)
    ).encode("utf-8")
    present = {
        relative for relative, _size, _digest in all_records
        if relative in BATCH13_ALLOWED_FILES
    }
    return all_records, protected, present, payload


def audit_batch13_frozen(overrides=None):
    """Recomputed freeze: everything batch13 did not legitimately touch."""
    all_records, protected, present, payload = batch13_manifest(overrides)
    issues = []
    if len(all_records) != BATCH13_TOTAL_FILES:
        issues.append(
            f"batch13 logical file count is {len(all_records)}, expected "
            f"{BATCH13_TOTAL_FILES}"
        )
    if present != BATCH13_ALLOWED_FILES:
        issues.append("batch13 whitelist membership changed")
    if len(protected) != BATCH13_PROTECTED_FILES:
        issues.append(
            f"batch13 protected file count is {len(protected)}, expected "
            f"{BATCH13_PROTECTED_FILES}"
        )
    if hashlib.sha256(payload).hexdigest() != BATCH13_PROTECTED_SHA256:
        issues.append("batch13 changed, added, or removed a non-whitelist file")
    return issues


def audit_batch13_wiring(source_text=None):
    """The batch13 gates must stay wired into audit_live and the self-test."""
    source = source_text or Path(__file__).read_text(encoding="utf-8")
    try:
        tree = ast.parse(source)
    except SyntaxError as exc:
        return [f"batch13 wiring is not parseable: {exc}"]
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def called(name, callee):
        function = functions.get(name)
        return bool(function) and any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == callee
            for node in ast.walk(function)
        )

    issues = []
    if not called("audit_live", "audit_batch13"):
        issues.append("audit_live no longer runs the batch13 gate")
    if not called("audit_live", "batch13_historical_state"):
        issues.append("audit_live no longer rewinds to the batch13 preimage")
    for callee in (
        "audit_batch13_ledgers",
        "audit_batch13_preimage",
        "audit_batch13_duty_subjects",
        "audit_batch13_frozen",
        "audit_batch13_wiring",
    ):
        if not called("audit_batch13", callee):
            issues.append(f"batch13 gate no longer calls {callee}")
    if not called("main", "batch13_negative_self_test"):
        issues.append("main no longer runs the batch13 self-test")
    if not called("batch13_historical_markup", "batch13_preimage_markup"):
        issues.append("batch13 historical projection no longer rebuilds the preimage")
    return issues


def audit_batch13(
    pages=None, *, page_bytes=None, reread_rows=None, contract_rows=None,
    source_rows=None, frozen_overrides=None, duty_pages=None,
    source_text=None,
):
    issues = []
    for slug in BATCH13_SLUGS:
        batch13_historical_markup(slug)
        issues.extend(_BATCH13_PREIMAGE_ISSUES.get(slug, []))
    issues.extend(audit_batch13_preimage(page_bytes))
    issues.extend(audit_batch13_ledgers(
        pages, reread_rows=reread_rows, contract_rows=contract_rows,
        source_rows=source_rows,
    ))
    issues.extend(audit_batch13_duty_subjects(duty_pages))
    issues.extend(audit_batch13_frozen(frozen_overrides))
    issues.extend(audit_batch13_wiring(source_text))
    return issues


def batch14_negative_self_test():
    """Real mutations of every batch-14 seam this module owns.

    Derived independently of check_languages.py: this module re-reads the
    preimage manifest, rebuilds the reversal itself, and mutates live text.
    """
    names, misses = [], []

    def record(name, caught):
        names.append(name)
        if not caught:
            misses.append(name)

    sample = ROOT / "posts" / f"{BATCH14_NEW_SLUGS[0]}.html"
    live = sample.read_text(encoding="utf-8")
    record(
        "01 batch14 dossier free of the decorative timeline class",
        'class="timeline timeline-list"' not in live,
    )
    record(
        "02 batch14 decorative timeline class detected if reintroduced",
        'class="timeline timeline-list"'
        in live.replace('class="timeline-list"', 'class="timeline timeline-list"', 1),
    )

    payloads = batch14_historical_bytes()
    record(
        "03 batch14 preimage reconstructs every captured file",
        len(payloads) == 67
        and "tools/data/source-date-ledger.tsv" in payloads
        and f"posts/{BATCH14_NEW_SLUGS[0]}.html" not in payloads,
    )
    tampered = batch14_preimage_text(
        "style.css",
        (ROOT / "style.css").read_text(encoding="utf-8") + "\n/* stray */\n",
        "",
        False,
    ).encode("utf-8")
    record(
        "04 batch14 preimage rejects a style.css edit outside the header rule",
        hashlib.sha256(tampered).hexdigest()
        != hashlib.sha256(payloads.get("style.css", b"")).hexdigest(),
    )
    record(
        "05 batch14 preimage restores the pre-batch14 style token",
        BATCH14_STYLE_VERSION_AFTER
        not in payloads.get(f"posts/{BATCH14_NEW_SLUGS[0]}.html", b"").decode(
            "utf-8", "ignore"
        ),
    )

    cards, _ = batch9_final2_report_cards()
    view = batch14_baseline_card_view(cards)
    record(
        "06 batch14 baseline card view restores the 54-card sequence",
        len(view) == 54
        and not ({c.get("slug", "") for c in view} & BATCH14_NEW_SLUG_SET),
    )
    record(
        "07 batch14 baseline card view drops only batch14 cards",
        len(cards) - len(view) == len(BATCH14_NEW_SLUGS),
    )
    record(
        "08 batch14 baseline card view shrinks when a batch14 card vanishes",
        len(batch14_baseline_card_view(
            [c for c in cards if c.get("slug", "") != BATCH14_NEW_SLUGS[2]]
        )) == 54,
    )
    record(
        "09 batch13 freeze stays clean with the batch14 successor applied",
        not audit_batch13_frozen(),
    )
    record(
        "10 batch13 freeze still fires on a real protected-file change",
        bool(audit_batch13_frozen(overrides={"index.html": b"<html>tampered</html>"})),
    )
    return len(names) - len(misses), len(names), misses


def batch13_negative_self_test(pages):
    """Nine named real mutations, including one must-not-fire reverse test."""
    names = []
    misses = []
    reread_rows, _ = batch9_final2_load_tsv(
        BATCH9_REREAD_PATH, BATCH9_FINAL2_REREAD_COLUMNS,
        "batch13 self-test reread",
    )

    def record(name, caught):
        names.append(name)
        if not caught:
            misses.append(name)

    def reported(marker, **kwargs):
        return any(
            marker in issue
            for issue in audit_batch13_ledgers(pages, **kwargs)
        )

    record(
        "01 batch13 reread append loses one of its 446 rows",
        reported("append has 445 rows", reread_rows=reread_rows[:-1]),
    )

    mismatched = deepcopy(reread_rows)
    mismatched[-1]["revised_text"] = (
        mismatched[-1]["revised_text"] + " 未經覆核的補充句。"
    )
    record(
        "02 batch13 revised text no longer matches the live DOM",
        reported(
            "revised text differs from the live DOM", reread_rows=mismatched
        ),
    )

    downgraded = deepcopy(reread_rows)
    downgraded[-1]["result"] = "PASS_NO_CHANGE"
    record(
        "03 batch13 reread result is not PASS_AFTER_REVISION",
        reported("is not a real revision", reread_rows=downgraded),
    )

    fabricated = deepcopy(reread_rows)
    fabricated[-1]["original_text"] = fabricated[-1]["revised_text"]
    record(
        "04 batch13 row fabricates a no-change revision",
        reported(
            "original text differs from the preimage DOM",
            reread_rows=fabricated,
        )
        and reported("is not a real revision", reread_rows=fabricated),
    )

    rewritten = deepcopy(reread_rows)
    rewritten[7]["revised_text"] = rewritten[7]["revised_text"] + " rewritten"
    record(
        "05 batch13 authenticated pre-16563 history is rewritten",
        reported(
            "completed-batch12 prefix differs", reread_rows=rewritten
        ),
    )

    chinese = BeautifulSoup(batch13_live_text("2024-report"), "html.parser")
    node = batch13_target_node(chinese, "zh", "2024-report-protection")
    node.append("國家必須立即公開全部記錄。")
    record(
        "06 protection column reintroduces a bare 國家必須 duty",
        any(
            "unqualified state subject" in issue
            for issue in audit_batch13_duty_subjects({"2024-report": chinese})
        ),
    )

    english = BeautifulSoup(batch13_live_text("2024-report"), "html.parser")
    english_node = batch13_target_node(
        english, "en", "2024-report-rights-analysis"
    )
    english_node.append(" The state must publish every enforcement record.")
    record(
        "07 rights-analysis column reintroduces The state must",
        any(
            "unqualified state subject" in issue
            for issue in audit_batch13_duty_subjects({"2024-report": english})
        ),
    )

    legitimate = BeautifulSoup(batch13_live_text("2024-report"), "html.parser")
    legitimate_node = batch13_target_node(
        legitimate, "zh", "2024-report-protection"
    )
    legitimate_node.append(
        "民主國家、聯合國機制及專業團體應協助保存證據。民主國家應公開其審查結論。"
    )
    record(
        "08 reverse test: 民主國家...應 must not be reported",
        not audit_batch13_duty_subjects({"2024-report": legitimate}),
    )

    # The needles below carry a real newline, so they cannot match the
    # escaped copies of themselves inside this function's own source.
    unwired = Path(__file__).read_text(encoding="utf-8").replace(
        "    issues.extend(audit_batch13(current_pages))\n",
        "    issues.extend([])\n",
        1,
    )
    unwired_duty = Path(__file__).read_text(encoding="utf-8").replace(
        "issues.extend(audit_batch13_duty_subjects(duty_pages))",
        "issues.extend([])",
        1,
    )
    record(
        "09 batch13 gate is unwired from audit_live",
        bool(audit_batch13_wiring(unwired))
        and bool(audit_batch13_wiring(unwired_duty)),
    )
    return len(names) - len(misses), len(names), misses


